    previous_revision_id     INTEGER,
    created                  TEXT,
    creator_name             TEXT,
    creator_url              TEXT,
    comment                  TEXT,
    reviewed                 INTEGER,
    reviewed_date            TEXT,
    reviewed_by              TEXT,
    is_approved              INTEGER,
    is_current               INTEGER,
    ready_for_l10n           INTEGER,
    readied_for_l10n_date    TEXT,
    readied_for_l10n_by      TEXT,
    status                   TEXT,
    source                   TEXT,
    content_html             TEXT,
    info_json                TEXT,
    scraped_at               TEXT
);
CREATE INDEX IF NOT EXISTS idx_revisions_status_reviewed
    ON revisions (status, reviewed_date);
CREATE INDEX IF NOT EXISTS idx_revisions_article ON revisions (article_slug);
CREATE TABLE IF NOT EXISTS article_revisions (
    revision_id              INTEGER PRIMARY KEY,
    locale                   TEXT,
    article_slug             TEXT,
    article_title            TEXT,
    article_url              TEXT,
    revision_url             TEXT,
    previous_revision_id     INTEGER,
    created                  TEXT,
