    reviewed_by              TEXT,
    is_approved              INTEGER,
    is_current               INTEGER,
    ready_for_l10n           INTEGER,
    readied_for_l10n_date    TEXT,
    readied_for_l10n_by      TEXT,
    status                   TEXT,
    source                   TEXT,
    content_html             TEXT,
