    significance             TEXT
);
CREATE INDEX IF NOT EXISTS idx_article_revisions_article
    ON article_revisions (article_slug, created);
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (31938,'en-US','add-email-accounts','Add email accounts','https://support.mozilla.org/en-US/kb/add-email-accounts','https://support.mozilla.org/en-US/kb/add-email-accounts/revision/31938',NULL,'2012-09-19T06:08:38-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','first rough draft',1,'2012-09-19T06:09:25-07:00','rtanglao',1,0,0,NULL,NULL,'approved','Please note that the email app doesn''t allow you to create a new email account. It only allows you to add an existing email account. If you need a new email account, please create a new account at your provider''s website before adding it to the email app.
# To open the email app, tap [[image for email app]]
# If this is the first time you have run the email app, it will present you with the new account wizard with a selection of email providers. If this is not the first time, tap [[image for drawer icon]] and then tap [[image for settings]] and then tap {button Add Account}
# Tap on the email provider for your account
# Enter your username and password
# Tap on {button Next}
# Your email account will be setup and then you are finished!','<p>Please note that the email app doesn''t allow you to create a new email account. It only allows you to add an existing email account. If you need a new email account, please create a new account at your provider''s website before adding it to the email app.
</p>
<ol><li> To open the email app, tap <a class="new" href="/en-US/kb/new?title=image+for+email+app" title="Page does not exist.">image for email app</a>
</li><li> If this is the first time you have run the email app, it will present you with the new account wizard with a selection of email providers. If this is not the first time, tap <a class="new" href="/en-US/kb/new?title=image+for+drawer+icon" title="Page does not exist.">image for drawer icon</a> and then tap <a class="new" href="/en-US/kb/new?title=image+for+settings" title="Page does not exist.">image for settings</a> and then tap <span class="button">Add Account</span>
</li><li> Tap on the email provider for your account
</li><li> Enter your username and password
</li><li> Tap on <span class="button">Next</span>
</li><li> Your email account will be setup and then you are finished!
</li></ol>','[{"label": "Revision id", "text": "31938", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 19, 2012, 6:08:38 AM", "datetime": "2012-09-19T06:08:38-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "first rough draft", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 19, 2012, 6:09:25 AM", "datetime": "2012-09-19T06:09:25-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:51:57+00:00');
