https://www.dropbox.com/sh/ygwfxk6chpshxdj/qcs8MQfc3g/Apps/Contacts/HTML5_Dialer_Contacts_20120810_R2S1_V6.0.pdf
page 24 beside "Carloci@gmail.com"
  -->
# Tap [[Image:unread]]  next to the email address you want to email
# The email app will start and the contact email address will be in the ''''To'''' field
# [[Composing and Sending Email|Compose and send the email]] just like any other email','<ol><li> Tap <img alt="contacts app" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-10-10-14-03-47-4136a9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> to open the Contacts app
</li><li> Tap on the contact you want to email
</li></ol>
<p>

</p><ol><li> Tap <img alt="unread" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-02-27-08d7ca.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">  next to the email address you want to email
</li><li> The email app will start and the contact email address will be in the <em>To</em> field
</li><li> <a href="/en-US/kb/send-and-manage-email">Compose and send the email</a> just like any other email
</li></ol>','[{"label": "Revision id", "text": "32353", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 27, 2012, 7:22:22 AM", "datetime": "2012-09-27T07:22:22-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "first version! work in progress, please help us out by editing if you have time!", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 27, 2012, 7:22:34 AM", "datetime": "2012-09-27T07:22:34-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:51:20+00:00');
