# To open the email app, tap [[Image:email]]
# Tap on an email to display it
# Tap [[Image:delete]] at the bottom to delete the email
# The email be deleted and the remaining emails in that folder will be displayed','<h2 id="w_deleting-a-single-email">Deleting a single email</h2>
<ol><li> To open the email app, tap <img alt="email" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-01-13-03-08-0c83f5.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on an email to display it
</li><li> Tap <img alt="delete" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-09-12-0ff64a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> at the bottom to delete the email
</li><li> The email be deleted and the remaining emails in that folder will be displayed
</li></ol>','[{"label": "Revision id", "text": "32374", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 28, 2012, 4:12:02 AM", "datetime": "2012-09-28T04:12:02-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "first draft with just single message delete", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 28, 2012, 4:12:24 AM", "datetime": "2012-09-28T04:12:24-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:51:16+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (32377,'en-US','deleting-email-messages-firefox-os','Deleting email messages in Firefox OS','https://support.mozilla.org/en-US/kb/deleting-email-messages-firefox-os','https://support.mozilla.org/en-US/kb/deleting-email-messages-firefox-os/revision/32377',32374,'2012-09-28T05:52:23-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','add section on deleting multiple emails',1,'2012-09-28T05:52:49-07:00','rtanglao',1,0,0,NULL,NULL,'approved','== Deleting a single email ==
# To open the email app, tap [[Image:email]]
# Tap on an email to display it.
# Tap [[Image:delete]] at the bottom to delete the email.
# The email will be deleted and moved to the trash and the remaining emails in that folder will be displayed.

== Deleting multiple emails ==
# To open the email app, tap [[Image:email]]
# Tap on [[Image:edit icon]]
#  Tap [[Image:red circle]] next to the emails you want to delete. Check marks will be displayed next the emails you have selected to delete. If you make a mistake, tap [[Image:red circle]] again to un-select an email for deletion.
# Tap [[Image:delete]] at the bottom to delete the selected emails
# The emails will be deleted and moved to the trash and the remaining emails in that folder will be displayed.','<h2 id="w_deleting-a-single-email">Deleting a single email</h2>
<ol><li> To open the email app, tap <img alt="email" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-01-13-03-08-0c83f5.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on an email to display it.
</li><li> Tap <img alt="delete" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-09-12-0ff64a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> at the bottom to delete the email.
</li><li> The email will be deleted and moved to the trash and the remaining emails in that folder will be displayed.
</li></ol>
<h2 id="w_deleting-multiple-emails">Deleting multiple emails</h2>
<ol><li> To open the email app, tap <img alt="email" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-01-13-03-08-0c83f5.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on <img alt="edit icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-03-25-eabe76.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li>  Tap The image "red circle" does not exist. next to the emails you want to delete. Check marks will be displayed next the emails you have selected to delete. If you make a mistake, tap The image "red circle" does not exist. again to un-select an email for deletion.
</li><li> Tap <img alt="delete" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-09-12-0ff64a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> at the bottom to delete the selected emails
</li><li> The emails will be deleted and moved to the trash and the remaining emails in that folder will be displayed.
</li></ol>','[{"label": "Revision id", "text": "32377", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 28, 2012, 5:52:23 AM", "datetime": "2012-09-28T05:52:23-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "add section on deleting multiple emails", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 28, 2012, 5:52:49 AM", "datetime": "2012-09-28T05:52:49-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:51:13+00:00');
