INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36259,'en-US','firefox-android-crashes-startup-how-fix','Firefox for Android Crashes On Startup - How To Fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix/revision/36259',NULL,'2013-02-06T08:30:09-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','first version with full content cut and pasted in installing and template for uninstalling',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','__TOC__
If Firefox for Android crashes on startup (you may or may not see this error message: "OpenGL-accelerated layers are a hard requirement on this platform"), here''s how to fix it:
* Step 1. Uninstall Firefox for Android. 
{note}''''''Important:''''''If you uninstall Firefox, you will lose your data such as bookmarks & history ; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.''''''{/note}
* Step 2. Install Firefox for Android.
=Step 1. Uninstall Firefox for Android=
{note}''''''Important:''''''If you uninstall Firefox, you will lose your data such as bookmarks & history ; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.''''''{/note}
[[T:How to uninstall Firefox for Android]]
=Step 2. Install Firefox for Android=
This article shows you how to download and install Firefox for mobile on Android devices that meet the following requirements:
*''''''Android 2.2'''''' or higher
*an ''''''ARMv7 processor'''''' and a min clock frequency of ''''''800MHz''''''
*Approximately ''''''17MB'''''' internal or SD storage. It runs best on devices with at least ''''''512MB'''''' of RAM
*a min display resolution of ''''''480 x 320''''''
*support of ''''''[http://en.wikipedia.org/wiki/OpenGL_ES OpenGL ES] 2.0''''''
{note}If Firefox can''t be found when trying to download or searching for it in Google Play, your device may not be supported.<br>For instructions about devices running Maemo or Meego, see instead [http://store.ovi.com/publisher/Firefox].{/note} 

==Prerequisites==
If you have installed and set up sync for any version of Firefox Beta, Aurora, or Nightly, you must uninstall that version before setting up sync on Firefox for Android.

==Downloading and installing Firefox==
#To download and install Firefox on your device just go to [http://www.mozilla.org/mobile/ mozilla.org/mobile] and tap on the download button.<br>
#:<br>[[Image:install_0]]<br><br>
#:The Google Play app will open the Firefox installation page. <br>
#Tap the Install button.<br>
#:<br>[[Image:install_1]]<br><br>
#Accept permissions and begin the download.<br>
#:<br>[[Image:install_3]]<br><br>
#:The installation will begin. <br>
#:<br>[[Image:install_5]]<br><br>
#Select the Allow automatic updates check box to be sure you get security updates every six weeks.
#:<br>[[Image:install_update]]<br><br>
#Finally, tap the Open button<br>
#:<br>[[Image:install_open]]<br><br>

[[Template:ShareArticle|link=http://mzl.la/MHkveD]]','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_step-1-uninstall-firefox-for-android"><span class="tocnumber">1</span> <span class="toctext">Step 1. Uninstall Firefox for Android</span></a></li><li class="toclevel-1"><a href="#w_step-2-install-firefox-for-android"><span class="tocnumber">2</span> <span class="toctext">Step 2. Install Firefox for Android</span></a><ul><li class="toclevel-2"><a href="#w_prerequisites"><span class="tocnumber">2.1</span> <span class="toctext">Prerequisites</span></a></li><li class="toclevel-2"><a href="#w_downloading-and-installing-firefox"><span class="tocnumber">2.2</span> <span class="toctext">Downloading and installing Firefox</span></a></li></ul></li></ul></div>
<p>If Firefox for Android crashes on startup (you may or may not see this error message: "OpenGL-accelerated layers are a hard requirement on this platform"), here''s how to fix it:
</p>
<ul><li> Step 1. Uninstall Firefox for Android. 
</li></ul>
<div class="note"><strong>Important:</strong>If you uninstall Firefox, you will lose your data such as bookmarks &amp; history&nbsp;; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.<strong></strong></div><strong>
</strong>
<ul><li> Step 2. Install Firefox for Android.
</li></ul>
<h1 id="w_step-1-uninstall-firefox-for-android">Step 1. Uninstall Firefox for Android</h1>
<div class="note"><strong>Important:</strong>If you uninstall Firefox, you will lose your data such as bookmarks &amp; history&nbsp;; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.<strong></strong></div><strong>
</strong>
<p></p><p>To uninstall Firefox, follow these steps:
</p>
<ol><li> Open the Google Play Store application and tap on the search icon which looks like a magnifying glass.<br><br><img alt="ICS - Android - Tapping Search icon in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-15-09-30-26d046.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Type "Firefox" and tap on the magnifying glass search icon.
</li><li> Tap on <span class="button">Firefox</span>.<br><br><img alt="ICS - Android - Searching for Firefox in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-14-54-24-c3148f.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on <span class="button">Uninstall</span>.<br><br><img alt="ICS - Android - Uninstalling from Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-14-40-51-75b561.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ol>
<p>Your uninstall of Firefox is finished.
</p>
<p></p>
<h1 id="w_step-2-install-firefox-for-android">Step 2. Install Firefox for Android</h1>
<p>This article shows you how to download and install Firefox for mobile on Android devices that meet the following requirements:
</p>
<ul><li><strong>Android 2.2</strong> or higher
</li><li>an <strong>ARMv7 processor</strong> and a min clock frequency of <strong>800MHz</strong>
</li><li>Approximately <strong>17MB</strong> internal or SD storage. It runs best on devices with at least <strong>512MB</strong> of RAM
</li><li>a min display resolution of <strong>480 x 320</strong>
</li><li>support of <strong><a href="http://en.wikipedia.org/wiki/OpenGL_ES">OpenGL ES</a> 2.0</strong>
</li></ul>
<div class="note">If Firefox can''t be found when trying to download or searching for it in Google Play, your device may not be supported.<br>For instructions about devices running Maemo or Meego, see instead <a href="http://store.ovi.com/publisher/Firefox">http://store.ovi.com/publisher/Firefox</a>.</div> 
<h2 id="w_prerequisites">Prerequisites</h2>
<p>If you have installed and set up sync for any version of Firefox Beta, Aurora, or Nightly, you must uninstall that version before setting up sync on Firefox for Android.
</p>
<h2 id="w_downloading-and-installing-firefox">Downloading and installing Firefox</h2>
<ol><li>To download and install Firefox on your device just go to <a href="http://www.mozilla.org/mobile/">mozilla.org/mobile</a> and tap on the download button.<br>
<dl><dd><br><img alt="install_0" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-23-01-0307d1.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd><dd>The Google Play app will open the Firefox installation page. <br>
</dd></dl>
</li><li>Tap the Install button.<br>
<dl><dd><br><img alt="install_1" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-22-30-b21327.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li><li>Accept permissions and begin the download.<br>
<dl><dd><br><img alt="install_3" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-22-06-4c5600.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd><dd>The installation will begin. <br>
</dd><dd><br><img alt="install_5" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-21-46-27b0e3.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li><li>Select the Allow automatic updates check box to be sure you get security updates every six weeks.
<dl><dd><br><img alt="install_update" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-20-15-30-52-3ac340.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li><li>Finally, tap the Open button<br>
<dl><dd><br><img alt="install_open" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-20-15-33-30-7cef8a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li></ol>
<p>&nbsp;

</p>','[{"label": "Revision id", "text": "36259", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 6, 2013, 8:30:09 AM", "datetime": "2013-02-06T08:30:09-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "first version with full content cut and pasted in installing and template for uninstalling", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:50:38+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36260,'en-US','firefox-android-crashes-startup-how-fix','Firefox for Android Crashes On Startup - How To Fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix/revision/36260',NULL,'2013-02-06T08:37:14-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','commented out template with short mzl.la link since i don''t know how to do this',1,'2013-02-06T08:44:15-08:00','mluna',1,0,1,'2013-02-06T08:44:15-08:00','mluna','approved','__TOC__
If Firefox for Android crashes on startup (you may or may not see this error message: "OpenGL-accelerated layers are a hard requirement on this platform"), here''s how to fix it:
* Step 1. Uninstall Firefox for Android. 
{note}''''''Important:''''''If you uninstall Firefox, you will lose your data such as bookmarks & history ; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.''''''{/note}
* Step 2. Install Firefox for Android.
=Step 1. Uninstall Firefox for Android=
{note}''''''Important:''''''If you uninstall Firefox, you will lose your data such as bookmarks & history ; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.''''''{/note}
[[T:How to uninstall Firefox for Android]]
=Step 2. Install Firefox for Android=
This article shows you how to download and install Firefox for mobile on Android devices that meet the following requirements:
*''''''Android 2.2'''''' or higher
*an ''''''ARMv7 processor'''''' and a min clock frequency of ''''''800MHz''''''
*Approximately ''''''17MB'''''' internal or SD storage. It runs best on devices with at least ''''''512MB'''''' of RAM
*a min display resolution of ''''''480 x 320''''''
*support of ''''''[http://en.wikipedia.org/wiki/OpenGL_ES OpenGL ES] 2.0''''''
{note}If Firefox can''t be found when trying to download or searching for it in Google Play, your device may not be supported.<br>For instructions about devices running Maemo or Meego, see instead [http://store.ovi.com/publisher/Firefox].{/note} 

==Prerequisites==
If you have installed and set up sync for any version of Firefox Beta, Aurora, or Nightly, you must uninstall that version before setting up sync on Firefox for Android.

==Downloading and installing Firefox==
#To download and install Firefox on your device just go to [http://www.mozilla.org/mobile/ mozilla.org/mobile] and tap on the download button.<br>
#:<br>[[Image:install_0]]<br><br>
#:The Google Play app will open the Firefox installation page. <br>
#Tap the Install button.<br>
#:<br>[[Image:install_1]]<br><br>
#Accept permissions and begin the download.<br>
#:<br>[[Image:install_3]]<br><br>
#:The installation will begin. <br>
#:<br>[[Image:install_5]]<br><br>
#Select the Allow automatic updates check box to be sure you get security updates every six weeks.
#:<br>[[Image:install_update]]<br><br>
#Finally, tap the Open button<br>
#:<br>[[Image:install_open]]<br><br>

<!--
[[Template:ShareArticle|link=http://mzl.la/MHkveD]]
-->','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_step-1-uninstall-firefox-for-android"><span class="tocnumber">1</span> <span class="toctext">Step 1. Uninstall Firefox for Android</span></a></li><li class="toclevel-1"><a href="#w_step-2-install-firefox-for-android"><span class="tocnumber">2</span> <span class="toctext">Step 2. Install Firefox for Android</span></a><ul><li class="toclevel-2"><a href="#w_prerequisites"><span class="tocnumber">2.1</span> <span class="toctext">Prerequisites</span></a></li><li class="toclevel-2"><a href="#w_downloading-and-installing-firefox"><span class="tocnumber">2.2</span> <span class="toctext">Downloading and installing Firefox</span></a></li></ul></li></ul></div>
<p>If Firefox for Android crashes on startup (you may or may not see this error message: "OpenGL-accelerated layers are a hard requirement on this platform"), here''s how to fix it:
</p>
<ul><li> Step 1. Uninstall Firefox for Android. 
</li></ul>
<div class="note"><strong>Important:</strong>If you uninstall Firefox, you will lose your data such as bookmarks &amp; history&nbsp;; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.<strong></strong></div><strong>
</strong>
<ul><li> Step 2. Install Firefox for Android.
</li></ul>
<h1 id="w_step-1-uninstall-firefox-for-android">Step 1. Uninstall Firefox for Android</h1>
<div class="note"><strong>Important:</strong>If you uninstall Firefox, you will lose your data such as bookmarks &amp; history&nbsp;; if you don''t want to lose your data, please wait for a Firefox update to fix this problem.<strong></strong></div><strong>
</strong>
<p></p><p>To uninstall Firefox, follow these steps:
</p>
<ol><li> Open the Google Play Store application and tap on the search icon which looks like a magnifying glass.<br><br><img alt="ICS - Android - Tapping Search icon in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-15-09-30-26d046.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Type "Firefox" and tap on the magnifying glass search icon.
</li><li> Tap on <span class="button">Firefox</span>.<br><br><img alt="ICS - Android - Searching for Firefox in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-14-54-24-c3148f.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on <span class="button">Uninstall</span>.<br><br><img alt="ICS - Android - Uninstalling from Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-14-40-51-75b561.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ol>
<p>Your uninstall of Firefox is finished.
</p>
<p></p>
<h1 id="w_step-2-install-firefox-for-android">Step 2. Install Firefox for Android</h1>
<p>This article shows you how to download and install Firefox for mobile on Android devices that meet the following requirements:
</p>
<ul><li><strong>Android 2.2</strong> or higher
</li><li>an <strong>ARMv7 processor</strong> and a min clock frequency of <strong>800MHz</strong>
</li><li>Approximately <strong>17MB</strong> internal or SD storage. It runs best on devices with at least <strong>512MB</strong> of RAM
</li><li>a min display resolution of <strong>480 x 320</strong>
</li><li>support of <strong><a href="http://en.wikipedia.org/wiki/OpenGL_ES">OpenGL ES</a> 2.0</strong>
</li></ul>
<div class="note">If Firefox can''t be found when trying to download or searching for it in Google Play, your device may not be supported.<br>For instructions about devices running Maemo or Meego, see instead <a href="http://store.ovi.com/publisher/Firefox">http://store.ovi.com/publisher/Firefox</a>.</div> 
<h2 id="w_prerequisites">Prerequisites</h2>
<p>If you have installed and set up sync for any version of Firefox Beta, Aurora, or Nightly, you must uninstall that version before setting up sync on Firefox for Android.
</p>
<h2 id="w_downloading-and-installing-firefox">Downloading and installing Firefox</h2>
<ol><li>To download and install Firefox on your device just go to <a href="http://www.mozilla.org/mobile/">mozilla.org/mobile</a> and tap on the download button.<br>
<dl><dd><br><img alt="install_0" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-23-01-0307d1.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd><dd>The Google Play app will open the Firefox installation page. <br>
</dd></dl>
</li><li>Tap the Install button.<br>
<dl><dd><br><img alt="install_1" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-22-30-b21327.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li><li>Accept permissions and begin the download.<br>
<dl><dd><br><img alt="install_3" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-22-06-4c5600.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd><dd>The installation will begin. <br>
</dd><dd><br><img alt="install_5" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-11-17-21-46-27b0e3.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li><li>Select the Allow automatic updates check box to be sure you get security updates every six weeks.
<dl><dd><br><img alt="install_update" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-20-15-30-52-3ac340.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li><li>Finally, tap the Open button<br>
<dl><dd><br><img alt="install_open" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-04-20-15-33-30-7cef8a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</dd></dl>
</li></ol>
<p>
</p>','[{"label": "Revision id", "text": "36260", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 6, 2013, 8:37:14 AM", "datetime": "2013-02-06T08:37:14-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "commented out template with short mzl.la link since i don''t know how to do this", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 6, 2013, 8:44:15 AM", "datetime": "2013-02-06T08:44:15-08:00", "href": null}, {"label": "Reviewed by", "text": "mluna", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Feb 6, 2013, 8:44:15 AM", "datetime": "2013-02-06T08:44:15-08:00", "href": null}, {"label": "Readied for localization by", "text": "mluna", "datetime": null, "href": null}]','2026-11-03T18:50:35+00:00');
