</p>','[{"label": "Revision id", "text": "36273", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 6, 2013, 2:05:32 PM", "datetime": "2013-02-06T14:05:32-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "REDIRECT  to \"Get started with Firefox for Android\" which has merged content from both articles now that Marketing has decided to use ''Android'' instead of ''Mobile''", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 6, 2013, 2:06:09 PM", "datetime": "2013-02-06T14:06:09-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jul 19, 2013, 6:22:32 AM", "datetime": "2013-07-19T06:22:32-07:00", "href": null}, {"label": "Readied for localization by", "text": "Verdi", "datetime": null, "href": null}]','2026-11-03T18:50:28+00:00');
