-->','<p>Firefox 18.0.2 for Android was released to fix the startup crash problem.
</p><p>To update to Firefox 18.0.2:
</p>
<ol><li> Open the Google Play Store application
</li><li> If you have set Firefox to allow automatic updating, then Firefox will start  updating automatically.
</li><li> If you have set Firefox for manual updating:
<ol><li> Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br><img alt="ICS - Android - Tapping Search icon in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-15-09-30-26d046.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Type "Firefox" and tap on the magnifying glass search icon.
</li><li> Tap on <span class="button">Firefox</span> and then tap on <span class="button">Update</span>.
</li></ol>
</li></ol>
<p>

</p>','[{"label": "Revision id", "text": "36329", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 7, 2013, 7:18:58 AM", "datetime": "2013-02-07T07:18:58-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "FF 18.0.2 is out so remove uninstall & install instructions", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:50:25+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36330,'en-US','firefox-android-crashes-startup-how-fix','Firefox for Android Crashes On Startup - How To Fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix/revision/36330',36261,'2013-02-07T08:15:16-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','remove nested lists because they don''t work well',1,'2013-02-07T08:17:11-08:00','mluna',1,0,0,NULL,NULL,'approved','Firefox 18.0.2 for Android was released to fix the startup crash problem. Please update to the latest release of Firefox to fix this issue.

=Automatically update Firefox=
If you have set Firefox to allow automatic updating, here''s how to update:
# Open the Google Play Store application.
# Firefox will start  updating automatically.
=Manually update Firefox=
If you have set Firefox for manual updating:
# Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br /><br />[[Image:ICS - Android - Tapping Search icon in Google Play]]
# Type "Firefox" and tap on the magnifying glass search icon.
# Tap on {button Firefox} and then tap on {button Update}.','<p>Firefox 18.0.2 for Android was released to fix the startup crash problem. Please update to the latest release of Firefox to fix this issue.
</p>
<h1 id="w_automatically-update-firefox">Automatically update Firefox</h1>
<p>If you have set Firefox to allow automatic updating, here''s how to update:
</p>
<ol><li> Open the Google Play Store application.
</li><li> Firefox will start  updating automatically.
</li></ol>
<h1 id="w_manually-update-firefox">Manually update Firefox</h1>
<p>If you have set Firefox for manual updating:
</p>
<ol><li> Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br><br><img alt="ICS - Android - Tapping Search icon in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-15-09-30-26d046.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Type "Firefox" and tap on the magnifying glass search icon.
</li><li> Tap on <span class="button">Firefox</span> and then tap on <span class="button">Update</span>.
</li></ol>','[{"label": "Revision id", "text": "36330", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 7, 2013, 8:15:16 AM", "datetime": "2013-02-07T08:15:16-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "remove nested lists because they don''t work well", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 7, 2013, 8:17:11 AM", "datetime": "2013-02-07T08:17:11-08:00", "href": null}, {"label": "Reviewed by", "text": "mluna", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:50:23+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36332,'en-US','firefox-android-crashes-startup-how-fix','Firefox for Android Crashes On Startup - How To Fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix/revision/36332',36330,'2013-02-07T08:33:11-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','hello localizers: given the fact that this article was only relevant for a few days, i shouldn''t have set it to ready for l10n, but i did! i.e. English only would probably have sufficed. But since I did, setting this edit to ready for l10n just in case.',1,'2013-02-07T08:33:35-08:00','rtanglao',1,0,1,'2013-02-07T08:33:35-08:00','rtanglao','approved','Firefox 18.0.2 for Android was released to fix the startup crash problem. Please update to the latest release of Firefox to fix this issue.

=Automatically update Firefox=
If you have set Firefox to allow automatic updating, here''s how to update:
# Open the Google Play Store application.
# Firefox will start  updating automatically.
=Manually update Firefox=
If you have set Firefox for manual updating:
# Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br /><br />[[Image:ICS - Android - Tapping Search icon in Google Play]]
# Type "Firefox" and tap on the magnifying glass search icon.
# Tap on {button Firefox} and then tap on {button Update}.','<p>Firefox 18.0.2 for Android was released to fix the startup crash problem. Please update to the latest release of Firefox to fix this issue.
</p>
<h1 id="w_automatically-update-firefox">Automatically update Firefox</h1>
<p>If you have set Firefox to allow automatic updating, here''s how to update:
</p>
<ol><li> Open the Google Play Store application.
</li><li> Firefox will start  updating automatically.
</li></ol>
<h1 id="w_manually-update-firefox">Manually update Firefox</h1>
<p>If you have set Firefox for manual updating:
</p>
<ol><li> Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br><br><img alt="ICS - Android - Tapping Search icon in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-15-09-30-26d046.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Type "Firefox" and tap on the magnifying glass search icon.
</li><li> Tap on <span class="button">Firefox</span> and then tap on <span class="button">Update</span>.
</li></ol>','[{"label": "Revision id", "text": "36332", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 7, 2013, 8:33:11 AM", "datetime": "2013-02-07T08:33:11-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "hello localizers: given the fact that this article was only relevant for a few days, i shouldn''t have set it to ready for l10n, but i did! i.e. English only would probably have sufficed. But since I did, setting this edit to ready for l10n just in case.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 7, 2013, 8:33:35 AM", "datetime": "2013-02-07T08:33:35-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Feb 7, 2013, 8:33:35 AM", "datetime": "2013-02-07T08:33:35-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:50:21+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36507,'en-US','make-firefox-default-browser-android','Set Firefox as your default browser on Android','https://support.mozilla.org/en-US/kb/make-firefox-default-browser-android','https://support.mozilla.org/en-US/kb/make-firefox-default-browser-android/revision/36507',36122,'2013-02-12T04:07:29-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','removed ff aurora, beta  and nightly from screenshots and made steps explicit per feedback from Michael Verdi',1,'2013-02-12T05:16:45-08:00','mluna',1,0,1,'2013-02-12T05:16:45-08:00','mluna','approved','__TOC__
This article explains how to make links on your Android device open in Firefox by default:
* 1. Clear the current browser that opens links.
* 2. Set Firefox to be the default browser for opening links.
=1. Clear the current browser that opens links=
# Open the Settings application and tap on {button Apps} (On some versions of Android this button is labelled "Applications").
# Tap on the {button All} tab.<br/>[[Image:Android ICS Manage Apps - Cropped just showing stock]]
# Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
# Tap on {button Clear defaults} to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another broswer or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser. 
[[Image:Android ICS Clear defaults - Cropped]]

=2. Set Firefox to be the default browser for opening links=
# Open a link in an Android application like the Mail application.
# Tap on {button Firefox} and then tap on {button Always}.
[[Image:Android ICS Complete Action using Firefox Always just showing stock and ff]]','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_1-clear-the-current-browser-that-opens-links"><span class="tocnumber">1</span> <span class="toctext">1. Clear the current browser that opens links</span></a></li><li class="toclevel-1"><a href="#w_2-set-firefox-to-be-the-default-browser-for-opening-links"><span class="tocnumber">2</span> <span class="toctext">2. Set Firefox to be the default browser for opening links</span></a></li></ul></div>
<p>This article explains how to make links on your Android device open in Firefox by default:
</p>
<ul><li> 1. Clear the current browser that opens links.
</li><li> 2. Set Firefox to be the default browser for opening links.
</li></ul>
<h1 id="w_1-clear-the-current-browser-that-opens-links">1. Clear the current browser that opens links</h1>
<ol><li> Open the Settings application and tap on <span class="button">Apps</span> (On some versions of Android this button is labelled "Applications").
</li><li> Tap on the <span class="button">All</span> tab.<br><img alt="Android ICS Manage Apps - Cropped just showing stock" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-12-11-59-02-8caa08.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
</li><li> Tap on <span class="button">Clear defaults</span> to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another broswer or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser. 
</li></ol>
<p><img alt="Android ICS Clear defaults - Cropped" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-03-22-30-33-ca626d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<h1 id="w_2-set-firefox-to-be-the-default-browser-for-opening-links">2. Set Firefox to be the default browser for opening links</h1>
<ol><li> Open a link in an Android application like the Mail application.
</li><li> Tap on <span class="button">Firefox</span> and then tap on <span class="button">Always</span>.
</li></ol>
<p><img alt="Android ICS Complete Action using Firefox Always just showing stock and ff" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-12-11-58-00-a88b4f.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>','[{"label": "Revision id", "text": "36507", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 12, 2013, 4:07:29 AM", "datetime": "2013-02-12T04:07:29-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "removed ff aurora, beta  and nightly from screenshots and made steps explicit per feedback from Michael Verdi", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 12, 2013, 5:16:45 AM", "datetime": "2013-02-12T05:16:45-08:00", "href": null}, {"label": "Reviewed by", "text": "mluna", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Feb 12, 2013, 5:16:45 AM", "datetime": "2013-02-12T05:16:45-08:00", "href": null}, {"label": "Readied for localization by", "text": "mluna", "datetime": null, "href": null}]','2026-11-03T18:50:18+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36537,'en-US','does-firefox-work-windows-8-and-windows-rt','Does Firefox work on Windows 8 and Windows RT?','https://support.mozilla.org/en-US/kb/does-firefox-work-windows-8-and-windows-rt','https://support.mozilla.org/en-US/kb/does-firefox-work-windows-8-and-windows-rt/revision/36537',36155,'2013-02-13T04:19:27-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','updating article now that Metro UI is supported in Nightly! DO NOT APPROVE until nightly is available which should be about 3p.m. pacific 13Feb2013',1,'2013-02-13T09:32:49-08:00','Verdi',1,0,0,NULL,NULL,'approved','Windows 8/RT was just released by Microsoft. This article will answer to some questions you could have if you have planned to upgrade your OS to Windows 8, buy a brand new computer on Windows 8 or a tablet (e.g. Surface) on Windows RT.
{for mac,linux}
{note}''''''Note:'''''' This article only applies to Windows. To see instructions, choose any Windows version from the dropdown menu above.{/note}
{/for}

{for win}
__TOC__

= Does Firefox work in the Windows 8 desktop view? =
Firefox 17 is the first version that officially supports Windows 8 in the desktop view although the previous versions of Firefox should work without major issues. See [http://www.mozilla.org/firefox/17.0/system-requirements/ Firefox 17 system requirements] for more details.

= Does Firefox work in the Windows 8 Metro interface? =
There is now experimental support for the Windows 8 Metro interface in [http://nightly.mozilla.org/ Firefox Nightly]. If you are technical, we would love your help testing the Windows 8 Metro support in Firefox Nightly. More info can be found in the [https://wiki.mozilla.org/Firefox/Windows_8_Integration Firefox Windows 8 Integration page on the Mozilla wiki].

= Does Firefox work on Windows RT? =
Currently, there is no version of Firefox for Windows RT.
{/for}','<p>Windows 8/RT was just released by Microsoft. This article will answer to some questions you could have if you have planned to upgrade your OS to Windows 8, buy a brand new computer on Windows 8 or a tablet (e.g. Surface) on Windows RT.
</p><div class="for" data-for="mac,linux">
<div class="note"><strong>Note:</strong> This article only applies to Windows. To see instructions, choose any Windows version from the dropdown menu above.</div>
</div><div class="for" data-for="win" style="display: none;">
<div id="toc"><h2>Table of Contents</h2><ul><span class="for" data-for="win" style="display: none;"><li class="toclevel-1"><a href="#w_does-firefox-work-in-the-windows-8-desktop-view"><span class="tocnumber">1</span> <span class="toctext">Does Firefox work in the Windows 8 desktop view?</span></a></li></span><span class="for" data-for="win" style="display: none;"><li class="toclevel-1"><a href="#w_does-firefox-work-in-the-windows-8-metro-interface"><span class="tocnumber">2</span> <span class="toctext">Does Firefox work in the Windows 8 Metro interface?</span></a></li></span><span class="for" data-for="win" style="display: none;"><li class="toclevel-1"><a href="#w_does-firefox-work-on-windows-rt"><span class="tocnumber">3</span> <span class="toctext">Does Firefox work on Windows RT?</span></a></li></span></ul></div>
<h1 id="w_does-firefox-work-in-the-windows-8-desktop-view">Does Firefox work in the Windows 8 desktop view?</h1>
<p>Firefox 17 is the first version that officially supports Windows 8 in the desktop view although the previous versions of Firefox should work without major issues. See <a href="http://www.mozilla.org/firefox/17.0/system-requirements/">Firefox&nbsp;17 system requirements</a> for more details.
</p>
<h1 id="w_does-firefox-work-in-the-windows-8-metro-interface">Does Firefox work in the Windows 8 Metro interface?</h1>
<p>There is now experimental support for the Windows 8 Metro interface in <a href="http://nightly.mozilla.org/">Firefox Nightly</a>. If you are technical, we would love your help testing the Windows 8 Metro support in Firefox Nightly. More info can be found in the <a href="https://wiki.mozilla.org/Firefox/Windows_8_Integration">Firefox Windows&nbsp;8 Integration page on the Mozilla wiki</a>.
</p>
<h1 id="w_does-firefox-work-on-windows-rt">Does Firefox work on Windows RT?</h1>
<p>Currently, there is no version of Firefox for Windows RT.
</p></div>','[{"label": "Revision id", "text": "36537", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 13, 2013, 4:19:27 AM", "datetime": "2013-02-13T04:19:27-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "updating article now that Metro UI is supported in Nightly! DO NOT APPROVE until nightly is available which should be about 3p.m. pacific 13Feb2013", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 13, 2013, 9:32:49 AM", "datetime": "2013-02-13T09:32:49-08:00", "href": null}, {"label": "Reviewed by", "text": "Verdi", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:50:16+00:00');
