INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (36857,'en-US','make-firefox-default-browser-android','Set Firefox as your default browser on Android','https://support.mozilla.org/en-US/kb/make-firefox-default-browser-android','https://support.mozilla.org/en-US/kb/make-firefox-default-browser-android/revision/36857',36540,'2013-02-20T13:41:41-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','Thanks to Tonnes for pointing out that you have to tap "Manage Applications" before tabs appear',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','This article explains how to make links on your Android device open in Firefox.
__TOC__
=Step 1: Clear the current browser that opens links=
# Open the Settings application and tap on {button Apps}. (On some versions of Android this button is labelled "Applications" and you will have to tap on {button Manage Applications} before the next step.)
# Tap on the {button All} tab.<br/><br/>[[Image:Android ICS Manage Apps - Cropped just showing stock]]
# Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
# Tap on {button Clear defaults} to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another browser or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser. 
[[Image:Android ICS Clear defaults - Cropped]]

=Step 2: Set Firefox to be the default browser for opening links=
# Open a link in an Android application like the Mail application.
# Tap on {button Firefox} and then tap on {button Always}.
[[Image:Android ICS Complete Action using Firefox Always just showing stock and ff]]','<p>This article explains how to make links on your Android device open in Firefox.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_step-1-clear-the-current-browser-that-opens-links"><span class="tocnumber">1</span> <span class="toctext">Step 1: Clear the current browser that opens links</span></a></li><li class="toclevel-1"><a href="#w_step-2-set-firefox-to-be-the-default-browser-for-opening-links"><span class="tocnumber">2</span> <span class="toctext">Step 2: Set Firefox to be the default browser for opening links</span></a></li></ul></div>
<h1 id="w_step-1-clear-the-current-browser-that-opens-links">Step 1: Clear the current browser that opens links</h1>
<ol><li> Open the Settings application and tap on <span class="button">Apps</span>. (On some versions of Android this button is labelled "Applications" and you will have to tap on <span class="button">Manage Applications</span> before the next step.)
</li><li> Tap on the <span class="button">All</span> tab.<br><br><img alt="Android ICS Manage Apps - Cropped just showing stock" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-12-11-59-02-8caa08.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
</li><li> Tap on <span class="button">Clear defaults</span> to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another browser or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser. 
</li></ol>
<p><img alt="Android ICS Clear defaults - Cropped" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-03-22-30-33-ca626d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<h1 id="w_step-2-set-firefox-to-be-the-default-browser-for-opening-links">Step 2: Set Firefox to be the default browser for opening links</h1>
<ol><li> Open a link in an Android application like the Mail application.
</li><li> Tap on <span class="button">Firefox</span> and then tap on <span class="button">Always</span>.
</li></ol>
<p><img alt="Android ICS Complete Action using Firefox Always just showing stock and ff" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-12-11-58-00-a88b4f.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>','[{"label": "Revision id", "text": "36857", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 20, 2013, 1:41:41 PM", "datetime": "2013-02-20T13:41:41-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "Thanks to Tonnes for pointing out that you have to tap \"Manage Applications\" before tabs appear", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:49:59+00:00');
