INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (37257,'en-US','using-dark-theme-firefox-android','Using Dark Theme in Firefox for Android','https://support.mozilla.org/en-US/kb/using-dark-theme-firefox-android','https://support.mozilla.org/en-US/kb/using-dark-theme-firefox-android/revision/37257',NULL,'2013-03-05T14:39:33-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','work in progress, please DO NOT APPROVE, needs screenshots',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','A theme is a simple type of Firefox add-on which allows you to customize your browser skin. This article describes how to find, install, and manage  themes Firefox for Android themes.

__TOC__

= What are themes? =

Firefox for Android themes allow changing of color scheme and background image of the Firefox toolbars

= How to install themes =
You can access the Android themes from the settings menu inside Firefox for Android:
#Tap the menu {button Menu} button (on some phones this is a hardware button, on others it is a soft menu in the top right) and then tap {button Tools} and tap {button Add-ons}.
#Tap the orange {button Folder} icon in the upper-right of the Add-ons screen. Alternatively you could go directly to https://addons.mozilla.org/android/ to achieve the same result.
#Tap on the  {button Themes} tab to see available themes.
#You will see ''''''Featured'''''' themes. You can search for themes or tap on the {button Popular}{/for} or {button Categories}{/for} tabs to find a theme you would like to try
# To try out a theme, simply tap on the theme''s graphic; Firefox will display ''''''"You''re trying it on!"''''''. To learn more about a theme, tap {button Theme Info}. 
# Install the theme you want by tapping {button Keep it}. Firefox will confirm the theme is installed by displaying ''''''"Added to Firefox"''''''.

= Managing themes =
== How to switch themes ==
To switch themes, simply follow the instructions for ''''''How to install Themes'''''' above and install another theme.

== How to remove a theme ==
If you wnat to go back to the default Firefox for Android theme, uninstall the current theme add-on:
#Tap the menu {button Menu} button (on some phones this is a hardware button, on others it is a soft menu in the top right) and then tap {button Tools}and tap {button Add-ons}.
# Tap on the add-on for the current theme  and then tap on {button Uninstall}
# The theme will be removed.
# Repeat the above for all theme','<p>A theme is a simple type of Firefox add-on which allows you to customize your browser skin. This article describes how to find, install, and manage  themes Firefox for Android themes.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_what-are-themes"><span class="tocnumber">1</span> <span class="toctext">What are themes?</span></a></li><li class="toclevel-1"><a href="#w_how-to-install-themes"><span class="tocnumber">2</span> <span class="toctext">How to install themes</span></a></li><li class="toclevel-1"><a href="#w_managing-themes"><span class="tocnumber">3</span> <span class="toctext">Managing themes</span></a><ul><li class="toclevel-2"><a href="#w_how-to-switch-themes"><span class="tocnumber">3.1</span> <span class="toctext">How to switch themes</span></a></li><li class="toclevel-2"><a href="#w_how-to-remove-a-theme"><span class="tocnumber">3.2</span> <span class="toctext">How to remove a theme</span></a></li></ul></li></ul></div>
<h1 id="w_what-are-themes">What are themes?</h1>
<p>Firefox for Android themes allow changing of color scheme and background image of the Firefox toolbars
</p>
<h1 id="w_how-to-install-themes">How to install themes</h1>
<p>You can access the Android themes from the settings menu inside Firefox for Android:
</p>
<ol><li>Tap the menu <span class="button">Menu</span> button (on some phones this is a hardware button, on others it is a soft menu in the top right) and then tap <span class="button">Tools</span> and tap <span class="button">Add-ons</span>.
</li><li>Tap the orange <span class="button">Folder</span> icon in the upper-right of the Add-ons screen. Alternatively you could go directly to <a href="https://addons.mozilla.org/android/">https://addons.mozilla.org/android/</a> to achieve the same result.
</li><li>Tap on the  <span class="button">Themes</span> tab to see available themes.
</li><li>You will see <strong>Featured</strong> themes. You can search for themes or tap on the <span class="button">Popular</span> or <span class="button">Categories</span> tabs to find a theme you would like to try
</li><li> To try out a theme, simply tap on the theme''s graphic; Firefox will display <strong>"You''re trying it on!"</strong>. To learn more about a theme, tap <span class="button">Theme Info</span>. 
</li><li> Install the theme you want by tapping <span class="button">Keep it</span>. Firefox will confirm the theme is installed by displaying <strong>"Added to Firefox"</strong>.
</li></ol>
<h1 id="w_managing-themes">Managing themes</h1>
<h2 id="w_how-to-switch-themes">How to switch themes</h2>
<p>To switch themes, simply follow the instructions for <strong>How to install Themes</strong> above and install another theme.
</p>
<h2 id="w_how-to-remove-a-theme">How to remove a theme</h2>
<p>If you wnat to go back to the default Firefox for Android theme, uninstall the current theme add-on:
</p>
<ol><li>Tap the menu <span class="button">Menu</span> button (on some phones this is a hardware button, on others it is a soft menu in the top right) and then tap <span class="button">Tools</span>and tap <span class="button">Add-ons</span>.
</li><li> Tap on the add-on for the current theme  and then tap on <span class="button">Uninstall</span>
</li><li> The theme will be removed.
</li><li> Repeat the above for all theme
</li></ol>','[{"label": "Revision id", "text": "37257", "datetime": null, "href": null}, {"label": "Created", "text": "Mar 5, 2013, 2:39:33 PM", "datetime": "2013-03-05T14:39:33-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "work in progress, please DO NOT APPROVE, needs screenshots", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:49:55+00:00');
