INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (37840,'en-US','will-firefox-work-my-mobile-device','Will Firefox work on my mobile device?','https://support.mozilla.org/en-US/kb/will-firefox-work-my-mobile-device','https://support.mozilla.org/en-US/kb/will-firefox-work-my-mobile-device/revision/37840',37595,'2013-03-19T07:40:51-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','add in QVGA, i.e. 320 wide by 420 pixels high note',1,'2013-03-19T07:41:49-07:00','rtanglao',1,0,1,'2013-03-19T07:41:49-07:00','rtanglao','approved','{for fx19} {for not fx20} Firefox is compatible with Android 2.2 and above devices. Installation requires about 16 MB internal storage and 512 MB of RAM. You can [http://www.mozilla.org/mobile download Firefox for Android] or search for Firefox in the Google Play store. {/for}

{for fx20} Firefox is compatible with Android 2.2 and above devices. Installation requires about 16 MB internal storage and 384 MB of RAM and a display that is at least 320 pixels wide and 240 pixels high. You can [http://www.mozilla.org/mobile download Firefox for Android] or search for Firefox in the Google Play store.{/for}


{warning}''''''Important:'''''' Some of the devices listed here only work with the latest version of Firefox. If you search for Firefox in the Google Play store and don''t find it, your device may not be compatible.{/warning}
__TOC__

= Phones =
<!-- URL to edit the template: https://support.mozilla.org/en-US/kb/templatetestedphones/edit -->
[[Template:testedphones]]

= Tablets =
<!-- URL to edit the template: https://support.mozilla.org/en-US/kb/templatetestedtablets/edit --> 
[[Template:testedtablets]]

= Other Operating Systems =
Firefox is ''''''NOT'''''' available for iOS (iPhone, iPad, iPod Touch), Windows Phone, Windows RT, Bada, Symbian, Blackberry OS, webOS, Android-x86 or other operating systems for mobile.


[[Template:ShareArticle|link=http://mzl.la/Ll6Mfq]]','<p><span class="for" data-for="fx19"> <span class="for" data-for="not fx20"> Firefox is compatible with Android 2.2 and above devices. Installation requires about 16 MB internal storage and 512 MB of RAM. You can <a href="http://www.mozilla.org/mobile">download Firefox for Android</a> or search for Firefox in the Google Play store. </span>
</span></p><p><span class="for" data-for="fx20"> Firefox is compatible with Android 2.2 and above devices. Installation requires about 16 MB internal storage and 384 MB of RAM and a display that is at least 320 pixels wide and 240 pixels high. You can <a href="http://www.mozilla.org/mobile">download Firefox for Android</a> or search for Firefox in the Google Play store.</span>
</p><p><br>
</p>
<div class="warning"><strong>Important:</strong> Some of the devices listed here only work with the latest version of Firefox. If you search for Firefox in the Google Play store and don''t find it, your device may not be compatible.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_phones"><span class="tocnumber">1</span> <span class="toctext">Phones</span></a></li><li class="toclevel-1"><a href="#w_tablets"><span class="tocnumber">2</span> <span class="toctext">Tablets</span></a></li><li class="toclevel-1"><a href="#w_other-operating-systems"><span class="tocnumber">3</span> <span class="toctext">Other Operating Systems</span></a></li></ul></div>
<h1 id="w_phones">Phones</h1>
<p>
</p><h2 id="w_acer">Acer</h2>
<ul><li>Acer Liquid mini E310
</li><li>Acer Liquid C1
</li></ul>
