</p>','[{"label": "Revision id", "text": "38412", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 3, 2013, 3:58:18 AM", "datetime": "2013-04-03T03:58:18-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "change home page to start screen as per feedback from Michael Verdi", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Apr 3, 2013, 3:58:40 AM", "datetime": "2013-04-03T03:58:40-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Apr 3, 2013, 3:58:40 AM", "datetime": "2013-04-03T03:58:40-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:48:58+00:00');
