INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (38717,'en-US','how-does-firefox-android-provide-secure-mobile-bro-redirect-1','How does Firefox for Android Provide Secure Mobile Browsing','https://support.mozilla.org/en-US/kb/how-does-firefox-android-provide-secure-mobile-bro-redirect-1','https://support.mozilla.org/en-US/kb/how-does-firefox-android-provide-secure-mobile-bro-redirect-1/revision/38717',NULL,'2013-04-09T14:25:32-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','REDIRECT [[How does Firefox for Android Provide Secure Mobile Browsing?]]','<p>REDIRECT <a href="/en-US/kb/how-does-firefox-android-provide-secure-mobile-bro">How does Firefox for Android Provide Secure Mobile Browsing?</a>
</p>','[{"label": "Revision id", "text": "38717", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 9, 2013, 2:25:32 PM", "datetime": "2013-04-09T14:25:32-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:48:22+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (39076,'en-US','firefox-android-crashes-startup-how-fix','Firefox for Android Crashes On Startup - How To Fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix','https://support.mozilla.org/en-US/kb/firefox-android-crashes-startup-how-fix/revision/39076',36771,'2013-04-18T02:23:43-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','removing reference to 18. As of this writing FF 20 is released and it has the lowest crash levels ever.',1,'2013-04-18T02:24:17-07:00','rtanglao',1,1,0,NULL,NULL,'approved','Please update to the latest release of Firefox to fix this issue. The development team has added some fixes which have reduced the crash rate to the lowest levels ever.

=Automatically update Firefox=
If you have set Firefox to allow automatic updating, here''s how to update:
# Open the Google Play Store application.
# Firefox will start  updating automatically.
=Manually update Firefox=
If you have set Firefox for manual updating:
# Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br /><br />[[Image:ICS - Android - Tapping Search icon in Google Play]]
# Type "Firefox" and tap on the magnifying glass search icon.
# Tap on {button Firefox} and then tap on {button Update}.

[[T:ShareArticle|link=http://mzl.la/138ymzG]]','<p>Please update to the latest release of Firefox to fix this issue. The development team has added some fixes which have reduced the crash rate to the lowest levels ever.
</p>
<h1 id="w_automatically-update-firefox">Automatically update Firefox</h1>
<p>If you have set Firefox to allow automatic updating, here''s how to update:
</p>
<ol><li> Open the Google Play Store application.
</li><li> Firefox will start  updating automatically.
</li></ol>
<h1 id="w_manually-update-firefox">Manually update Firefox</h1>
<p>If you have set Firefox for manual updating:
</p>
<ol><li> Open the Google Play Store application and tap on the search icon which looks like a magnifying glass. <br><br><img alt="ICS - Android - Tapping Search icon in Google Play" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-06-15-09-30-26d046.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Type "Firefox" and tap on the magnifying glass search icon.
</li><li> Tap on <span class="button">Firefox</span> and then tap on <span class="button">Update</span>.
</li></ol>
<p>&nbsp;

</p>','[{"label": "Revision id", "text": "39076", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 18, 2013, 2:23:43 AM", "datetime": "2013-04-18T02:23:43-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "removing reference to 18. As of this writing FF 20 is released and it has the lowest crash levels ever.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Apr 18, 2013, 2:24:17 AM", "datetime": "2013-04-18T02:24:17-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:48:20+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (39151,'en-US','send-and-manage-email','Send and manage email','https://support.mozilla.org/en-US/kb/send-and-manage-email','https://support.mozilla.org/en-US/kb/send-and-manage-email/revision/39151',38655,'2013-04-19T04:30:09-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','tap the "create message" icon instead of "+" to create a new message',1,'2013-04-19T04:30:35-07:00','rtanglao',1,0,0,NULL,NULL,'approved','= Composing and Sending Emails =
{note}Before you start sending emails make sure your email account is set up.  See [[Add a new email account to Firefox OS]] for help if needed.{/note}

# To open the email application, tap the [[Image:email]] icon.
# Tap the [[Image:Create Message Icon]] create message icon to compose a new message.
# You will then be presented with this screen: <br> [[Image:Compose message]]
# Enter recipients in the ''''To'''' and/or ''''cc/bcc'''' field. You can do this in 3 different ways:
#* Tap [[Image:add icon]] to see your contacts and select them as well. 
#* Enter a full email address. (eg. 123@mozilla.org) 
#* Enter part of an email address or name and tap [[Image:add icon]]. Matching contacts will be presented to select from. <br> <br>
# Enter your email ''''Subject'''' and text in the fields below.
# Tap the {button Send} button to send your email.

[[Template:ShareArticle|link=http://mzl.la/12PunHT]]','<h1 id="w_composing-and-sending-emails">Composing and Sending Emails</h1>
<div class="note">Before you start sending emails make sure your email account is set up.  See <a href="/en-US/kb/add-email-accounts">Add email accounts</a> for help if needed.</div>
<ol><li> To open the email application, tap the <img alt="email" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-01-13-03-08-0c83f5.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> icon.
</li><li> Tap the <img alt="Create Message Icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-04-21-08-25-eba4c9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> create message icon to compose a new message.
</li><li> You will then be presented with this screen: <br> <img alt="Compose message" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-04-07-17-53-24-7c3f9d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> Enter recipients in the <em>To</em> and/or <em>cc/bcc</em> field. You can do this in 3 different ways:
<ul><li> Tap <img alt="add icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-08-57-8cef3c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> to see your contacts and select them as well. 
</li><li> Enter a full email address. (eg. <a href="mailto:123@mozilla.org">123@mozilla.org</a>) 
</li><li> Enter part of an email address or name and tap <img alt="add icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-08-57-8cef3c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">. Matching contacts will be presented to select from. <br> <br>
</li></ul>
</li><li> Enter your email <em>Subject</em> and text in the fields below.
</li><li> Tap the <span class="button">Send</span> button to send your email.
</li></ol>
<p>&nbsp;

</p>','[{"label": "Revision id", "text": "39151", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 19, 2013, 4:30:09 AM", "datetime": "2013-04-19T04:30:09-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "tap the \"create message\" icon instead of \"+\" to create a new message", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Apr 19, 2013, 4:30:35 AM", "datetime": "2013-04-19T04:30:35-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:48:11+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (41420,'en-US','record-videos','Record Videos','https://support.mozilla.org/en-US/kb/record-videos','https://support.mozilla.org/en-US/kb/record-videos/revision/41420',NULL,'2013-06-12T16:50:49-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','work in progress - needs feedback from Michael Verdi or Michelle Luna, do not approve',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','==How To Record Videos ==

# To open the camera app, tap [[Image:camera app]]. <!-- Add in a future revision of this article: screenshot of camera app viewfinder -->
# If you do not see the video icon ([[Image:video]]) highlighted in blue then you are in photo mode. Tap the video icon, [[Image:video]], to change the camera app to video mode. Here''s a screenshot that shows the camera app''s video mode:<br /><br />[[Image:video mode]]<br/><br/>
# Position your camera to what needs to be taken and then tap the video icon [[Image:video]] to start recording. When you are done, tap it again to stop recording.
#:{note} You might see a screen asking if you want to allow geolocation, select Allow to add this information to your videos and photos. Go to Settings > App Permissions > Camera to adjust the Geolocation setting for your camera app.{/note}
# Your video should now be captured and a thumbnail of the video will be displayed for half a second. If you want to share or delete this video, tap on the video thumbnail.

{note} Note: You can always delete or share videos later from the gallery.{/note}

<!--
[[Template:ShareArticle|link=http://mzl.la/11MRLLe]]
-->','<h2 id="w_how-to-record-videos">How To Record Videos</h2>
<ol><li> To open the camera app, tap <img alt="camera app" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-17-06-cae5d0.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">. 
</li><li> If you do not see the video icon (<img alt="video" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-03-52-8437aa.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">) highlighted in blue then you are in photo mode. Tap the video icon, <img alt="video" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-03-52-8437aa.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">, to change the camera app to video mode. Here''s a screenshot that shows the camera app''s video mode:<br><br><img alt="video mode" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-06-12-23-48-59-c4010d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</li><li> Position your camera to what needs to be taken and then tap the video icon <img alt="video" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-03-52-8437aa.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> to start recording. When you are done, tap it again to stop recording.
<dl><dd><div class="note"> You might see a screen asking if you want to allow geolocation, select Allow to add this information to your videos and photos. Go to Settings &gt; App Permissions &gt; Camera to adjust the Geolocation setting for your camera app.</div>
</dd></dl>
</li><li> Your video should now be captured and a thumbnail of the video will be displayed for half a second. If you want to share or delete this video, tap on the video thumbnail.
</li></ol>
<div class="note"> Note: You can always delete or share videos later from the gallery.</div>
<p>
</p>','[{"label": "Revision id", "text": "41420", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 12, 2013, 4:50:49 PM", "datetime": "2013-06-12T16:50:49-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "work in progress - needs feedback from Michael Verdi or Michelle Luna, do not approve", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:48:09+00:00');
