INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (41462,'en-US','manage-photo-and-video-gallery','Manage photo and video gallery','https://support.mozilla.org/en-US/kb/manage-photo-and-video-gallery','https://support.mozilla.org/en-US/kb/manage-photo-and-video-gallery/revision/41462',40541,'2013-06-13T16:10:59-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','DO NOT APPROVE PLEASE - requires feedback from Michelle Luna or Michael Verdi',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','__TOC__

=How to view picture and videos=
# To open the Gallery application, tap [[Image:gallery]].
# The Gallery application with your pictures and videos will be shown in a grid view. 
# Tap on a picture or video to view it in full size. 
# Swipe left to view the previous picture or video, or swipe right to view the next picture or video. <br> {note} If you reach a certain point where you are not able to swipe anymore, it means you have reached the first item or the last item in the gallery.{/note}
# To return to the grid view, tap [[Image: Grid Icon in FxOS Gallery]].

{note}''''''Tip:'''''' You can also launch the camera from the Gallery by tapping [[Image:camera]].{/note}

=Deleting Pictures and Videos=
There are two ways to delete pictures and videos:

==Deleting a Single Picture or Video==
# Open the picture or video and tap [[Image: Gallery delete icon in Firefox OS]].
# Tap {button OK} to confirm the deletion. 

==Deleting Multiple Pictures and Videos ==
# Tap [[Image: Multiple select icon in Firefox OS]].
# Tap the pictures and videos you wish to delete. Selected pictures and videos will have a blue border around them. Tapping on it again will deselect it.
# Tap [[Image: Gallery delete icon in Firefox OS]].
# Tap {button OK} to confirm your deletion.

{note} ''''''Important'''''': Once a picture or video is deleted, it CANNOT be recovered.{/note}

=Editing Pictures and Videos =
{note} Currently you can only edit pictures.{/note}
# Tap the picture you want to edit.
# Tap [[Image:edit icon]]. From here, you can edit the exposure, add effects, borders and crop the picture.

=How To Share Pictures and Videos =
# Tap the picture or video you want to share.
# Tap [[Image:share]].
# Choose how you would like to share the picture or video.
# The relevant application will open, and your picture or video will be ready to share.
[[T:ShareArticle|link=http://mzl.la/17wMiaA]]','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-to-view-picture-and-videos"><span class="tocnumber">1</span> <span class="toctext">How to view picture and videos</span></a></li><li class="toclevel-1"><a href="#w_deleting-pictures-and-videos"><span class="tocnumber">2</span> <span class="toctext">Deleting Pictures and Videos</span></a><ul><li class="toclevel-2"><a href="#w_deleting-a-single-picture-or-video"><span class="tocnumber">2.1</span> <span class="toctext">Deleting a Single Picture or Video</span></a></li><li class="toclevel-2"><a href="#w_deleting-multiple-pictures-and-videos"><span class="tocnumber">2.2</span> <span class="toctext">Deleting Multiple Pictures and Videos</span></a></li></ul></li><li class="toclevel-1"><a href="#w_editing-pictures-and-videos"><span class="tocnumber">3</span> <span class="toctext">Editing Pictures and Videos</span></a></li><li class="toclevel-1"><a href="#w_how-to-share-pictures-and-videos"><span class="tocnumber">4</span> <span class="toctext">How To Share Pictures and Videos</span></a></li></ul></div>
<h1 id="w_how-to-view-picture-and-videos">How to view picture and videos</h1>
<ol><li> To open the Gallery application, tap <img alt="gallery" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-10-21-08-13-07-2767cc.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> The Gallery application with your pictures and videos will be shown in a grid view. 
</li><li> Tap on a picture or video to view it in full size. 
</li><li> Swipe left to view the previous picture or video, or swipe right to view the next picture or video. <br> <div class="note"> If you reach a certain point where you are not able to swipe anymore, it means you have reached the first item or the last item in the gallery.</div>
</li><li> To return to the grid view, tap <img alt="Grid Icon in FxOS Gallery" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-04-16-13-25-40-d28922.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li></ol>
<div class="note"><strong>Tip:</strong> You can also launch the camera from the Gallery by tapping <img alt="camera" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-04-09-702338.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.</div>
<h1 id="w_deleting-pictures-and-videos">Deleting Pictures and Videos</h1>
<p>There are two ways to delete pictures and videos:
</p>
<h2 id="w_deleting-a-single-picture-or-video">Deleting a Single Picture or Video</h2>
<ol><li> Open the picture or video and tap <img alt="Gallery delete icon in Firefox OS" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-04-16-14-00-30-6239b9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> Tap <span class="button">OK</span> to confirm the deletion. 
</li></ol>
<h2 id="w_deleting-multiple-pictures-and-videos">Deleting Multiple Pictures and Videos</h2>
<ol><li> Tap <img alt="Multiple select icon in Firefox OS" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-04-16-13-47-47-8bb87c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> Tap the pictures and videos you wish to delete. Selected pictures and videos will have a blue border around them. Tapping on it again will deselect it.
</li><li> Tap <img alt="Gallery delete icon in Firefox OS" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-04-16-14-00-30-6239b9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> Tap <span class="button">OK</span> to confirm your deletion.
</li></ol>
<div class="note"> <strong>Important</strong>: Once a picture or video is deleted, it CANNOT be recovered.</div>
<h1 id="w_editing-pictures-and-videos">Editing Pictures and Videos</h1>
<div class="note"> Currently you can only edit pictures.</div>
<ol><li> Tap the picture you want to edit.
</li><li> Tap <img alt="edit icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-03-25-eabe76.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">. From here, you can edit the exposure, add effects, borders and crop the picture.
</li></ol>
<h1 id="w_how-to-share-pictures-and-videos">How To Share Pictures and Videos</h1>
<ol><li> Tap the picture or video you want to share.
</li><li> Tap <img alt="share" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-09-19-16-10-33-53a09a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> Choose how you would like to share the picture or video.
</li><li> The relevant application will open, and your picture or video will be ready to share.
</li></ol>
<p>&nbsp;

</p>','[{"label": "Revision id", "text": "41462", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 13, 2013, 4:10:59 PM", "datetime": "2013-06-13T16:10:59-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "DO NOT APPROVE PLEASE - requires feedback from Michelle Luna or Michael Verdi", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:48:04+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (41610,'en-US','firefox-health-report-understand-your-android-browser-perf','Firefox Health Report - understand your Android browser performance','https://support.mozilla.org/en-US/kb/firefox-health-report-understand-your-android-browser-perf','https://support.mozilla.org/en-US/kb/firefox-health-report-understand-your-android-browser-perf/revision/41610',NULL,'2013-06-19T16:06:36-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','first version, do not change the category because we don''t want it to show up in the IA until FF23 beta is out!',1,'2013-06-19T16:07:58-07:00','rtanglao',1,0,0,NULL,NULL,'approved','The Firefox Health Report (FHR) provides insights and performance information about your browser.  By analysing your browser’s performance information, FHR is able to provide you with useful tips that help you get the best from Firefox. For more information about how we handle your data, see our privacy policy (''''''LINK'''''')

{for not m23}
[[Template:ApplytoFx|channel=beta|slug=mobile/beta]]
{/for}

__TOC__
=How to view your Firefox Health Report=
#Tap the {button Menu} button [[Template:AndroidMenuLocation]].
#Tap {button Settings}.
#Tap {button Data choices}.
#Tap on the {button Firefox Health Report} link to view the Firefox Health Report.
<!--
{note}''''''Note:'''''' If you have just installed Firefox, the information in the Health Report may not be accurate. It typically takes 14 days of browser use to see any trends.{/note}
-->

=How to turn data sharing on or off=
Data sharing is on by default but you can always turn it on or off:
#Tap the {button Menu} button [[Template:AndroidMenuLocation]].
#Tap {button Settings}.
#Tap {button Data choices}.
#Check or uncheck the box next to ''''''Firefoxh Health Report''''''


When you turn sharing off, Firefox will stop sending information about your browser to Mozilla servers. Firefox will send a request to the Mozilla servers to delete the previously submitted information.  This request is processed immediately after being successfully received.  If the browser does not receive a response that the request was succesfully processed (due to lack of internet connectivity for instance), the browser will continue to send the delete request periodically until it is successfully received.

If  you do not turn sharing off, but the browser is no longer sending data (due to being uninstalled or no longer being used), the previously sent data from your browser will be deleted after 180 days.

Even if you choose not to share data with Mozilla, you will still see be able to see information about your browser when you go to the Firefox Health Report page, and you can view the comparison data from other browsers that are sharing their data.  The comparison data will not be based on the data from your browser since it was not shared with Mozilla.

<!--
=What is the Startup Time graph?=
The ''''''Startup Time by Day'''''' graph shows how long it took your browser to start on any given day. The default view (Average), shows the median startup time for that day. Clicking on the “All” toggle shows all the startup times for the day. You can see up to 90 days of data on the graph.

=How do I view the raw data collected?=
You can view a text file of the data that Firefox Health Report collects by clicking on the ''''''Raw Data'''''' tab. This display shows the exact data that is being sent to Mozilla (if sharing is on).
-->
<!-- =Who owns the data collected?=
You own all data collected by FHR. You can delete it anytime by going to _____ and by pressing the delete button. After information is sent to Mozilla’s servers, it stays there for 180 days and is automatically deleted after that. -->
=What data is shared with Mozilla?=

The ''''''Important Metrics'''''' section in the Firefox Health Report has all the data that is shared with Mozilla. To look at the exact data being shared with Mozilla, tap on the {button what you share with Mozilla}{/for} link under the ''''''Important Metrics'''''' section.

<!-- commenting this out for now because the url might change
[[Template:ShareArticle|link=http://mzl.la/171LPjo]]
-->','<p>The Firefox Health Report (FHR) provides insights and performance information about your browser.  By analysing your browser’s performance information, FHR is able to provide you with useful tips that help you get the best from Firefox. For more information about how we handle your data, see our privacy policy (<strong>LINK</strong>)
</p><div class="for" data-for="not m23"><p></p><div class="note"><strong>Note:</strong> This applies to the latest Firefox beta version which can be downloaded from <a href="http://www.mozilla.org/mobile/beta">mozilla.org/mobile/beta</a>.</div>
<p></p></div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-to-view-your-firefox-health-report"><span class="tocnumber">1</span> <span class="toctext">How to view your Firefox Health Report</span></a></li><li class="toclevel-1"><a href="#w_how-to-turn-data-sharing-on-or-off"><span class="tocnumber">2</span> <span class="toctext">How to turn data sharing on or off</span></a></li><li class="toclevel-1"><a href="#w_what-data-is-shared-with-mozilla"><span class="tocnumber">3</span> <span class="toctext">What data is shared with Mozilla?</span></a></li></ul></div>
<h1 id="w_how-to-view-your-firefox-health-report">How to view your Firefox Health Report</h1>
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
.
</li><li>Tap <span class="button">Settings</span>.
</li><li>Tap <span class="button">Data choices</span>.
</li><li>Tap on the <span class="button">Firefox Health Report</span> link to view the Firefox Health Report.
</li></ol>
<p>
</p>
<h1 id="w_how-to-turn-data-sharing-on-or-off">How to turn data sharing on or off</h1>
<p>Data sharing is on by default but you can always turn it on or off:
</p>
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
.
</li><li>Tap <span class="button">Settings</span>.
</li><li>Tap <span class="button">Data choices</span>.
</li><li>Check or uncheck the box next to <strong>Firefoxh Health Report</strong>
</li></ol>
<p><br>
When you turn sharing off, Firefox will stop sending information about your browser to Mozilla servers. Firefox will send a request to the Mozilla servers to delete the previously submitted information.  This request is processed immediately after being successfully received.  If the browser does not receive a response that the request was succesfully processed (due to lack of internet connectivity for instance), the browser will continue to send the delete request periodically until it is successfully received.
</p><p>If  you do not turn sharing off, but the browser is no longer sending data (due to being uninstalled or no longer being used), the previously sent data from your browser will be deleted after 180 days.
</p><p>Even if you choose not to share data with Mozilla, you will still see be able to see information about your browser when you go to the Firefox Health Report page, and you can view the comparison data from other browsers that are sharing their data.  The comparison data will not be based on the data from your browser since it was not shared with Mozilla.
</p><p>

</p>
<h1 id="w_what-data-is-shared-with-mozilla">What data is shared with Mozilla?</h1>
<p>The <strong>Important Metrics</strong> section in the Firefox Health Report has all the data that is shared with Mozilla. To look at the exact data being shared with Mozilla, tap on the <span class="button">what you share with Mozilla</span> link under the <strong>Important Metrics</strong> section.
</p><p>
