INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (50773,'en-US','install-older-version-firefox','Install an older version of Firefox','https://support.mozilla.org/en-US/kb/install-older-version-firefox','https://support.mozilla.org/en-US/kb/install-older-version-firefox/revision/50773',49881,'2013-11-18T07:02:23-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','as per https://bugzilla.mozilla.org/show_bug.cgi?id=939785 need to change directory listing urls  to use the ftp server',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Often when there is a problem with a Firefox update, people look for a way to go back to the previous version. That usually doesn''t solve the problem and will make your computer and information vulnerable to attack. This article gives you some alternatives to downgrading and links to old versions of Firefox if you do choose to downgrade.

= Installing a previous version doesn''t fix most problems=
Problems with an update are generally not caused by the new version of Firefox, but rather the update process. Installing a previous version will not help in most cases. Instead, see:
[[Template:UpdateProblems]]

{for not fx13}
Other problems can be solved by [[Use the Profile Manager to create and remove Firefox profiles#w_creating-a-profile|creating a new profile]] or by following the steps in the [[Troubleshoot and diagnose Firefox problems]] article. 
{/for}
{for fx13}
Other problems can be solved with [[Reset Firefox – easily fix most problems|the Reset Firefox feature]]. It restores Firefox to its factory default state while saving your essential information.
{/for} 

= I still want to downgrade — where can I get the previous version? =
Although Mozilla has a [https://ftp.mozilla.org/pub/mozilla.org/firefox/releases/ website] with old versions of Firefox for testing purposes, it is not recommended that you use anything but the latest version. {warning}''''''Warning:'''''' Using old versions of Firefox poses a significant security risk.{/warning}
