INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (52092,'en-US','using-master-password-firefox-android','Using Master Password on Firefox for Android','https://support.mozilla.org/en-US/kb/using-master-password-firefox-android','https://support.mozilla.org/en-US/kb/using-master-password-firefox-android/revision/52092',52088,'2013-12-20T05:04:47-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fix remove master password section by adding firefox 25 and above and firefox 24 and below instructions',1,'2013-12-20T05:05:11-08:00','rtanglao',1,0,1,'2013-12-20T05:05:11-08:00','rtanglao','approved','Firefox can save usernames and passwords that you use to access online services, such as banking and email. In order to prevent someone else from accessing your accounts if they have your device, you can set a master password. This article explains how to use a master password.
;[[Image:master_password0-ics]]

__TOC__

= How does the master password work?=
After you have defined a master password, you will be prompted to enter it when Firefox needs to access your stored passwords. This will "unlock" the usernames and passwords that you''ve saved and Firefox will automatically fill them in for you as you browse from website to website. When you are done using the web, you can quit Firefox to "lock up" your usernames and passwords.
{note}''''''Note:'''''' The Android system on your device may quit Firefox automatically to free up resources when you are using another app. If that happens, you''ll be asked to enter your master password again when you switch back to Firefox.{/note}

= How do I set up a master password? =
By default, Firefox doesn''t use a master password to protect your saved usernames and passwords. To set one up:
{for not m25}
#Tap the {button Menu} button [[Template:AndroidMenuLocation]] and then {button Settings} [[Template:AndroidMore]].
# Tap the {button Use master password} check box.
#;[[Image:master_passwords-ics]]
# Type a password into the entry fields. {note} ''''''Tip:'''''' Remember to make your password something that is easy for you to remember, but difficult for others to guess. See  [[Choosing More Secure Passwords]] to learn how.{/note}
#;[[Image:master_password2-ics]]
# To set the master password, tap {button OK}.
{/for}
{for m25}
#Tap the {button Menu} button [[Template:AndroidMenuLocation]] and then {button Settings} [[Template:AndroidMore]].
# Then tap {button Privacy} and choose {button Use master password}.
#;[[Image:master_passwords-ics]]
# Type a password into the entry fields. {note} ''''''Tip:'''''' Remember to make your password something that is easy for you to remember, but difficult for others to guess. See  [[Choosing More Secure Passwords]] to learn how.{/note}
#;[[Image:master_password2-ics]]
# To set the master password, tap {button OK}.
{/for}
{note}When Master Password is enabled, passwords will stop syncing to Firefox for Android. {/note}

=How do I remove a master password? =
If you want to stop using a master password, you can easily remove it:
{for not m25}
# Tap the {button Menu} button [[Template:AndroidMenuLocation]] and then {button Settings} [[Template:AndroidMore]].
# Tap the Use Master Password check box. 
# Type your master password into the entry field.
# Click {button OK} to remove the Master Password.
{/for}
{for m25}
#Tap the {button Menu} button [[Template:AndroidMenuLocation]] and then {button Settings} [[Template:AndroidMore]].
# Then tap {button Privacy}
# Tap the Use Master Password check box. 
# Type your master password into the entry field.
# Click {button OK} to remove the Master Password.
{/for}
{note}When Master Password is disabled, passwords will begin syncing again.{/note}

= What can I do if I forget my master password? =
If you''ve forgotten your master password, you''ll have to reset it:
{warning}''''''Warning:'''''' Resetting your master password will remove all of your saved usernames and passwords.{/warning}
# Delete Firefox for Android data from the Google Settings application. 
# The master password will be deleted and you''ll be able reset it. 

[[Template:ShareArticle|link=http://mzl.la/SVtPzw]]','<p>Firefox can save usernames and passwords that you use to access online services, such as banking and email. In order to prevent someone else from accessing your accounts if they have your device, you can set a master password. This article explains how to use a master password.
</p>
<dl><dt><img alt="master_password0-ics" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-04-07-29-14-519db0.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-does-the-master-password-work"><span class="tocnumber">1</span> <span class="toctext">How does the master password work?</span></a></li><li class="toclevel-1"><a href="#w_how-do-i-set-up-a-master-password"><span class="tocnumber">2</span> <span class="toctext">How do I set up a master password?</span></a></li><li class="toclevel-1"><a href="#w_how-do-i-remove-a-master-password"><span class="tocnumber">3</span> <span class="toctext">How do I remove a master password?</span></a></li><li class="toclevel-1"><a href="#w_what-can-i-do-if-i-forget-my-master-password"><span class="tocnumber">4</span> <span class="toctext">What can I do if I forget my master password?</span></a></li></ul></div>
<h1 id="w_how-does-the-master-password-work">How does the master password work?</h1>
<p>After you have defined a master password, you will be prompted to enter it when Firefox needs to access your stored passwords. This will "unlock" the usernames and passwords that you''ve saved and Firefox will automatically fill them in for you as you browse from website to website. When you are done using the web, you can quit Firefox to "lock up" your usernames and passwords.
</p>
<div class="note"><strong>Note:</strong> The Android system on your device may quit Firefox automatically to free up resources when you are using another app. If that happens, you''ll be asked to enter your master password again when you switch back to Firefox.</div>
<h1 id="w_how-do-i-set-up-a-master-password">How do I set up a master password?</h1>
<p>By default, Firefox doesn''t use a master password to protect your saved usernames and passwords. To set one up:
</p><div class="for" data-for="not m25">
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
 and then <span class="button">Settings</span> (you may need to tap <span class="menu">More</span> first)
.
</li><li> Tap the <span class="button">Use master password</span> check box.
<dl><dt><img alt="master_passwords-ics" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-04-07-31-24-269ed6.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> Type a password into the entry fields. <div class="note"> <strong>Tip:</strong> Remember to make your password something that is easy for you to remember, but difficult for others to guess. See  <a href="/en-US/kb/password-strength">Choose a strong password</a> to learn how.</div>
<dl><dt><img alt="master_password2-ics" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-04-07-33-48-6ccea9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> To set the master password, tap <span class="button">OK</span>.
</li></ol>
</div><div class="for" data-for="m25">
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
 and then <span class="button">Settings</span> (you may need to tap <span class="menu">More</span> first)
.
</li><li> Then tap <span class="button">Privacy</span> and choose <span class="button">Use master password</span>.
<dl><dt><img alt="master_passwords-ics" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-04-07-31-24-269ed6.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> Type a password into the entry fields. <div class="note"> <strong>Tip:</strong> Remember to make your password something that is easy for you to remember, but difficult for others to guess. See  <a href="/en-US/kb/password-strength">Choose a strong password</a> to learn how.</div>
<dl><dt><img alt="master_password2-ics" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-04-07-33-48-6ccea9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> To set the master password, tap <span class="button">OK</span>.
</li></ol>
</div>
<div class="note">When Master Password is enabled, passwords will stop syncing to Firefox for Android. </div>
<h1 id="w_how-do-i-remove-a-master-password">How do I remove a master password?</h1>
<p>If you want to stop using a master password, you can easily remove it:
</p><div class="for" data-for="not m25">
<ol><li> Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
 and then <span class="button">Settings</span> (you may need to tap <span class="menu">More</span> first)
.
</li><li> Tap the Use Master Password check box. 
</li><li> Type your master password into the entry field.
</li><li> Click <span class="button">OK</span> to remove the Master Password.
</li></ol>
</div><div class="for" data-for="m25">
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
 and then <span class="button">Settings</span> (you may need to tap <span class="menu">More</span> first)
.
</li><li> Then tap <span class="button">Privacy</span>
</li><li> Tap the Use Master Password check box. 
</li><li> Type your master password into the entry field.
</li><li> Click <span class="button">OK</span> to remove the Master Password.
</li></ol>
</div>
<div class="note">When Master Password is disabled, passwords will begin syncing again.</div>
<h1 id="w_what-can-i-do-if-i-forget-my-master-password">What can I do if I forget my master password?</h1>
<p>If you''ve forgotten your master password, you''ll have to reset it:
</p>
<div class="warning"><strong>Warning:</strong> Resetting your master password will remove all of your saved usernames and passwords.</div>
<ol><li> Delete Firefox for Android data from the Google Settings application. 
</li><li> The master password will be deleted and you''ll be able reset it. 
</li></ol>
<p>&nbsp;

</p>','[{"label": "Revision id", "text": "52092", "datetime": null, "href": null}, {"label": "Created", "text": "Dec 20, 2013, 5:04:47 AM", "datetime": "2013-12-20T05:04:47-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix remove master password section by adding firefox 25 and above and firefox 24 and below instructions", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Dec 20, 2013, 5:05:11 AM", "datetime": "2013-12-20T05:05:11-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Dec 20, 2013, 5:05:11 AM", "datetime": "2013-12-20T05:05:11-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:45:21+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (56067,'en-US','troubleshoot-mode-thunderbird','Troubleshoot Mode Thunderbird','https://support.mozilla.org/en-US/kb/troubleshoot-mode-thunderbird','https://support.mozilla.org/en-US/kb/troubleshoot-mode-thunderbird/revision/56067',54333,'2014-02-20T15:48:16-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','tb5 is ancient history so remove all showfor that refers to less than<=tb5',1,'2014-02-20T15:48:32-08:00','rtanglao',1,0,1,'2014-02-20T15:48:32-08:00','rtanglao','approved','''''''Safe Mode'''''' is a special Thunderbird execution mode that can be used to troubleshoot issues in Thunderbird. In Safe Mode, you can reset some settings or disable add-ons that might be the source of problems. By comparing Thunderbird behavior in normal mode to its behavior in Safe Mode, you find that problems are being caused by a specific add-on.

;:{note}''''''Note:'''''' Windows users may be familiar with a Safe Mode for Windows. Thunderbird Safe Mode has ''''''no relation to Windows Safe Mode.''''''{/note}

;:{note}''''''Note:'''''' In Thunderbird versions prior to 5, there was a shortcut on the Windows start menu for Thunderbird Safe Mode. As of [[New in Thunderbird 5|Thunderbird 5]]  this item has been removed, and replaced with a ''''Restart with Add-ons Disabled'''' entry on the help menu.{/note}

__TOC__

= How to start Thunderbird in Safe Mode =


# ''''If Thunderbird is not running:'''' Start Thunderbird in Safe Mode by {for win}holding down the {key shift} key while starting the application.{/for}{for mac}holding down the {key option} key while starting the application.{/for}{for linux}going to your ''''''Terminal'''''' and running: <code>thunderbird -safe-mode</code><br>You may need to specify the Thunderbird installation path (e.g. {filepath /usr/lib/thunderbird}).{/for}<br/>''''If Thunderbird is already running:'''' At the top of the Thunderbird window, click the {menu Help} menu, and select the {menu Restart with Add-ons Disabled...} menu item and then click the {button Restart} button in the dialog box.
# The Thunderbird Safe Mode dialog opens: <br><br>[[Image:thunderbird safe mode]]<br><br>
# Click on the {button Continue in Safe Mode} button to finish.

= Confirming that Safe Mode is activated =

To confirm that Thunderbird is running in safe mode, click the {menu Tools} menu and then click {menu Add-Ons} and {menu Extensions}. Above your list of Add-ons, there will be a banner displayed stating that Thunderbird is in Safe Mode.

= Exiting Safe Mode =

{for mac}
# Close down Thunderbird completely: On the menu bar, click the {menu Thunderbird} menu, and select the {menu Quit Thunderbird} menu item.
# Start Thunderbird as you normally would.
{/for}

{for win, linux}
# Close down Thunderbird completely: At the top of the Thunderbird window, click the {menu File} menu, and select the {menu Quit} menu item.
# Start Thunderbird as you normally would.
{/for}
{note}If Thunderbird keeps starting in Safe Mode see [[Thunderbird is stuck in Safe Mode]].{/note}

<!-- MZ credit --> 
<br/> <br/>
''''''''''Based on information from  [http://kb.mozillazine.org/Safe_Mode Safe mode (mozillaZine KB)]''''''''''','<p><strong>Safe Mode</strong> is a special Thunderbird execution mode that can be used to troubleshoot issues in Thunderbird. In Safe Mode, you can reset some settings or disable add-ons that might be the source of problems. By comparing Thunderbird behavior in normal mode to its behavior in Safe Mode, you find that problems are being caused by a specific add-on.
</p>
<dl><dt><dl><dd><div class="note"><strong>Note:</strong> Windows users may be familiar with a Safe Mode for Windows. Thunderbird Safe Mode has <strong>no relation to Windows Safe Mode.</strong></div>
</dd></dl>
</dt></dl>
<dl><dt><dl><dd><div class="note"><strong>Note:</strong> In Thunderbird versions prior to 5, there was a shortcut on the Windows start menu for Thunderbird Safe Mode. As of <a href="/en-US/kb/new-thunderbird-5">Thunderbird 5</a>  this item has been removed, and replaced with a <em>Restart with Add-ons Disabled</em> entry on the help menu.</div>
</dd></dl>
</dt></dl>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-to-start-thunderbird-in-safe-mode"><span class="tocnumber">1</span> <span class="toctext">How to start Thunderbird in Safe Mode</span></a></li><li class="toclevel-1"><a href="#w_confirming-that-safe-mode-is-activated"><span class="tocnumber">2</span> <span class="toctext">Confirming that Safe Mode is activated</span></a></li><li class="toclevel-1"><a href="#w_exiting-safe-mode"><span class="tocnumber">3</span> <span class="toctext">Exiting Safe Mode</span></a></li></ul></div>
<h1 id="w_how-to-start-thunderbird-in-safe-mode">How to start Thunderbird in Safe Mode</h1>
<ol><li> <em>If Thunderbird is not running:</em> Start Thunderbird in Safe Mode by <span class="for" data-for="win" style="display: none;">holding down the <span class="key">shift</span> key while starting the application.</span><span class="for" data-for="mac">holding down the <span class="key">option</span> key while starting the application.</span><span class="for" data-for="linux" style="display: none;">going to your <strong>Terminal</strong> and running: <code>thunderbird -safe-mode</code><br>You may need to specify the Thunderbird installation path (e.g. <span class="filepath">/usr/lib/thunderbird</span>).</span><br><em>If Thunderbird is already running:</em> At the top of the Thunderbird window, click the <span class="menu">Help</span> menu, and select the <span class="menu">Restart with Add-ons Disabled...</span> menu item and then click the <span class="button">Restart</span> button in the dialog box.
</li><li> The Thunderbird Safe Mode dialog opens: <br><br><img alt="thunderbird safe mode" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-08-24-13-24-10-5afd48.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</li><li> Click on the <span class="button">Continue in Safe Mode</span> button to finish.
</li></ol>
<h1 id="w_confirming-that-safe-mode-is-activated">Confirming that Safe Mode is activated</h1>
<p>To confirm that Thunderbird is running in safe mode, click the <span class="menu">Tools</span> menu and then click <span class="menu">Add-Ons</span> and <span class="menu">Extensions</span>. Above your list of Add-ons, there will be a banner displayed stating that Thunderbird is in Safe Mode.
</p>
<h1 id="w_exiting-safe-mode">Exiting Safe Mode</h1>
<div class="for" data-for="mac">
<ol><li> Close down Thunderbird completely: On the menu bar, click the <span class="menu">Thunderbird</span> menu, and select the <span class="menu">Quit Thunderbird</span> menu item.
</li><li> Start Thunderbird as you normally would.
</li></ol>
</div><div class="for" data-for="win,linux" style="display: none;">
<ol><li> Close down Thunderbird completely: At the top of the Thunderbird window, click the <span class="menu">File</span> menu, and select the <span class="menu">Quit</span> menu item.
</li><li> Start Thunderbird as you normally would.
</li></ol>
</div>
<div class="note">If Thunderbird keeps starting in Safe Mode see <a href="/en-US/kb/thunderbird-stuck-safe-mode">Thunderbird is stuck in Safe Mode</a>.</div>
<p> 
<br> <br>
<em><strong>Based on information from  <a href="http://kb.mozillazine.org/Safe_Mode">Safe mode (mozillaZine KB)</a></strong></em>
</p>','[{"label": "Revision id", "text": "56067", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 20, 2014, 3:48:16 PM", "datetime": "2014-02-20T15:48:16-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "tb5 is ancient history so remove all showfor that refers to less than<=tb5", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 20, 2014, 3:48:32 PM", "datetime": "2014-02-20T15:48:32-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Feb 20, 2014, 3:48:32 PM", "datetime": "2014-02-20T15:48:32-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:45:18+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (58506,'en-US','forum-response-troubleshooting-thunderbird-safe','Forum Response - Troubleshooting Thunderbird using Throubleshoot Mode','https://support.mozilla.org/en-US/kb/forum-response-troubleshooting-thunderbird-safe','https://support.mozilla.org/en-US/kb/forum-response-troubleshooting-thunderbird-safe/revision/58506',NULL,'2014-03-19T11:57:07-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','rename and move to canned responses and small edits',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','To diagnose problems with Thunderbird and the operating system, you can restart Thunderbird with add-ons disabled  and you can also try restarting your computer''s operating system into its safe mode.

*Restart Thunderbird with add-ons disabled. (Thunderbird safe mode) Thus is on the help menu (Ctrl + H). If Thunderbird works like normal, there is an Add-on or Theme interfering with normal operations, you will need to re enable add-ons one at a time until you locate the offender.
*Restart the operating system in [http://en.wikipedia.org/wiki/Safe_mode safe mode] with Networking. Instructions for the various operating systems can be found by clicking on their name. [http://windows.microsoft.com/en-us/windows-8/windows-startup-settings-including-safe-mode Windows 8], [http://windows.microsoft.com/en-us/windows/start-computer-safe-mode#start-computer-safe-mode=windows-7 Windows 7], [http://windows.microsoft.com/en-us/windows/start-computer-safe-mode#start-computer-safe-mode=windows-vista Windows Vista],  [http://www.microsoft.com/resources/documentation/windows/xp/all/proddocs/en-us/boot_failsafe.mspx?mfr=true" Windows XP],  [http://support.apple.com/kb/ht1564 OSX]  
If safe mode for the operating system fixes the issue, it will be resident software loaded into your computer other than Thunderbird that is the cause.  Possibilities include but not limited to: AV scanning, virus/malware, background downloads such as program updates.

Safe mode for your operating system does not load anything but the very basics needed to start your computer. Hence the "with networking". This allows the internet','<p>To diagnose problems with Thunderbird and the operating system, you can restart Thunderbird with add-ons disabled  and you can also try restarting your computer''s operating system into its safe mode.
</p>
<ul><li>Restart Thunderbird with add-ons disabled. (Thunderbird safe mode) Thus is on the help menu (Ctrl + H). If Thunderbird works like normal, there is an Add-on or Theme interfering with normal operations, you will need to re enable add-ons one at a time until you locate the offender.
</li><li>Restart the operating system in <a href="http://en.wikipedia.org/wiki/Safe_mode">safe mode</a> with Networking. Instructions for the various operating systems can be found by clicking on their name. <a href="http://windows.microsoft.com/en-us/windows-8/windows-startup-settings-including-safe-mode">Windows 8</a>, <a href="http://windows.microsoft.com/en-us/windows/start-computer-safe-mode#start-computer-safe-mode=windows-7">Windows 7</a>, <a href="http://windows.microsoft.com/en-us/windows/start-computer-safe-mode#start-computer-safe-mode=windows-vista">Windows Vista</a>,  <a href="http://www.microsoft.com/resources/documentation/windows/xp/all/proddocs/en-us/boot_failsafe.mspx?mfr=true">Windows XP</a>,  <a href="http://support.apple.com/kb/ht1564">OSX</a>  
</li></ul>
<p>If safe mode for the operating system fixes the issue, it will be resident software loaded into your computer other than Thunderbird that is the cause.  Possibilities include but not limited to: AV scanning, virus/malware, background downloads such as program updates.
</p><p>Safe mode for your operating system does not load anything but the very basics needed to start your computer. Hence the "with networking". This allows the internet
</p>','[{"label": "Revision id", "text": "58506", "datetime": null, "href": null}, {"label": "Created", "text": "Mar 19, 2014, 11:57:07 AM", "datetime": "2014-03-19T11:57:07-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "rename and move to canned responses and small edits", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:45:16+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (61418,'en-US','use-awesome-screen-search-web-bookmarks-and-more','Use the Awesome Screen to search the web, bookmarks and more','https://support.mozilla.org/en-US/kb/use-awesome-screen-search-web-bookmarks-and-more','https://support.mozilla.org/en-US/kb/use-awesome-screen-search-web-bookmarks-and-more/revision/61418',61414,'2014-04-21T04:58:05-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','change to use [[Template:AndroidMenuLocation]]',1,'2014-04-21T04:59:15-07:00','rtanglao',1,0,0,NULL,NULL,'approved','The Awesome Screen gets you where you want to go quickly by giving you a list of your most often visited sites along with the ability to search the web, your bookmarks and browsing history all from one place. Just tap on the site you want to visit. No typing involved! 

__TOC__
=Access your top sites=
{for not m26}
Just open Firefox and you have access to all of the sites you visit most frequently. This list of sites will change as your habits change. 
;[[Image:Top Sites 25]]
If you''d like to make sure something always shows up here, you can pin it.
*Tap and hold on a site and then choose {menu Pin Site}. A mark in the upper-right corner lets you know the site is pinned.
*;[[Image:Pinned site 25]]
{/for}
{for m26}
Just open Firefox to have the sites you visit the most frequently right at your fingertips. This list of sites will change as your habits change. 
;[[Image:Top Sites 26]]
If you''d like to make sure something always shows up here, you can pin it.
*Tap and hold on a site and then choose {menu Pin Site}. You''ll see a small push-pin next to the name of the site.
*;[[Image:Pinned site 26]]
{for m29}
{note}''''''Don''t want to see your top sites?'''''' You can display your bookmarks, reading list or history instead. See [[Use the Awesome Screen to search the web, bookmarks and more#w_customize-your-home-screen|customize your home screen]] for more information.{/note}
{/for}
{/for}

=Search the web, your bookmarks and browsing history all from one place=
The Awesome Screen gets its name from the fact that you can search everything from one place.
*Tap the address bar or [[Using Tabs on Firefox for Android|open a new tab]] and start typing. You will see sites you''ve bookmarked or visited before along with web searches you can do. Just tap the thing you want and you''re set.
*;[[Image:Awesome search 26]]
Of course, if you''d rather scroll through your bookmarks or history, you can do that too.
{for not m26}
*Tap the address bar or [[Using Tabs on Firefox for Android|open a new tab]] and then select the Bookmarks or History tab instead of typing. 
*;[[Image:Awesome browse 25]]
{/for}
{for m26}
*Just select History or Bookmarks from the Top Sites screen or a [[Using Tabs on Firefox for Android|new tab]]. 
*;[[Image:Awesome browse 26]]
{/for}
{note}''''''Tip:'''''' You can access your desktop bookmarks, history and more from your Android device by [[How do I set up Firefox Sync?|setting up Firefox Sync]].{/note}

=Customize the way the Awesome Screen works=
''''Make Firefox work just the way you want.''''
{for m29}
==Customize your home screen==
Want to start your day with your bookmarks, reading list or top sites? Now you can choose which panel to load when you start Firefox. You can also hide the panels that you don''t use.
#Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Settings} (on some phones you may need to tap {menu More} first)
#;[[Image:android setting]]
#Tap {menu Customize}, and then {menu Home}.
#On the ''''Home'''' menu, tap on a panel: ''''History, Top Sites, Bookmarks, or Reading List''''.
#Choose {menu Set as default} if you want that panel as your default or {menu Hide} if you don''t want to see it at all. If a panel is already hidden, you can choose {menu Show} to unhide it.
{/for}

==Turn on search suggestions==
Turn on search suggestions to show related Google suggestions alongside your search words.
{for not m25}
*Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Settings} (on some phones you may need to tap {menu More} first) and check the ''''''Show search suggestions'''''' option.
{/for}
{for m25}
*Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Settings} (on some phones you may need to tap {menu More} first), {menu Customize}{for m26}, {menu Search settings}{/for}. Finally, check the ''''''Show search suggestions'''''' option.
{/for}

==Add search engines and choose the default one==
Want to add YouTube results to your searches or use DuckDuckGo? No problem.
#Go to the site of the search engine you want to use. For example, youtube.com. 
#Tap and hold inside the search box and choose {menu Add a Search Engine}.
{note}''''''Search within a specific website.'''''' Some websites offer their own search engines. Use the same steps above to add them to Firefox, and you''ll be able to search a specific site directly from your search bar.{/note}
Change your default search engine:
{for not m26}
#Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Tools} (or {menu More} if tools is not an option) and {menu Add-ons}.
#Tap the search engine that you would like to set as default and choose {menu Set as Default}.
{/for}
{for m26}
#Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Settings} (on some phones you may need to tap {menu More} first), {menu Customize}, {menu Search settings}.
#Tap the search engine that you would like to set as default and choose {menu Set as default}.
{/for}

==Show the URL in the address bar instead of the website name==
{for not m25}
*Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Settings} (on some phones you may need to tap {menu More} first) . Scroll down and tap the {menu Title bar} setting and choose ''''''Show page address''''''.
{/for}
{for m25}
*Tap the {button Menu} button [[Template:AndroidMenuLocation]], then {menu Settings} (on some phones you may need to tap {menu More} first), {menu Display}. Then tap the {menu Title bar} setting and choose ''''''Show page address''''''.
{/for}

[[Template:ShareArticle|link=http://mzl.la/LnnpCM]]','<p>The Awesome Screen gets you where you want to go quickly by giving you a list of your most often visited sites along with the ability to search the web, your bookmarks and browsing history all from one place. Just tap on the site you want to visit. No typing involved! 
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_access-your-top-sites"><span class="tocnumber">1</span> <span class="toctext">Access your top sites</span></a></li><li class="toclevel-1"><a href="#w_search-the-web-your-bookmarks-and-browsing-history-all-from-one-place"><span class="tocnumber">2</span> <span class="toctext">Search the web, your bookmarks and browsing history all from one place</span></a></li><li class="toclevel-1"><a href="#w_customize-the-way-the-awesome-screen-works"><span class="tocnumber">3</span> <span class="toctext">Customize the way the Awesome Screen works</span></a><ul><span class="for" data-for="m29"><li class="toclevel-2"><a href="#w_customize-your-home-screen"><span class="tocnumber">3.1</span> <span class="toctext">Customize your home screen</span></a></li></span><li class="toclevel-2"><a href="#w_turn-on-search-suggestions"><span class="tocnumber">3.2</span> <span class="toctext">Turn on search suggestions</span></a></li><li class="toclevel-2"><a href="#w_add-search-engines-and-choose-the-default-one"><span class="tocnumber">3.3</span> <span class="toctext">Add search engines and choose the default one</span></a></li><li class="toclevel-2"><a href="#w_show-the-url-in-the-address-bar-instead-of-the-website-name"><span class="tocnumber">3.4</span> <span class="toctext">Show the URL in the address bar instead of the website name</span></a></li></ul></li></ul></div>
<h1 id="w_access-your-top-sites">Access your top sites</h1>
<div class="for" data-for="not m26" style="display: none;"><p>Just open Firefox and you have access to all of the sites you visit most frequently. This list of sites will change as your habits change. 
</p>
<dl><dt><img alt="Top Sites 25" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-05-19-44-f7727d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>If you''d like to make sure something always shows up here, you can pin it.
</p>
<ul><li>Tap and hold on a site and then choose <span class="menu">Pin Site</span>. A mark in the upper-right corner lets you know the site is pinned.
<dl><dt><img alt="Pinned site 25" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-05-20-28-a8d2fc.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
</div><div class="for" data-for="m26"><p>Just open Firefox to have the sites you visit the most frequently right at your fingertips. This list of sites will change as your habits change. 
</p>
<dl><dt><img alt="Top Sites 26" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-05-25-20-f67c17.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>If you''d like to make sure something always shows up here, you can pin it.
</p>
<ul><li>Tap and hold on a site and then choose <span class="menu">Pin Site</span>. You''ll see a small push-pin next to the name of the site.
<dl><dt><img alt="Pinned site 26" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-05-26-08-daf183.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
<div class="for" data-for="m29">
<div class="note"><strong>Don''t want to see your top sites?</strong> You can display your bookmarks, reading list or history instead. See <a href="/en-US/kb/customize-firefox-home-screen#w_customize-your-home-screen">customize your home screen</a> for more information.</div>
</div></div>
<h1 id="w_search-the-web-your-bookmarks-and-browsing-history-all-from-one-place">Search the web, your bookmarks and browsing history all from one place</h1>
<p>The Awesome Screen gets its name from the fact that you can search everything from one place.
</p>
<ul><li>Tap the address bar or <a href="/en-US/kb/manage-tabs-firefox-android">open a new tab</a> and start typing. You will see sites you''ve bookmarked or visited before along with web searches you can do. Just tap the thing you want and you''re set.
<dl><dt><img alt="Awesome search 26" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-11-54-33-6a7dc5.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
<p>Of course, if you''d rather scroll through your bookmarks or history, you can do that too.
</p><div class="for" data-for="not m26" style="display: none;">
<ul><li>Tap the address bar or <a href="/en-US/kb/manage-tabs-firefox-android">open a new tab</a> and then select the Bookmarks or History tab instead of typing. 
<dl><dt><img alt="Awesome browse 25" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-15-19-12-29c621.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
</div><div class="for" data-for="m26">
<ul><li>Just select History or Bookmarks from the Top Sites screen or a <a href="/en-US/kb/manage-tabs-firefox-android">new tab</a>. 
<dl><dt><img alt="Awesome browse 26" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-11-08-06-12-57-386f56.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
</div>
<div class="note"><strong>Tip:</strong> You can access your desktop bookmarks, history and more from your Android device by <a href="/en-US/kb/how-do-i-set-sync-my-computer">setting up Firefox Sync</a>.</div>
<h1 id="w_customize-the-way-the-awesome-screen-works">Customize the way the Awesome Screen works</h1>
<p><em>Make Firefox work just the way you want.</em>
</p><div class="for" data-for="m29">
<h2 id="w_customize-your-home-screen">Customize your home screen</h2>
<p>Want to start your day with your bookmarks, reading list or top sites? Now you can choose which panel to load when you start Firefox. You can also hide the panels that you don''t use.
</p>
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Settings</span> (on some phones you may need to tap <span class="menu">More</span> first)
<dl><dt><img alt="android setting" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-04-17-18-01-39-2e5d8a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>Tap <span class="menu">Customize</span>, and then <span class="menu">Home</span>.
</li><li>On the <em>Home</em> menu, tap on a panel: <em>History, Top Sites, Bookmarks, or Reading List</em>.
</li><li>Choose <span class="menu">Set as default</span> if you want that panel as your default or <span class="menu">Hide</span> if you don''t want to see it at all. If a panel is already hidden, you can choose <span class="menu">Show</span> to unhide it.
</li></ol>
</div>
<h2 id="w_turn-on-search-suggestions">Turn on search suggestions</h2>
<p>Turn on search suggestions to show related Google suggestions alongside your search words.
</p><div class="for" data-for="not m25" style="display: none;">
<ul><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Settings</span> (on some phones you may need to tap <span class="menu">More</span> first) and check the <strong>Show search suggestions</strong> option.
</li></ul>
</div><div class="for" data-for="m25">
<ul><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Settings</span> (on some phones you may need to tap <span class="menu">More</span> first), <span class="menu">Customize</span><span class="for" data-for="m26">, <span class="menu">Search settings</span></span>. Finally, check the <strong>Show search suggestions</strong> option.
</li></ul>
</div>
<h2 id="w_add-search-engines-and-choose-the-default-one">Add search engines and choose the default one</h2>
<p>Want to add YouTube results to your searches or use DuckDuckGo? No problem.
</p>
<ol><li>Go to the site of the search engine you want to use. For example, <a href="http://youtube.com">youtube.com</a>. 
</li><li>Tap and hold inside the search box and choose <span class="menu">Add a Search Engine</span>.
</li></ol>
<div class="note"><strong>Search within a specific website.</strong> Some websites offer their own search engines. Use the same steps above to add them to Firefox, and you''ll be able to search a specific site directly from your search bar.</div>
<p>Change your default search engine:
</p><div class="for" data-for="not m26" style="display: none;">
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Tools</span> (or <span class="menu">More</span> if tools is not an option) and <span class="menu">Add-ons</span>.
</li><li>Tap the search engine that you would like to set as default and choose <span class="menu">Set as Default</span>.
</li></ol>
</div><div class="for" data-for="m26">
<ol><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Settings</span> (on some phones you may need to tap <span class="menu">More</span> first), <span class="menu">Customize</span>, <span class="menu">Search settings</span>.
</li><li>Tap the search engine that you would like to set as default and choose <span class="menu">Set as default</span>.
</li></ol>
</div>
<h2 id="w_show-the-url-in-the-address-bar-instead-of-the-website-name">Show the URL in the address bar instead of the website name</h2>
<div class="for" data-for="not m25" style="display: none;">
<ul><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Settings</span> (on some phones you may need to tap <span class="menu">More</span> first) . Scroll down and tap the <span class="menu">Title bar</span> setting and choose <strong>Show page address</strong>.
</li></ul>
</div><div class="for" data-for="m25">
<ul><li>Tap the <span class="button">Menu</span> button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
, then <span class="menu">Settings</span> (on some phones you may need to tap <span class="menu">More</span> first), <span class="menu">Display</span>. Then tap the <span class="menu">Title bar</span> setting and choose <strong>Show page address</strong>.
</li></ul>
</div><p>&nbsp;

</p>','[{"label": "Revision id", "text": "61418", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 21, 2014, 4:58:05 AM", "datetime": "2014-04-21T04:58:05-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "change to use [[Template:AndroidMenuLocation]]", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Apr 21, 2014, 4:59:15 AM", "datetime": "2014-04-21T04:59:15-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:45:13+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (65101,'en-US','filelink-large-attachments','Filelink for Large Attachments','https://support.mozilla.org/en-US/kb/filelink-large-attachments','https://support.mozilla.org/en-US/kb/filelink-large-attachments/revision/65101',60573,'2014-06-03T02:52:07-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','changed yousendit to hightail',1,'2014-06-03T02:52:34-07:00','rtanglao',1,0,1,'2014-06-03T02:52:34-07:00','rtanglao','approved','Many email servers do not accept messages with large file attachments. The file size restriction varies depending on the mail server configuration. While you might be able to send a message with a large attachment, the receiving mail server might refuse to accept a message with a large attachment. This is all beyond the control of Thunderbird.

Starting in Thunderbird 13, Thunderbird Filelink eliminated this problem by adding support for online storage services. It allows you to upload attachments to an online storage service and then replaces the attachment in the message with a link. The message recipient clicks the link to download the attachment. As additional benefits, sending and receiving large files is much faster and both you and the recipient will save disk space.

Note that you can use Thunderbird Filelink in addition to [[how to use attachments|conventional attachments]]. For example, you can attach small files directly to a message and use Filelink for large attachments in the same message. 

The instructions below show how to configure and use Filelink with the [https://www.hightail.com/ Hightail] (formerly YousSendIt) online storage service. [https://www.box.com/ Box] is the other provider supported by default,  but the community has been active in adding other providers through the use of [https://addons.mozilla.org/thunderbird/search/?q=filelink add-ons] with hubiC, AjaXplorer,  FileSwap.com, and ~okeanos currently having add-ons

__TOC__

= Configuring Filelink =

To use Filelink, you must first create a new account (or configure an existing account) with an online storage service provider. 

[[Template:optionspreferences tb]] Click on the {button Attachments} button, then click {button Outgoing}. Select the desired service provider from the drop-down list. Click the {button Add} button. Enter the username for  your online storage account, or click link to create an accout with your selected provider.

[[Image:FilelinkDialog]] 

If you are creating a new account, a browser window will open that displays the service provider''s registration page. Create an account as instructed. The service provider will send you a validation email message. Click the validation link in the message to activate your account. Enter your username (your email address) in the dialog shown above and enter your password when prompted.

In the main configuration dialog, check {button Offer to share for files larger than...} and specify a file size (in megabytes) if you want Thunderbird to prompt you to use Filelink when a message attachment exceeds the specified size.

= Using Filelink =

When you attach a file to a message, if the file size exceeds the amount specified above, Thunderbird will offer to let you use Filelink:



To force a file to be attached using Filelink (rather than relying on Thunderbird to determine if the attached file exceeds the specified size), you can click the down arrow next to the {button Attach} button on the message toolbar to access the Filelink menu option.

Click the {button Link} button to upload the file to the online storage service provider.  (Alternatively click {button Ignore} to attach the file as a [[how to use attachments|conventional attachment]].)

[[Image:FileLinkAsk]] 

When you select {button Link} the displayed message will update to 

[[Image:FileLinkLinkingMessage]] 

When the linking is complete, that is your attachment has been uploaded to the service provider your email will be modified and a block of text and a link will be added to the body of your email as shown below.

[[Image:FileLinkLinked]] 

When the recipient receives the message, they will see the same information and clicking the link in the message will take them to a download page to download the attachment

= Filelink FAQ =

Attachments that you send via Filelink are not stored on Mozilla servers. Each file storage service provider has its own privacy policy and terms of service. The file storage service provider has reviewed the Filelink feature to ensure that it is consistent with their policies.

== Q: Does Mozilla know which provider the user has picked? ==

A: No. Mozilla is unaware of which provider has been selected by a user. Provider configuration is stored on the local machine.

== Q: What storage services are currently supported? ==

A: As of Thunderbird 16, we have reached agreement with [https://www.box.com/ Box], [https://one.ubuntu.com/ Ubuntu One] and [https://www.hightail.com Hightail] to integrate  their services directly into Thunderbird. You can install support for more providers with add-ons, like:
* [https://addons.mozilla.org/thunderbird/addon/dropbox-for-filelink/ Dropbox]
* [https://addons.mozilla.org/thunderbird/addon/fileswapcom-filelink FileSwap.com] 
* [https://addons.mozilla.org/thunderbird/addon/dl-for-thunderbird/ DL for Thunderbird] may be the best if you prefer using your own server instead of relying on 3rd-party providers.
* Last but not least, you can use Filelink with a WebDAV server with the [https://addons.mozilla.org/thunderbird/addon/webdav-for-filelink WebDAV for Filelink] add-on.

== Q: Can the storage service view my attachments? ==

A: Unless you encrypt the file before uploading, the storage services will be able to view the file, as will anyone who obtains the link to the attachment.  Users must decide on their own which service provider they trust with that responsibility. (Service providers generally explain your privacy rights in their terms of service.) Note that standard attachment functionality is also not encrypted. When you send an attachment the "normal" way, the file can be accessed by anyone that can access the message between your system and the recipients system (such as your email service provider). Filelink adds some security as file uploads to the storage service provider are sent via HTTPS, a secure protocol.

== Q: How long will my file be available on the storage service provider''s site? ==

A: The file will remain available on the storage service provider''s site until you specifically delete it. Log in to the provider''s website to view and delete the files in your storage space.

== Q: Can you support service provider X or protocol Y? ==

A: We plan to support SpiderOak. We also have an "[http://blog.mozilla.org/thunderbird/ Up-for-grabs]" project available if anybody would like to add  support for more services or protocols. Developer documentation for the Filelink feature can be found here: [https://developer.mozilla.org/en/Thunderbird/Filelink_Providers]

== Q: I don''t like the idea of storing my files with third-parties like this. Do regular attachments still work? ==

A: Regular email attachments still work the same as they always have. We''ve just given you the ability to choose to upload large attachments somewhere else, if you wish. Thunderbird''s notion of a large file  defaults to 1 MB, but can be customized in Thunderbird''s Preferences. ([[Template:optionspreferences tb]]) The offer to upload can also be disabled entirely.

[[T:ShareArticle|link=http://mzl.la/1fNR49i]]','<p>Many email servers do not accept messages with large file attachments. The file size restriction varies depending on the mail server configuration. While you might be able to send a message with a large attachment, the receiving mail server might refuse to accept a message with a large attachment. This is all beyond the control of Thunderbird.
</p><p>Starting in Thunderbird 13, Thunderbird Filelink eliminated this problem by adding support for online storage services. It allows you to upload attachments to an online storage service and then replaces the attachment in the message with a link. The message recipient clicks the link to download the attachment. As additional benefits, sending and receiving large files is much faster and both you and the recipient will save disk space.
</p><p>Note that you can use Thunderbird Filelink in addition to <a class="new" href="/en-US/kb/new?title=how+to+use+attachments" title="Page does not exist.">conventional attachments</a>. For example, you can attach small files directly to a message and use Filelink for large attachments in the same message. 
</p><p>The instructions below show how to configure and use Filelink with the <a href="https://www.hightail.com/">Hightail</a> (formerly YousSendIt) online storage service. <a href="https://www.box.com/">Box</a> is the other provider supported by default,  but the community has been active in adding other providers through the use of <a href="https://addons.mozilla.org/thunderbird/search/?q=filelink">add-ons</a> with hubiC, AjaXplorer,  <a href="http://FileSwap.com">FileSwap.com</a>, and ~okeanos currently having add-ons
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configuring-filelink"><span class="tocnumber">1</span> <span class="toctext">Configuring Filelink</span></a></li><li class="toclevel-1"><a href="#w_using-filelink"><span class="tocnumber">2</span> <span class="toctext">Using Filelink</span></a></li><li class="toclevel-1"><a href="#w_filelink-faq"><span class="tocnumber">3</span> <span class="toctext">Filelink FAQ</span></a><ul><li class="toclevel-2"><a href="#w_q-does-mozilla-know-which-provider-the-user-has-picked"><span class="tocnumber">3.1</span> <span class="toctext">Q: Does Mozilla know which provider the user has picked?</span></a></li><li class="toclevel-2"><a href="#w_q-what-storage-services-are-currently-supported"><span class="tocnumber">3.2</span> <span class="toctext">Q: What storage services are currently supported?</span></a></li><li class="toclevel-2"><a href="#w_q-can-the-storage-service-view-my-attachments"><span class="tocnumber">3.3</span> <span class="toctext">Q: Can the storage service view my attachments?</span></a></li><li class="toclevel-2"><a href="#w_q-how-long-will-my-file-be-available-on-the-storage-service-providers-site"><span class="tocnumber">3.4</span> <span class="toctext">Q: How long will my file be available on the storage service provider''s site?</span></a></li><li class="toclevel-2"><a href="#w_q-can-you-support-service-provider-x-or-protocol-y"><span class="tocnumber">3.5</span> <span class="toctext">Q: Can you support service provider X or protocol Y?</span></a></li><li class="toclevel-2"><a href="#w_q-i-dont-like-the-idea-of-storing-my-files-with-third-parties-like-this-do-regular-attachments-still-work"><span class="tocnumber">3.6</span> <span class="toctext">Q: I don''t like the idea of storing my files with third-parties like this. Do regular attachments still work?</span></a></li></ul></li></ul></div>
<h1 id="w_configuring-filelink">Configuring Filelink</h1>
<p>To use Filelink, you must first create a new account (or configure an existing account) with an online storage service provider. 
</p><p>The template "optionspreferences tb" does not exist or has no approved revision. Click on the <span class="button">Attachments</span> button, then click <span class="button">Outgoing</span>. Select the desired service provider from the drop-down list. Click the <span class="button">Add</span> button. Enter the username for  your online storage account, or click link to create an accout with your selected provider.
</p><p><img alt="FilelinkDialog" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-05-05-00-08-05-f11c60.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>If you are creating a new account, a browser window will open that displays the service provider''s registration page. Create an account as instructed. The service provider will send you a validation email message. Click the validation link in the message to activate your account. Enter your username (your email address) in the dialog shown above and enter your password when prompted.
</p><p>In the main configuration dialog, check <span class="button">Offer to share for files larger than...</span> and specify a file size (in megabytes) if you want Thunderbird to prompt you to use Filelink when a message attachment exceeds the specified size.
</p>
<h1 id="w_using-filelink">Using Filelink</h1>
<p>When you attach a file to a message, if the file size exceeds the amount specified above, Thunderbird will offer to let you use Filelink:
</p><p><br>
</p><p>To force a file to be attached using Filelink (rather than relying on Thunderbird to determine if the attached file exceeds the specified size), you can click the down arrow next to the <span class="button">Attach</span> button on the message toolbar to access the Filelink menu option.
</p><p>Click the <span class="button">Link</span> button to upload the file to the online storage service provider.  (Alternatively click <span class="button">Ignore</span> to attach the file as a <a class="new" href="/en-US/kb/new?title=how+to+use+attachments" title="Page does not exist.">conventional attachment</a>.)
</p><p><img alt="FileLinkAsk" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-05-05-00-14-52-b76fb9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>When you select <span class="button">Link</span> the displayed message will update to 
</p><p><img alt="FileLinkLinkingMessage" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-05-05-00-17-58-59e694.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>When the linking is complete, that is your attachment has been uploaded to the service provider your email will be modified and a block of text and a link will be added to the body of your email as shown below.
</p><p><img alt="FileLinkLinked" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-05-05-01-21-28-8e37a8.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>When the recipient receives the message, they will see the same information and clicking the link in the message will take them to a download page to download the attachment
</p>
<h1 id="w_filelink-faq">Filelink FAQ</h1>
<p>Attachments that you send via Filelink are not stored on Mozilla servers. Each file storage service provider has its own privacy policy and terms of service. The file storage service provider has reviewed the Filelink feature to ensure that it is consistent with their policies.
</p>
<h2 id="w_q-does-mozilla-know-which-provider-the-user-has-picked">Q: Does Mozilla know which provider the user has picked?</h2>
<p>A: No. Mozilla is unaware of which provider has been selected by a user. Provider configuration is stored on the local machine.
</p>
<h2 id="w_q-what-storage-services-are-currently-supported">Q: What storage services are currently supported?</h2>
<p>A: As of Thunderbird 16, we have reached agreement with <a href="https://www.box.com/">Box</a>, <a href="https://one.ubuntu.com/">Ubuntu One</a> and <a href="https://www.hightail.com">Hightail</a> to integrate  their services directly into Thunderbird. You can install support for more providers with add-ons, like:
</p>
<ul><li> <a href="https://addons.mozilla.org/thunderbird/addon/dropbox-for-filelink/">Dropbox</a>
</li><li> <a href="https://addons.mozilla.org/thunderbird/addon/fileswapcom-filelink">FileSwap.com</a> 
</li><li> <a href="https://addons.mozilla.org/thunderbird/addon/dl-for-thunderbird/">DL for Thunderbird</a> may be the best if you prefer using your own server instead of relying on 3rd-party providers.
</li><li> Last but not least, you can use Filelink with a WebDAV server with the <a href="https://addons.mozilla.org/thunderbird/addon/webdav-for-filelink">WebDAV for Filelink</a> add-on.
</li></ul>
<h2 id="w_q-can-the-storage-service-view-my-attachments">Q: Can the storage service view my attachments?</h2>
<p>A: Unless you encrypt the file before uploading, the storage services will be able to view the file, as will anyone who obtains the link to the attachment.  Users must decide on their own which service provider they trust with that responsibility. (Service providers generally explain your privacy rights in their terms of service.) Note that standard attachment functionality is also not encrypted. When you send an attachment the "normal" way, the file can be accessed by anyone that can access the message between your system and the recipients system (such as your email service provider). Filelink adds some security as file uploads to the storage service provider are sent via HTTPS, a secure protocol.
</p>
<h2 id="w_q-how-long-will-my-file-be-available-on-the-storage-service-providers-site">Q: How long will my file be available on the storage service provider''s site?</h2>
<p>A: The file will remain available on the storage service provider''s site until you specifically delete it. Log in to the provider''s website to view and delete the files in your storage space.
</p>
<h2 id="w_q-can-you-support-service-provider-x-or-protocol-y">Q: Can you support service provider X or protocol Y?</h2>
<p>A: We plan to support SpiderOak. We also have an "<a href="http://blog.mozilla.org/thunderbird/">Up-for-grabs</a>" project available if anybody would like to add  support for more services or protocols. Developer documentation for the Filelink feature can be found here: <a href="https://developer.mozilla.org/en/Thunderbird/Filelink_Providers">https://developer.mozilla.org/en/Thun.../Filelink_Providers</a>
</p>
<h2 id="w_q-i-dont-like-the-idea-of-storing-my-files-with-third-parties-like-this-do-regular-attachments-still-work">Q: I don''t like the idea of storing my files with third-parties like this. Do regular attachments still work?</h2>
<p>A: Regular email attachments still work the same as they always have. We''ve just given you the ability to choose to upload large attachments somewhere else, if you wish. Thunderbird''s notion of a large file  defaults to 1 MB, but can be customized in Thunderbird''s Preferences. (The template "optionspreferences tb" does not exist or has no approved revision.) The offer to upload can also be disabled entirely.
</p><p>&nbsp;

</p>','[{"label": "Revision id", "text": "65101", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 3, 2014, 2:52:07 AM", "datetime": "2014-06-03T02:52:07-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "changed yousendit to hightail", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jun 3, 2014, 2:52:34 AM", "datetime": "2014-06-03T02:52:34-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jun 3, 2014, 2:52:34 AM", "datetime": "2014-06-03T02:52:34-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:45:11+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (67599,'en-US','cannot-delete-messages','Cannot delete messages','https://support.mozilla.org/en-US/kb/cannot-delete-messages','https://support.mozilla.org/en-US/kb/cannot-delete-messages/revision/67599',NULL,'2014-07-11T14:17:32-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fix nits and remove un-needed keywords (since they are in the body of the text they aren''t needed)',1,'2014-07-11T14:18:29-07:00','rtanglao',1,0,1,'2014-07-11T14:18:29-07:00','rtanglao','approved','If you cannot delete messages in Thunderbird, it may be caused by a corrupted trash folder.

Here is how to delete the corrupted trash folder and create a new one:

# First, open your Profile folder. 
# At the top right of the Thunderbird window, click the menu button [[Image:New Fx Menu]], then select {menu ?} and {menu Troubleshooting Information}. The Troubleshooting Information tab will open. 
# Under the ''''''Application Basics'''''' section, click on {button {for win}Show Folder{/for}{for mac}Show in Finder{/for}{for linux}Open Directory{/for}}. A window with your profile {for not mac}files{/for}{for mac}folder{/for} will open.
# Close Thunderbird
# Click on the {filepath Mail} (or {filepath ImapMail}) folder in your file manager (according to whether you are using POP or IMAP with the affected account)
# Click on the folder with your mail account name (something like {filepath imap.googlemail.com} or {filepath pop.googlemail.com})
# Select {filepath Trash} and {filepath Trash.msf} files and delete them. In some accounts, these may be named {filepath Bin} or {filepath Deleted}. 
# Restart Thunderbird 

A new Trash folder will be created by Thunderbird. This should make it possible to delete email again.','<p>If you cannot delete messages in Thunderbird, it may be caused by a corrupted trash folder.
</p><p>Here is how to delete the corrupted trash folder and create a new one:
</p>
<ol><li> First, open your Profile folder. 
</li><li> At the top right of the Thunderbird window, click the menu button <img alt="New Fx Menu" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-01-10-13-08-08-f52b8c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">, then select <span class="menu">?</span> and <span class="menu">Troubleshooting Information</span>. The Troubleshooting Information tab will open. 
</li><li> Under the <strong>Application Basics</strong> section, click on <span class="button"><span class="for" data-for="win" style="display: none;">Show Folder</span><span class="for" data-for="mac">Show in Finder</span><span class="for" data-for="linux" style="display: none;">Open Directory</span></span>. A window with your profile <span class="for" data-for="not mac" style="display: none;">files</span><span class="for" data-for="mac">folder</span> will open.
</li><li> Close Thunderbird
</li><li> Click on the <span class="filepath">Mail</span> (or <span class="filepath">ImapMail</span>) folder in your file manager (according to whether you are using POP or IMAP with the affected account)
</li><li> Click on the folder with your mail account name (something like <span class="filepath"><a href="http://imap.googlemail.com">imap.googlemail.com</a></span> or <span class="filepath"><a href="http://pop.googlemail.com">pop.googlemail.com</a></span>)
</li><li> Select <span class="filepath">Trash</span> and <span class="filepath">Trash.msf</span> files and delete them. In some accounts, these may be named <span class="filepath">Bin</span> or <span class="filepath">Deleted</span>. 
</li><li> Restart Thunderbird 
</li></ol>
<p>A new Trash folder will be created by Thunderbird. This should make it possible to delete email again.
</p>','[{"label": "Revision id", "text": "67599", "datetime": null, "href": null}, {"label": "Created", "text": "Jul 11, 2014, 2:17:32 PM", "datetime": "2014-07-11T14:17:32-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix nits and remove un-needed keywords (since they are in the body of the text they aren''t needed)", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jul 11, 2014, 2:18:29 PM", "datetime": "2014-07-11T14:18:29-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jul 11, 2014, 2:18:29 PM", "datetime": "2014-07-11T14:18:29-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:45:08+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (67821,'en-US','remote-content-in-messages','Remote Content in Messages','https://support.mozilla.org/en-US/kb/remote-content-in-messages','https://support.mozilla.org/en-US/kb/remote-content-in-messages/revision/67821',NULL,'2014-07-15T07:48:50-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','change e-mail to email, reorder sections',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','= Remote Content in Messages =

Email messages can contain remote content such as images, stylesheets or videos.
By default Thunderbird does not load remote content automatically, but instead
shows a notification bar that it blocked remote content to protect your privacy.

Remote content is a privacy concern because it allows the message
sender to know: 

* each time you view the message
* rough details about what application and what platform you are using
* your current geographic location (a rough approximation by IP address)
* that your email address is actually used ("alive")

This is almost the same information web sites commonly collect about you
during normal web surfing. While browsing has the same privacy
implications, what makes remote content in messages different is that it is
targeted at you initially, so you can assume your access is directly
linkable to your email address. This is also why spam often contains
remote images (also known as "web bugs") which allow the spammer to mark your address as valid if the image is ever loaded.

On the other hand, if you do get many genuine emails containing remote content 
it can get annoying having to click "Show remote content in this message" for 
each message. Emails look much better with images and stylesheets 
turned on.  

All in all, however, what you do online in a web browser
is usually disclosing much more information about yourself than loading content
in an email message.

=== Remote content is blocked by default===

This is the default, and what most people should be using. In this mode, Thunderbird will show a blocked remote content notification bar
when content is blocked.

=== Display remote content for a particular message ===
 From the notification bar you can choose to:
* {button Show remote content in this message} to show remote content just for this particular message OR
* {button Edit remote content preferences...} to Display remote content by default (see next section).
* {button Allow remote content for...} to show the remote content for all messages from this sender.

{button Allow remote content for...} adds the sender email address or sites (currently blocked in the message)
to the remote content whitelist. 
Note however, that email addresses are easily spoofable in contrast  to web sites that serve remote
content. As long as the network is not  compromised, it is much more difficult to spoof content than email addresses.

=== Display remote content by default ===

If you are willing to accept the privacy implications of displaying remote content for all messages, Thunderbird allows you to display remote content by default.

This is set in  {for mac}{menu Thunderbird | Preferences}{/for}{for win}{menu Tools | Options}{/for}{for linux}{menu Edit | Preferences}{/for} followed by selecting the {menu Privacy tab}.

If the {button Allow remote content in messages} checkbox is ticked, all remote
content will be loaded, just like it would in a browser. You can exclude
specific sites from the rule by clicking {button Exceptions...} and
adding the domain or email address.

