INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (73142,'en-US','im-having-problems-confirming-my-firefox-account','I''m having problems confirming my Mozilla account','https://support.mozilla.org/en-US/kb/im-having-problems-confirming-my-firefox-account','https://support.mozilla.org/en-US/kb/im-having-problems-confirming-my-firefox-account/revision/73142',72746,'2014-08-25T02:28:26-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','"sync" is not needed as keyword since it''s in the body text',1,'2014-08-25T02:30:01-07:00','rtanglao',1,0,1,'2014-08-25T02:30:01-07:00','rtanglao','approved','When you sign up for a new Firefox Account, we send you an email with a confirmation link. Clicking on the link tells us that you own the email address connected to the account. If you''re having issues confirming your account, try these common solutions. <!-- check: capitalize "account" in "Firefox Account" only? -->

=I haven''t received my confirmation email=
The confirmation email can take a few minutes to get to your inbox. Spam filters might also prevent it from reaching the right folder. If you''ve already waited a few minutes and refreshed your inbox, try the following steps:

*Check your junk mail or spam folder to see if your confirmation email ended up there.
*Click the ''''''Resend email'''''' link on the Firefox Sync signup page.

If you still don''t see the confirmation email after trying the preceding steps, a strong spam filter might have prevented the confirmation email from reaching you at all. Try adding ''''accounts<!---->.firefox.com'''' to your list of allowed senders to keep your email provider from blocking the email.

=I clicked on the link, but my account still isn''t verified=
If you see a "you need to verify''" message on the browser even after clicking the link, it''s likely that our accounts server hasn''t communicated with your browser yet.

Your browser will check your status with the server periodically, but you can  try the following steps either on your desktop computer or Android device to force a manual update.

''''''From your desktop computer:''''''
#{for win,linux}Press {key Alt}{/for}{for linux}+{key T}{/for} {for win,linux}to bring up the menu bar.{/for} Click on the {menu Tools} menu at the top of the browser.
#Click {menu Sync Now}.

''''''From your Android device:''''''
#Open the Settings app on your Android device.
#Tap on {menu Accounts}.
#Tap {menu Firefox}.
#Tap on the menu button and then {menu Sync all}.','<p>When you sign up for a new Firefox Account, we send you an email with a confirmation link. Clicking on the link tells us that you own the email address connected to the account. If you''re having issues confirming your account, try these common solutions. 
</p>
<h1 id="w_i-havent-received-my-confirmation-email">I haven''t received my confirmation email</h1>
<p>The confirmation email can take a few minutes to get to your inbox. Spam filters might also prevent it from reaching the right folder. If you''ve already waited a few minutes and refreshed your inbox, try the following steps:
</p>
<ul><li>Check your junk mail or spam folder to see if your confirmation email ended up there.
</li><li>Click the <strong>Resend email</strong> link on the Firefox Sync signup page.
</li></ul>
<p>If you still don''t see the confirmation email after trying the preceding steps, a strong spam filter might have prevented the confirmation email from reaching you at all. Try adding <em>accounts.<a href="http://firefox.com">firefox.com</a></em> to your list of allowed senders to keep your email provider from blocking the email.
</p>
<h1 id="w_i-clicked-on-the-link-but-my-account-still-isnt-verified">I clicked on the link, but my account still isn''t verified</h1>
<p>If you see a "you need to verify''" message on the browser even after clicking the link, it''s likely that our accounts server hasn''t communicated with your browser yet.
</p><p>Your browser will check your status with the server periodically, but you can  try the following steps either on your desktop computer or Android device to force a manual update.
</p><p><strong>From your desktop computer:</strong>
</p>
<ol><li><span class="for" data-for="win,linux" style="display: none;">Press <span class="key">Alt</span></span><span class="for" data-for="linux" style="display: none;">+<span class="key">T</span></span> <span class="for" data-for="win,linux" style="display: none;">to bring up the menu bar.</span> Click on the <span class="menu">Tools</span> menu at the top of the browser.
</li><li>Click <span class="menu">Sync Now</span>.
</li></ol>
<p><strong>From your Android device:</strong>
</p>
<ol><li>Open the Settings app on your Android device.
</li><li>Tap on <span class="menu">Accounts</span>.
</li><li>Tap <span class="menu">Firefox</span>.
</li><li>Tap on the menu button and then <span class="menu">Sync all</span>.
</li></ol>','[{"label": "Revision id", "text": "73142", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 25, 2014, 2:28:26 AM", "datetime": "2014-08-25T02:28:26-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "\"sync\" is not needed as keyword since it''s in the body text", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 25, 2014, 2:30:01 AM", "datetime": "2014-08-25T02:30:01-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 25, 2014, 2:30:01 AM", "datetime": "2014-08-25T02:30:01-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:44:59+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (73177,'en-US','moving-thunderbird-data-to-a-new-computer','Move Thunderbird data to a new computer','https://support.mozilla.org/en-US/kb/moving-thunderbird-data-to-a-new-computer','https://support.mozilla.org/en-US/kb/moving-thunderbird-data-to-a-new-computer/revision/73177',56278,'2014-08-25T07:23:58-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','https://support.mozilla.org/en-US/kb/moving-thunderbird-data-to-a-new-computer/discuss/5453',1,'2014-08-25T07:24:24-07:00','rtanglao',1,0,1,'2014-08-25T07:24:24-07:00','rtanglao','approved','__TOC__


<!--
Based on important anecdotal evidence about MozBackup corrupting user data I am  commenting this out.
https://support.mozilla.org/en-US/kb/moving-thunderbird-data-to-a-new-computer/discuss/5453

{for win}
=Mozbackup=
Moving Thunderbird on Windows is as simple as downloading the [http://mozbackup.jasnapaka.com/download.php mozbackup] utility and using it to move your messages and profile data. While this utility is not supplied or supported by Mozilla, it provides a full backup and restore service tailored to Mozilla products.
-->

= Windows Easy Transfer Wizard= 
Recent versions of Windows come with an Easy Transfer Wizard which offers to transfer your data, documents, videos and email to your new computer. The default settings for this transfer wizard do not transfer Thunderbird data to your new computer. However, it is simple to make the changes necessary to have the software move your Thunderbird data.

Once the wizard has finished the "Checking what can be transferred" routine, a customize option will appear under the account name. Click this option to open a dialog that provides access to advanced options.
<br><br> [[Image:ETOptionsDialog]] <br>

Click {menu Advanced} at the bottom of the list, which opens a file selection dialog. Expand the folder named {filepath Application data} and check the box beside the folder name {filepath Thunderbird} as shown below.
<br><br>[[Image:ETFilePicker]] <br>

Click {button Save} and continue with the wizard.  Your Thunderbird data is now included in the data that will be transferred from your old computer to your new computer.
{/for}

= Manually moving files =

If you are moving from one operating system to another (such as changing from Windows to Mac) then you must manually move your profile from one computer to the next.  You''ll need to first back up your profile using the instructions on the [[Profiles TB|Profiles]] page, then follow the directions on that page for "Restoring to a different location." 

= Using Gmail to move  messages =

In this method, you transfer messages to a Gmail account and then synchronize them to your new Thunderbird installation. 

<ol>
<li>Create a Gmail account if you don''t already have one.</li>
<li>Create a Thunderbird [[Automatic Account Configuration|account]] on the original computer for your Gmail account.</li>
<li>Make sure that your Gmail account properties are configured to use IMAP rather than POP3.</li>
<li>In Thunderbird, create matching subfolders under your Gmail account for every message folder you want to move. Thunderbird will automatically create a corresponding folder in your Gmail account.  You can create nested subfolders.  For example...</li>

[[Image:Thunderbird folders]]

<li> For each folder you want to transfer, go to the original folder in Thunderbird, select all the messages, right-click and select {menu Copy To} and then select the corresponding folder in the Gmail account.  As Thunderbird copies the messages to the new folder they are also copied to your online Gmail storage space.</li>
<li>On your new computer, install Thunderbird and create your Gmail account.</li>
<li>Your online folders and messages should now be available in Thunderbird on the new computer.  As you click on each folder, it will synchronize with your Gmail account.</li>
</ol>

=See Also=

* [http://en.flossmanuals.net/thunderbird/migrating/ Migrate to Thunderbird chapter] in the Thunderbird FLOSS manual

[[Template:ShareArticle|link=http://mzl.la/1nWgylz]]','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_windows-easy-transfer-wizard"><span class="tocnumber">1</span> <span class="toctext">Windows Easy Transfer Wizard</span></a></li><li class="toclevel-1"><a href="#w_manually-moving-files"><span class="tocnumber">2</span> <span class="toctext">Manually moving files</span></a></li><li class="toclevel-1"><a href="#w_using-gmail-to-move-messages"><span class="tocnumber">3</span> <span class="toctext">Using Gmail to move  messages</span></a></li><li class="toclevel-1"><a href="#w_see-also"><span class="tocnumber">4</span> <span class="toctext">See Also</span></a></li></ul></div>
<p><br>

</p>
<h1 id="w_windows-easy-transfer-wizard">Windows Easy Transfer Wizard</h1>
<p>Recent versions of Windows come with an Easy Transfer Wizard which offers to transfer your data, documents, videos and email to your new computer. The default settings for this transfer wizard do not transfer Thunderbird data to your new computer. However, it is simple to make the changes necessary to have the software move your Thunderbird data.
</p><p>Once the wizard has finished the "Checking what can be transferred" routine, a customize option will appear under the account name. Click this option to open a dialog that provides access to advanced options.
<br><br> <img alt="ETOptionsDialog" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-11-19-18-34-32-3f0e63.PNG" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> <br>
</p><p>Click <span class="menu">Advanced</span> at the bottom of the list, which opens a file selection dialog. Expand the folder named <span class="filepath">Application data</span> and check the box beside the folder name <span class="filepath">Thunderbird</span> as shown below.
<br><br><img alt="ETFilePicker" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-11-19-18-39-57-b36fe0.PNG" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> <br>
</p><p>Click <span class="button">Save</span> and continue with the wizard.  Your Thunderbird data is now included in the data that will be transferred from your old computer to your new computer.
</p>
<h1 id="w_manually-moving-files">Manually moving files</h1>
<p>If you are moving from one operating system to another (such as changing from Windows to Mac) then you must manually move your profile from one computer to the next.  You''ll need to first back up your profile using the instructions on the <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Profiles</a> page, then follow the directions on that page for "Restoring to a different location." 
</p>
<h1 id="w_using-gmail-to-move-messages">Using Gmail to move  messages</h1>
<p>In this method, you transfer messages to a Gmail account and then synchronize them to your new Thunderbird installation. 
</p>
<ol>
<li>Create a Gmail account if you don''t already have one.</li>
<li>Create a Thunderbird <a href="/en-US/kb/automatic-account-configuration">account</a> on the original computer for your Gmail account.</li>
<li>Make sure that your Gmail account properties are configured to use IMAP rather than POP3.</li>
<li>In Thunderbird, create matching subfolders under your Gmail account for every message folder you want to move. Thunderbird will automatically create a corresponding folder in your Gmail account.  You can create nested subfolders.  For example...</li>
<p><img alt="Thunderbird folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-12-16-12-49-59-cbe8f3.JPG" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<li> For each folder you want to transfer, go to the original folder in Thunderbird, select all the messages, right-click and select <span class="menu">Copy To</span> and then select the corresponding folder in the Gmail account.  As Thunderbird copies the messages to the new folder they are also copied to your online Gmail storage space.</li>
<li>On your new computer, install Thunderbird and create your Gmail account.</li>
<li>Your online folders and messages should now be available in Thunderbird on the new computer.  As you click on each folder, it will synchronize with your Gmail account.</li>
</ol>
<h1 id="w_see-also">See Also</h1>
<ul><li> <a href="http://en.flossmanuals.net/thunderbird/migrating/">Migrate to Thunderbird chapter</a> in the Thunderbird FLOSS manual
</li></ul>
<p>&nbsp;

</p>','[{"label": "Revision id", "text": "73177", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 25, 2014, 7:23:58 AM", "datetime": "2014-08-25T07:23:58-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "https://support.mozilla.org/en-US/kb/moving-thunderbird-data-to-a-new-computer/discuss/5453", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 25, 2014, 7:24:24 AM", "datetime": "2014-08-25T07:24:24-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 25, 2014, 7:24:24 AM", "datetime": "2014-08-25T07:24:24-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:44:56+00:00');
