INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (76930,'en-US','thunderbird-cant-be-opened-after-install-on-mac','Thunderbird can''t be opened after you install it on a Mac - How to fix','https://support.mozilla.org/en-US/kb/thunderbird-cant-be-opened-after-install-on-mac','https://support.mozilla.org/en-US/kb/thunderbird-cant-be-opened-after-install-on-mac/revision/76930',NULL,'2014-09-25T04:35:31-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','do not approve, needs thunderbird screenshot before this can go live',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','{for win, linux}{warning}This issue applies to Mac devices only.{/warning}{/for}

Apple has introduced a security change to Mac OS X 10.9.5 which causes the error message ''''''Thunderbird.app cannot be opened because the identity of the developer cannot be confirmed'''''' to appear when you try to install Firefox on your Mac.

Here are some steps you can take if you see this message:

=Option 1 - Recommended=
# Hold down the {key Control} key while clicking on the Thunderbird file.
# Click {menu Open} in the context menu.
# Click {button Open} in the following dialog window. 

=Option 2 - Open Thunderbird through the System Preferences=
# Click on the Apple icon at the top left corner of your screen and open {menu System Preferences…}.
# Click on {menu Security & Privacy}, then the {menu General} tab.
# You''ll see a message stating that the ''''Thunderbird.app'''' was blocked. Click on {button Open Anyway}:
#;[[Image:blocked firefox mac]]','<div class="for" data-for="win,linux" style="display: none;"><div class="warning">This issue applies to Mac devices only.</div></div>
<p>Apple has introduced a security change to Mac OS X 10.9.5 which causes the error message <strong>Thunderbird.app cannot be opened because the identity of the developer cannot be confirmed</strong> to appear when you try to install Firefox on your Mac.
</p><p>Here are some steps you can take if you see this message:
</p>
<h1 id="w_option-1-recommended">Option 1 - Recommended</h1>
<ol><li> Hold down the <span class="key">Control</span> key while clicking on the Thunderbird file.
</li><li> Click <span class="menu">Open</span> in the context menu.
</li><li> Click <span class="button">Open</span> in the following dialog window. 
</li></ol>
<h1 id="w_option-2-open-thunderbird-through-the-system-preferences">Option 2 - Open Thunderbird through the System Preferences</h1>
<ol><li> Click on the Apple icon at the top left corner of your screen and open <span class="menu">System Preferences…</span>.
</li><li> Click on <span class="menu">Security &amp; Privacy</span>, then the <span class="menu">General</span> tab.
</li><li> You''ll see a message stating that the <em>Thunderbird.app</em> was blocked. Click on <span class="button">Open Anyway</span>:
<dl><dt><img alt="blocked firefox mac" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-09-22-16-59-58-34a31b.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ol>','[{"label": "Revision id", "text": "76930", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 25, 2014, 4:35:31 AM", "datetime": "2014-09-25T04:35:31-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "do not approve, needs thunderbird screenshot before this can go live", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:44:49+00:00');
