INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (87448,'en-US','firefox-installer-crashes-windows-xp','Firefox installer crashes on Windows XP','https://support.mozilla.org/en-US/kb/firefox-installer-crashes-windows-xp','https://support.mozilla.org/en-US/kb/firefox-installer-crashes-windows-xp/revision/87448',NULL,'2015-01-15T03:09:01-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fix typos add markup and links to the bug and microsoft''s firewall support article',1,'2015-01-15T03:10:08-08:00','rtanglao',1,0,1,'2015-01-20T07:20:37-08:00','heyjoni','approved','If your latest version of Firefox is crashing when you are trying to install it on Windows XP, this might be caused by your Windows Firewall being turned off. This is how to quickly fix it:

1. Enable Windows Firewall by clicking {button Start}, click {button Run}, type ''''''Firewall.cpl'''''', and then click OK.

2. On the {menu General} tab, click {button ON} (recommended)

3. Click {button OK}.

4. Install Firefox by running the Firefox installer.

More information about turning on the Windows XP firewall can be found in: [http://support.microsoft.com/kb/283673 How can I turn on or turn off the firewall in Windows XP Service Pack 2 or later versions?].

Technical information about this problem can be found in: [https://bugzilla.mozilla.org/show_bug.cgi?id=1120673 bug 1120673].','<p>If your latest version of Firefox is crashing when you are trying to install it on Windows XP, this might be caused by your Windows Firewall being turned off. This is how to quickly fix it:
</p><p>1. Enable Windows Firewall by clicking <span class="button">Start</span>, click <span class="button">Run</span>, type <strong>Firewall.cpl</strong>, and then click OK.
</p><p>2. On the <span class="menu">General</span> tab, click <span class="button">ON</span> (recommended)
</p><p>3. Click <span class="button">OK</span>.
</p><p>4. Install Firefox by running the Firefox installer.
</p><p>More information about turning on the Windows XP firewall can be found in: <a href="http://support.microsoft.com/kb/283673">How can I turn on or turn off the firewall in Windows XP Service Pack 2 or later versions?</a>.
</p><p>Technical information about this problem can be found in: <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=1120673">bug 1120673</a>.
</p>','[{"label": "Revision id", "text": "87448", "datetime": null, "href": null}, {"label": "Created", "text": "Jan 15, 2015, 3:09:01 AM", "datetime": "2015-01-15T03:09:01-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix typos add markup and links to the bug and microsoft''s firewall support article", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jan 15, 2015, 3:10:08 AM", "datetime": "2015-01-15T03:10:08-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jan 20, 2015, 7:20:37 AM", "datetime": "2015-01-20T07:20:37-08:00", "href": null}, {"label": "Readied for localization by", "text": "heyjoni", "datetime": null, "href": null}]','2026-11-03T18:44:03+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (89193,'en-US','forum-response-no-eudora-ose-or-eudora-thunderbird','Forum Response - No Eudora OSE or the Eudora Thunderbird add-on support','https://support.mozilla.org/en-US/kb/forum-response-no-eudora-ose-or-eudora-thunderbird','https://support.mozilla.org/en-US/kb/forum-response-no-eudora-ose-or-eudora-thunderbird/revision/89193',NULL,'2015-02-03T05:41:00-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','rewriting to use Wayne Mery''s excellent wording from https://wiki.mozilla.org/Eudora_OSE',1,'2015-02-03T05:41:50-08:00','rtanglao',1,1,0,NULL,NULL,'approved','It is Mozilla''s understanding that Qualcomm is no longer developing Eudora OSE and its community support forum no longer exists. Furthermore, the last released version is based on an old version of Thunderbird which is no longer supported, has many bugs and performance problems, and known security issues. Users might like to try [http://www.getthunderbird.com/ Thunderbird] as an alternative email program. The user interface and features are not the same, but Thunderbird has an [https://support.mozilla.org/products/thunderbird active support community], and its features and UI can be improved with [https://addons.mozilla.org/thunderbird addons], which in some cases add [https://addons.mozilla.org/thunderbird/search/?q=eudora Eudora-like functionality].','<p>It is Mozilla''s understanding that Qualcomm is no longer developing Eudora OSE and its community support forum no longer exists. Furthermore, the last released version is based on an old version of Thunderbird which is no longer supported, has many bugs and performance problems, and known security issues. Users might like to try <a href="http://www.getthunderbird.com/">Thunderbird</a> as an alternative email program. The user interface and features are not the same, but Thunderbird has an <a href="https://support.mozilla.org/products/thunderbird">active support community</a>, and its features and UI can be improved with <a href="https://addons.mozilla.org/thunderbird">addons</a>, which in some cases add <a href="https://addons.mozilla.org/thunderbird/search/?q=eudora">Eudora-like functionality</a>.
</p>','[{"label": "Revision id", "text": "89193", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 3, 2015, 5:41:00 AM", "datetime": "2015-02-03T05:41:00-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "rewriting to use Wayne Mery''s excellent wording from https://wiki.mozilla.org/Eudora_OSE", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 3, 2015, 5:41:50 AM", "datetime": "2015-02-03T05:41:50-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:44:01+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (90635,'en-US','getting-started-firefox-android-tablet-browser','Get started with Firefox for Android on tablets','https://support.mozilla.org/en-US/kb/getting-started-firefox-android-tablet-browser','https://support.mozilla.org/en-US/kb/getting-started-firefox-android-tablet-browser/revision/90635',90615,'2015-02-23T00:33:16-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','the bookmark star shows up in 10" tablets, not 7" tablets and not on phablets',1,'2015-02-23T00:33:32-08:00','rtanglao',1,0,1,'2015-02-23T00:33:32-08:00','rtanglao','approved','{for not m36}

<!-- unhide this comment when m36 is on general release

{warning}This feature has been updated on the new version of Firefox for Android. [[Update to the latest version of Firefox for Android]] for the new Firefox experience.{/warning}

-->

This article describes how to get started with  Firefox for Android on tablets by describing the differences between the tablet and phone user experience (also known as [http://en.wikipedia.org/wiki/User_experience UX]). The Firefox for Android tablet user experience displays more controls in the top bar in order to take advantage of the larger screen size on tablets.

{note} ''''''Note:'''''' Tablets with screens smaller than seven inches do not get the tablet user experience.  Tablets smaller than seven inches in screen size, including [http://en.wikipedia.org/wiki/Phablet phablets] like the Samsung Galaxy Note I, II and III, get the phone user experience; see [[Getting started with Firefox for mobile]]. {/note}

The following image shows the Firefox for Android tablet interface in portrait mode.

[[Image:tablet 10 inch portrait top bar m26]]

The following image shows the Firefox for Android tablet interface in portrait mode for seven inch tablets:

[[Image:tablet 7 inch portrait top bar m26]]

The navigation and menus are across the top of the screen, from left to right, as shown in the above screenshots:

*Tabs icon - Displays the number of open tabs, tap to show tabs in the sidebar. To hide the tabs in landscape mode, swipe left across the black tab margin. To hide the tabs in portrait mode, swipe up on the current web page.
*Location bar - Tap the location bar to access your history and bookmarks. Or type an address or search term, then press Enter on the soft keyboard to go.
*Reload page - Tap to reload the page.
*Bookmark page - Tap the star to add a page to your bookmarks list. On seven inch tablets, the star is displayed in the menu instead of the top of the screen to save screen space.
*Main Menu - Tap this to access the Firefox for Android menu (seven inch tablets display the bookmark star in the menu instead of in the top bar).
{/for}

{for m36}
Firefox is optimized for Android devices of all screen sizes! We''ll show you how to browse the Web using Firefox''s improved tablet experience.

{note} ''''''Note:'''''' The tablet experience applies to devices with a screen size of seven inches (17.78 cm) or larger. Tablets smaller than seven inches in screen size, including [http://en.wikipedia.org/wiki/Phablet phablets] like the Samsung Galaxy Note I, II and III, get the phone user experience; see [[Getting started with Firefox for mobile]]. {/note}

__TOC__

=Bookmarks=
Tap the star icon to save your favorite pages so you can access them later. To remove a bookmark, visit the site you want to remove, then tap the star again.
[[Image:bookmarks tablet]]
*If your tablet''s screen is smaller than 10", tap the menu button to see the bookmark (star) button.

{note}''''''Access your bookmarks:'''''' Tap the address bar to bring up the [[Use the Awesome Screen to search the web, bookmarks and more | home screen]] where you can access your bookmarks.{/note}

=Address Bar=
Tap the address bar to search the Web, enter a website address, or to bring up your [[Use the Awesome Screen to search the web, bookmarks and more | home screen]].
[[Image:tablet url]]

''''Things you can do with the address bar:''''
*''''''Home screen:'''''' Tapping the address bar brings up your [[Use the Awesome Screen to search the web, bookmarks and more | home screen]], where you can access your <b>bookmarks, reading list, tabs you''ve synchronized</b> with other devices, and your most visited sites.
;[[Image:home screen tablet]]
*''''''Search:'''''' Search the Web, your bookmarks, history or open tabs, all in one place. Just enter your search and Firefox will match the results as you type.
*''''''Web address:'''''' Enter the address for a website you want to visit.

=Tabs=
Firefox for Android lets you open multiple tabs on your tablet. Your open tabs will appear across your tab strip above the toolbar.
[[Image:tablet browsing]]

==Open new tab==
Click the plus symbol to open a new tab.
;[[Image: new tab tablet]]

{note}You can also open a link as a new tab by pressing down on it, then choosing {menu Open Link in New Tab} from the menu.{/note}

==View open tabs== 
Scroll left or right on the tab strip to view your open tabs.

To display a gallery of your open tabs:
# Tap the tab number:
#;[[Image:tab number tablet]]
#All your open tabs will appear in gallery view.
#;[[Image:tab gallery]] 
#From here, you can also tap the [[Private Browsing on Firefox for Android|Private Browsing]] icon to open a private tab for sites that you don''t want stored in your history.
#;[[Image:private browsing tablet]]

=Menu button=
Tap this to use other Firefox features, such as sending content to your [[Use Firefox for Android to send videos to Chromecast | Chromecast]] or [[Use Firefox for Android to send videos to your Roku | Roku]], or changing your settings or customizations. 

{warning}If you don''t see the menu icon on your toolbar, it''s because your device already has a menu button built into the hardware. Use the built-in menu button instead. See [[Firefox menu icon is missing on Android - how to access the menu]] for more information.{/warning}

=Reload button=
Tap this button to see any new changes on a page.
[[Image:reload tablet]]

=Sharing and synchronizing tabs=
Now that you know the basics, see [[Using Tabs on Firefox for Android]] for information on sharing and synchronizing your tabs.

{/for}','<div class="for" data-for="not m36" style="display: none;"><p>
</p><p>This article describes how to get started with  Firefox for Android on tablets by describing the differences between the tablet and phone user experience (also known as <a href="http://en.wikipedia.org/wiki/User_experience">UX</a>). The Firefox for Android tablet user experience displays more controls in the top bar in order to take advantage of the larger screen size on tablets.
</p>
<div class="note"> <strong>Note:</strong> Tablets with screens smaller than seven inches do not get the tablet user experience.  Tablets smaller than seven inches in screen size, including <a href="http://en.wikipedia.org/wiki/Phablet">phablets</a> like the Samsung Galaxy Note I, II and III, get the phone user experience; see <a href="/en-US/kb/get-started-firefox-android">Get started with Firefox for Android</a>. </div>
<p>The following image shows the Firefox for Android tablet interface in portrait mode.
</p><p><img alt="tablet 10 inch portrait top bar m26" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-12-20-11-31-35-fd2ff6.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p>The following image shows the Firefox for Android tablet interface in portrait mode for seven inch tablets:
</p><p><img alt="tablet 7 inch portrait top bar m26" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-12-20-11-35-05-8ff2e2.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p>The navigation and menus are across the top of the screen, from left to right, as shown in the above screenshots:
</p>
<ul><li>Tabs icon - Displays the number of open tabs, tap to show tabs in the sidebar. To hide the tabs in landscape mode, swipe left across the black tab margin. To hide the tabs in portrait mode, swipe up on the current web page.
</li><li>Location bar - Tap the location bar to access your history and bookmarks. Or type an address or search term, then press Enter on the soft keyboard to go.
</li><li>Reload page - Tap to reload the page.
</li><li>Bookmark page - Tap the star to add a page to your bookmarks list. On seven inch tablets, the star is displayed in the menu instead of the top of the screen to save screen space.
</li><li>Main Menu - Tap this to access the Firefox for Android menu (seven inch tablets display the bookmark star in the menu instead of in the top bar).
</li></ul>
</div><div class="for" data-for="m36"><p>Firefox is optimized for Android devices of all screen sizes! We''ll show you how to browse the Web using Firefox''s improved tablet experience.
</p>
<div class="note"> <strong>Note:</strong> The tablet experience applies to devices with a screen size of seven inches (17.78 cm) or larger. Tablets smaller than seven inches in screen size, including <a href="http://en.wikipedia.org/wiki/Phablet">phablets</a> like the Samsung Galaxy Note I, II and III, get the phone user experience; see <a href="/en-US/kb/get-started-firefox-android">Get started with Firefox for Android</a>. </div>
<div id="toc"><h2>Table of Contents</h2><ul><span class="for" data-for="m36"><li class="toclevel-1"><a href="#w_bookmarks"><span class="tocnumber">1</span> <span class="toctext">Bookmarks</span></a></li></span><span class="for" data-for="m36"><li class="toclevel-1"><a href="#w_address-bar"><span class="tocnumber">2</span> <span class="toctext">Address Bar</span></a></li></span><span class="for" data-for="m36"><li class="toclevel-1"><a href="#w_tabs"><span class="tocnumber">3</span> <span class="toctext">Tabs</span></a><ul><span class="for" data-for="m36"><li class="toclevel-2"><a href="#w_open-new-tab"><span class="tocnumber">3.1</span> <span class="toctext">Open new tab</span></a></li></span><span class="for" data-for="m36"><li class="toclevel-2"><a href="#w_view-open-tabs"><span class="tocnumber">3.2</span> <span class="toctext">View open tabs</span></a></li></span></ul></li></span><span class="for" data-for="m36"><li class="toclevel-1"><a href="#w_menu-button"><span class="tocnumber">4</span> <span class="toctext">Menu button</span></a></li></span><span class="for" data-for="m36"><li class="toclevel-1"><a href="#w_reload-button"><span class="tocnumber">5</span> <span class="toctext">Reload button</span></a></li></span><span class="for" data-for="m36"><li class="toclevel-1"><a href="#w_sharing-and-synchronizing-tabs"><span class="tocnumber">6</span> <span class="toctext">Sharing and synchronizing tabs</span></a></li></span></ul></div>
<h1 id="w_bookmarks">Bookmarks</h1>
<p>Tap the star icon to save your favorite pages so you can access them later. To remove a bookmark, visit the site you want to remove, then tap the star again.
<img alt="bookmarks tablet" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-15-52-29-1a7795.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<ul><li>If your tablet''s screen is smaller than 10", tap the menu button to see the bookmark (star) button.
</li></ul>
<div class="note"><strong>Access your bookmarks:</strong> Tap the address bar to bring up the <a href="/en-US/kb/customize-firefox-home-screen"> home screen</a> where you can access your bookmarks.</div>
<h1 id="w_address-bar">Address Bar</h1>
<p>Tap the address bar to search the Web, enter a website address, or to bring up your <a href="/en-US/kb/customize-firefox-home-screen"> home screen</a>.
<img alt="tablet url" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-15-46-14-884d98.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p><em>Things you can do with the address bar:</em>
</p>
<ul><li><strong>Home screen:</strong> Tapping the address bar brings up your <a href="/en-US/kb/customize-firefox-home-screen"> home screen</a>, where you can access your <b>bookmarks, reading list, tabs you''ve synchronized</b> with other devices, and your most visited sites.
</li></ul>
<dl><dt><img alt="home screen tablet" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-15-45-27-106a6c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<ul><li><strong>Search:</strong> Search the Web, your bookmarks, history or open tabs, all in one place. Just enter your search and Firefox will match the results as you type.
</li><li><strong>Web address:</strong> Enter the address for a website you want to visit.
</li></ul>
<h1 id="w_tabs">Tabs</h1>
<p>Firefox for Android lets you open multiple tabs on your tablet. Your open tabs will appear across your tab strip above the toolbar.
<img alt="tablet browsing" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-15-47-03-1e0953.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<h2 id="w_open-new-tab">Open new tab</h2>
<p>Click the plus symbol to open a new tab.
</p>
<dl><dt><img alt="new tab tablet" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-15-57-57-6e3efd.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<div class="note">You can also open a link as a new tab by pressing down on it, then choosing <span class="menu">Open Link in New Tab</span> from the menu.</div>
<h2 id="w_view-open-tabs">View open tabs</h2>
<p>Scroll left or right on the tab strip to view your open tabs.
</p><p>To display a gallery of your open tabs:
</p>
<ol><li> Tap the tab number:
<dl><dt><img alt="tab number tablet" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-16-04-56-8fcdf0.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>All your open tabs will appear in gallery view.
<dl><dt><img alt="tab gallery" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-16-01-14-9c5cf8.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li>From here, you can also tap the <a href="/en-US/kb/private-browsing-firefox-android">Private Browsing</a> icon to open a private tab for sites that you don''t want stored in your history.
<dl><dt><img alt="private browsing tablet" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-16-16-16-2c17c6.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ol>
<h1 id="w_menu-button">Menu button</h1>
<p>Tap this to use other Firefox features, such as sending content to your <a href="/en-US/kb/use-firefox-android-send-videos-chromecast"> Chromecast</a> or <a href="/en-US/kb/use-firefox-android-send-videos-your-roku"> Roku</a>, or changing your settings or customizations. 
</p>
<div class="warning">If you don''t see the menu icon on your toolbar, it''s because your device already has a menu button built into the hardware. Use the built-in menu button instead. See <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu">Firefox menu icon is missing on Android - how to access the menu</a> for more information.</div>
<h1 id="w_reload-button">Reload button</h1>
<p>Tap this button to see any new changes on a page.
<img alt="reload tablet" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-01-22-15-50-32-24bc8a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<h1 id="w_sharing-and-synchronizing-tabs">Sharing and synchronizing tabs</h1>
<p>Now that you know the basics, see <a href="/en-US/kb/manage-tabs-firefox-android">Manage tabs in Firefox for Android</a> for information on sharing and synchronizing your tabs.
</p></div>','[{"label": "Revision id", "text": "90635", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 23, 2015, 12:33:16 AM", "datetime": "2015-02-23T00:33:16-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "the bookmark star shows up in 10\" tablets, not 7\" tablets and not on phablets", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 23, 2015, 12:33:32 AM", "datetime": "2015-02-23T00:33:32-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Feb 23, 2015, 12:33:32 AM", "datetime": "2015-02-23T00:33:32-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:43:59+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (91185,'en-US','thunderbird-and-gmail','Thunderbird and Gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail/revision/91185',91106,'2015-03-06T10:51:29-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','thunderbird 38 is may 12, 2015 not april 2015; otherwise minor edits',1,'2015-03-06T10:51:42-08:00','rtanglao',1,0,1,'2015-03-06T10:51:42-08:00','rtanglao','approved','Thunderbird can be configured to work seamlessly with Google''s [http://gmail.google.com Gmail] service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.

{warning}''''''Gmail accounts created on or about June 2014 (exact date unknown, Google only mentions [http://googleonlinesecurity.blogspot.ca/2014/04/new-security-measures-will-affect-older.html "second half of 2014" in their new authentication blog post]) won''t work with Thunderbird until the Thunderbird team implements Google''s non-email-standard authentication''''''. This is currently scheduled for Thunderbird 38 which will be released on May 12, 2015. See [https://bugzilla.mozilla.org/show_bug.cgi?id=849540 bug 849540 for the full technical details].{/warning}

__TOC__

= Configuring your Gmail account =

To configure Thunderbird to work with Gmail, first enable IMAP on your Gmail account. 
See [http://mail.google.com/support/bin/answer.py?answer=77695 Gmail''s instructions] for help. (IMAP is enabled on new Gmail accounts by default.)
<!-- 
remove the following paragraph in Thunderbird 38 when google''s non standard
auth is implemented
-->
Double check that "Access for less secure apps" is enabled. See [https://www.google.com/settings/security/lesssecureapps Google''s article on "less secure apps"] for help.

Next, select {menu File | New | Existing Mail Account...}. The "Mail Account Setup" dialog is displayed. After you provide your account information, Thunderbird will automatically configure your Gmail connection. 

For more detailed information, please refer to:
* [[Automatic Account Configuration]] 
* [http://mail.google.com/support/bin/answer.py?answer=180189 First steps with IMAP on Gmail]  
* [http://mail.google.com/support/bin/topic.py?topic=12806 Gmail''s IMAP tips]

= Archiving messages =

In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the "All Mail" folder, and not in an "Archive" folder as it does for other accounts (as described in the [[Archived Messages]] article).

[[Image:Gmail Archive settings]] 

Note that the {button Archive options...} button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.

= Subscribing to folders and synchronizing messages =
== Understanding Gmail labels and Thunderbird folders ==
Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.

In the example shown below, the folders at the same level as the "''''[Gmail]''''" folder ("g+", "Personal", "Receipts", "Travel" and "Work") correspond to Gmail labels.<br> <!--changed order according to screenshot (Artist, Sept. 23, 2014) -->

[[Image:default gmail folders]] <br>

There is also a set of special sub-folders for the "<i>[Gmail]</i> " folder:
* All Mail: contains all of the messages in your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the ''''[Gmail]/All Mail'''' folder.
* Drafts: contains draft messages.
* Sent Mail: contains sent messages.
* Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
* Starred: contains messages that were starred (either by Gmail or Thunderbird).
* Trash: contains deleted messages.
* Important: contains messages that Gmail has flagged as "important". (See [http://support.google.com/mail/bin/answer.py?answer=186531&topic=1669050&ctx=topic Priority Inbox overview] for more details about this Gmail feature.)

Note that a message can have multiple labels (for instance, "Personal", "Travel", "All Mail" and "Starred"). In this case, a copy of this message will be downloaded and displayed in all the corresponding Thunderbird''s folders.

== Subscribing to or unsubscribing from folders (labels) ==

You can configure which Gmail folders you want to display in Thunderbird. By default all Gmail folders are displayed, as described above. To configure folder display, right-click any folder and select {menu Subscribe}. <br><!-- removed horizontal ellipsis because the menu shown in the screenshot does not show any (unless it is outdated) Artist, Sept. 23, 2014 -->

[[Image:subscribe gmail folders]] 

Uncheck any folders that you don''t want to display in Thunderbird. Messages will still be downloaded and available through the "All Mail" folder. They will also be included in search results. However, the Gmail label (Thunderbird folder) will not be displayed. 


== Synchronizing folders (labels) ==

If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click on the message header.

To change how messages are downloaded, set synchronization options for the account and for individual folders. ({for win,mac}{menu Tools | Account Settings...}{/for}{for linux}{menu Edit | Account Settings...}{/for}) See [[IMAP Synchronization#w_synchronization]] for more information.


= Useful Add-ons =
* If you want to sync your contacts between Thunderbird and Gmail, you should try either the [https://addons.mozilla.org/thunderbird/addon/google-contacts/ Google Contacts] or [https://addons.mozilla.org/thunderbird/addon/gcontactsync gContactSync] add-ons.
* If you want to sync your calendar between Lightning and Google Calendar, you should read [[Using Lightning with Google Calendar]].
* [https://addons.mozilla.org/thunderbird/addon/flat-folder-tree Flat Folder Tree]  is useful to show all the sub-folders of the [Gmail] IMAP''s folder at the same level than your other folders.
* [https://addons.mozilla.org/thunderbird/addon/gmailbuttons Gmail Buttons] makes it easier to move messages to the Trash and Spam folders. Beta version also shows all Gmail labels for each message.

= Gmail and BCC addresses =

When you are using a mail client (such as Thunderbird, Outlook, Entourage, etc.)  with a Gmail account and your account is configured to synchronize mail using the IMAP protocol, you cannot see BCC message recipients when you look at the message in the "Sent Mail" folder. (See [[Configure an Account]] for a description of the IMAP and POP protocols.)

For example, say that you sent a message with the following recipients:

[[Image:75cc304ad20b8d48904ad675f7dafcef-1295389047-245-1.jpg]]

If you subsequently viewed the message in the "Sent Mail" folder, only the "To" and "CC" addresses would be shown as message recipients. This is because Gmail strips the BCC recipient(s) from messages. The message is sent to the BCC recipient, but the BCC recipient is not displayed in the saved sent message. (The BCC recipient is also not displayed on Gmail''s web-based interface if the message originated in Thunderbird.)

To work around this problem, use the Gmail web interface to send messages when you need to include a BCC recipient. Alternatively, use an SMTP server other than Gmail''s. For example, your Internet Service Provider (ISP) probably provides access to an SMTP server, which you could use to send messages. (See [[Configure an Account]] for help.)

For more information on this topic, see [https://support.google.com/mail/answer/78892?hl=en Gmail''s support article].','<p>Thunderbird can be configured to work seamlessly with Google''s <a href="http://gmail.google.com">Gmail</a> service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.
</p>
<div class="warning"><strong>Gmail accounts created on or about June 2014 (exact date unknown, Google only mentions <a href="http://googleonlinesecurity.blogspot.ca/2014/04/new-security-measures-will-affect-older.html">"second half of 2014" in their new authentication blog post</a>) won''t work with Thunderbird until the Thunderbird team implements Google''s non-email-standard authentication</strong>. This is currently scheduled for Thunderbird 38 which will be released on May 12, 2015. See <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=849540">bug 849540 for the full technical details</a>.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configuring-your-gmail-account"><span class="tocnumber">1</span> <span class="toctext">Configuring your Gmail account</span></a></li><li class="toclevel-1"><a href="#w_archiving-messages"><span class="tocnumber">2</span> <span class="toctext">Archiving messages</span></a></li><li class="toclevel-1"><a href="#w_subscribing-to-folders-and-synchronizing-messages"><span class="tocnumber">3</span> <span class="toctext">Subscribing to folders and synchronizing messages</span></a><ul><li class="toclevel-2"><a href="#w_understanding-gmail-labels-and-thunderbird-folders"><span class="tocnumber">3.1</span> <span class="toctext">Understanding Gmail labels and Thunderbird folders</span></a></li><li class="toclevel-2"><a href="#w_subscribing-to-or-unsubscribing-from-folders-labels"><span class="tocnumber">3.2</span> <span class="toctext">Subscribing to or unsubscribing from folders (labels)</span></a></li><li class="toclevel-2"><a href="#w_synchronizing-folders-labels"><span class="tocnumber">3.3</span> <span class="toctext">Synchronizing folders (labels)</span></a></li></ul></li><li class="toclevel-1"><a href="#w_useful-add-ons"><span class="tocnumber">4</span> <span class="toctext">Useful Add-ons</span></a></li><li class="toclevel-1"><a href="#w_gmail-and-bcc-addresses"><span class="tocnumber">5</span> <span class="toctext">Gmail and BCC addresses</span></a></li></ul></div>
<h1 id="w_configuring-your-gmail-account">Configuring your Gmail account</h1>
<p>To configure Thunderbird to work with Gmail, first enable IMAP on your Gmail account. 
See <a href="http://mail.google.com/support/bin/answer.py?answer=77695">Gmail''s instructions</a> for help. (IMAP is enabled on new Gmail accounts by default.)

Double check that "Access for less secure apps" is enabled. See <a href="https://www.google.com/settings/security/lesssecureapps">Google''s article on "less secure apps"</a> for help.
</p><p>Next, select <span class="menu">File | New | Existing Mail Account...</span>. The "Mail Account Setup" dialog is displayed. After you provide your account information, Thunderbird will automatically configure your Gmail connection. 
</p><p>For more detailed information, please refer to:
</p>
<ul><li> <a href="/en-US/kb/automatic-account-configuration">Automatic Account Configuration</a> 
</li><li> <a href="http://mail.google.com/support/bin/answer.py?answer=180189">First steps with IMAP on Gmail</a>  
</li><li> <a href="http://mail.google.com/support/bin/topic.py?topic=12806">Gmail''s IMAP tips</a>
</li></ul>
<h1 id="w_archiving-messages">Archiving messages</h1>
<p>In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the "All Mail" folder, and not in an "Archive" folder as it does for other accounts (as described in the <a href="/en-US/kb/archived-messages">Archived Messages</a> article).
</p><p><img alt="Gmail Archive settings" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-17-04-13-09-41649e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>Note that the <span class="button">Archive options...</span> button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.
</p>
<h1 id="w_subscribing-to-folders-and-synchronizing-messages">Subscribing to folders and synchronizing messages</h1>
<h2 id="w_understanding-gmail-labels-and-thunderbird-folders">Understanding Gmail labels and Thunderbird folders</h2>
<p>Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.
</p><p>In the example shown below, the folders at the same level as the "<em>[Gmail]</em>" folder ("g+", "Personal", "Receipts", "Travel" and "Work") correspond to Gmail labels.<br> 
</p><p><img alt="default gmail folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-22-16-07-48-8304a9.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> <br>
</p><p>There is also a set of special sub-folders for the "<i>[Gmail]</i>&nbsp;" folder:
</p>
<ul><li> All Mail: contains all of the messages in your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the <em>[Gmail]/All Mail</em> folder.
</li><li> Drafts: contains draft messages.
</li><li> Sent Mail: contains sent messages.
</li><li> Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
</li><li> Starred: contains messages that were starred (either by Gmail or Thunderbird).
</li><li> Trash: contains deleted messages.
</li><li> Important: contains messages that Gmail has flagged as "important". (See <a href="http://support.google.com/mail/bin/answer.py?answer=186531&amp;topic=1669050&amp;ctx=topic">Priority Inbox overview</a> for more details about this Gmail feature.)
</li></ul>
<p>Note that a message can have multiple labels (for instance, "Personal", "Travel", "All Mail" and "Starred"). In this case, a copy of this message will be downloaded and displayed in all the corresponding Thunderbird''s folders.
</p>
<h2 id="w_subscribing-to-or-unsubscribing-from-folders-labels">Subscribing to or unsubscribing from folders (labels)</h2>
<p>You can configure which Gmail folders you want to display in Thunderbird. By default all Gmail folders are displayed, as described above. To configure folder display, right-click any folder and select <span class="menu">Subscribe</span>. <br>
</p><p><img alt="subscribe gmail folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-22-16-20-21-1f5531.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>Uncheck any folders that you don''t want to display in Thunderbird. Messages will still be downloaded and available through the "All Mail" folder. They will also be included in search results. However, the Gmail label (Thunderbird folder) will not be displayed. 
</p><p><br>
</p>
<h2 id="w_synchronizing-folders-labels">Synchronizing folders (labels)</h2>
<p>If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click on the message header.
</p><p>To change how messages are downloaded, set synchronization options for the account and for individual folders. (<span class="for" data-for="win,mac"><span class="menu">Tools | Account Settings...</span></span><span class="for" data-for="linux" style="display: none;"><span class="menu">Edit | Account Settings...</span></span>) See <a href="/en-US/kb/imap-synchronization#w_synchronization">IMAP Synchronization</a> for more information.
</p><p><br>
</p>
<h1 id="w_useful-add-ons">Useful Add-ons</h1>
<ul><li> If you want to sync your contacts between Thunderbird and Gmail, you should try either the <a href="https://addons.mozilla.org/thunderbird/addon/google-contacts/">Google Contacts</a> or <a href="https://addons.mozilla.org/thunderbird/addon/gcontactsync">gContactSync</a> add-ons.
</li><li> If you want to sync your calendar between Lightning and Google Calendar, you should read <a href="/en-US/kb/using-lightning-google-calendar">Using Thunderbird with Google Calendar</a>.
</li><li> <a href="https://addons.mozilla.org/thunderbird/addon/flat-folder-tree">Flat Folder Tree</a>  is useful to show all the sub-folders of the [Gmail] IMAP''s folder at the same level than your other folders.
</li><li> <a href="https://addons.mozilla.org/thunderbird/addon/gmailbuttons">Gmail Buttons</a> makes it easier to move messages to the Trash and Spam folders. Beta version also shows all Gmail labels for each message.
</li></ul>
<h1 id="w_gmail-and-bcc-addresses">Gmail and BCC addresses</h1>
<p>When you are using a mail client (such as Thunderbird, Outlook, Entourage, etc.)  with a Gmail account and your account is configured to synchronize mail using the IMAP protocol, you cannot see BCC message recipients when you look at the message in the "Sent Mail" folder. (See <a class="new" href="/en-US/kb/new?title=Configure+an+Account" title="Page does not exist.">Configure an Account</a> for a description of the IMAP and POP protocols.)
</p><p>For example, say that you sent a message with the following recipients:
</p><p><img alt="75cc304ad20b8d48904ad675f7dafcef-1295389047-245-1.jpg" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-03-14-10-05-42-b419eb.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p>If you subsequently viewed the message in the "Sent Mail" folder, only the "To" and "CC" addresses would be shown as message recipients. This is because Gmail strips the BCC recipient(s) from messages. The message is sent to the BCC recipient, but the BCC recipient is not displayed in the saved sent message. (The BCC recipient is also not displayed on Gmail''s web-based interface if the message originated in Thunderbird.)
</p><p>To work around this problem, use the Gmail web interface to send messages when you need to include a BCC recipient. Alternatively, use an SMTP server other than Gmail''s. For example, your Internet Service Provider (ISP) probably provides access to an SMTP server, which you could use to send messages. (See <a class="new" href="/en-US/kb/new?title=Configure+an+Account" title="Page does not exist.">Configure an Account</a> for help.)
</p><p>For more information on this topic, see <a href="https://support.google.com/mail/answer/78892?hl=en">Gmail''s support article</a>.
</p>','[{"label": "Revision id", "text": "91185", "datetime": null, "href": null}, {"label": "Created", "text": "Mar 6, 2015, 10:51:29 AM", "datetime": "2015-03-06T10:51:29-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "thunderbird 38 is may 12, 2015 not april 2015; otherwise minor edits", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Mar 6, 2015, 10:51:42 AM", "datetime": "2015-03-06T10:51:42-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Mar 6, 2015, 10:51:42 AM", "datetime": "2015-03-06T10:51:42-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:43:56+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (94429,'en-US','calendar-integration-thunderbird','Calendar integration into Thunderbird','https://support.mozilla.org/en-US/kb/calendar-integration-thunderbird','https://support.mozilla.org/en-US/kb/calendar-integration-thunderbird/revision/94429',94255,'2015-05-11T14:11:28-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','remove en-us from links',1,'2015-05-11T14:12:27-07:00','rtanglao',1,0,1,'2015-05-11T14:21:32-07:00','rtanglao','approved','Starting with Thunderbird 38, the calendaring extension [https://addons.mozilla.org/thunderbird/addon/lightning/ Lightning] has been packaged with Thunderbird. This is a big advantage for previous Lightning users, because a compatible version of Lightning is always available with Thunderbird. It is also a great opportunity for Thunderbird users that haven''t been using Lightning, as it becomes easier to process emails that contain invitations.

[[Image:calendar interface]]

Maintain your schedule locally using the precreated "Home" calendar, or synchronize with a remote calendar using iCalendar files on a WebDAV server or a calendaring server supporting the CalDAV protocol. There are also extensions available for enhanced Google Calendar support and Microsoft Exchange among others. You can find them on [https://addons.mozilla.org/thunderbird/search/?cat=1%252C0&q=provider&platform=all&appver=any addons.mozilla.org]. An article on [[creating new calendars|creating new calendars]] is available for more information.

For more information, you can read more on [[Using the Lightning Calendar Add-on|using Lightning]] or visit the [https://support.mozilla.org/products/thunderbird/calendar calendar overview page] for more support topics.

This integration of course does not mean that you must use  Lightning. You are free to disable it at any time, but for the sake of making it easier to identify issues in the future, it is recommended to leave it enabled and hide the features you do not use. There should not be a notable performance impact, especially when you have not added any events. You can hide the "Today Pane" by clicking the button in the status bar at the bottom of the screen. 

[[Image:lightning-today-pane-button]].','<p>Starting with Thunderbird 38, the calendaring extension <a href="https://addons.mozilla.org/thunderbird/addon/lightning/">Lightning</a> has been packaged with Thunderbird. This is a big advantage for previous Lightning users, because a compatible version of Lightning is always available with Thunderbird. It is also a great opportunity for Thunderbird users that haven''t been using Lightning, as it becomes easier to process emails that contain invitations.
</p><p><img alt="calendar interface" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-06-19-13-56-12-b23803.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p>Maintain your schedule locally using the precreated "Home" calendar, or synchronize with a remote calendar using iCalendar files on a WebDAV server or a calendaring server supporting the CalDAV protocol. There are also extensions available for enhanced Google Calendar support and Microsoft Exchange among others. You can find them on <a href="https://addons.mozilla.org/thunderbird/search/?cat=1%252C0&amp;q=provider&amp;platform=all&amp;appver=any">addons.mozilla.org</a>. An article on <a class="new" href="/en-US/kb/new?title=creating+new+calendars" title="Page does not exist.">creating new calendars</a> is available for more information.
</p><p>For more information, you can read more on <a href="/en-US/kb/using-lightning-calendar-add-on">using Lightning</a> or visit the <a href="https://support.mozilla.org/products/thunderbird/calendar">calendar overview page</a> for more support topics.
</p><p>This integration of course does not mean that you must use  Lightning. You are free to disable it at any time, but for the sake of making it easier to identify issues in the future, it is recommended to leave it enabled and hide the features you do not use. There should not be a notable performance impact, especially when you have not added any events. You can hide the "Today Pane" by clicking the button in the status bar at the bottom of the screen. 
</p><p><img alt="lightning-today-pane-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-05-09-06-27-26-87dc39.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</p>','[{"label": "Revision id", "text": "94429", "datetime": null, "href": null}, {"label": "Created", "text": "May 11, 2015, 2:11:28 PM", "datetime": "2015-05-11T14:11:28-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "remove en-us from links", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "May 11, 2015, 2:12:27 PM", "datetime": "2015-05-11T14:12:27-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "May 11, 2015, 2:21:32 PM", "datetime": "2015-05-11T14:21:32-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:43:54+00:00');
