INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (94640,'en-US','calendar-integration-thunderbird','Calendar integration into Thunderbird','https://support.mozilla.org/en-US/kb/calendar-integration-thunderbird','https://support.mozilla.org/en-US/kb/calendar-integration-thunderbird/revision/94640',94429,'2015-05-14T06:24:30-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fix minor typos',1,'2015-05-14T06:25:15-07:00','rtanglao',1,0,1,'2015-05-14T06:25:15-07:00','rtanglao','approved','Starting with Thunderbird 38, the calendaring extension [https://addons.mozilla.org/thunderbird/addon/lightning/ Lightning] has been packaged with Thunderbird. This is a big advantage for previous Lightning users, because a compatible version of Lightning is always available with Thunderbird. It is also a great opportunity for Thunderbird users that haven''t been using Lightning as it becomes easier to process emails that contain invitations.

[[Image:calendar interface]]

Maintain your schedule locally using the pre-created "Home" calendar, or synchronize with a remote calendar using iCalendar files on a WebDAV server or a calendaring server supporting the CalDAV protocol. There are also extensions available for enhanced Google Calendar support and Microsoft Exchange among others. You can find them on [https://addons.mozilla.org/thunderbird/search/?cat=1%252C0&q=provider&platform=all&appver=any addons.mozilla.org]. An article on [[creating new calendars|creating new calendars]] is available for more information.

For more information read [[Using the Lightning Calendar Add-on|using Lightning]] or visit the [https://support.mozilla.org/products/thunderbird/calendar calendar overview page] for support topics.

This integration of course does not mean that you must use Lightning. If you haven''t used Lightning before, you can do this directly from the notification bar at the bottom of the Thunderbird window.

[[Image:Lightning-optout-bar]]

You are also free to disable Lightning at any time in the addons manager, but in order to make it easier to identify future issues it is recommended that you leave it enabled and hide the features you do not use. There should not be a significant  performance impact, especially when you have not added any events. You can hide the "Today Pane" by clicking the button in the status bar at the bottom of the screen. 

[[Image:lightning-today-pane-button]].','<p>Starting with Thunderbird 38, the calendaring extension <a href="https://addons.mozilla.org/thunderbird/addon/lightning/">Lightning</a> has been packaged with Thunderbird. This is a big advantage for previous Lightning users, because a compatible version of Lightning is always available with Thunderbird. It is also a great opportunity for Thunderbird users that haven''t been using Lightning as it becomes easier to process emails that contain invitations.
