</li><li>
</li></ol>','[{"label": "Revision id", "text": "96954", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 12, 2015, 9:24:23 AM", "datetime": "2015-06-12T09:24:23-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP do not approve, a better stub", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:43:24+00:00');
