# Click the Application menu button [[Image:New Fx Menu]].
# Click {menu {for win,linux}Options{/for}{for mac}Preferences{/for}} and then {for win,linux}{menu Options}{/for}{for mac}{menu Preferences}{/for}.
# Click {menu Advanced} and then click {menu General}.
# Next to "Message Store Type for new accounts", select {button File per message (maildir)}.
# Any email account created from now on will use Maildir (existing accounts will continue to use mbox). Please [https://bugzilla.mozilla.org/enter_bug.cgi?product=Thunderbird file a bug] if you encounter any Maildir issues.','<p>Thunderbird has had hidden support (Maildir is disabled by default) for the <a href="https://en.wikipedia.org/wiki/Maildir">Maildir</a> mail storage format for several years, but Maildir is still not 100% ready for users. This article explains the format change and how to test Maildir starting in Thunderbird 38 (Maildir is not ready for testing prior to version 38). 
</p>
<div class="warning">WARNING:Unless you are advanced and know how to backup your email before turning on Maildir and how to restore it if you run into problems, we suggest you leave Maildir disabled.</div>
<p>Maildir is a single file per email (<a href="https://en.wikipedia.org/wiki/Email#Filename_extensions">EML</a>), unlike the current default monolithic single file format, which is one file per folder (known as <a href="https://en.wikipedia.org/wiki/Mbox">mbox</a>). This storage format has significant benefits:
</p>
<ul><li> Backups are easier because the amount of data needed to be backed up is reduced to just those emails that have changed since the last backup.
</li><li> It is easier for anti-virus to scan emails in individual files, and infected mails can be removed without the loss of all the other mail in the folder, as often occurs today with anti-virus software which cannot handle multiple emails in one file.
</li></ul>
<p>This is a major change for Thunderbird because it changes the mail storage mechanism. The development team have spent a significant amount of time developing maildir. 
</p><p>However, due to a lack of time and testers before Thunderbird 38 was released, the actual underlying changes have not had the extensive manual testing that would normally occur for such a major change.
</p>
<h1 id="w_how-to-turn-on-maildir">How to turn on Maildir</h1>
<div class="warning">WARNING: Again, this feature is experimental and we recommend that you know how to file bugs and how to backup and restore your email before turning on Maildir.</div>
<p>Here''s how to turn on Maildir:
</p>
<ol><li> Backup your email. <strong>If you don''t know how to backup and restore your email, then you are not qualified to test Maildir.</strong>
</li><li> Click the Application menu button <img alt="New Fx Menu" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-01-10-13-08-08-f52b8c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> Click <span class="menu"><span class="for" data-for="win,linux" style="display: none;">Options</span><span class="for" data-for="mac">Preferences</span></span> and then <span class="for" data-for="win,linux" style="display: none;"><span class="menu">Options</span></span><span class="for" data-for="mac"><span class="menu">Preferences</span></span>.
</li><li> Click <span class="menu">Advanced</span> and then click <span class="menu">General</span>.
</li><li> Next to "Message Store Type for new accounts", select <span class="button">File per message (maildir)</span>.
</li><li> Any email account created from now on will use Maildir (existing accounts will continue to use mbox). Please <a href="https://bugzilla.mozilla.org/enter_bug.cgi?product=Thunderbird">file a bug</a> if you encounter any Maildir issues.
</li></ol>','[{"label": "Revision id", "text": "97175", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 15, 2015, 1:43:38 AM", "datetime": "2015-06-15T01:43:38-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "minor nits!", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jun 15, 2015, 1:43:48 AM", "datetime": "2015-06-15T01:43:48-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:43:01+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (97259,'en-US','new-thunderbird-38','New in Thunderbird 38.0','https://support.mozilla.org/en-US/kb/new-thunderbird-38','https://support.mozilla.org/en-US/kb/new-thunderbird-38/revision/97259',96851,'2015-06-16T05:44:58-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','now that the thunderbird and gmail has been updated to support oauth link to that article instead of the bug',1,'2015-06-16T05:45:29-07:00','rtanglao',1,0,1,'2015-06-16T05:45:29-07:00','rtanglao','approved','This article describes the major changes that are visible to users in Thunderbird version 38. Full details of all the changes can be found in the Thunderbird 38 [https://www.mozilla.org/en-US/thunderbird/38.0.1/releasenotes/ release notes].

__TOC__

=Chat supports Yahoo Messenger=
Thunderbird chat now supports [https://bugzilla.mozilla.org/show_bug.cgi?id=955574 Yahoo Messenger].

=Filtering sent/archived messages = 
You can now filter on [https://bugzilla.mozilla.org/show_bug.cgi?id=11039 sent] and [https://bugzilla.mozilla.org/show_bug.cgi?id=479823 archived] messages.

=Search multiple address books =
You can now [https://bugzilla.mozilla.org/show_bug.cgi?id=170270 search multiple address books]!

=Expanded Folder Pane columns=
In the  folder pane (the list of folders on the left), you can now show expanded options (Unread, Total and Size) {menu View|Layout|Folder Pane Columns}.

=Google OAuth2=
Thunderbird 38 [[Thunderbird and Gmail|now supports]] the [https://developers.google.com/gmail/oauth_overview OAuth 2.0 protocol] now used by Google for authentication.

=Calendar integration=
Starting in Thunderbird 38, the [[Integration into Thunderbird|Lightning]] calendar add-on is bundled with Thunderbird.

=Mail Composition Fixes=
Some idiosyncrasies in the message compose window have been addressed: The composition font is no longer lost after clicking elsewhere in the message and then returning to the end of the line of the text being entered. Also, the composition font is no longer lost after pasting a bitmap from the clipboard. The inline spell checker no longer loses red underlines.

Inline spell checking: New messages will now always be spell-checked in the language selected in {menu Tools|Options|Composition|Spelling|Language} and not as before in the last language used. Also, the spell checking language is now always synchronised between subject and message body. You can even compose messages in different languages concurrently now without having to switch dictionaries.

=Font Handling on Linux=
Linux provides system fonts "sans-serif", "serif" and "monospace". These font names conflict with the generic CSS font family names. Therefore and for compatibility with Thunderbirds on other platforms, the ability to compose messages using these three fonts was removed on Linux. Users who had selected one of these fonts as their default composition font have to select a different font. Instead of "sans-serif", "serif" or "monospace" users should select "Helvetica, Arial", "Times" or "Courier" (or "Fixed Width") respectively.

The three aforementioned Linux system fonts can still be used as default display fonts.','<p>This article describes the major changes that are visible to users in Thunderbird version 38. Full details of all the changes can be found in the Thunderbird 38 <a href="https://www.mozilla.org/en-US/thunderbird/38.0.1/releasenotes/">release notes</a>.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_chat-supports-yahoo-messenger"><span class="tocnumber">1</span> <span class="toctext">Chat supports Yahoo Messenger</span></a></li><li class="toclevel-1"><a href="#w_filtering-sentarchived-messages"><span class="tocnumber">2</span> <span class="toctext">Filtering sent/archived messages</span></a></li><li class="toclevel-1"><a href="#w_search-multiple-address-books"><span class="tocnumber">3</span> <span class="toctext">Search multiple address books</span></a></li><li class="toclevel-1"><a href="#w_expanded-folder-pane-columns"><span class="tocnumber">4</span> <span class="toctext">Expanded Folder Pane columns</span></a></li><li class="toclevel-1"><a href="#w_google-oauth2"><span class="tocnumber">5</span> <span class="toctext">Google OAuth2</span></a></li><li class="toclevel-1"><a href="#w_calendar-integration"><span class="tocnumber">6</span> <span class="toctext">Calendar integration</span></a></li><li class="toclevel-1"><a href="#w_mail-composition-fixes"><span class="tocnumber">7</span> <span class="toctext">Mail Composition Fixes</span></a></li><li class="toclevel-1"><a href="#w_font-handling-on-linux"><span class="tocnumber">8</span> <span class="toctext">Font Handling on Linux</span></a></li></ul></div>
<h1 id="w_chat-supports-yahoo-messenger">Chat supports Yahoo Messenger</h1>
<p>Thunderbird chat now supports <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=955574">Yahoo Messenger</a>.
</p>
<h1 id="w_filtering-sentarchived-messages">Filtering sent/archived messages</h1>
<p>You can now filter on <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=11039">sent</a> and <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=479823">archived</a> messages.
</p>
<h1 id="w_search-multiple-address-books">Search multiple address books</h1>
<p>You can now <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=170270">search multiple address books</a>!
</p>
<h1 id="w_expanded-folder-pane-columns">Expanded Folder Pane columns</h1>
<p>In the  folder pane (the list of folders on the left), you can now show expanded options (Unread, Total and Size) <span class="menu">View|Layout|Folder Pane Columns</span>.
</p>
<h1 id="w_google-oauth2">Google OAuth2</h1>
<p>Thunderbird 38 <a href="/en-US/kb/thunderbird-and-gmail">now supports</a> the <a href="https://developers.google.com/gmail/oauth_overview">OAuth 2.0 protocol</a> now used by Google for authentication.
</p>
<h1 id="w_calendar-integration">Calendar integration</h1>
<p>Starting in Thunderbird 38, the <a href="/en-US/kb/calendar-integration-thunderbird">Lightning</a> calendar add-on is bundled with Thunderbird.
</p>
<h1 id="w_mail-composition-fixes">Mail Composition Fixes</h1>
<p>Some idiosyncrasies in the message compose window have been addressed: The composition font is no longer lost after clicking elsewhere in the message and then returning to the end of the line of the text being entered. Also, the composition font is no longer lost after pasting a bitmap from the clipboard. The inline spell checker no longer loses red underlines.
</p><p>Inline spell checking: New messages will now always be spell-checked in the language selected in <span class="menu">Tools|Options|Composition|Spelling|Language</span> and not as before in the last language used. Also, the spell checking language is now always synchronised between subject and message body. You can even compose messages in different languages concurrently now without having to switch dictionaries.
</p>
<h1 id="w_font-handling-on-linux">Font Handling on Linux</h1>
<p>Linux provides system fonts "sans-serif", "serif" and "monospace". These font names conflict with the generic CSS font family names. Therefore and for compatibility with Thunderbirds on other platforms, the ability to compose messages using these three fonts was removed on Linux. Users who had selected one of these fonts as their default composition font have to select a different font. Instead of "sans-serif", "serif" or "monospace" users should select "Helvetica, Arial", "Times" or "Courier" (or "Fixed Width") respectively.
</p><p>The three aforementioned Linux system fonts can still be used as default display fonts.
</p>','[{"label": "Revision id", "text": "97259", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 16, 2015, 5:44:58 AM", "datetime": "2015-06-16T05:44:58-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "now that the thunderbird and gmail has been updated to support oauth link to that article instead of the bug", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jun 16, 2015, 5:45:29 AM", "datetime": "2015-06-16T05:45:29-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jun 16, 2015, 5:45:29 AM", "datetime": "2015-06-16T05:45:29-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:42:58+00:00');
