INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (101814,'en-US','clear-browsing-history-firefox-ios','Clear browsing history in Firefox for iOS','https://support.mozilla.org/en-US/kb/clear-browsing-history-firefox-ios','https://support.mozilla.org/en-US/kb/clear-browsing-history-firefox-ios/revision/101814',101470,'2015-08-11T16:15:14-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','you have to tap "Clear" in the "Clear Everything" dialog',1,'2015-08-11T16:15:35-07:00','rtanglao',1,0,1,'2015-08-11T16:15:35-07:00','rtanglao','approved','Firefox stores websites you''ve visited in your history as you browse the Web. Follow these steps to delete your history.

#[[Template:tabios]]
#[[Template:settingsios]]
#In the Firefox Settings menu, tap {menu Clear Private Data}.
#In the {menu Clear Everything} dialog, tap {button Clear} to clear all of your data including history and close all of your tabs.','<p>Firefox stores websites you''ve visited in your history as you browse the Web. Follow these steps to delete your history.
</p>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap <span class="menu">Settings</span> in the menu panel.

</li><li>In the Firefox Settings menu, tap <span class="menu">Clear Private Data</span>.
</li><li>In the <span class="menu">Clear Everything</span> dialog, tap <span class="button">Clear</span> to clear all of your data including history and close all of your tabs.
</li></ol>','[{"label": "Revision id", "text": "101814", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 11, 2015, 4:15:14 PM", "datetime": "2015-08-11T16:15:14-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "you have to tap \"Clear\" in the \"Clear Everything\" dialog", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 11, 2015, 4:15:35 PM", "datetime": "2015-08-11T16:15:35-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 11, 2015, 4:15:35 PM", "datetime": "2015-08-11T16:15:35-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:42:54+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (101890,'en-US','use-tabs-firefox-ios','Use tabs in Firefox for iOS','https://support.mozilla.org/en-US/kb/use-tabs-firefox-ios','https://support.mozilla.org/en-US/kb/use-tabs-firefox-ios/revision/101890',101806,'2015-08-12T06:09:16-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','resize tap the + sign at the top of the badge and put a red box around +',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Use tabs to open, view and manage multiple web pages in Firefox for iOS.

=Open a tab=
#[[Template:tabios]]
#Tap the plus sign at the top of the screen.
;[[Image:v1-ios-add-tab]]

=Close a tab=
#[[Template:tabios]]
#Tap the x on the window you want to close.  [[Image:FxiOSshut]]  

{note}''''''Tip'''''': You can also swipe a window to the side to close it.{/note}

=View tabs=
#[[Template:tabios]]

Your open tabs will display on the screen:
*Compact tab view
*;[[Image:compact tabs ios]]

*Full-size tab view
*;[[Image:regular tabs ios]]

To change your tab view, see [[Change the tab list view in Firefox for iOS]].','<p>Use tabs to open, view and manage multiple web pages in Firefox for iOS.
</p>
<h1 id="w_open-a-tab">Open a tab</h1>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap the plus sign at the top of the screen.
</li></ol>
<dl><dt><img alt="v1-ios-add-tab" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-12-13-04-26-058740.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<h1 id="w_close-a-tab">Close a tab</h1>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap the x on the window you want to close.  <img alt="FxiOSshut" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-12-10-44-32-716f6b.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">  
</li></ol>
<div class="note"><strong>Tip</strong>: You can also swipe a window to the side to close it.</div>
<h1 id="w_view-tabs">View tabs</h1>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li></ol>
<p>Your open tabs will display on the screen:
</p>
<ul><li>Compact tab view
<dl><dt><img alt="compact tabs ios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-11-17-11-20-0f073e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
<ul><li>Full-size tab view
<dl><dt><img alt="regular tabs ios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-11-17-27-05-a988b5.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
<p>To change your tab view, see <a href="/en-US/kb/change-the-tab-list-view-in-firefox-for-ios">Change the tab list view in Firefox for iOS</a>.
</p>','[{"label": "Revision id", "text": "101890", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 12, 2015, 6:09:16 AM", "datetime": "2015-08-12T06:09:16-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "resize tap the + sign at the top of the badge and put a red box around +", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:42:45+00:00');
