INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (101921,'en-US','uninstall-firefox-ios','Uninstall Firefox for iOS','https://support.mozilla.org/en-US/kb/uninstall-firefox-ios','https://support.mozilla.org/en-US/kb/uninstall-firefox-ios/revision/101921',101711,'2015-08-12T14:18:21-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','we can add a screenshot when firefox goes to v1.0!',1,'2015-08-12T14:18:54-07:00','rtanglao',1,0,1,'2015-08-12T14:18:54-07:00','rtanglao','approved','If Firefox isn''t for you, uninstalling it only takes a few seconds:

#Touch and hold the Firefox icon until it shakes.
#Tap the ''''X'''' on the icon.
#Tap {button Delete} on the confirmation prompt to finish.
;<!--insert screenshot here. It still says fennec/aurora [[Image:-->

To reinstall Firefox in the future, see [[Install Firefox on your iPad, iPhone or iPod]].','<p>If Firefox isn''t for you, uninstalling it only takes a few seconds:
</p>
<ol><li>Touch and hold the Firefox icon until it shakes.
</li><li>Tap the <em>X</em> on the icon.
</li><li>Tap <span class="button">Delete</span> on the confirmation prompt to finish.
</li></ol>
<dl><dt>
</dt></dl>
<p>To reinstall Firefox in the future, see <a href="/en-US/kb/install-firefox-your-ipad-iphone-or-ipod">Install Firefox on your iPad, iPhone or iPod</a>.
</p>','[{"label": "Revision id", "text": "101921", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 12, 2015, 2:18:21 PM", "datetime": "2015-08-12T14:18:21-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "we can add a screenshot when firefox goes to v1.0!", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 12, 2015, 2:18:54 PM", "datetime": "2015-08-12T14:18:54-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 12, 2015, 2:18:54 PM", "datetime": "2015-08-12T14:18:54-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:42:40+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (101922,'en-US','change-the-tab-list-view-in-firefox-for-ios','Change the tab list view in Firefox for iOS','https://support.mozilla.org/en-US/kb/change-the-tab-list-view-in-firefox-for-ios','https://support.mozilla.org/en-US/kb/change-the-tab-list-view-in-firefox-for-ios/revision/101922',101697,'2015-08-12T14:30:41-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','add regular view screenshot',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Firefox lets you change the size of your tabs on the tab list.

=Compact Tabs=
If you prefer to minimize scrolling, set Firefox to use Compact Tabs to see more of them in one view.
#[[Template:tabios]]
#[[Template:settingsios]]
#Tap the switch next to ''''Use Compact Tabs'''' to turn it on: [[Image:switchonios]]

<!--Compact tabs Screenshot here-->


=Regular view=
To view larger, but fewer tabs on your tab list, turn off Compact Tabs:
#[[Template:tabios]]
#[[Template:settingsios]]
#Tap the switch next to ''''Use Compact Tabs'''' to turn it off: [[Image:switchoffios]]
#;[[Image:FxiOS-regular-tab-view]]

{note}''''''Learn more about tabs'''''' by visiting [[Use tabs in Firefox for iOS]].{/note}','<p>Firefox lets you change the size of your tabs on the tab list.
</p>
<h1 id="w_compact-tabs">Compact Tabs</h1>
<p>If you prefer to minimize scrolling, set Firefox to use Compact Tabs to see more of them in one view.
</p>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap <span class="menu">Settings</span> in the menu panel.

</li><li>Tap the switch next to <em>Use Compact Tabs</em> to turn it on: <img alt="switchonios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2017-11-01-22-03-04-3327d9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ol>
<p>
</p><p><br>
</p>
<h1 id="w_regular-view">Regular view</h1>
<p>To view larger, but fewer tabs on your tab list, turn off Compact Tabs:
</p>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap <span class="menu">Settings</span> in the menu panel.

</li><li>Tap the switch next to <em>Use Compact Tabs</em> to turn it off: <img alt="switchoffios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-07-18-34-36-7e3f4a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
<dl><dt><img alt="FxiOS-regular-tab-view" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-12-21-29-53-d8dd3a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ol>
<div class="note"><strong>Learn more about tabs</strong> by visiting <a href="/en-US/kb/use-tabs-firefox-ios">Use tabs in Firefox for iOS</a>.</div>','[{"label": "Revision id", "text": "101922", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 12, 2015, 2:30:41 PM", "datetime": "2015-08-12T14:30:41-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "add regular view screenshot", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:42:38+00:00');
