INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (105406,'en-US','cannot-send-messages','Cannot send messages','https://support.mozilla.org/en-US/kb/cannot-send-messages','https://support.mozilla.org/en-US/kb/cannot-send-messages/revision/105406',79253,'2015-09-28T04:46:46-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fixed some of the links over lunch, more link cleanup needed!',1,'2015-09-28T04:47:43-07:00','rtanglao',1,0,1,'2015-09-28T04:48:08-07:00','rtanglao','approved','If you cannot send messages, this page provides a series of steps you can use to check for common problems.

__TOC__


= Verify your SMTP outgoing email settings =

* ''''''Tools|Account Settings...'''''' and then select ''''''Outgoing Server (SMTP)'''''' from the bottom of the list on the left side of the panel. Check that the settings are the same as documented on the mail settings article for your mail provider on support.mozilla.org [[(Thunderbird and Gmail|Gmail]], [[Thunderbird and Yahoo|Yahoo]], [[Thunderbird and Comcast|Comcast]], [[Thunderbird and Hotmail|Hotmail]], [[Thunderbird and Sympatico|Sympatico]]) ''''''OR''''''

* If there is no support.mozilla.org article with your specific mail provider''s mail settings then look for an SMTP mail settings article on the mail provider''s site. This is usually in the support section of their website; searching for "mail settings" or "SMTP" will usually find it. Check that your Thunderbird settings match the documented settings.


[[Image:fbc7355532a508eb55186ebf7bbb1cd1-1277326689-659-1.jpg]]


= Verify the correct SMTP Server is being used =

* ''''''Tools|Account Settings...'''''' Verify that you are using the right SMTP server for the email address. Most of the time you cannot send messages from one account provider using another account provider''s service. For example, you cannot send a mail from "joe@gmail.com" through Yahoo''s SMTP server.

[[Image:fbc7355532a508eb55186ebf7bbb1cd1-1277326770-967-1.jpg]]


= Verify that your outgoing email is not being blocked =

Verify that your outgoing email is not being blocked by your firewall, anti-virus software or your Internet Service Provider:

* Try briefly turning both anti-virus and firewall off, sending a test email and turning them on and sending another test email.
* Many ISPs block outgoing email on port 25. You may have to switch to another port (e.g. 587 or 465). Contact your ISP''s support to see if they are blocking your outgoing email port.

= Delete SMTP Password =

Try [https://support.mozilla.org/kb/configuration-options-security#w_view-or-delete-passwords-for-email-accounts deleting your SMTP password].

= Reset SMTP Password =

Try changing your SMTP password. This is usually done via a ''reset email password'' form on your ISP''s support website.

= If this list doesn''t help =

Please [https://support.mozilla.org/questions/new/thunderbird create a ''''new'''' support request] with a screenshot of your SMTP settings with your userid obscured and include the following information: your mail provider (for example, Gmail), ISP (for example, Comcast), firewall version (if any), anti-virus software and version (if any), operating system and version (for example Windows 7 or Mac OS X Leopard), Thunderbird version (for example Thunderbird 3.0.5). (How to make a screenshot: [http://www.wikihow.com/Take-a-Screenshot-in-Microsoft-Windows Windows], [http://www.wikihow.com/Take-a-Screenshot-in-Mac-OS-X Mac])

= More resources =

*[http://kb.mozillazine.org/Cannot_send_mail MozillaZine''s technical but very helpful knowledge base article on this topic]
* [https://wiki.mozilla.org/Thunderbird:Testing:Antivirus_Related_Performance_Issues Thunderbird 3 and Anti-Virus related issues]','<p>If you cannot send messages, this page provides a series of steps you can use to check for common problems.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_verify-your-smtp-outgoing-email-settings"><span class="tocnumber">1</span> <span class="toctext">Verify your SMTP outgoing email settings</span></a></li><li class="toclevel-1"><a href="#w_verify-the-correct-smtp-server-is-being-used"><span class="tocnumber">2</span> <span class="toctext">Verify the correct SMTP Server is being used</span></a></li><li class="toclevel-1"><a href="#w_verify-that-your-outgoing-email-is-not-being-blocked"><span class="tocnumber">3</span> <span class="toctext">Verify that your outgoing email is not being blocked</span></a></li><li class="toclevel-1"><a href="#w_delete-smtp-password"><span class="tocnumber">4</span> <span class="toctext">Delete SMTP Password</span></a></li><li class="toclevel-1"><a href="#w_reset-smtp-password"><span class="tocnumber">5</span> <span class="toctext">Reset SMTP Password</span></a></li><li class="toclevel-1"><a href="#w_if-this-list-doesnt-help"><span class="tocnumber">6</span> <span class="toctext">If this list doesn''t help</span></a></li><li class="toclevel-1"><a href="#w_more-resources"><span class="tocnumber">7</span> <span class="toctext">More resources</span></a></li></ul></div>
<p><br>
</p>
<h1 id="w_verify-your-smtp-outgoing-email-settings">Verify your SMTP outgoing email settings</h1>
<ul><li> <strong>Tools|Account Settings...</strong> and then select <strong>Outgoing Server (SMTP)</strong> from the bottom of the list on the left side of the panel. Check that the settings are the same as documented on the mail settings article for your mail provider on <a href="http://support.mozilla.org">support.mozilla.org</a> <a class="new" href="/en-US/kb/new?title=%28Thunderbird+and+Gmail" title="Page does not exist.">Gmail</a>, <a href="/en-US/kb/thunderbird-and-yahoo">Yahoo</a>, <a href="/en-US/kb/thunderbird-and-comcast">Comcast</a>, <a href="/en-US/kb/thunderbird-and-hotmail">Hotmail</a>, <a href="/en-US/kb/thunderbird-and-sympatico">Sympatico</a>) <strong>OR</strong>
</li></ul>
<ul><li> If there is no <a href="http://support.mozilla.org">support.mozilla.org</a> article with your specific mail provider''s mail settings then look for an SMTP mail settings article on the mail provider''s site. This is usually in the support section of their website; searching for "mail settings" or "SMTP" will usually find it. Check that your Thunderbird settings match the documented settings.
</li></ul>
<p><br>
<img alt="fbc7355532a508eb55186ebf7bbb1cd1-1277326689-659-1.jpg" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-03-14-10-05-42-6d0685.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p><br>
</p>
<h1 id="w_verify-the-correct-smtp-server-is-being-used">Verify the correct SMTP Server is being used</h1>
<ul><li> <strong>Tools|Account Settings...</strong> Verify that you are using the right SMTP server for the email address. Most of the time you cannot send messages from one account provider using another account provider''s service. For example, you cannot send a mail from "<a href="mailto:joe@gmail.com">joe@gmail.com</a>" through Yahoo''s SMTP server.
</li></ul>
<p><img alt="fbc7355532a508eb55186ebf7bbb1cd1-1277326770-967-1.jpg" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-03-14-10-07-36-101def.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p><p><br>
</p>
<h1 id="w_verify-that-your-outgoing-email-is-not-being-blocked">Verify that your outgoing email is not being blocked</h1>
<p>Verify that your outgoing email is not being blocked by your firewall, anti-virus software or your Internet Service Provider:
</p>
<ul><li> Try briefly turning both anti-virus and firewall off, sending a test email and turning them on and sending another test email.
</li><li> Many ISPs block outgoing email on port 25. You may have to switch to another port (e.g. 587 or 465). Contact your ISP''s support to see if they are blocking your outgoing email port.
</li></ul>
<h1 id="w_delete-smtp-password">Delete SMTP Password</h1>
<p>Try <a href="https://support.mozilla.org/kb/configuration-options-security#w_view-or-delete-passwords-for-email-accounts">deleting your SMTP password</a>.
</p>
<h1 id="w_reset-smtp-password">Reset SMTP Password</h1>
<p>Try changing your SMTP password. This is usually done via a ''reset email password'' form on your ISP''s support website.
</p>
<h1 id="w_if-this-list-doesnt-help">If this list doesn''t help</h1>
<p>Please <a href="https://support.mozilla.org/questions/new/thunderbird">create a <em>new</em> support request</a> with a screenshot of your SMTP settings with your userid obscured and include the following information: your mail provider (for example, Gmail), ISP (for example, Comcast), firewall version (if any), anti-virus software and version (if any), operating system and version (for example Windows 7 or Mac OS X Leopard), Thunderbird version (for example Thunderbird 3.0.5). (How to make a screenshot: <a href="http://www.wikihow.com/Take-a-Screenshot-in-Microsoft-Windows">Windows</a>, <a href="http://www.wikihow.com/Take-a-Screenshot-in-Mac-OS-X">Mac</a>)
</p>
<h1 id="w_more-resources">More resources</h1>
<ul><li><a href="http://kb.mozillazine.org/Cannot_send_mail">MozillaZine''s technical but very helpful knowledge base article on this topic</a>
</li><li> <a href="https://wiki.mozilla.org/Thunderbird:Testing:Antivirus_Related_Performance_Issues">Thunderbird 3 and Anti-Virus related issues</a>
</li></ul>','[{"label": "Revision id", "text": "105406", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 28, 2015, 4:46:46 AM", "datetime": "2015-09-28T04:46:46-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fixed some of the links over lunch, more link cleanup needed!", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 28, 2015, 4:47:43 AM", "datetime": "2015-09-28T04:47:43-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Sep 28, 2015, 4:48:08 AM", "datetime": "2015-09-28T04:48:08-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:42:17+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (106644,'en-US','scan-qr-codes-firefox-android','Scan QR codes in Firefox for Android','https://support.mozilla.org/en-US/kb/scan-qr-codes-firefox-android','https://support.mozilla.org/en-US/kb/scan-qr-codes-firefox-android/revision/106644',106080,'2015-10-16T13:34:18-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','re-added beta template, corrected minor typos and a few style edits',1,'2015-10-16T13:35:43-07:00','rtanglao',1,0,1,'2015-10-16T13:35:53-07:00','rtanglao','approved','{for not m42}[[Template:updateandroidbeta]]{/for}

Firefox for Android has a QR code reader in the URL bar to allow a user to load a webpage using its QR code. This article will show you how to use a QR code reader, including how to scan the QR code from the URL bar.

{warning}
''''''Note'''''' 
*Mozilla has only tested the official ZXing  [https://play.google.com/store/apps/details?id=com.google.zxing.client.android Barcode Scanner ] app that works with the ZX library.
* Before you begin, install this QR code scanner. Otherwise you will not see the QR Code reader icon in the URL bar. 
 {/warning}

''''To see this feature, ''''''Tap'''''' on the URL bar''''

<center>[[Image:qr code 1-2]]</center>

__TOC__
=How to use the QR code reader=
Tap the QR code icon.
;[[Image:qr code 2]]

It will automatically open the ZXing Barcode Scanner app for scanning QR codes.
;[[Image:qr code 3]]

After scanning, you will see the web address in URL bar. Now tap {button Go} to load the web page in Firefox for Android. 
;[[Image:qr code 4]]

If words instead of a web address show up after scanning, you may perform a search using those words by choosing a search engine (or simply tap {button Go} to use the default). 
;[[Image:qr code 5]]

=How to enable or disable the QR code reader=
Tap the menu button [[Template:AndroidMenuLocation]] and then select {menu Settings} [[Template:AndroidMore]], then select {menu Display}.
;[[Image:qr code 61]]

*Here you can enable or disable the QR code reader:
;* To enable, tap {menu QR code reader} until it is checked.
;;[[Image:qr 71]]
;* To disable, tap {menu QR code reader} until it is unchecked or you may uninstall [https://play.google.com/store/apps/details?id=com.google.zxing.client.android ZXing Barcode Scanner app] from your device. 
;;[[Image:qr 72]]','<div class="for" data-for="not m42" style="display: none;"><div class="warning">This feature will be available to all Firefox for Android users soon. In the meantime, try it on <a href="https://play.google.com/store/apps/details?id=org.mozilla.firefox_beta">Firefox Beta</a>.</div></div>
<p></p><p>Firefox for Android has a QR code reader in the URL bar to allow a user to load a webpage using its QR code. This article will show you how to use a QR code reader, including how to scan the QR code from the URL bar.
</p>
<div class="warning">
<p><strong>Note</strong> 
</p>
<ul><li>Mozilla has only tested the official ZXing  <a href="https://play.google.com/store/apps/details?id=com.google.zxing.client.android">Barcode Scanner </a> app that works with the ZX library.
</li><li> Before you begin, install this QR code scanner. Otherwise you will not see the QR Code reader icon in the URL bar. 
</li></ul>
 </div>
<p><em>To see this feature, <strong>Tap</strong> on the URL bar</em>
</p>
<center><img alt="qr code 1-2" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-00-27-17-8c01bb.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></center>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-to-use-the-qr-code-reader"><span class="tocnumber">1</span> <span class="toctext">How to use the QR code reader</span></a></li><li class="toclevel-1"><a href="#w_how-to-enable-or-disable-the-qr-code-reader"><span class="tocnumber">2</span> <span class="toctext">How to enable or disable the QR code reader</span></a></li></ul></div>
<h1 id="w_how-to-use-the-qr-code-reader">How to use the QR code reader</h1>
<p>Tap the QR code icon.
</p>
<dl><dt><img alt="qr code 2" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-17-18-d95882.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>It will automatically open the ZXing Barcode Scanner app for scanning QR codes.
</p>
<dl><dt><img alt="qr code 3" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-20-57-eda5d9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>After scanning, you will see the web address in URL bar. Now tap <span class="button">Go</span> to load the web page in Firefox for Android. 
</p>
<dl><dt><img alt="qr code 4" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-28-33-ebcf7e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>If words instead of a web address show up after scanning, you may perform a search using those words by choosing a search engine (or simply tap <span class="button">Go</span> to use the default). 
</p>
<dl><dt><img alt="qr code 5" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-42-07-ed240b.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<h1 id="w_how-to-enable-or-disable-the-qr-code-reader">How to enable or disable the QR code reader</h1>
<p>Tap the menu button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
 and then select <span class="menu">Settings</span> (you may need to tap <span class="menu">More</span> first)
, then select <span class="menu">Display</span>.
</p>
<dl><dt><img alt="qr code 61" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-02-05-07-18e9d9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<ul><li>Here you can enable or disable the QR code reader:
</li></ul>
<dl><dt><ul><li> To enable, tap <span class="menu">QR code reader</span> until it is checked.
</li></ul>
</dt></dl>
<dl><dt><dl><dt><img alt="qr 71" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-02-10-12-285ea0.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</dt></dl>
<dl><dt><ul><li> To disable, tap <span class="menu">QR code reader</span> until it is unchecked or you may uninstall <a href="https://play.google.com/store/apps/details?id=com.google.zxing.client.android">ZXing Barcode Scanner app</a> from your device. 
</li></ul>
</dt></dl>
<dl><dt><dl><dt><img alt="qr 72" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-02-11-56-e1d1e9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</dt></dl>','[{"label": "Revision id", "text": "106644", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 16, 2015, 1:34:18 PM", "datetime": "2015-10-16T13:34:18-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "re-added beta template, corrected minor typos and a few style edits", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 16, 2015, 1:35:43 PM", "datetime": "2015-10-16T13:35:43-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 16, 2015, 1:35:53 PM", "datetime": "2015-10-16T13:35:53-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:42:14+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (107415,'en-US','sync-bookmarks-logins-and-browsing-history-firefox','Sync bookmarks, logins and browsing history on Firefox for iOS','https://support.mozilla.org/en-US/kb/sync-bookmarks-logins-and-browsing-history-firefox','https://support.mozilla.org/en-US/kb/sync-bookmarks-logins-and-browsing-history-firefox/revision/107415',103482,'2015-10-25T15:17:15-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','added Android',1,'2015-10-25T15:18:21-07:00','rtanglao',1,0,1,'2015-11-13T08:24:53-08:00','heyjoni','approved','[[Template:ioscoming]]

If you use Firefox on multiple devices, a free Firefox Account lets you sync your history, open tabs, bookmarks and passwords on all your devices. All you need is an email address and password.

{warning}''''''Bookmarks:'''''' This version of Firefox allows you to sync bookmarks from Firefox on your Android device, or Mac, Windows or Linux computer to your iPad, iPhone or iPod touch. Bookmarks saved on your iOS devices will not sync to your Android device, Mac, Windows or Linux computer.{/warning}

__TOC__

=Part 1: Set up Firefox Accounts=
{note}''''''New Firefox Accounts'''''': if you are creating a new Firefox Account account, start with the device that has all the information you want to sync. {/note}
#[[Template:tabios]]
#[[Template:settingsios]]
#Tap {menu Sign in} to open the ''''Create an account'''' page.
#Follow the instructions to create an account. Take note of your login information. You will need it to connect your other devices.
#Check your email for the verification link and tap on it to confirm your account.

Once you''ve finished this step, move on to Part 2.

=Part 2: Connect your iOS device=
#[[Template:tabios]]
#[[Template:settingsios]]
#Tap {menu Sign in} to open the ''''Create an account'''' page.
#Tap ''''''I already have an account'''''' and follow the instructions to log in.

Your information will sync in a few moments. To force a sync at any time, tap {menu Sync Now} in the Firefox ''''Settings'''' menu.

To set up Sync on another device, see:
*''''''Desktop or laptop computers'''''': [[How do I set up Firefox Sync?]]
*''''''Android phones and tablets:'''''': [[Sync bookmarks, tabs, history and passwords on Android]]','<p></p><div class="warning"> This article shows an upcoming version of Firefox for iOS, so yours might look different. Please update in a few weeks to get these features.</div>
<p></p><p>If you use Firefox on multiple devices, a free Firefox Account lets you sync your history, open tabs, bookmarks and passwords on all your devices. All you need is an email address and password.
</p>
<div class="warning"><strong>Bookmarks:</strong> This version of Firefox allows you to sync bookmarks from Firefox on your Android device, or Mac, Windows or Linux computer to your iPad, iPhone or iPod touch. Bookmarks saved on your iOS devices will not sync to your Android device, Mac, Windows or Linux computer.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_part-1-set-up-firefox-accounts"><span class="tocnumber">1</span> <span class="toctext">Part 1: Set up Firefox Accounts</span></a></li><li class="toclevel-1"><a href="#w_part-2-connect-your-ios-device"><span class="tocnumber">2</span> <span class="toctext">Part 2: Connect your iOS device</span></a></li></ul></div>
<h1 id="w_part-1-set-up-firefox-accounts">Part 1: Set up Firefox Accounts</h1>
<div class="note"><strong>New Firefox Accounts</strong>: if you are creating a new Firefox Account account, start with the device that has all the information you want to sync. </div>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap <span class="menu">Settings</span> in the menu panel.

</li><li>Tap <span class="menu">Sign in</span> to open the <em>Create an account</em> page.
</li><li>Follow the instructions to create an account. Take note of your login information. You will need it to connect your other devices.
</li><li>Check your email for the verification link and tap on it to confirm your account.
</li></ol>
<p>Once you''ve finished this step, move on to Part 2.
</p>
<h1 id="w_part-2-connect-your-ios-device">Part 2: Connect your iOS device</h1>
<ol><li>Tap the numeric tab icon at the bottom of the screen.<br><img alt="tabios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-04-17-06-44-39-154c58.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" width="400">

</li><li>Tap <span class="menu">Settings</span> in the menu panel.

</li><li>Tap <span class="menu">Sign in</span> to open the <em>Create an account</em> page.
</li><li>Tap <strong>I already have an account</strong> and follow the instructions to log in.
</li></ol>
<p>Your information will sync in a few moments. To force a sync at any time, tap <span class="menu">Sync Now</span> in the Firefox <em>Settings</em> menu.
</p><p>To set up Sync on another device, see:
</p>
<ul><li><strong>Desktop or laptop computers</strong>: <a href="/en-US/kb/how-do-i-set-sync-my-computer">How do I set up Sync on my computer?</a>
</li><li><strong>Android phones and tablets:</strong>: <a href="/en-US/kb/sync-bookmarks-tabs-history-and-passwords-android">Sync bookmarks, history, passwords and tabs on Android</a>
</li></ul>','[{"label": "Revision id", "text": "107415", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 25, 2015, 3:17:15 PM", "datetime": "2015-10-25T15:17:15-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "added Android", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 25, 2015, 3:18:21 PM", "datetime": "2015-10-25T15:18:21-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Nov 13, 2015, 8:24:53 AM", "datetime": "2015-11-13T08:24:53-08:00", "href": null}, {"label": "Readied for localization by", "text": "heyjoni", "datetime": null, "href": null}]','2026-11-03T18:42:12+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (107758,'en-US','forum-response-android-turn-family-friendly-browsi','Forum Response - Android Turn on Family Friendly Browsing','https://support.mozilla.org/en-US/kb/forum-response-android-turn-family-friendly-browsi','https://support.mozilla.org/en-US/kb/forum-response-android-turn-family-friendly-browsi/revision/107758',107757,'2015-10-29T10:28:01-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fix minor typos',1,'2015-10-29T10:54:01-07:00','rtanglao',1,1,0,NULL,NULL,'approved','In order to activate family-friendly browsing, make sure you are on an Android device that is on version 4.3 of Android or higher; please note this feature is only available on tablets. 

To get started, see the instructions here [https://support.mozilla.org/en-US/kb/controlledaccess]

If you have any other questions, or any difficulties activating this we are happy to help.','<p>In order to activate family-friendly browsing, make sure you are on an Android device that is on version 4.3 of Android or higher; please note this feature is only available on tablets. 
</p><p>To get started, see the instructions here <a href="https://support.mozilla.org/en-US/kb/controlledaccess">https://support.mozilla.org/en-US/kb/controlledaccess</a>
</p><p>If you have any other questions, or any difficulties activating this we are happy to help.
</p>','[{"label": "Revision id", "text": "107758", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 29, 2015, 10:28:01 AM", "datetime": "2015-10-29T10:28:01-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix minor typos", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 29, 2015, 10:54:01 AM", "datetime": "2015-10-29T10:54:01-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:42:09+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (107843,'en-US','enhanced-tracking-protection-firefox-android','Enhanced Tracking Protection in Firefox for Android','https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-android','https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-android/revision/107843',107592,'2015-10-30T07:04:40-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','very very minor typo',1,'2015-10-30T07:05:02-07:00','rtanglao',1,0,0,NULL,NULL,'approved','Tracking generally refers to the collection of a person’s browsing data across multiple sites. Firefox for Android’s Tracking Protection feature uses a list provided by Disconnect to identify and block trackers.

{note}[https://disconnect.me/trackerprotection Read more] about tracking and the standards Disconnect uses to create its list. [https://wiki.mozilla.org/Security/Tracking_protection#Lists Learn more] about the lists used by Firefox for Android for Tracking Protection.{/note}

=Tracking Protection in Private Browsing=
When you open a [[Private Browsing on Firefox for Android|Private Tab on Firefox for Android]], Tracking Protection is enabled by default. 

When you visit a web page with trackers, a shield icon [[Image:tracking protection icon fxos]] will appear in the address bar to let you know that Firefox is actively blocking trackers on that page. 

;[[Image:tracking protection icon 42]]

==Disable Tracking Protection on a specific page==
If you are on a website and you want to view the page with tracking enabled, you can disable Tracking Protection by following these steps:
#Tap the shield icon [[Image:tracking protection icon fxos]] on the address bar to see the Control center.
#Tap {button Disable protection} to turn Tracking Protection off.
#A red line will appear across the shield [[Image:tracking protection off fxos]] when Tracking Protection has been deactivated.

To re-enable Tracking Protection, repeat the steps above to open the Control Center and tap {button Enable protection}.

==Change your Tracking Protection settings in Private Browsing==
Tracking Protection is enabled by default in Private Browsing for additional privacy. Follow these steps to disable it on all pages you visit.
#Tap the menu button (either below the screen on some devices or at the top-right corner of the browser).
#Tap {menu Settings}, followed by {menu Privacy}.
#Remove the check mark next to ''''''Tracking protection:'''''' Enabled in Private Browsing to disable it.

To re-enable Tracking Protection, repeat these steps and add a check mark to the box.','<p>Tracking generally refers to the collection of a person’s browsing data across multiple sites. Firefox for Android’s Tracking Protection feature uses a list provided by Disconnect to identify and block trackers.
</p>
<div class="note"><a href="https://disconnect.me/trackerprotection">Read more</a> about tracking and the standards Disconnect uses to create its list. <a href="https://wiki.mozilla.org/Security/Tracking_protection#Lists">Learn more</a> about the lists used by Firefox for Android for Tracking Protection.</div>
<h1 id="w_tracking-protection-in-private-browsing">Tracking Protection in Private Browsing</h1>
<p>When you open a <a href="/en-US/kb/private-browsing-firefox-android">Private Tab on Firefox for Android</a>, Tracking Protection is enabled by default. 
</p><p>When you visit a web page with trackers, a shield icon <img alt="tracking protection icon fxos" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-12-14-13-33-8e488a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> will appear in the address bar to let you know that Firefox is actively blocking trackers on that page. 
</p>
<dl><dt><img alt="tracking protection icon 42" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-08-28-19-41-44-28c69b.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<h2 id="w_disable-tracking-protection-on-a-specific-page">Disable Tracking Protection on a specific page</h2>
<p>If you are on a website and you want to view the page with tracking enabled, you can disable Tracking Protection by following these steps:
</p>
<ol><li>Tap the shield icon <img alt="tracking protection icon fxos" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-12-14-13-33-8e488a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> on the address bar to see the Control center.
</li><li>Tap <span class="button">Disable protection</span> to turn Tracking Protection off.
</li><li>A red line will appear across the shield <img alt="tracking protection off fxos" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-12-14-18-27-18e5df.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> when Tracking Protection has been deactivated.
</li></ol>
<p>To re-enable Tracking Protection, repeat the steps above to open the Control Center and tap <span class="button">Enable protection</span>.
</p>
<h2 id="w_change-your-tracking-protection-settings-in-private-browsing">Change your Tracking Protection settings in Private Browsing</h2>
<p>Tracking Protection is enabled by default in Private Browsing for additional privacy. Follow these steps to disable it on all pages you visit.
</p>
<ol><li>Tap the menu button (either below the screen on some devices or at the top-right corner of the browser).
</li><li>Tap <span class="menu">Settings</span>, followed by <span class="menu">Privacy</span>.
</li><li>Remove the check mark next to <strong>Tracking protection:</strong> Enabled in Private Browsing to disable it.
</li></ol>
<p>To re-enable Tracking Protection, repeat these steps and add a check mark to the box.
</p>','[{"label": "Revision id", "text": "107843", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 30, 2015, 7:04:40 AM", "datetime": "2015-10-30T07:04:40-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "very very minor typo", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 30, 2015, 7:05:02 AM", "datetime": "2015-10-30T07:05:02-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:42:07+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (107851,'en-US','copy-saved-password-firefox-android','Copy a saved password in Firefox for Android','https://support.mozilla.org/en-US/kb/copy-saved-password-firefox-android','https://support.mozilla.org/en-US/kb/copy-saved-password-firefox-android/revision/107851',105660,'2015-10-30T07:33:30-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','nuances about multiple logins',1,'2015-10-30T08:02:58-07:00','heyjoni',1,0,1,'2015-10-30T08:04:21-07:00','heyjoni','approved','{for not m41}[[Template:updateandroid]]{/for}

If you have multiple logins for a website and Firefox has saved the passwords for those logins, then Firefox lets you copy a saved password to your clipboard so you can paste it somewhere else.

Here’s how to do it:

#Tap the lock icon [[Image:lock icon on android]] on the address bar to bring up a window with your site information.
#;[[Image:lock icon address bar android]]
#At the bottom of the window, tap {button Copy} to copy the password for the username that''s displayed.
#If you have multiple logins saved for that website, tap ''''''Select another login'''''' to copy another password.
#;[[Image:select another login android]]
#Select the username from the list. A confirmation message will appear when your password has been copied.','<div class="for" data-for="not m41" style="display: none;"><div class="warning">This article applies to the latest version of Firefox for Android. Please <a href="/en-US/kb/update-latest-version-firefox-android">update your version</a> first to enjoy these features.</div></div>
<p></p><p>If you have multiple logins for a website and Firefox has saved the passwords for those logins, then Firefox lets you copy a saved password to your clipboard so you can paste it somewhere else.
</p><p>Here’s how to do it:
</p>
<ol><li>Tap the lock icon <img alt="lock icon on android" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-09-16-16-06-46-2faa61.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> on the address bar to bring up a window with your site information.
<dl><dt><img alt="lock icon address bar android" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-09-16-16-12-09-ff97ed.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>At the bottom of the window, tap <span class="button">Copy</span> to copy the password for the username that''s displayed.
</li><li>If you have multiple logins saved for that website, tap <strong>Select another login</strong> to copy another password.
<dl><dt><img alt="select another login android" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-01-19-05-50-f7d603.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>Select the username from the list. A confirmation message will appear when your password has been copied.
</li></ol>','[{"label": "Revision id", "text": "107851", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 30, 2015, 7:33:30 AM", "datetime": "2015-10-30T07:33:30-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "nuances about multiple logins", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 30, 2015, 8:02:58 AM", "datetime": "2015-10-30T08:02:58-07:00", "href": null}, {"label": "Reviewed by", "text": "heyjoni", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 30, 2015, 8:04:21 AM", "datetime": "2015-10-30T08:04:21-07:00", "href": null}, {"label": "Readied for localization by", "text": "heyjoni", "datetime": null, "href": null}]','2026-11-03T18:42:04+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (109094,'en-US','sync-firefox-bookmaks-and-browsing-history-ios','Sync your Firefox bookmaks and browsing history in iOS','https://support.mozilla.org/en-US/kb/sync-firefox-bookmaks-and-browsing-history-ios','https://support.mozilla.org/en-US/kb/sync-firefox-bookmaks-and-browsing-history-ios/revision/109094',NULL,'2015-11-12T03:28:46-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','REDIRECT [[Sync your Firefox bookmarks and browsing history in iOS]]','<p>REDIRECT <a href="/en-US/kb/sync-bookmarks-logins-and-browsing-history-on-firefox-for-ios">Sync bookmarks, logins and browsing history on FIrefox for iOS</a>
</p>','[{"label": "Revision id", "text": "109094", "datetime": null, "href": null}, {"label": "Created", "text": "Nov 12, 2015, 3:28:46 AM", "datetime": "2015-11-12T03:28:46-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:42:02+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (110091,'en-US','maildir-thunderbird','Maildir in Thunderbird','https://support.mozilla.org/en-US/kb/maildir-thunderbird','https://support.mozilla.org/en-US/kb/maildir-thunderbird/revision/110091',102800,'2015-11-25T01:57:00-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','document about:config variable',1,'2015-11-25T01:57:35-08:00','rtanglao',1,0,1,'2015-11-25T02:06:50-08:00','wsmwk','approved','Thunderbird has had hidden support (Maildir is disabled by default) for the [https://en.wikipedia.org/wiki/Maildir Maildir] mail storage format for several years, but Maildir [http://mzl.la/1HTGlUw still has many bugs] and is not 100% ready for users. This article explains the format change and how to test Maildir starting in Thunderbird 38 (Maildir is not ready for testing prior to version 38). 

{warning}WARNING: We suggest you leave Maildir disabled unless you are advanced user, willing to risk your data, and know how to backup your email before turning on Maildir and how to restore it if you run into problems.{/warning}

Maildir is a single file per email ([https://en.wikipedia.org/wiki/Email#Filename_extensions EML]), unlike the current default monolithic single file format, which is one file per folder (known as [https://en.wikipedia.org/wiki/Mbox mbox]). This storage format has significant benefits:
* Backups are easier because the amount of data needed to be backed up is reduced to just those emails that have changed since the last backup.
* It is easier for anti-virus to scan emails in individual files, and infected mails can be removed without the loss of all the other mail in the folder, as often occurs today with anti-virus software which cannot handle multiple emails in one file.

This is a major change for Thunderbird because it changes the mail storage mechanism. The development team have spent a significant amount of time developing maildir<!-- but one last software change is still missing and that an option in the user interface to enable maildir globally -->. 

However, due to a lack of time and testers before Thunderbird 38 was released, the actual underlying changes have not had the extensive manual testing that would normally occur for such a major change.

= How to turn on Maildir =
{warning}WARNING: Again, this feature is experimental and we recommend that you know how to file bugs and how to backup and restore your email before turning on Maildir.{/warning}
Here''s how to turn on Maildir:
# Backup your email. ''''''If you don''t know how to backup and restore your email, then you are not qualified to test Maildir.''''''
# [https://wiki.mozilla.org/Thunderbird/Maildir Set the about:config variable documented in the Maildir wiki page]. ''''''If you don''t know how set an about:config variable, then you are not qualified to test Maildir.''''''
# Click the Application menu button [[Image:New Fx Menu]].
# Click {menu {for win}Options{/for}{for mac,linux}Preferences{/for}} and then {for win}{menu Options}{/for}{for mac, linux}{menu Preferences}{/for}.
# Click {menu Advanced} and then click {menu General}.
# Next to "Message Store Type for new accounts", select {button File per message (maildir)}.
# Any email account created from now on will use Maildir (existing accounts will continue to use mbox). 

''''''Please [https://bugzilla.mozilla.org/enter_bug.cgi?product=Thunderbird file a bug] if you encounter any Maildir issues.''''''  See also [http://mzl.la/1HTGlUw already filed bug reports].','<p>Thunderbird has had hidden support (Maildir is disabled by default) for the <a href="https://en.wikipedia.org/wiki/Maildir">Maildir</a> mail storage format for several years, but Maildir <a href="http://mzl.la/1HTGlUw">still has many bugs</a> and is not 100% ready for users. This article explains the format change and how to test Maildir starting in Thunderbird 38 (Maildir is not ready for testing prior to version 38). 
</p>
<div class="warning">WARNING: We suggest you leave Maildir disabled unless you are advanced user, willing to risk your data, and know how to backup your email before turning on Maildir and how to restore it if you run into problems.</div>
<p>Maildir is a single file per email (<a href="https://en.wikipedia.org/wiki/Email#Filename_extensions">EML</a>), unlike the current default monolithic single file format, which is one file per folder (known as <a href="https://en.wikipedia.org/wiki/Mbox">mbox</a>). This storage format has significant benefits:
</p>
<ul><li> Backups are easier because the amount of data needed to be backed up is reduced to just those emails that have changed since the last backup.
</li><li> It is easier for anti-virus to scan emails in individual files, and infected mails can be removed without the loss of all the other mail in the folder, as often occurs today with anti-virus software which cannot handle multiple emails in one file.
</li></ul>
<p>This is a major change for Thunderbird because it changes the mail storage mechanism. The development team have spent a significant amount of time developing maildir. 
</p><p>However, due to a lack of time and testers before Thunderbird 38 was released, the actual underlying changes have not had the extensive manual testing that would normally occur for such a major change.
</p>
<h1 id="w_how-to-turn-on-maildir">How to turn on Maildir</h1>
<div class="warning">WARNING: Again, this feature is experimental and we recommend that you know how to file bugs and how to backup and restore your email before turning on Maildir.</div>
<p>Here''s how to turn on Maildir:
</p>
<ol><li> Backup your email. <strong>If you don''t know how to backup and restore your email, then you are not qualified to test Maildir.</strong>
</li><li> <a href="https://wiki.mozilla.org/Thunderbird/Maildir">Set the about:config variable documented in the Maildir wiki page</a>. <strong>If you don''t know how set an about:config variable, then you are not qualified to test Maildir.</strong>
</li><li> Click the Application menu button <img alt="New Fx Menu" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-01-10-13-08-08-f52b8c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">.
</li><li> Click <span class="menu"><span class="for" data-for="win" style="display: none;">Options</span><span class="for" data-for="mac,linux">Preferences</span></span> and then <span class="for" data-for="win" style="display: none;"><span class="menu">Options</span></span><span class="for" data-for="mac,linux"><span class="menu">Preferences</span></span>.
</li><li> Click <span class="menu">Advanced</span> and then click <span class="menu">General</span>.
</li><li> Next to "Message Store Type for new accounts", select <span class="button">File per message (maildir)</span>.
</li><li> Any email account created from now on will use Maildir (existing accounts will continue to use mbox). 
</li></ol>
<p><strong>Please <a href="https://bugzilla.mozilla.org/enter_bug.cgi?product=Thunderbird">file a bug</a> if you encounter any Maildir issues.</strong>  See also <a href="http://mzl.la/1HTGlUw">already filed bug reports</a>.
</p>','[{"label": "Revision id", "text": "110091", "datetime": null, "href": null}, {"label": "Created", "text": "Nov 25, 2015, 1:57:00 AM", "datetime": "2015-11-25T01:57:00-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "document about:config variable", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Nov 25, 2015, 1:57:35 AM", "datetime": "2015-11-25T01:57:35-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Nov 25, 2015, 2:06:50 AM", "datetime": "2015-11-25T02:06:50-08:00", "href": null}, {"label": "Readied for localization by", "text": "wsmwk", "datetime": null, "href": null}]','2026-11-03T18:42:00+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (114725,'en-US','send-text-or-multimedia-messages-firefox-android','Send text or multimedia messages from Firefox for Android','https://support.mozilla.org/en-US/kb/send-text-or-multimedia-messages-firefox-android','https://support.mozilla.org/en-US/kb/send-text-or-multimedia-messages-firefox-android/revision/114725',NULL,'2016-01-15T07:10:08-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','wip',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Firefox for Android supports sending text (SMS) or multimedia (MMS) messages directly from the web pages that offer it

#Tap on the SMS or MMS link (usually a phone number) on the web page to launch the messaging app.
#If you''re using this feature for the first time, a prompt will ask you to choose an app. Choose your phone''s messaging app which in most devices is Messenger or Hangouts.
<!--
#;[[Image:messenger app]]
-->
#Your messaging app will open and automatically fill in the number and message that was on the website.
#Edit as needed and tap send.','<p>Firefox for Android supports sending text (SMS) or multimedia (MMS) messages directly from the web pages that offer it
</p>
<ol><li>Tap on the SMS or MMS link (usually a phone number) on the web page to launch the messaging app.
</li><li>If you''re using this feature for the first time, a prompt will ask you to choose an app. Choose your phone''s messaging app which in most devices is Messenger or Hangouts.
</li></ol>
<p>
</p>
<ol><li>Your messaging app will open and automatically fill in the number and message that was on the website.
</li><li>Edit as needed and tap send.
</li></ol>','[{"label": "Revision id", "text": "114725", "datetime": null, "href": null}, {"label": "Created", "text": "Jan 15, 2016, 7:10:08 AM", "datetime": "2016-01-15T07:10:08-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "wip", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:41:51+00:00');
