INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (117680,'en-US','firefox-no-longer-supported-this-version-android','Firefox no longer supported on this version of Android','https://support.mozilla.org/en-US/kb/firefox-no-longer-supported-this-version-android','https://support.mozilla.org/en-US/kb/firefox-no-longer-supported-this-version-android/revision/117680',117676,'2016-02-18T11:43:41-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','fix minor typo',1,'2016-02-18T12:10:48-08:00','rtanglao',1,0,0,NULL,NULL,'approved','In the future, Firefox will no longer support this version of Android.

If you have already installed Firefox, it will remain on your tablet until you uninstall it, but it will no longer be updated with new features or security and stability fixes.

For the best Firefox experience, see if a newer version of Android is available for your tablet, to use the latest version of Firefox.

=Get a supported version of Android=
Check to see if a system update is available for your tablet. See [[Will Firefox work on my mobile device?]] for information on versions of Android that Firefox supports.

=Update to the latest version of Firefox=
Once you’ve updated to a supported version of Android, see this article on [[Update to the latest version of Firefox for Android | how to update to the latest version of Firefox for Android]].','<p>In the future, Firefox will no longer support this version of Android.
</p><p>If you have already installed Firefox, it will remain on your tablet until you uninstall it, but it will no longer be updated with new features or security and stability fixes.
</p><p>For the best Firefox experience, see if a newer version of Android is available for your tablet, to use the latest version of Firefox.
</p>
<h1 id="w_get-a-supported-version-of-android">Get a supported version of Android</h1>
<p>Check to see if a system update is available for your tablet. See <a href="/en-US/kb/will-firefox-work-my-mobile-device">Will Firefox work on my mobile device?</a> for information on versions of Android that Firefox supports.
</p>
<h1 id="w_update-to-the-latest-version-of-firefox">Update to the latest version of Firefox</h1>
<p>Once you’ve updated to a supported version of Android, see this article on <a href="/en-US/kb/update-latest-version-firefox-android"> how to update to the latest version of Firefox for Android</a>.
</p>','[{"label": "Revision id", "text": "117680", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 18, 2016, 11:43:41 AM", "datetime": "2016-02-18T11:43:41-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix minor typo", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 18, 2016, 12:10:48 PM", "datetime": "2016-02-18T12:10:48-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:41:40+00:00');
