INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (132534,'en-US','add-ons-firefox-ios','Add-ons in Firefox for iOS','https://support.mozilla.org/en-US/kb/add-ons-firefox-ios','https://support.mozilla.org/en-US/kb/add-ons-firefox-ios/revision/132534',NULL,'2016-09-28T10:33:08-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','safari extensions don''t work with firefox for ios or any other app that isn''t safari.',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Add-ons for the desktop version of Firefox are not available for Firefox for iOS. 

= Apple policy =
Apple doesn''t allow browsers on iOS to use a different rendering engine than the one used in Safari. 

= iOS extensions =
iOS has its own extension system which is incompatible with Firefox add-ons and extensions for Android, Mac, Windows and Linux. iOS extensions written for other iOS apps won''t work on Firefox for iOS.','<p>Add-ons for the desktop version of Firefox are not available for Firefox for iOS. 
</p>
<h1 id="w_apple-policy">Apple policy</h1>
<p>Apple doesn''t allow browsers on iOS to use a different rendering engine than the one used in Safari. 
</p>
<h1 id="w_ios-extensions">iOS extensions</h1>
<p>iOS has its own extension system which is incompatible with Firefox add-ons and extensions for Android, Mac, Windows and Linux. iOS extensions written for other iOS apps won''t work on Firefox for iOS.
</p>','[{"label": "Revision id", "text": "132534", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 28, 2016, 10:33:08 AM", "datetime": "2016-09-28T10:33:08-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "safari extensions don''t work with firefox for ios or any other app that isn''t safari.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:41:21+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (132535,'en-US','add-ons-firefox-ios','Add-ons in Firefox for iOS','https://support.mozilla.org/en-US/kb/add-ons-firefox-ios','https://support.mozilla.org/en-US/kb/add-ons-firefox-ios/revision/132535',NULL,'2016-09-28T10:38:53-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','just trying to clarify! cilias, thanks for starting this shouldn''t it be a canned response instead of a kb article?',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Add-ons for the desktop and Android version of Firefox are not available for Firefox for iOS. 

Apple has created a proprietary iOS extension system which is incompatible with Firefox add-ons and extensions for Android, Mac, Windows and Linux. Also, iOS extensions written for other iOS apps won''t work on Firefox for iOS.','<p>Add-ons for the desktop and Android version of Firefox are not available for Firefox for iOS. 
</p><p>Apple has created a proprietary iOS extension system which is incompatible with Firefox add-ons and extensions for Android, Mac, Windows and Linux. Also, iOS extensions written for other iOS apps won''t work on Firefox for iOS.
</p>','[{"label": "Revision id", "text": "132535", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 28, 2016, 10:38:53 AM", "datetime": "2016-09-28T10:38:53-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "just trying to clarify! cilias, thanks for starting this shouldn''t it be a canned response instead of a kb article?", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:41:19+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (132611,'en-US','add-ons-firefox-ios','Add-ons in Firefox for iOS','https://support.mozilla.org/en-US/kb/add-ons-firefox-ios','https://support.mozilla.org/en-US/kb/add-ons-firefox-ios/revision/132611',NULL,'2016-09-29T04:25:01-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','chris was right; this should be an article. added a note to indicate that safari extensions don''t work automatically w/ffios See bug 1162174',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Add-ons for the desktop and Android version of Firefox are not available for Firefox for iOS. 

Apple has created a proprietary iOS extension system which is incompatible with Firefox add-ons and extensions for Android, Mac, Windows and Linux. Also, iOS extensions written for other iOS apps won''t work on Firefox for iOS (for example extensions writen for Safari won''t automatically work on Firefox for iOS).','<p>Add-ons for the desktop and Android version of Firefox are not available for Firefox for iOS. 
</p><p>Apple has created a proprietary iOS extension system which is incompatible with Firefox add-ons and extensions for Android, Mac, Windows and Linux. Also, iOS extensions written for other iOS apps won''t work on Firefox for iOS (for example extensions writen for Safari won''t automatically work on Firefox for iOS).
</p>','[{"label": "Revision id", "text": "132611", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 29, 2016, 4:25:01 AM", "datetime": "2016-09-29T04:25:01-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "chris was right; this should be an article. added a note to indicate that safari extensions don''t work automatically w/ffios See bug 1162174", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:41:16+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (134861,'en-US','scan-qr-codes-firefox-android','Scan QR codes in Firefox for Android','https://support.mozilla.org/en-US/kb/scan-qr-codes-firefox-android','https://support.mozilla.org/en-US/kb/scan-qr-codes-firefox-android/revision/134861',108082,'2016-11-10T05:35:47-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','wip do not approve, need joni''s input',1,'2016-11-10T07:11:12-08:00','heyjoni',1,0,1,'2016-11-10T07:11:12-08:00','heyjoni','approved','{for not m42}[[Template:updateandroid]]{/for}

Firefox for Android has a QR code reader in the URL bar to allow a user to load a webpage using its QR code. This article will show you how to use a QR code reader, including how to scan the QR code from the URL bar.

{warning}
''''''Note'''''' 
*Mozilla has only tested the official ZXing  [https://play.google.com/store/apps/details?id=com.google.zxing.client.android Barcode Scanner] app that works with the ZX library.
* Before you begin, install this QR code scanner. Otherwise you will not see the QR Code reader icon in the URL bar. 
{/warning}

''''To see this feature, ''''''tap'''''' on the URL bar.''''

<center>[[Image:qr code 1-2]]</center>

__TOC__
=How to use the QR code reader=
Tap the QR code icon.
;[[Image:qr code 2]]

It will automatically open the ZXing Barcode Scanner app for scanning QR codes.
;[[Image:qr code 3]]

After scanning, you will see the web address in URL bar. Now tap {button Go} to load the web page in Firefox for Android. 
;[[Image:qr code 4]]

If words instead of a web address show up after scanning, you may perform a search using those words by choosing a search engine (or simply tap {button Go} to use the default). 
;[[Image:qr code 5]]

=How to enable or disable the QR code reader=
Tap the menu button [[Template:AndroidMenuLocation]] and then select {menu Settings} [[Template:AndroidMore]], then select {menu Accessibility}.
<!-- (upgrade to FF50 or later)
;[[Image:qr code 61]]
-->

*Here you can enable or disable the QR code reader:
;* To enable, tap {menu QR code reader} until the slider is in the ON position which is usually on the right (in some versions of Android you will see a checkmark; make sure it is checked).
<!--
;;[[Image:qr 71]]
-->
;* To disable, tap {menu QR code reader} until the slider is in the OFF position which is usually on the left (in some versions of Android you will see a checkmark; make sure it is unchecked)., or you may uninstall [https://play.google.com/store/apps/details?id=com.google.zxing.client.android ZXing Barcode Scanner app] from your device. 
<!--
;;[[Image:qr 72]]
-->','<div class="for" data-for="not m42" style="display: none;"><div class="warning">This article applies to the latest version of Firefox for Android. Please <a href="/en-US/kb/update-latest-version-firefox-android">update your version</a> first to enjoy these features.</div></div>
<p></p><p>Firefox for Android has a QR code reader in the URL bar to allow a user to load a webpage using its QR code. This article will show you how to use a QR code reader, including how to scan the QR code from the URL bar.
</p>
<div class="warning">
<p><strong>Note</strong> 
</p>
<ul><li>Mozilla has only tested the official ZXing  <a href="https://play.google.com/store/apps/details?id=com.google.zxing.client.android">Barcode Scanner</a> app that works with the ZX library.
</li><li> Before you begin, install this QR code scanner. Otherwise you will not see the QR Code reader icon in the URL bar. 
</li></ul>
</div>
<p><em>To see this feature, <strong>tap</strong> on the URL bar.</em>
</p>
<center><img alt="qr code 1-2" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-00-27-17-8c01bb.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></center>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-to-use-the-qr-code-reader"><span class="tocnumber">1</span> <span class="toctext">How to use the QR code reader</span></a></li><li class="toclevel-1"><a href="#w_how-to-enable-or-disable-the-qr-code-reader"><span class="tocnumber">2</span> <span class="toctext">How to enable or disable the QR code reader</span></a></li></ul></div>
<h1 id="w_how-to-use-the-qr-code-reader">How to use the QR code reader</h1>
<p>Tap the QR code icon.
</p>
<dl><dt><img alt="qr code 2" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-17-18-d95882.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>It will automatically open the ZXing Barcode Scanner app for scanning QR codes.
</p>
<dl><dt><img alt="qr code 3" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-20-57-eda5d9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>After scanning, you will see the web address in URL bar. Now tap <span class="button">Go</span> to load the web page in Firefox for Android. 
</p>
<dl><dt><img alt="qr code 4" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-28-33-ebcf7e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>If words instead of a web address show up after scanning, you may perform a search using those words by choosing a search engine (or simply tap <span class="button">Go</span> to use the default). 
</p>
<dl><dt><img alt="qr code 5" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2015-10-08-01-42-07-ed240b.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<h1 id="w_how-to-enable-or-disable-the-qr-code-reader">How to enable or disable the QR code reader</h1>
<p>Tap the menu button (either <a href="/en-US/kb/firefox-menu-icon-missing-android-how-access-menu"> at the bottom right on some devices</a> or in the upper right of the browser)
 and then select <span class="menu">Settings</span> (you may need to tap <span class="menu">More</span> first)
, then select <span class="menu">Accessibility</span>.

</p>
<ul><li>Here you can enable or disable the QR code reader:
</li></ul>
<dl><dt><ul><li> To enable, tap <span class="menu">QR code reader</span> until the slider is in the ON position which is usually on the right (in some versions of Android you will see a checkmark; make sure it is checked).
</li></ul>
</dt></dl>
<p>
</p>
<dl><dt><ul><li> To disable, tap <span class="menu">QR code reader</span> until the slider is in the OFF position which is usually on the left (in some versions of Android you will see a checkmark; make sure it is unchecked)., or you may uninstall <a href="https://play.google.com/store/apps/details?id=com.google.zxing.client.android">ZXing Barcode Scanner app</a> from your device. 
</li></ul>
</dt></dl>
<p>
</p>','[{"label": "Revision id", "text": "134861", "datetime": null, "href": null}, {"label": "Created", "text": "Nov 10, 2016, 5:35:47 AM", "datetime": "2016-11-10T05:35:47-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "wip do not approve, need joni''s input", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Nov 10, 2016, 7:11:12 AM", "datetime": "2016-11-10T07:11:12-08:00", "href": null}, {"label": "Reviewed by", "text": "heyjoni", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Nov 10, 2016, 7:11:12 AM", "datetime": "2016-11-10T07:11:12-08:00", "href": null}, {"label": "Readied for localization by", "text": "heyjoni", "datetime": null, "href": null}]','2026-11-03T18:41:14+00:00');
