INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (145009,'en-US','enhanced-tracking-protection-firefox-ios','Enhanced Tracking Protection in Firefox for iOS','https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-ios','https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-ios/revision/145009',145002,'2017-09-11T13:56:11-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','menu button is on the top right of the screen of your iPad (unlike iPhone where it is at the bottom)',1,'2017-09-11T13:56:36-07:00','rtanglao',1,0,1,'2017-09-11T13:56:36-07:00','rtanglao','approved','{note}''''''This feature requires iOS version 11:'''''' Please make sure you are running the latest version of iOS to enjoy this feature.{/note}

Firefox for iOS has a Tracking Protection feature that uses a list provided by Disconnect to identify and block trackers.

=Change your Tracking Protection settings=
Tracking Protection is enabled by default in [[Private Browsing in Firefox for iOS]] for additional privacy. Follow these steps to turn on Tracking Protection in regular browsing mode or to turn it off completely.
#Tap the menu button at the bottom of the screen on your iPhone or at the top right of the screen on your iPad. (You might need to scroll all the way to the top of the page for the menu button to appear).
#Tap the Settings icon in the menu panel at the bottom of the screen. (You might need to swipe to the next panel first.) 
#Scroll to the ''''Privacy'''' section and tap {menu Tracking Protection}.
#;[[Image:tracking protection ios]]
#Tap the option that you prefer to put a check mark next to it:
#*''''''Always on:'''''' Blocks trackers even in regular browsing.
#*''''''Private Browsing Mode only:'''''' Blocks trackers only on Private Tabs. This is the default option.
#*''''''Never:'''''' Firefox will not block trackers.

{note}[https://disconnect.me/trackerprotection Read more] about tracking and the standards Disconnect uses to create its list. [https://wiki.mozilla.org/Security/Tracking_protection#Lists Learn more] about the lists used by Firefox for iOS for Tracking Protection.{/note}','<div class="note"><strong>This feature requires iOS version 11:</strong> Please make sure you are running the latest version of iOS to enjoy this feature.</div>
<p>Firefox for iOS has a Tracking Protection feature that uses a list provided by Disconnect to identify and block trackers.
</p>
<h1 id="w_change-your-tracking-protection-settings">Change your Tracking Protection settings</h1>
<p>Tracking Protection is enabled by default in <a href="/en-US/kb/private-browsing-firefox-ios">About private browsing in Firefox for iOS</a> for additional privacy. Follow these steps to turn on Tracking Protection in regular browsing mode or to turn it off completely.
</p>
<ol><li>Tap the menu button at the bottom of the screen on your iPhone or at the top right of the screen on your iPad. (You might need to scroll all the way to the top of the page for the menu button to appear).
</li><li>Tap the Settings icon in the menu panel at the bottom of the screen. (You might need to swipe to the next panel first.) 
</li><li>Scroll to the <em>Privacy</em> section and tap <span class="menu">Tracking Protection</span>.
<dl><dt><img alt="tracking protection ios" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2017-09-11-13-35-42-00f944.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>Tap the option that you prefer to put a check mark next to it:
<ul><li><strong>Always on:</strong> Blocks trackers even in regular browsing.
</li><li><strong>Private Browsing Mode only:</strong> Blocks trackers only on Private Tabs. This is the default option.
</li><li><strong>Never:</strong> Firefox will not block trackers.
</li></ul>
</li></ol>
<div class="note"><a href="https://disconnect.me/trackerprotection">Read more</a> about tracking and the standards Disconnect uses to create its list. <a href="https://wiki.mozilla.org/Security/Tracking_protection#Lists">Learn more</a> about the lists used by Firefox for iOS for Tracking Protection.</div>','[{"label": "Revision id", "text": "145009", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 11, 2017, 1:56:11 PM", "datetime": "2017-09-11T13:56:11-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "menu button is on the top right of the screen of your iPad (unlike iPhone where it is at the bottom)", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 11, 2017, 1:56:36 PM", "datetime": "2017-09-11T13:56:36-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Sep 11, 2017, 1:56:36 PM", "datetime": "2017-09-11T13:56:36-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:40:19+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (148795,'en-US','set-firefox-focus-default-browser-android','Set Firefox Focus as default browser on Android','https://support.mozilla.org/en-US/kb/set-firefox-focus-default-browser-android','https://support.mozilla.org/en-US/kb/set-firefox-focus-default-browser-android/revision/148795',147820,'2017-10-23T15:37:22-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP do not approve, needs input from Joni and Tonnes',1,'2017-10-25T02:06:28-07:00','heyjoni',1,0,1,'2017-10-25T02:06:28-07:00','heyjoni','approved','Set Firefox Focus as your default browser if you want it to open links by default. Here''s how to do it for different versions of Android:

=Android version 7 and Android version 8=

#Tap the menu button at the top right corner
#;[[Image:focus menu android]]
#Tap {menu Settings}.
#Tap the switch next to ''''Make default browser'''' to turn it on (blue means on).
#This will open up the ''''Default apps'''' screen.
#Tap {menu Browser app}.
#Tap ''''''Firefox Focus'''''' to select it.

=Android version 6=
#In the Settings menu on your phone, tap ''''''Apps & notifications'''''' (it may be called ''''''Apps'''''' on some versions of Android).
#Tap {menu Advanced} (you may have to tap on the {button Gear} icon first on some versions of Android).
#Tap {menu Default apps}.
#Tap {menu Browser app} to open a list of choices.
#Tap ''''''Firefox Focus'''''' to select it.

=Android version 5 and older=

==Step 1: Clear the current browser that opens links==
# Open the Settings application and tap on {button Apps}. (On some versions of Android this button is labelled "Applications" and you may have to tap on {button Manage applications} before the next step.)
# Tap on the {button All} tab.
#;[[Image:Android ICS Manage Apps - Cropped just showing stock]]
# Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
# Tap on {button Clear defaults} to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another browser or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser.
#;[[Image:Android ICS Clear defaults - Cropped]]

==Step 2: Set Firefox Focus to be the default browser for opening links==
# Open a link in an Android application like the Mail application.
# Tap on {button Firefox Focus} and then tap on {button Always}.','<p>Set Firefox Focus as your default browser if you want it to open links by default. Here''s how to do it for different versions of Android:
</p>
<h1 id="w_android-version-7-and-android-version-8">Android version 7 and Android version 8</h1>
<ol><li>Tap the menu button at the top right corner
<dl><dt><img alt="focus menu android" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2017-05-18-06-44-43-c75311.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>Tap <span class="menu">Settings</span>.
</li><li>Tap the switch next to <em>Make default browser</em> to turn it on (blue means on).
</li><li>This will open up the <em>Default apps</em> screen.
</li><li>Tap <span class="menu">Browser app</span>.
</li><li>Tap <strong>Firefox Focus</strong> to select it.
</li></ol>
<h1 id="w_android-version-6">Android version 6</h1>
<ol><li>In the Settings menu on your phone, tap <strong>Apps &amp; notifications</strong> (it may be called <strong>Apps</strong> on some versions of Android).
</li><li>Tap <span class="menu">Advanced</span> (you may have to tap on the <span class="button">Gear</span> icon first on some versions of Android).
</li><li>Tap <span class="menu">Default apps</span>.
</li><li>Tap <span class="menu">Browser app</span> to open a list of choices.
</li><li>Tap <strong>Firefox Focus</strong> to select it.
</li></ol>
<h1 id="w_android-version-5-and-older">Android version 5 and older</h1>
<h2 id="w_step-1-clear-the-current-browser-that-opens-links">Step 1: Clear the current browser that opens links</h2>
<ol><li> Open the Settings application and tap on <span class="button">Apps</span>. (On some versions of Android this button is labelled "Applications" and you may have to tap on <span class="button">Manage applications</span> before the next step.)
</li><li> Tap on the <span class="button">All</span> tab.
<dl><dt><img alt="Android ICS Manage Apps - Cropped just showing stock" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-12-11-59-02-8caa08.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
</li><li> Tap on <span class="button">Clear defaults</span> to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another browser or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser.
<dl><dt><img alt="Android ICS Clear defaults - Cropped" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-03-22-30-33-ca626d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ol>
<h2 id="w_step-2-set-firefox-focus-to-be-the-default-browser-for-opening-links">Step 2: Set Firefox Focus to be the default browser for opening links</h2>
<ol><li> Open a link in an Android application like the Mail application.
</li><li> Tap on <span class="button">Firefox Focus</span> and then tap on <span class="button">Always</span>.
</li></ol>','[{"label": "Revision id", "text": "148795", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 23, 2017, 3:37:22 PM", "datetime": "2017-10-23T15:37:22-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP do not approve, needs input from Joni and Tonnes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 25, 2017, 2:06:28 AM", "datetime": "2017-10-25T02:06:28-07:00", "href": null}, {"label": "Reviewed by", "text": "heyjoni", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 25, 2017, 2:06:28 AM", "datetime": "2017-10-25T02:06:28-07:00", "href": null}, {"label": "Readied for localization by", "text": "heyjoni", "datetime": null, "href": null}]','2026-11-03T18:40:17+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (149061,'en-US','templateandroidversion','Template:androidversion','https://support.mozilla.org/en-US/kb/templateandroidversion','https://support.mozilla.org/en-US/kb/templateandroidversion/revision/149061',NULL,'2017-10-25T03:52:13-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','add comments about specific android versions',1,'2017-10-25T03:52:50-07:00','rtanglao',1,0,1,'2017-10-25T03:52:50-07:00','rtanglao','approved','<!--
Samsung Note 8, Android 7.1.1 Settings->About phone->Software information
Samsung SII, Android 4.1.2 Settings->About device
-->
{note}To find your version of Android, open the Settings app, tap ''''''About phone'''''', ''''''About tablet'''''' or ''''''About device'''''' and if your Android version is not shown, tap ''''''Android version'''''' (or ''''''Software information'''''' on some versions of Android).{/note}','<p>
</p>
<div class="note">To find your version of Android, open the Settings app, tap <strong>About phone</strong>, <strong>About tablet</strong> or <strong>About device</strong> and if your Android version is not shown, tap <strong>Android version</strong> (or <strong>Software information</strong> on some versions of Android).</div>','[{"label": "Revision id", "text": "149061", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 25, 2017, 3:52:13 AM", "datetime": "2017-10-25T03:52:13-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "add comments about specific android versions", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 25, 2017, 3:52:50 AM", "datetime": "2017-10-25T03:52:50-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 25, 2017, 3:52:50 AM", "datetime": "2017-10-25T03:52:50-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:40:15+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (149062,'en-US','set-firefox-focus-default-browser-android','Set Firefox Focus as default browser on Android','https://support.mozilla.org/en-US/kb/set-firefox-focus-default-browser-android','https://support.mozilla.org/en-US/kb/set-firefox-focus-default-browser-android/revision/149062',148795,'2017-10-25T03:57:08-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','add [[template::androidversion]]',1,'2017-10-25T03:57:30-07:00','rtanglao',1,0,1,'2017-10-25T03:57:30-07:00','rtanglao','approved','Set Firefox Focus as your default browser if you want it to open links by default. The instructions vary depending on your version of Android:
[[Template:androidversion]]
Here''s how to do it for your version of Android:

=Android version 7 and Android version 8=

#Tap the menu button at the top right corner
#;[[Image:focus menu android]]
#Tap {menu Settings}.
#Tap the switch next to ''''Make default browser'''' to turn it on (blue means on).
#This will open up the ''''Default apps'''' screen.
#Tap {menu Browser app}.
#Tap ''''''Firefox Focus'''''' to select it.

=Android version 6=
#In the Settings menu on your phone, tap ''''''Apps & notifications'''''' (it may be called ''''''Apps'''''' on some versions of Android).
#Tap {menu Advanced} (you may have to tap on the {button Gear} icon first on some versions of Android).
#Tap {menu Default apps}.
#Tap {menu Browser app} to open a list of choices.
#Tap ''''''Firefox Focus'''''' to select it.

=Android version 5 and older=

==Step 1: Clear the current browser that opens links==
# Open the Settings application and tap on {button Apps}. (On some versions of Android this button is labelled "Applications" and you may have to tap on {button Manage applications} before the next step.)
# Tap on the {button All} tab.
#;[[Image:Android ICS Manage Apps - Cropped just showing stock]]
# Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
# Tap on {button Clear defaults} to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another browser or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser.
#;[[Image:Android ICS Clear defaults - Cropped]]

==Step 2: Set Firefox Focus to be the default browser for opening links==
# Open a link in an Android application like the Mail application.
# Tap on {button Firefox Focus} and then tap on {button Always}.','<p>Set Firefox Focus as your default browser if you want it to open links by default. The instructions vary depending on your version of Android:
</p><p>
</p>
<div class="note">To find your version of Android, open the Settings app, tap <strong>About phone</strong>, <strong>About tablet</strong> or <strong>About device</strong> (you may have to tap on the <strong>More</strong> tab on some versions of Android) and if your Android version is not shown, tap <strong>Android version</strong> (or <strong>Software information</strong> on some versions of Android).</div>
Here''s how to do it for your version of Android:
<p></p>
<h1 id="w_android-version-7-and-android-version-8">Android version 7 and Android version 8</h1>
<ol><li>Tap the menu button at the top right corner
<dl><dt><img alt="focus menu android" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2017-05-18-06-44-43-c75311.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li>Tap <span class="menu">Settings</span>.
</li><li>Tap the switch next to <em>Make default browser</em> to turn it on (blue means on).
</li><li>This will open up the <em>Default apps</em> screen.
</li><li>Tap <span class="menu">Browser app</span>.
</li><li>Tap <strong>Firefox Focus</strong> to select it.
</li></ol>
<h1 id="w_android-version-6">Android version 6</h1>
<ol><li>In the Settings menu on your phone, tap <strong>Apps &amp; notifications</strong> (it may be called <strong>Apps</strong> on some versions of Android).
</li><li>Tap <span class="menu">Advanced</span> (you may have to tap on the <span class="button">Gear</span> icon first on some versions of Android).
</li><li>Tap <span class="menu">Default apps</span>.
</li><li>Tap <span class="menu">Browser app</span> to open a list of choices.
</li><li>Tap <strong>Firefox Focus</strong> to select it.
</li></ol>
<h1 id="w_android-version-5-and-older">Android version 5 and older</h1>
<h2 id="w_step-1-clear-the-current-browser-that-opens-links">Step 1: Clear the current browser that opens links</h2>
<ol><li> Open the Settings application and tap on <span class="button">Apps</span>. (On some versions of Android this button is labelled "Applications" and you may have to tap on <span class="button">Manage applications</span> before the next step.)
</li><li> Tap on the <span class="button">All</span> tab.
<dl><dt><img alt="Android ICS Manage Apps - Cropped just showing stock" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-12-11-59-02-8caa08.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> Tap on the current browser that opens links. This is usually the default browser which is called "Browser" or "Internet".
</li><li> Tap on <span class="button">Clear defaults</span> to prevent this browser from opening links by default. If "Clear defaults" is greyed out, then either you have not installed another browser or you have installed another browser like Opera and it is set to be the default browser. If you have installed another browser, go back to the previous step and repeat with the default browser.
<dl><dt><img alt="Android ICS Clear defaults - Cropped" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-02-03-22-30-33-ca626d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ol>
<h2 id="w_step-2-set-firefox-focus-to-be-the-default-browser-for-opening-links">Step 2: Set Firefox Focus to be the default browser for opening links</h2>
<ol><li> Open a link in an Android application like the Mail application.
</li><li> Tap on <span class="button">Firefox Focus</span> and then tap on <span class="button">Always</span>.
</li></ol>','[{"label": "Revision id", "text": "149062", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 25, 2017, 3:57:08 AM", "datetime": "2017-10-25T03:57:08-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "add [[template::androidversion]]", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 25, 2017, 3:57:30 AM", "datetime": "2017-10-25T03:57:30-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 25, 2017, 3:57:30 AM", "datetime": "2017-10-25T03:57:30-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:40:12+00:00');
