INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (155932,'en-US','utf-8-only-file-paths','File system paths on Linux are always treated as UTF-8','https://support.mozilla.org/en-US/kb/utf-8-only-file-paths','https://support.mozilla.org/en-US/kb/utf-8-only-file-paths/revision/155932',155921,'2018-01-18T09:22:33-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','minor nits!',1,'2018-01-18T09:22:54-08:00','rtanglao',1,1,1,'2018-01-18T09:22:54-08:00','rtanglao','approved','{for not linux}{warning}This article applies to Linux systems only.{/warning}{/for}

If you are using Linux, your file system has to be encoded in UTF-8 or Firefox won''t understand it and it will generate error messages such as "Error: The profile path is not valid UTF-8. Unable to continue."

If you''re not able to configure your filesystem as UTF-8, we recommend using only the letters a-z in the name of the Firefox profile and the download directory.

To change the way your file system is encoded, please consult the documentation for your Linux distribution.

{note}For more information about UTF-8, see [https://developer.mozilla.org/en-US/docs/Glossary/UTF-8 UTF-8 on the Mozilla Developer Network (MDN)].{/note}','<div class="for" data-for="not linux"><div class="warning">This article applies to Linux systems only.</div></div>
<p>If you are using Linux, your file system has to be encoded in UTF-8 or Firefox won''t understand it and it will generate error messages such as "Error: The profile path is not valid UTF-8. Unable to continue."
</p><p>If you''re not able to configure your filesystem as UTF-8, we recommend using only the letters a-z in the name of the Firefox profile and the download directory.
</p><p>To change the way your file system is encoded, please consult the documentation for your Linux distribution.
</p>
<div class="note">For more information about UTF-8, see <a href="https://developer.mozilla.org/en-US/docs/Glossary/UTF-8">UTF-8 on the Mozilla Developer Network (MDN)</a>.</div>','[{"label": "Revision id", "text": "155932", "datetime": null, "href": null}, {"label": "Created", "text": "Jan 18, 2018, 9:22:33 AM", "datetime": "2018-01-18T09:22:33-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "minor nits!", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jan 18, 2018, 9:22:54 AM", "datetime": "2018-01-18T09:22:54-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jan 18, 2018, 9:22:54 AM", "datetime": "2018-01-18T09:22:54-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:39:54+00:00');
