INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (263988,'en-US','troubleshoot-mode-thunderbird','Troubleshoot Mode Thunderbird','https://support.mozilla.org/en-US/kb/troubleshoot-mode-thunderbird','https://support.mozilla.org/en-US/kb/troubleshoot-mode-thunderbird/revision/263988',253973,'2023-08-01T09:55:45-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','link to see [[userChrome.css and .js and userContent are unsupported]]',1,'2023-08-01T09:56:05-07:00','rtanglao',1,0,1,'2023-08-01T09:56:05-07:00','rtanglao','approved','''''''Troubleshoot Mode'''''' runs Thunderbird with some features and customizations disabled ([[#w_what-does-troubleshoot-mode-disable|see below]] for details), does not affect your data,  and changes are temporary unless you choose to make them permanent. If you are having a problem in Thunderbird that does not occur in Troubleshoot Mode, then the cause of the problem is one of the disabled items.
{note}''''''Note:'''''' Thunderbird Troubleshoot Mode was previously called ''''Thunderbird Safe Mode''''{for mac,linux}.{/for}{for win}, which has no relation to ''''Windows'''' Safe Mode.{/for} Prior to Thunderbird 91, the menu entry was labeled ''''Restart with Add-ons Disabled''''.{/note}

__TOC__

=Starting Thunderbird in Troubleshoot Mode=

# Switch to Troubleshoot Mode:
#* ''''''If Thunderbird is not running:'''''' {for win}Hold down the {key Shift} key while starting Thunderbird.{/for}{for mac}Hold down the {key option} key while starting Thunderbird.{/for}{for linux}From ''''''Terminal'''''', run this command: <code>thunderbird -safe-mode</code><br>You may need to specify the Thunderbird installation path (e.g. {filepath /usr/lib/thunderbird} or {filepath ~/Downloads/thunderbird/thunderbird}).{/for}
#* ''''''If Thunderbird is already running:'''''' Click {button ≡} > {menu Help} > {menu Troubleshoot Mode} and in the ''''Restart in Troubleshoot Mode'''' prompt, choose {button Restart}.
# In the ''''''Thunderbird Troubleshoot Mode'''''' dialog, click {button Continue in Troubleshoot Mode} button.
#;[[Image:TB91-thunderbird-troubleshoot-mode-dialog-marked]]
#;{note}If you want Troubleshoot Mode changes to be temporary, do not check the checkboxes - temporary is the default. But you can choose to make the changes permanent.{/note}
# Click {button ≡}  > {menu Help} and check if you see {menu Turn Troubleshoot Mode Off} in the menu, to confirm that Thunderbird is currently running in Troubleshoot Mode.

=Turning Troubleshoot Mode off=
Click {button ≡} > {menu Help} > {menu Turn Troubleshoot Mode Off} to immediately close Thunderbird and restart it in normal mode.

Or you can just exit Thunderbird and start as you normally would.

=Diagnosing problems in Troubleshoot Mode=
After you start Thunderbird in ''''Troubleshoot Mode'''', test its behavior to see if the problem goes away.

==The problem still happens in Troubleshoot Mode==
If the problem still happens in Troubleshoot Mode, it is not being caused by an extension or theme installed in Thunderbird. Possible causes and solutions include:

{for win}
* Something wrong with your Thunderbird installation: Reinstall Thunderbird from https://www.thunderbird.net/.
{/for}
{for linux}
* Something is wrong with your Thunderbird installation: If you had installed Thunderbird using the Linux package manager, try reinstalling it. Also investigate possible library conflicts, and consider using the Thunderbird supplied package from https://www.thunderbird.net/.
{/for}
{for win}
* Something wrong with your operating system: Start [https://support.microsoft.com/en-us/help/12376/windows-10-start-your-pc-in-safe-mode Windows in safe mode].
{/for}
* Changes made to Thunderbird preference settings not disabled in Troubleshoot Mode.

<!-- See the following articles for solutions:
*[[Troubleshoot and diagnose Firefox problems]] -->
<!-- *[[Reset Firefox preferences to troubleshoot and fix problems]] -->

==The problem no longer happens in Troubleshoot Mode==
If the problem no longer happens in Troubleshoot Mode, the most likely cause is an extension, theme or hardware acceleration. Possible solutions include switching back to normal mode, then doing the following. (You may need to restart Thunderbird after each step to see if it solves the problem.)
* Progressively disable extensions in the add-ons manager: Click {button ≡} > {button Add-ons and Themes} > {button Extensions}, then check if the problem remains after disabling each extension. When the problem goes away, the last disabled extension is probably the trouble causer. You can try to update it, reinstall it, leave it disabled, or remove it.
* Set the default theme in the add-ons manager: Click {button ≡} > {button Add-ons and Themes} > {button Themes}, then enable the default theme.
* Try turning off hardware acceleration in Thunderbird''s settings: Click {button ≡} > {menu Settings} > {menu General}, then uncheck {menu Use hardware acceleration when available}.

<!-- See this article for solutions:
*[[Troubleshoot extensions, themes and hardware acceleration issues to solve common Firefox problems]] -->

=What does Troubleshoot Mode disable?=

*[[Thunderbird add-ons - frequently asked questions|Add-ons (extensions and themes)]]
*[[Upgrade your graphics drivers to use hardware acceleration and WebGL|Hardware acceleration]]
*[[Changes to toolbars and window sizes are not saved|Window and sidebar size and position settings]] (described in terms of Firefox)
*userChrome and userContent customizations ; see [[userChrome.css and .js and userContent are unsupported]]
*[https://hacks.mozilla.org/2017/02/a-crash-course-in-just-in-time-jit-compilers/ JavaScript Just-in-time (JIT) compiler]','<p><strong>Troubleshoot Mode</strong> runs Thunderbird with some features and customizations disabled (<a href="#w_what-does-troubleshoot-mode-disable">see below</a> for details), does not affect your data,  and changes are temporary unless you choose to make them permanent. If you are having a problem in Thunderbird that does not occur in Troubleshoot Mode, then the cause of the problem is one of the disabled items.
</p>
<div class="note"><strong>Note:</strong> Thunderbird Troubleshoot Mode was previously called <em>Thunderbird Safe Mode</em><span class="for" data-for="mac,linux">.</span><span class="for" data-for="win" style="display: none;">, which has no relation to <em>Windows</em> Safe Mode.</span> Prior to Thunderbird 91, the menu entry was labeled <em>Restart with Add-ons Disabled</em>.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_starting-thunderbird-in-troubleshoot-mode"><span class="tocnumber">1</span> <span class="toctext">Starting Thunderbird in Troubleshoot Mode</span></a></li><li class="toclevel-1"><a href="#w_turning-troubleshoot-mode-off"><span class="tocnumber">2</span> <span class="toctext">Turning Troubleshoot Mode off</span></a></li><li class="toclevel-1"><a href="#w_diagnosing-problems-in-troubleshoot-mode"><span class="tocnumber">3</span> <span class="toctext">Diagnosing problems in Troubleshoot Mode</span></a><ul><li class="toclevel-2"><a href="#w_the-problem-still-happens-in-troubleshoot-mode"><span class="tocnumber">3.1</span> <span class="toctext">The problem still happens in Troubleshoot Mode</span></a></li><li class="toclevel-2"><a href="#w_the-problem-no-longer-happens-in-troubleshoot-mode"><span class="tocnumber">3.2</span> <span class="toctext">The problem no longer happens in Troubleshoot Mode</span></a></li></ul></li><li class="toclevel-1"><a href="#w_what-does-troubleshoot-mode-disable"><span class="tocnumber">4</span> <span class="toctext">What does Troubleshoot Mode disable?</span></a></li></ul></div>
<h1 id="w_starting-thunderbird-in-troubleshoot-mode">Starting Thunderbird in Troubleshoot Mode</h1>
<ol><li> Switch to Troubleshoot Mode:
<ul><li> <strong>If Thunderbird is not running:</strong> <span class="for" data-for="win" style="display: none;">Hold down the <span class="key">Shift</span> key while starting Thunderbird.</span><span class="for" data-for="mac">Hold down the <span class="key">option</span> key while starting Thunderbird.</span><span class="for" data-for="linux" style="display: none;">From <strong>Terminal</strong>, run this command: <code>thunderbird -safe-mode</code><br>You may need to specify the Thunderbird installation path (e.g. <span class="filepath">/usr/lib/thunderbird</span> or <span class="filepath">~/Downloads/thunderbird/thunderbird</span>).</span>
</li><li> <strong>If Thunderbird is already running:</strong> Click <span class="button">≡</span> &gt; <span class="menu">Help</span> &gt; <span class="menu">Troubleshoot Mode</span> and in the <em>Restart in Troubleshoot Mode</em> prompt, choose <span class="button">Restart</span>.
</li></ul>
</li><li> In the <strong>Thunderbird Troubleshoot Mode</strong> dialog, click <span class="button">Continue in Troubleshoot Mode</span> button.
<dl><dt><img alt="TB91-thunderbird-troubleshoot-mode-dialog-marked" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2021-08-20-15-10-04-736db0.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt><dt><div class="note">If you want Troubleshoot Mode changes to be temporary, do not check the checkboxes - temporary is the default. But you can choose to make the changes permanent.</div>
</dt></dl>
</li><li> Click <span class="button">≡</span>  &gt; <span class="menu">Help</span> and check if you see <span class="menu">Turn Troubleshoot Mode Off</span> in the menu, to confirm that Thunderbird is currently running in Troubleshoot Mode.
</li></ol>
<h1 id="w_turning-troubleshoot-mode-off">Turning Troubleshoot Mode off</h1>
<p>Click <span class="button">≡</span> &gt; <span class="menu">Help</span> &gt; <span class="menu">Turn Troubleshoot Mode Off</span> to immediately close Thunderbird and restart it in normal mode.
</p><p>Or you can just exit Thunderbird and start as you normally would.
</p>
<h1 id="w_diagnosing-problems-in-troubleshoot-mode">Diagnosing problems in Troubleshoot Mode</h1>
<p>After you start Thunderbird in <em>Troubleshoot Mode</em>, test its behavior to see if the problem goes away.
</p>
<h2 id="w_the-problem-still-happens-in-troubleshoot-mode">The problem still happens in Troubleshoot Mode</h2>
<p>If the problem still happens in Troubleshoot Mode, it is not being caused by an extension or theme installed in Thunderbird. Possible causes and solutions include:
</p><div class="for" data-for="win" style="display: none;">
<ul><li> Something wrong with your Thunderbird installation: Reinstall Thunderbird from <a href="https://www.thunderbird.net/">https://www.thunderbird.net/</a>.
</li></ul>
</div><div class="for" data-for="linux" style="display: none;">
<ul><li> Something is wrong with your Thunderbird installation: If you had installed Thunderbird using the Linux package manager, try reinstalling it. Also investigate possible library conflicts, and consider using the Thunderbird supplied package from <a href="https://www.thunderbird.net/">https://www.thunderbird.net/</a>.
</li></ul>
</div><div class="for" data-for="win" style="display: none;">
<ul><li> Something wrong with your operating system: Start <a href="https://support.microsoft.com/en-us/help/12376/windows-10-start-your-pc-in-safe-mode">Windows in safe mode</a>.
</li></ul>
</div>
<ul><li> Changes made to Thunderbird preference settings not disabled in Troubleshoot Mode.
</li></ul>
<p>

</p><p>
</p>
<h2 id="w_the-problem-no-longer-happens-in-troubleshoot-mode">The problem no longer happens in Troubleshoot Mode</h2>
<p>If the problem no longer happens in Troubleshoot Mode, the most likely cause is an extension, theme or hardware acceleration. Possible solutions include switching back to normal mode, then doing the following. (You may need to restart Thunderbird after each step to see if it solves the problem.)
</p>
<ul><li> Progressively disable extensions in the add-ons manager: Click <span class="button">≡</span> &gt; <span class="button">Add-ons and Themes</span> &gt; <span class="button">Extensions</span>, then check if the problem remains after disabling each extension. When the problem goes away, the last disabled extension is probably the trouble causer. You can try to update it, reinstall it, leave it disabled, or remove it.
</li><li> Set the default theme in the add-ons manager: Click <span class="button">≡</span> &gt; <span class="button">Add-ons and Themes</span> &gt; <span class="button">Themes</span>, then enable the default theme.
</li><li> Try turning off hardware acceleration in Thunderbird''s settings: Click <span class="button">≡</span> &gt; <span class="menu">Settings</span> &gt; <span class="menu">General</span>, then uncheck <span class="menu">Use hardware acceleration when available</span>.
</li></ul>
<p>

</p><h1 id="w_what-does-troubleshoot-mode-disable">What does Troubleshoot Mode disable?</h1>
<ul><li><a href="/en-US/kb/thunderbird-add-ons-frequently-asked-questions">Add-ons (extensions and themes)</a>
</li><li><a href="/en-US/kb/upgrade-graphics-drivers-use-hardware-acceleration">Hardware acceleration</a>
</li><li><a href="/en-US/kb/changes-toolbars-and-window-sizes-are-not-saved">Window and sidebar size and position settings</a> (described in terms of Firefox)
</li><li>userChrome and userContent customizations&nbsp;; see <a href="/en-US/kb/userchromecss-js-usercontent-unsupported">userChrome.css and .js and userContent are unsupported</a>
</li><li><a href="https://hacks.mozilla.org/2017/02/a-crash-course-in-just-in-time-jit-compilers/">JavaScript Just-in-time (JIT) compiler</a>
</li></ul>','[{"label": "Revision id", "text": "263988", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 1, 2023, 9:55:45 AM", "datetime": "2023-08-01T09:55:45-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "link to see [[userChrome.css and .js and userContent are unsupported]]", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 1, 2023, 9:56:05 AM", "datetime": "2023-08-01T09:56:05-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 1, 2023, 9:56:05 AM", "datetime": "2023-08-01T09:56:05-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:37:41+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (263989,'en-US','firefox-advanced-customization-and-configuration','Firefox advanced customization and configuration options','https://support.mozilla.org/en-US/kb/firefox-advanced-customization-and-configuration','https://support.mozilla.org/en-US/kb/firefox-advanced-customization-and-configuration/revision/263989',259638,'2023-08-01T09:59:27-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','link to new Thunderbird article about userChrome not being supported.',1,'2023-08-01T10:00:17-07:00','rtanglao',1,0,1,'2023-08-01T10:00:17-07:00','rtanglao','approved','Firefox supports a wide range of customization options that are well-suited to all skill levels. The [[Customize Firefox controls, buttons and toolbars|toolbar layout can be customized]], numerous [[Firefox options, preferences and settings|settings can be configured]], and the [https://addons.mozilla.org Mozilla Add-ons] directory contains a massive library of [[Find and install add-ons to add features to Firefox|extensions]] and [[Use themes to change the look of Firefox|themes]] to add additional functionality and make Firefox reflect your own needs and personality.

Two other forms of advanced configuration allow even further customization: ''''about:config'''' preference modifications and ''''userChrome.css'''' or ''''userContent.css'''' custom style rules. However, Mozilla highly recommends that only the developers consider these customizations, as they could cause unexpected behavior or even break Firefox.

Firefox is a work in progress and, to allow for continuous innovation, Mozilla cannot guarantee that future updates won’t impact these customizations. For this reason, Mozilla does not officially support adding custom style rules with a {filepath userChrome.css} or {filepath userContent.css} file, or using the ''''about:config'''' [[Configuration Editor for Firefox|configuration editor]] to modify preference settings.

If Firefox suddenly appears broken after an update, you may need to [[Refresh Firefox - reset add-ons and settings|use the Refresh feature]] to restore Firefox to a default state while keeping important data. Alternatively, you can selectively reverse your advanced customization and configuration changes, as follows: 
*To reverse changes you made to Firefox with a {filepath userChrome.css} or {filepath userContent.css} file, use ''''about:config'''' to [[Configuration Editor for Firefox#w_resetting-or-deleting-preferences|reset the preference]] {pref toolkit.legacyUserProfileCustomizations.stylesheets} to {pref false} and then remove (or rename) the {filepath userChrome.css} or {filepath userContent.css} file located inside the {filepath chrome} folder in your Firefox [[Profiles - Where Firefox stores your bookmarks, passwords and other user data|profile folder]].  This also applies to Thunderbird. Please refer to Thunderbird''s article: [[userChrome.css and .js and userContent are unsupported]]
*To reset all preference modifications, either use ''''about:config'''' to [[Configuration Editor for Firefox#w_resetting-or-deleting-preferences|reset all modified preferences]] or else delete the preference file(s) in your [[Profiles - Where Firefox stores your bookmarks, passwords and other user data|profile folder]], as explained [[Reset Firefox preferences to troubleshoot and fix problems#w_solution-2-delete-firefox-preference-files|here]], to restore all preferences to default settings.','<p>Firefox supports a wide range of customization options that are well-suited to all skill levels. The <a href="/en-US/kb/customize-firefox-controls-buttons-and-toolbars">toolbar layout can be customized</a>, numerous <a href="/en-US/kb/firefox-options-preferences-and-settings">settings can be configured</a>, and the <a href="https://addons.mozilla.org">Mozilla Add-ons</a> directory contains a massive library of <a href="/en-US/kb/find-and-install-add-ons-add-features-to-firefox">extensions</a> and <a href="/en-US/kb/use-themes-change-look-of-firefox">themes</a> to add additional functionality and make Firefox reflect your own needs and personality.
</p><p>Two other forms of advanced configuration allow even further customization: <em>about:config</em> preference modifications and <em>userChrome.css</em> or <em>userContent.css</em> custom style rules. However, Mozilla highly recommends that only the developers consider these customizations, as they could cause unexpected behavior or even break Firefox.
</p><p>Firefox is a work in progress and, to allow for continuous innovation, Mozilla cannot guarantee that future updates won’t impact these customizations. For this reason, Mozilla does not officially support adding custom style rules with a <span class="filepath">userChrome.css</span> or <span class="filepath">userContent.css</span> file, or using the <em>about:config</em> <a href="/en-US/kb/about-config-editor-firefox">configuration editor</a> to modify preference settings.
</p><p>If Firefox suddenly appears broken after an update, you may need to <a href="/en-US/kb/refresh-firefox-reset-add-ons-and-settings">use the Refresh feature</a> to restore Firefox to a default state while keeping important data. Alternatively, you can selectively reverse your advanced customization and configuration changes, as follows: 
</p>
<ul><li>To reverse changes you made to Firefox with a <span class="filepath">userChrome.css</span> or <span class="filepath">userContent.css</span> file, use <em>about:config</em> to <a href="/en-US/kb/about-config-editor-firefox#w_resetting-or-deleting-preferences">reset the preference</a> <span class="pref">toolkit.legacyUserProfileCustomizations.stylesheets</span> to <span class="pref">false</span> and then remove (or rename) the <span class="filepath">userChrome.css</span> or <span class="filepath">userContent.css</span> file located inside the <span class="filepath">chrome</span> folder in your Firefox <a href="/en-US/kb/profiles-where-firefox-stores-user-data">profile folder</a>.  This also applies to Thunderbird. Please refer to Thunderbird''s article: <a href="/en-US/kb/userchromecss-js-usercontent-unsupported">userChrome.css and .js and userContent are unsupported</a>
</li><li>To reset all preference modifications, either use <em>about:config</em> to <a href="/en-US/kb/about-config-editor-firefox#w_resetting-or-deleting-preferences">reset all modified preferences</a> or else delete the preference file(s) in your <a href="/en-US/kb/profiles-where-firefox-stores-user-data">profile folder</a>, as explained <a href="/en-US/kb/reset-preferences-fix-problems#w_solution-2-delete-firefox-preference-files">here</a>, to restore all preferences to default settings.
</li></ul>','[{"label": "Revision id", "text": "263989", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 1, 2023, 9:59:27 AM", "datetime": "2023-08-01T09:59:27-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "link to new Thunderbird article about userChrome not being supported.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 1, 2023, 10:00:17 AM", "datetime": "2023-08-01T10:00:17-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 1, 2023, 10:00:17 AM", "datetime": "2023-08-01T10:00:17-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:37:38+00:00');
