</p>','[{"label": "Revision id", "text": "265432", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 6, 2023, 12:52:51 PM", "datetime": "2023-09-06T12:52:51-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "Why are my Thunderbird customizations broken in 115?", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 6, 2023, 12:53:22 PM", "datetime": "2023-09-06T12:53:22-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:37:08+00:00');
