</td></tr>
<tr>
<td><a href="/en-US/kb/archived-messages">Archive Message</a></td><td><span class="key">A</span>
</td></tr>
<tr>
<td>Delete message, folder, attachment, or selected search text</td><td><span class="key">Del</span>
</td></tr>
<tr>
<td>Delete message bypassing trash (no Undo!)</td><td><span class="key">Shift</span> + <span class="key">Del</span>
</td></tr>
<tr>
<td>Undo</td><td><span class="for" data-for="win,linux" style="display: none;"><span class="key">Ctrl</span> + <span class="key">Z</span></span><span class="for" data-for="mac"><span class="key">Command</span> + <span class="key">Z</span></span>
</td></tr>
<tr>
<td>Redo</td><td><span class="for" data-for="win,linux" style="display: none;"><span class="key">Ctrl</span> + <span class="key">Y</span></span><span class="for" data-for="mac"><span class="key">Command</span> + <span class="key">Y</span></span>
</td></tr>
<tr>
<td>Rename Folder</td><td><span class="for" data-for="win,linux" style="display: none;"><span class="key">F2</span></span>
</td></tr>
<tr>
<th><a href="/en-US/kb/message-tags">Tagging</a> and marking your messages</th><th>
</th></tr>
<tr>
<td>Add/Remove Tag</td><td><span class="key">1</span> to <span class="key">9</span>
</td></tr>
<tr>
<td>Remove All Tags from Message</td><td><span class="key">0</span> (zero)
</td></tr>
<tr>
<td>Mark Message as Read/Unread</td><td><span class="key">M</span>
</td></tr>
<tr>
<td>Mark Thread as Read</td><td><span class="key">R</span>
</td></tr>
<tr>
<td>Mark All Read</td><td><span class="key">Shift</span> + <span class="key">C</span>
</td></tr>
<tr>
<td>Mark as Read By Date</td><td><span class="key">C</span>
</td></tr>
<tr>
<td>Mark as Junk</td><td><span class="key">J</span>
</td></tr>
<tr>
<td>Mark as Not Junk</td><td><span class="key">Shift</span> + <span class="key">J</span>
</td></tr>
<tr>
<td>Add/Remove Star</td><td><span class="key">S</span>
</td></tr></tbody></table>
