INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (275522,'en-US','microsoft-oauth-authentication-and-thunderbird-202','Microsoft OAuth Authentication and Thunderbird in 2026','https://support.mozilla.org/en-US/kb/microsoft-oauth-authentication-and-thunderbird-202','https://support.mozilla.org/en-US/kb/microsoft-oauth-authentication-and-thunderbird-202/revision/275522',275440,'2024-01-31T17:18:03.777101-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','add TOC and fix formatting: https://github.com/thunderbird/knowledgebase-issues/issues/37',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Microsoft has made some changes to authentication for their hosted email services for business and academic accounts. This article describes these changes and how to adjust to them. As of January 2024, this information is still evolving and subject to change.

