</p>','[{"label": "Revision id", "text": "277320", "datetime": null, "href": null}, {"label": "Created", "text": "Mar 5, 2024, 9:47:11 AM", "datetime": "2024-03-05T09:47:11.837248-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not approve, needs collapsible sections and wayne''s approval", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:34:14+00:00');
