</p>','[{"label": "Revision id", "text": "282401", "datetime": null, "href": null}, {"label": "Created", "text": "Jul 11, 2024, 12:11:07 AM", "datetime": "2024-07-11T00:11:07.584759-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP, do not translate, needs approval from Wayne et al", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:33:08+00:00');
