</li><li> Non-ASCII email addresses are not supported.
</li></ul>','[{"label": "Revision id", "text": "287383", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 24, 2024, 8:44:10 AM", "datetime": "2024-10-24T08:44:10.847405-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not localize, needs content obviously (blocked on this feature being finished); https://github.com/thunderbird/android-knowledgebase-issues/issues/5#issuecomment-2435563117", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 24, 2024, 8:44:25 AM", "datetime": "2024-10-24T08:44:25.586292-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:31:46+00:00');
