</li></ul>','[{"label": "Revision id", "text": "289567", "datetime": null, "href": null}, {"label": "Created", "text": "Nov 27, 2024, 7:59:11 AM", "datetime": "2024-11-27T07:59:11.050093-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix typo", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Nov 27, 2024, 7:59:21 AM", "datetime": "2024-11-27T07:59:21.832750-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:30:01+00:00');
