INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (301112,'en-US','new-email-notifications-thunderbird','New email notifications in Thunderbird','https://support.mozilla.org/en-US/kb/new-email-notifications-thunderbird','https://support.mozilla.org/en-US/kb/new-email-notifications-thunderbird/revision/301112',301109,'2025-07-21T22:59:51.578423-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','prepare for screenshot of settings WIP, do not localize or approve please :-) For discussion please leave comments in https://github.com/thunderbird/knowledgebase-issues/issues/89',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','In order for this feature to work, you have to enable and configure notifications both in Thunderbird and in your operating system.
__TOC__
=1. Turn on native notifications in Thunderbird=

# Thunderbird app menu {menu ☰} > {button Settings} > {menu General} > search for ''''''When new messages arrive''''''. {for win}Tick i.e. ensure ''''''Use the system notification'''''' is checked "✓" {/for}
# Click {button Customize...}
# Select which fields and actions you would like to display in your new email notifications.
#;
{warning}Some operating systems have limits on how many actions are displayed in a notification. Windows 11 for example will only display 4 action buttons even if you have selected 5 or more actions.{/warning}
=2. Configure your operating system''s native notifications=
Please follow your operating system''s documentation to enable and configure notifications native to your operating system.','<p>In order for this feature to work, you have to enable and configure notifications both in Thunderbird and in your operating system.
</p>
