INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (304400,'en-US','keyboard-shortcuts-thunderbird','Keyboard shortcuts - perform common Thunderbird tasks quickly','https://support.mozilla.org/en-US/kb/keyboard-shortcuts-thunderbird','https://support.mozilla.org/en-US/kb/keyboard-shortcuts-thunderbird/revision/304400',270016,'2025-09-05T20:13:35.060751-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','caps lock WIP, do not localize or approve please :-) For discussion please comment in: https://github.com/thunderbird/knowledgebase-issues/issues/105',1,'2025-09-05T20:16:38.960208-07:00','rtanglao',1,0,0,NULL,NULL,'approved','Keyboard shortcuts are quick key combinations that let you perform certain tasks in Thunderbird faster. For example, if you want to [[Archived Messages|archive a message]], you can simply strike the {key a} (this is case sensitive, uppercase {key A} doesn''t work unless {key Caps Lock} is on) <!-- uppercase A doesn''t work on macOS and Windows -->
key rather than using the mouse to click the option in a menu. Some shortcuts can be customized or disabled with the use of an add-on.

__TOC__

= About keyboard shortcuts =

In Thunderbird, keyboard shortcuts are context sensitive, which means that they vary according to the area of the Thunderbird interface that is currently "active". For example, when a message is selected in the message list, the Cut, Copy, and Paste keyboard shortcuts are disabled (because it doesn''t make sense to cut and paste text into the message list). Similarly, if you select text while you are reading a message, the Copy shortcut is available, but not the Cut or Paste shortcuts (because while it makes sense to copy text from a message you are reading, it doesn''t make sense to paste text into or cut text from a message you are reading).

The keyboard shortcut functions themselves may vary depending on the part of the Thunderbird interface that is active. For example, if you are writing a message, the {for win,linux}{key Ctrl+A}{/for}{for mac}{key Command+A}{/for} keyboard shortcut selects all the text in the message. However, if a message is highlighted in the message list, {for win,linux}{key Ctrl+A}{/for}{for mac}{key Command+A}{/for} selects all the messages in the message list.

= Shortcut keys and operating systems =

*On Windows and Linux, the shortcut accelerator key is usually the {key Ctrl} key.
*On macOS, the shortcut accelerator key is usually the {key Command} key.
*On macOS laptops, you must hold down the {key fn} key to enable a function key.

= List of keyboard shortcuts =

View Keyboard Shortcuts for:
* [[#w_message-functions|Message functions]]
* [[#w_search-and-filter-functions|Search and filter functions]]
* [[#w_moving-around-thunderbird|Moving around Thunderbird]]
* [[#w_writing-messages|Writing messages]]
* [[#w_address-book|Address Book]]
* [[#w_calendar|Calendar]]
* [[#w_miscellaneous|Miscellaneous]]

