INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (309112,'en-US','thunderbird-and-exchange','Thunderbird and Microsoft protocols (Exchange and Graph)','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange/revision/309112',303318,'2025-10-16T14:31:02.498216-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP: do not localize please until 145 is released, discussion: https://github.com/thunderbird/knowledgebase-issues/issues/109',1,'2025-10-16T14:31:27.061287-07:00','rtanglao',1,0,0,NULL,NULL,'approved','{warning}Warning: The current built-in code for Exchange in Thunderbird is limited to email. Other features (calendar, address book) are planned to follow, but are not available yet. We recommend using Thunderbird 144 or newer for for a more polished, stable experience, Please refer to our [https://wiki.mozilla.org/Thunderbird:Exchange Thunderbird:Exchange wiki page] for full details.{/warning}
__TOC__
==1. Configure your Exchange account==
===Thunderbird profiles with 1 or more accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with one or more accounts, you will see the new Thunderbird ''''''Account Hub'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} 
# Follow the flow by entering your name, email address, and if required, your [https://en.wikipedia.org/wiki/Multi-factor_authentication two factor authentication code] for your Exchange email account. {note}Note: you do not need to enter your password in the ''''''Password'''''' field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.{/note} Here is a screenshot of that panel provided by Microsoft:
#;[[Image:tb-141-oauth-microsoft-enter-password-win11]] 
# Click the {button Exchange} button (not the one labelled {button Exchange  REQUIRES ADD-ON}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange code.{note}Note: The {button Exchange} button only appears if the email you entered is an Exchange account.{/note}
#;[[Image:tb142-beta-exchange-support-button]] 
# Follow the prompts to finish adding your Exchange account.
[[UI:details_start]]
===Thunderbird profile with no accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with no accounts, you will see the older, ''''''Set Up Your Existing Email Address'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} 
# Follow the flow by entering your name, email address, and if required, your [https://en.wikipedia.org/wiki/Multi-factor_authentication two factor authentication code] for your Exchange email account.. {note}Note: you do not need to enter your password in the ''''''Password'''''' field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.{/note} Here is a screenshot of that panel provided by Microsoft:
#;[[Image:tb-141-oauth-microsoft-enter-password-win11]] 
# Click the {button Exchange Web Services} button (not the one labelled {button Exchange/Office365}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange implementation.{note}Note: The {button Exchange Web Services} button only appears if the email you entered is an Exchange account.{/note}
#;[[Image:tb142-beta-old-pre-account-hub-flow-exchange-webservices-button]] 
# Follow the prompts to finish adding your Exchange account.
[[UI:details_end]]
==2. Send and receive emails with your Exchange Account==
Once you have configured your Exchange Account, you can use it to [[Send and receive messages in Thunderbird|send and receive emails]] just like an IMAP or POP account.','<div class="warning">Warning: The current built-in code for Exchange in Thunderbird is limited to email. Other features (calendar, address book) are planned to follow, but are not available yet. We recommend using Thunderbird 144 or newer for for a more polished, stable experience, Please refer to our <a href="https://wiki.mozilla.org/Thunderbird:Exchange">Thunderbird:Exchange wiki page</a> for full details.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_1-configure-your-exchange-account"><span class="tocnumber">1</span> <span class="toctext">1. Configure your Exchange account</span></a><ul><li class="toclevel-2"><a href="#w_thunderbird-profiles-with-1-or-more-accounts"><span class="tocnumber">1.1</span> <span class="toctext">Thunderbird profiles with 1 or more accounts</span></a></li><li class="toclevel-2"><a href="#w_thunderbird-profile-with-no-accounts"><span class="tocnumber">1.2</span> <span class="toctext">Thunderbird profile with no accounts</span></a></li></ul></li><li class="toclevel-1"><a href="#w_2-send-and-receive-emails-with-your-exchange-account"><span class="tocnumber">2</span> <span class="toctext">2. Send and receive emails with your Exchange Account</span></a></li></ul></div>
<h2 id="w_1-configure-your-exchange-account">1. Configure your Exchange account</h2>
<h3 id="w_thunderbird-profiles-with-1-or-more-accounts">Thunderbird profiles with 1 or more accounts</h3>
<p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with one or more accounts, you will see the new Thunderbird <strong>Account Hub</strong> flow:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> 
</li><li> Follow the flow by entering your name, email address, and if required, your <a href="https://en.wikipedia.org/wiki/Multi-factor_authentication">two factor authentication code</a> for your Exchange email account. <div class="note">Note: you do not need to enter your password in the <strong>Password</strong> field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.</div> Here is a screenshot of that panel provided by Microsoft:
<dl><dt><img alt="tb-141-oauth-microsoft-enter-password-win11" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-25-21-26-20-034f89.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Click the <span class="button">Exchange</span> button (not the one labelled <span class="button">Exchange  REQUIRES ADD-ON</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange code.<div class="note">Note: The <span class="button">Exchange</span> button only appears if the email you entered is an Exchange account.</div>
<dl><dt><img alt="tb142-beta-exchange-support-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-03-20-2802fd.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Follow the prompts to finish adding your Exchange account.
</li></ol>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h3 id="w_thunderbird-profile-with-no-accounts" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Thunderbird profile with no accounts</button></h3><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true"><p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with no accounts, you will see the older, <strong>Set Up Your Existing Email Address</strong> flow:
</p><ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> 
</li><li> Follow the flow by entering your name, email address, and if required, your <a href="https://en.wikipedia.org/wiki/Multi-factor_authentication">two factor authentication code</a> for your Exchange email account.. <div class="note">Note: you do not need to enter your password in the <strong>Password</strong> field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.</div> Here is a screenshot of that panel provided by Microsoft:
<dl><dt><img alt="tb-141-oauth-microsoft-enter-password-win11" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-25-21-26-20-034f89.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Click the <span class="button">Exchange Web Services</span> button (not the one labelled <span class="button">Exchange/Office365</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange implementation.<div class="note">Note: The <span class="button">Exchange Web Services</span> button only appears if the email you entered is an Exchange account.</div>
<dl><dt><img alt="tb142-beta-old-pre-account-hub-flow-exchange-webservices-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-23-12-9340ff.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Follow the prompts to finish adding your Exchange account.
</li></ol><p></p></div>


</section>
<p></p>
<h2 id="w_2-send-and-receive-emails-with-your-exchange-account">2. Send and receive emails with your Exchange Account</h2>
<p>Once you have configured your Exchange Account, you can use it to <a href="/en-US/kb/sending-and-receiving-messages-thunderbird">send and receive emails</a> just like an IMAP or POP account.
</p>','[{"label": "Revision id", "text": "309112", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 16, 2025, 2:31:02 PM", "datetime": "2025-10-16T14:31:02.498216-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not localize please until 145 is released, discussion: https://github.com/thunderbird/knowledgebase-issues/issues/109", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 16, 2025, 2:31:27 PM", "datetime": "2025-10-16T14:31:27.061287-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:25:30+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (309224,'en-US','stop-screen-brightness-dimming-thunderbird-android','Stop screen brightness from dimming in Thunderbird for Android','https://support.mozilla.org/en-US/kb/stop-screen-brightness-dimming-thunderbird-android','https://support.mozilla.org/en-US/kb/stop-screen-brightness-dimming-thunderbird-android/revision/309224',308286,'2025-10-17T15:20:14.066131-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP, do not approve or localize :-), needs Wayne and Laurel''s approval please. Discussion: https://github.com/thunderbird/android-knowledgebase-issues/issues/20',1,'2025-10-17T15:21:10.285100-07:00','rtanglao',1,0,0,NULL,NULL,'approved','[[T:TBAndroidMore]]

Android''s settings and automatic screen dimming can make it difficult to read the screen in Thunderbird. Here''s how to reduce screen dimming and make Thunderbird more readable.

__TOC__ 
=General tips and tricks=
* A dirty proximity sensor (located near the front facing camera) can cause your screen to dim. To prevent this, keep the area around the front-facing camera clean.
* Different manufacturers often implement different variants of Android and have slightly differently named Android settings. Also, setting names change in newer versions of Android. It is therefore impossible to give a comprehensive guide to the relevant settings for all Android devices for all Android versions.

Here are some specific tips that will allow you to find the relevant settings for screen dimming on your device: Look for Android settings under sections with words like: 
* ''''''Eye comfort shield'''''': Turn off.
* ''''''Power saving'''''': Turn off or increase timeout before it starts.
* ''''''Battery saver'''''': Turn off or increase timeout to prevent dimming.
* ''''''Accessibility'''''' and ''''''Display'''''': Look for settings related to screen dimming, screen timouts and lock settings and turn off all automatic screen dimming, extra screen dimming (often found in {menu Android Settings} > {menu Acccessiblity} > {menu Extra dim}) and increase timeouts for screen locking.
=Thunderbird settings=
==Use Thunderbird''s Dark Theme==
# Tap {button ≡} at the top left > tap the gear icon:{button [[Image:gear icon]]} at the bottom left.
# Tap {button General settings} > tap {menu Display} > tap {button Dark} under ''''''Theme''''''.
=Third Party documentation=
== Google Android settings==
* Turn on the Dark theme for more contrast. See Google''s documentation: [https://support.google.com/accessibility/android/answer/6151800 Turn on Dark theme & color inversion].
* How to turn off ''''''Extra dim'''''' can be found in Google''s article: [https://support.google.com/accessibility/android/answer/11183305#colorcorrection&zippy=%2Cuse-color-correction%2Cdim-your-screen Change text & display settings].
* For more information on the features for low-vision assistance, visit the [https://support.google.com/accessibility/android Android Accessibility Help Centre].
[[UI:details_start]]
==Google Pixel settings==
Pixel phones have their own variant of Android. Please refer to the official documentation: [https://support.google.com/pixelphone/answer/6111557 Manage screen & display settings on a Pixel phone]
[[UI:details_end]]
[[UI:details_start]]
==Samsung phones and tablets==
Samsung has specific documentation for all of their Android devices (both non Galaxy and Galaxy):
* [https://www.samsung.com/us/support/answer/ANS10003431/ Stop the screen brightness from dimming on your Galaxy phone or tablet].
* [https://www.samsung.com/us/support/troubleshoot/TSG10001443/ Unable to turn on Eye comfort shield on Samsung phone or tablet]

[[UI:details_end]]
[[UI:details_start]]
==Third Party links disclaimer==
{note}Please note that following the external links to Samsung and Google''s websites in the previous sections will direct you to an external website that is not operated by Mozilla. These links can  break at any time without notice.{/note}
[[UI:details_end]]','<p></p><div class="warning">More for Thunderbird for Android: <strong>o</strong> Vote on &amp; suggest improvements at <a href="https://connect.mozilla.org/t5/ideas/idb-p/ideas/label-name/thunderbird%20android">Connect</a> <strong>o</strong> <a href="https://www.thunderbird.net/participate/">Participate/Contribute</a> <strong>o</strong> <a href="https://support.mozilla.org/questions/new/thunderbird-android/form">Get Support</a></div>
<p></p><p>Android''s settings and automatic screen dimming can make it difficult to read the screen in Thunderbird. Here''s how to reduce screen dimming and make Thunderbird more readable.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_general-tips-and-tricks"><span class="tocnumber">1</span> <span class="toctext">General tips and tricks</span></a></li><li class="toclevel-1"><a href="#w_thunderbird-settings"><span class="tocnumber">2</span> <span class="toctext">Thunderbird settings</span></a><ul><li class="toclevel-2"><a href="#w_use-thunderbirds-dark-theme"><span class="tocnumber">2.1</span> <span class="toctext">Use Thunderbird''s Dark Theme</span></a></li></ul></li><li class="toclevel-1"><a href="#w_third-party-documentation"><span class="tocnumber">3</span> <span class="toctext">Third Party documentation</span></a><ul><li class="toclevel-2"><a href="#w_google-android-settings"><span class="tocnumber">3.1</span> <span class="toctext">Google Android settings</span></a></li><li class="toclevel-2"><a href="#w_google-pixel-settings"><span class="tocnumber">3.2</span> <span class="toctext">Google Pixel settings</span></a></li><li class="toclevel-2"><a href="#w_samsung-phones-and-tablets"><span class="tocnumber">3.3</span> <span class="toctext">Samsung phones and tablets</span></a></li><li class="toclevel-2"><a href="#w_third-party-links-disclaimer"><span class="tocnumber">3.4</span> <span class="toctext">Third Party links disclaimer</span></a></li></ul></li></ul></div> 
<h1 id="w_general-tips-and-tricks">General tips and tricks</h1>
<ul><li> A dirty proximity sensor (located near the front facing camera) can cause your screen to dim. To prevent this, keep the area around the front-facing camera clean.
</li><li> Different manufacturers often implement different variants of Android and have slightly differently named Android settings. Also, setting names change in newer versions of Android. It is therefore impossible to give a comprehensive guide to the relevant settings for all Android devices for all Android versions.
</li></ul>
<p>Here are some specific tips that will allow you to find the relevant settings for screen dimming on your device: Look for Android settings under sections with words like: 
</p>
<ul><li> <strong>Eye comfort shield</strong>: Turn off.
</li><li> <strong>Power saving</strong>: Turn off or increase timeout before it starts.
</li><li> <strong>Battery saver</strong>: Turn off or increase timeout to prevent dimming.
</li><li> <strong>Accessibility</strong> and <strong>Display</strong>: Look for settings related to screen dimming, screen timouts and lock settings and turn off all automatic screen dimming, extra screen dimming (often found in <span class="menu">Android Settings</span> &gt; <span class="menu">Acccessiblity</span> &gt; <span class="menu">Extra dim</span>) and increase timeouts for screen locking.
</li></ul>
<h1 id="w_thunderbird-settings">Thunderbird settings</h1>
<h2 id="w_use-thunderbirds-dark-theme">Use Thunderbird''s Dark Theme</h2>
<ol><li> Tap <span class="button">≡</span> at the top left &gt; tap the gear icon:<span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> at the bottom left.
</li><li> Tap <span class="button">General settings</span> &gt; tap <span class="menu">Display</span> &gt; tap <span class="button">Dark</span> under <strong>Theme</strong>.
</li></ol>
<h1 id="w_third-party-documentation">Third Party documentation</h1>
<h2 id="w_google-android-settings">Google Android settings</h2>
<ul><li> Turn on the Dark theme for more contrast. See Google''s documentation: <a href="https://support.google.com/accessibility/android/answer/6151800">Turn on Dark theme &amp; color inversion</a>.
</li><li> How to turn off <strong>Extra dim</strong> can be found in Google''s article: <a href="https://support.google.com/accessibility/android/answer/11183305#colorcorrection&amp;zippy=%2Cuse-color-correction%2Cdim-your-screen">Change text &amp; display settings</a>.
</li><li> For more information on the features for low-vision assistance, visit the <a href="https://support.google.com/accessibility/android">Android Accessibility Help Centre</a>.
</li></ul>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h2 id="w_google-pixel-settings" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Google Pixel settings</button></h2>
<p class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true">Pixel phones have their own variant of Android. Please refer to the official documentation: <a href="https://support.google.com/pixelphone/answer/6111557">Manage screen &amp; display settings on a Pixel phone</a>
</p></section>
<section class="mzp-c-details is-details">
<p></p>
<h2 id="w_samsung-phones-and-tablets" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-1" aria-expanded="false">Samsung phones and tablets</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-1" aria-hidden="true"><p>Samsung has specific documentation for all of their Android devices (both non Galaxy and Galaxy):
</p><ul><li> <a href="https://www.samsung.com/us/support/answer/ANS10003431/">Stop the screen brightness from dimming on your Galaxy phone or tablet</a>.
</li><li> <a href="https://www.samsung.com/us/support/troubleshoot/TSG10001443/">Unable to turn on Eye comfort shield on Samsung phone or tablet</a>
</li></ul><p></p></div>


</section>
<section class="mzp-c-details is-details">
<p></p>
<h2 id="w_third-party-links-disclaimer" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-2" aria-expanded="false">Third Party links disclaimer</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-2" aria-hidden="true"><div class="note">Please note that following the external links to Samsung and Google''s websites in the previous sections will direct you to an external website that is not operated by Mozilla. These links can  break at any time without notice.</div><p></p></div>

