<p></p>','[{"label": "Revision id", "text": "309224", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 17, 2025, 3:20:14 PM", "datetime": "2025-10-17T15:20:14.066131-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP, do not approve or localize :-), needs Wayne and Laurel''s approval please. Discussion: https://github.com/thunderbird/android-knowledgebase-issues/issues/20", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 17, 2025, 3:21:10 PM", "datetime": "2025-10-17T15:21:10.285100-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:25:28+00:00');
