INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (319667,'en-US','install-thunderbird-pro-add-thunderbird-desktop','Install the Thunderbird Pro Add-on in Thunderbird Desktop','https://support.mozilla.org/en-US/kb/install-thunderbird-pro-add-thunderbird-desktop','https://support.mozilla.org/en-US/kb/install-thunderbird-pro-add-thunderbird-desktop/revision/319667',NULL,'2026-02-10T08:54:52.888942-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','english only for now, so do not translate please! Discussion please https://github.com/thunderbird/knowledgebase-issues/issues/111',1,'2026-02-10T08:55:41.899727-08:00','rtanglao',1,0,0,NULL,NULL,'approved','[[Template:TBproEarlyBirdInviteOnly]]

{note}''''''PLEASE NOTE'''''': Thunderbird Pro requires Thunderbird 140 for Desktop or newer. We recommend the latest monthly release version of Thunderbird, which is documented here: [[New in Thunderbird Desktop]].{/note}

= Install the Thunderbird Pro Add-on =

The [https://addons.thunderbird.net/thunderbird/addon/tbpro-addon/ ''''''Thunderbird Pro add-on''''''] is [[Installing an Add-on in Thunderbird|installed]] like any other Thunderbird add-on:

# Thunderbird app menu {menu ≡} > Settings gear icon {button [[Image:gear icon]]}“ > {menu Add-ons and Themes}.
# Enter “''''''tbpro''''''” in ''''''Find more add-ons''''''.
# Click {button Add to Thunderbird} and then {button Add} in the dialogue that pops up. Follow the prompts to complete the process.

= Explore the Power of Thunderbird Pro! =

<!--
* FIXME: &#91;&#91;Thunderbird for Desktop and Thundermail|Add your Thundermail account to Thunderbird Desktop&#93;&#93; and send some messages!
* If you have an Android phone, FIXME: &#91;&#91;Thundermail and Thunderbird for Android|add your Thundermail account to Thunderbird for Android&#93;&#93; and send some email while on the go.
-->
* Configure [https://support.tb.pro/hc/sections/43937747865235 Thunderbird Send''''''] for sending large files.
* Have folks book time on your calendar by setting up [https://support.tb.pro/hc/sections/43161318933907 ''''''Thunderbird Appointment''''''].

And more!','<p></p><div class="warning">NOTE: Thundermail (formerly known as Thunderbird Pro) is currently in its Early Bird release and available  by invitation only. To learn more and join the waitlist, visit <a href="https://tb.pro/">our website</a>. We’ll be opening Thundermail to the public once the Early Bird release concludes.</div>
<p></p>
<div class="note"><strong>PLEASE NOTE</strong>: Thunderbird Pro requires Thunderbird 140 for Desktop or newer. We recommend the latest monthly release version of Thunderbird, which is documented here: <a href="/en-US/kb/new-thunderbird-desktop">New in Thunderbird Desktop</a>.</div>
<h1 id="w_install-the-thunderbird-pro-add-on">Install the Thunderbird Pro Add-on</h1>
<p>The <a href="https://addons.thunderbird.net/thunderbird/addon/tbpro-addon/"><strong>Thunderbird Pro add-on</strong></a> is <a href="/en-US/kb/installing-addon-thunderbird">installed</a> like any other Thunderbird add-on:
</p>
<ol><li> Thunderbird app menu <span class="menu">≡</span> &gt; Settings gear icon <span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span>“ &gt; <span class="menu">Add-ons and Themes</span>.
</li><li> Enter “<strong>tbpro</strong>” in <strong>Find more add-ons</strong>.
</li><li> Click <span class="button">Add to Thunderbird</span> and then <span class="button">Add</span> in the dialogue that pops up. Follow the prompts to complete the process.
</li></ol>
<h1 id="w_explore-the-power-of-thunderbird-pro">Explore the Power of Thunderbird Pro!</h1>
<p>
</p>
<ul><li> Configure <a href="https://support.tb.pro/hc/sections/43937747865235">Thunderbird Send<strong></strong></a><strong> for sending large files.
</strong>
</li><li> Have folks book time on your calendar by setting up <a href="https://support.tb.pro/hc/sections/43161318933907"><strong>Thunderbird Appointment</strong></a>.
</li></ul>
<p>And more!
</p>','[{"label": "Revision id", "text": "319667", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 10, 2026, 8:54:52 AM", "datetime": "2026-02-10T08:54:52.888942-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "english only for now, so do not translate please! Discussion please https://github.com/thunderbird/knowledgebase-issues/issues/111", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 10, 2026, 8:55:41 AM", "datetime": "2026-02-10T08:55:41.899727-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:23:57+00:00');
