INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (319693,'en-US','thundermail-and-thunderbird-android','Thundermail and Thunderbird for Android','https://support.mozilla.org/en-US/kb/thundermail-and-thunderbird-android','https://support.mozilla.org/en-US/kb/thundermail-and-thunderbird-android/revision/319693',319684,'2026-02-10T12:12:17.245301-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','works on k-9 too of course! english only for now, so do not translate please! Discussion please https://github.com/thunderbird/android-knowledgebase-issues/issues/23',1,'2026-02-10T12:12:32.426434-08:00','rtanglao',1,0,0,NULL,NULL,'approved','[[Template:TBproEarlyBirdInviteOnly]]
Here’s how to get started with Mozilla’s Thundermail service. 

=Configure Thundermail for Thunderbird for Android=
''''''NOTE'''''': Thunderbird Pro requires Thunderbird (and of course K-9 as well) 15 for Android or newer. We recommend the latest monthly release version of Thunderbird for Android, which is documented in [[New in Thunderbird for Android]].

# Thunderbird app menu {menu ≡} > Settings gear icon {button [[Image:gear icon]]} > {menu Add account}.
# Enter your Thundermail email address (for example [mailto:nemo@thundermail.com nemo@thundermail.com]) 
# Click {button Next}.
# The next screen will prompt you to ''''''Please specify the special folders for your account'''''' along with some suggested settings for your Thunderbird special folders. For most people the defaults are fine. Configure them to your needs and click {button Next}. 
# On the next screen, configure your user name under ''''''Your name'''''' and optionally your signature and {button Next}.
# The next screen will give you some sync and notification options. For most people, the defaults are fine. Configure them to your needs and click {button Next} .

=Manual settings=

Thunderbird should automatically configure your Thundermail email settings to match your [https://accounts.tb.pro/self-serve/connection-info TB Pro accounts page]. If it doesn’t, please try manually changing the receiving email and sending email settings as per the sections below. If manual setup fails, please create a support ticket using our form at: https://accounts.tb.pro/contact/
[[UI:details_start]]

==Receiving Email==
# Thunderbird app menu {menu ≡} > Settings gear icon {button [[Image:gear icon]]}
# Under ''''''Accounts'''''', tap on your Thundermail email account. (For example: [mailto:nemo@thundermail.com nemo@thundermail.com])
# Tap {menu Fetching mail} > {menu Incoming Server} and set the following values:
*''''''Server:'''''' [http://mail.thundermail.com mail.thundermail.com] ''''''Security:'''''' SSL/TLS ''''''Port:'''''' 993
*''''''Authentication:'''''' OAuth 2.0
*''''''Username:'''''' your full Thundermail email address e.g. [mailto:nemo@thundermail.com nemo@thundermail.com]

==Sending Email==
# Thunderbird app menu {menu ≡} > Settings gear icon {button [[Image:gear icon]]}
# Under ''''''Accounts'''''', tap on your Thundermail email account. (For example: [mailto:nemo@thundermail.com nemo@thundermail.com])
# Tap {menu Sending mail} > {menu Outgoing server} and set the following values:
* ''''''Server Name:'''''' [http://mail.thundermail.com mail.thundermail.com] ''''''Connection'''''' ''''''Security:'''''' SSL/TLS ''''''Port:'''''' 465
* ''''''Authentication:'''''' OAuth 2.0
* ''''''Username:'''''' your full Thundermail email address For example: nemo@thundermail.com

[[UI:details_end]]

=Send and receive email and have some fun!=
* Send and receive email with Thundermail.
<!--
* If you have large files, you can send them with FIXME because Send on Mobile needs some polish: add link to Thunderbird Send which is included with your Thunderbird Pro subscription.
-->
* New to Thunderbird for Android? Then check out [[Getting started with Thunderbird for Android]].','<p></p><div class="warning">NOTE: Thundermail (formerly known as Thunderbird Pro) is currently in its Early Bird release and available  by invitation only. To learn more and join the waitlist, visit <a href="https://tb.pro/">our website</a>. We’ll be opening Thundermail to the public once the Early Bird release concludes.</div>
Here’s how to get started with Mozilla’s Thundermail service. 
<p></p>
<h1 id="w_configure-thundermail-for-thunderbird-for-android">Configure Thundermail for Thunderbird for Android</h1>
<p><strong>NOTE</strong>: Thunderbird Pro requires Thunderbird (and of course K-9 as well) 15 for Android or newer. We recommend the latest monthly release version of Thunderbird for Android, which is documented in <a href="/en-US/kb/new-thunderbird-android">New in Thunderbird for Android</a>.
</p>
<ol><li> Thunderbird app menu <span class="menu">≡</span> &gt; Settings gear icon <span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> &gt; <span class="menu">Add account</span>.
</li><li> Enter your Thundermail email address (for example <a href="mailto:nemo@thundermail.com">nemo@thundermail.com</a>) 
</li><li> Click <span class="button">Next</span>.
</li><li> The next screen will prompt you to <strong>Please specify the special folders for your account</strong> along with some suggested settings for your Thunderbird special folders. For most people the defaults are fine. Configure them to your needs and click <span class="button">Next</span>. 
</li><li> On the next screen, configure your user name under <strong>Your name</strong> and optionally your signature and <span class="button">Next</span>.
</li><li> The next screen will give you some sync and notification options. For most people, the defaults are fine. Configure them to your needs and click <span class="button">Next</span> .
</li></ol>
<h1 id="w_manual-settings">Manual settings</h1>
<p>Thunderbird should automatically configure your Thundermail email settings to match your <a href="https://accounts.tb.pro/self-serve/connection-info">TB Pro accounts page</a>. If it doesn’t, please try manually changing the receiving email and sending email settings as per the sections below. If manual setup fails, please create a support ticket using our form at: <a href="https://accounts.tb.pro/contact/">https://accounts.tb.pro/contact/</a>
</p><section class="mzp-c-details is-details">
<p></p>
