INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (330154,'en-US','thunderbird-desktop-and-thundermail','Thunderbird for Desktop and Thundermail','https://support.mozilla.org/en-US/kb/thunderbird-desktop-and-thundermail','https://support.mozilla.org/en-US/kb/thunderbird-desktop-and-thundermail/revision/330154',329960,'2026-06-02T22:43:52.104180-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP, please do not translate. Discussion: https://github.com/thunderbird/knowledgebase-issues/issues/199',1,'2026-06-02T22:44:16.938559-07:00','rtanglao',1,0,1,'2026-09-02T13:08:18.744266-07:00','rtanglao','approved','[[Template:TBproEarlyBirdInviteOnly]]

