</li></ol>','[{"label": "Revision id", "text": "333925", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 17, 2026, 11:05:10 PM", "datetime": "2026-06-17T23:05:10.365865-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix typos, sumo kb formatting, do not approve please. Discussion: https://github.com/thunderbird/knowledgebase-issues/issues/198", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jun 17, 2026, 11:05:30 PM", "datetime": "2026-06-17T23:05:30.135700-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:19:41+00:00');
