</p><p>Need help? <a href="http://support.mozilla.org/questions/new/thunderbird/form">Ask for support</a> in our <a href="https://support.mozilla.org/products/thunderbird">Thunderbird community forum</a> from our global community of volunteers who have been doing most Thunderbird support for over 20 years.
</p>','[{"label": "Revision id", "text": "337845", "datetime": null, "href": null}, {"label": "Created", "text": "Jun 30, 2026, 9:55:21 PM", "datetime": "2026-06-30T21:55:21.997756-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "Menubar is hidden in windows so use keyboard shortcut control U, use markup for keys;   WIP: pls do not approve, discussion: https://github.com/thunderbird/knowledgebase-issues/issues/215", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jun 30, 2026, 10:00:51 PM", "datetime": "2026-06-30T22:00:51.442383-07:00", "href": null}, {"label": "Reviewed by", "text": "wsmwk", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Jun 30, 2026, 10:00:51 PM", "datetime": "2026-06-30T22:00:51.442383-07:00", "href": null}, {"label": "Readied for localization by", "text": "wsmwk", "datetime": null, "href": null}]','2026-11-03T18:18:58+00:00');
