</p>','[{"label": "Revision id", "text": "359087", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 5, 2026, 12:48:05 AM", "datetime": "2026-10-05T00:48:05.358134-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "update screenshots, do not translate. need wayne''s approval, discussion: https://github.com/thunderbird/knowledgebase-issues/issues/230roval, discussion", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 5, 2026, 12:51:22 AM", "datetime": "2026-10-05T00:51:22.468029-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:16:34+00:00');
