# Under ''''''Application Basics'''''', refer to the number beside ''''''Version''''''. That is the version of Thunderbird you are using.','<ol><li> Click the Thunderbird App Menu <span class="menu">☰</span> &gt; <span class="menu">Help</span> menu &gt; <span class="menu">Troubleshooting Information</span>. A new tab will open with information about your setup.
</li><li> Under <strong>Application Basics</strong>, refer to the number beside <strong>Version</strong>. That is the version of Thunderbird you are using.
</li></ol>','[{"label": "Revision id", "text": "363144", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 9, 2026, 9:26:53 AM", "datetime": "2026-10-09T09:26:53.442381-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "Discussion: https://github.com/thunderbird/knowledgebase-issues/issues/238", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 9, 2026, 9:27:21 AM", "datetime": "2026-10-09T09:27:21.403371-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Nov 2, 2026, 6:08:49 PM", "datetime": "2026-11-02T18:08:49.922299-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:14:44+00:00');
INSERT INTO revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at) VALUES (363928,'en-US','thunderbird-and-hotmail','Thunderbird and Microsoft email (Office365, Hotmail, outlook.com, etc)','https://support.mozilla.org/en-US/kb/thunderbird-and-hotmail','https://support.mozilla.org/en-US/kb/thunderbird-and-hotmail/revision/363928',124048,'2026-10-13T00:03:11.989945-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','wip do not approve: discussion: https://github.com/thunderbird/knowledgebase-issues/issues/241',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Thunderbird can be used as a client for all of Microsoft''s email services (Hotmail, Outlook<!-- -->.com and Windows Live Mail, Office 365, Microsoft 365, etc) henceforth referred to as''''Microsoft email''''. Thunderbird will download messages from the Microsoft server and store them on your local system. Similarly, Thunderbird can be used to compose messages which are sent through Hotmail''s mail servers. You can still use Microsoft''s web-based application (for example outlook.com) - Thunderbird will query the server and synchronize messages.
__TOC__
==Configuring servers==
Microsoft accounts are configured automatically in Thunderbird using Thunderbird Account Hub.

Enter your Microsoft email address (for example: <code>tbtesttb@hotmail.com</code>) and password when prompted, and Thunderbird will configure the server settings for you. Whether you are using IMAP or POP, Thunderbird will automatically configure the server settings for you. 

For more details please refer to [[Account Hub for Thunderbird Desktop]].

If Thunderbird cannot configure the server settings automatically, you can manually configure or modify the server settings.

* As of late 2026, here is a screenshot of the IMAP server settings in the Account Hub
*;[[Image:tb157-microsoft-email-imap-account-hub]]
* And here is a screenshot of the POP server settings in the Account Hub:
*;[[Image:tb157-microsoft-email-pop-account-hub]]


===Manually Configuring IMAP and POP accounts===
To manually configure or modify Microsoft email account settings:

# Click Thunderbird app menu {menu ☰} > {menu Account Settings}. The Account Settings dialog window will be displayed.
# Select your Microsoft email account from the list on the left.
# In the left panel, below your Microsoft email account name, click on {menu Server Settings}. The server settings will be displayed in the right panel.
{note}''''''Note'''''': For an explanation of IMAP and POP, please refer to [[Glossary of Terms including types of Accounts]].{/note}
====IMAP mail account settings====
Configure the  server settings according to the settings provided by your Microsoft account administrators. Here are some typical settings as of this writing.
*Server Name: <code>outlook.office366.com</code>
*Port: 993
*User Name: your username (for example ''''tbtesttb@hotmail.com'''')
*Connection security: SSL/TLS
*Authentication method: OAuth2
====POP mail account settings====
CConfigure the  server settings according to the settings provided by your Microsoft account administrators. Here are some typical settings:.
*Server Name:  <code>outlook.office366.com</code>
*Port: 995
*User Name: your username (for example ''''tbtesttb@hotmail.com'''')
*Connection security: SSL/TLS
*Authentication method: OAuth2
*Configure the rest of the server settings according to the settings provided by your Microsoft account administrators.

===Configuring the SMTP outgoing server===
Configure the  server settings according to the settings provided by your Microsoft account administrators. Here are some typical settings:.
*At the bottom left, click {button Edit outgoing server…}. Configure them as follows:
**Server Name: smtp-mail.outlook<!-- -->.com
**Port: 587
**Connection security: STARTTLS
**Authentication method:OAuth2
**User Name: your username (for example ''''tbtesttb@hotmail.com'''')

{note}''''''Note'''''': If you receive a password error in Thunderbird when trying to retrieve messages using POP, you may need to sign in using webmail first and [http://windows.microsoft.com/en-us/windows/outlook/send-receive-from-app enable POP settings] under the Options section of your Outlook<!-- -->.com email account.{/note}','<p>Thunderbird can be used as a client for all of Microsoft''s email services (Hotmail, Outlook.com and Windows Live Mail, Office 365, Microsoft 365, etc) henceforth referred to as<em>Microsoft email</em>. Thunderbird will download messages from the Microsoft server and store them on your local system. Similarly, Thunderbird can be used to compose messages which are sent through Hotmail''s mail servers. You can still use Microsoft''s web-based application (for example <a href="http://outlook.com">outlook.com</a>) - Thunderbird will query the server and synchronize messages.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configuring-servers"><span class="tocnumber">1</span> <span class="toctext">Configuring servers</span></a><ul><li class="toclevel-2"><a href="#w_manually-configuring-imap-and-pop-accounts"><span class="tocnumber">1.1</span> <span class="toctext">Manually Configuring IMAP and POP accounts</span></a><ul><li class="toclevel-3"><a href="#w_imap-mail-account-settings"><span class="tocnumber">1.1.1</span> <span class="toctext">IMAP mail account settings</span></a></li><li class="toclevel-3"><a href="#w_pop-mail-account-settings"><span class="tocnumber">1.1.2</span> <span class="toctext">POP mail account settings</span></a></li></ul></li><li class="toclevel-2"><a href="#w_configuring-the-smtp-outgoing-server"><span class="tocnumber">1.2</span> <span class="toctext">Configuring the SMTP outgoing server</span></a></li></ul></li></ul></div>
<h2 id="w_configuring-servers">Configuring servers</h2>
<p>Microsoft accounts are configured automatically in Thunderbird using Thunderbird Account Hub.
</p><p>Enter your Microsoft email address (for example: <code>tbtesttb@hotmail.com</code>) and password when prompted, and Thunderbird will configure the server settings for you. Whether you are using IMAP or POP, Thunderbird will automatically configure the server settings for you. 
</p><p>For more details please refer to <a href="/en-US/kb/account-hub-thunderbird-desktop">Account Hub for Thunderbird Desktop</a>.
</p><p>If Thunderbird cannot configure the server settings automatically, you can manually configure or modify the server settings.
</p>
<ul><li> As of late 2026, here is a screenshot of the IMAP server settings in the Account Hub
<dl><dt><img alt="tb157-microsoft-email-imap-account-hub" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-10-13-00-05-51-76c18c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> And here is a screenshot of the POP server settings in the Account Hub:
<dl><dt><img alt="tb157-microsoft-email-pop-account-hub" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2026-10-13-00-08-29-23715b.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ul>
<p><br>
</p>
<h3 id="w_manually-configuring-imap-and-pop-accounts">Manually Configuring IMAP and POP accounts</h3>
<p>To manually configure or modify Microsoft email account settings:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Account Settings</span>. The Account Settings dialog window will be displayed.
</li><li> Select your Microsoft email account from the list on the left.
</li><li> In the left panel, below your Microsoft email account name, click on <span class="menu">Server Settings</span>. The server settings will be displayed in the right panel.
</li></ol>
<div class="note"><strong>Note</strong>: For an explanation of IMAP and POP, please refer to <a href="/en-US/kb/glossary-terms-including-types-accounts">Glossary of Terms including types of Accounts</a>.</div>
<h4 id="w_imap-mail-account-settings">IMAP mail account settings</h4>
<p>Configure the  server settings according to the settings provided by your Microsoft account administrators. Here are some typical settings as of this writing.
</p>
<ul><li>Server Name: <code>outlook.office366.com</code>
</li><li>Port: 993
</li><li>User Name: your username (for example <em><a href="mailto:tbtesttb@hotmail.com">tbtesttb@hotmail.com</a></em>)
</li><li>Connection security: SSL/TLS
</li><li>Authentication method: OAuth2
</li></ul>
<h4 id="w_pop-mail-account-settings">POP mail account settings</h4>
<p>CConfigure the  server settings according to the settings provided by your Microsoft account administrators. Here are some typical settings:.
</p>
<ul><li>Server Name:  <code>outlook.office366.com</code>
</li><li>Port: 995
</li><li>User Name: your username (for example <em><a href="mailto:tbtesttb@hotmail.com">tbtesttb@hotmail.com</a></em>)
</li><li>Connection security: SSL/TLS
</li><li>Authentication method: OAuth2
</li><li>Configure the rest of the server settings according to the settings provided by your Microsoft account administrators.
</li></ul>
<h3 id="w_configuring-the-smtp-outgoing-server">Configuring the SMTP outgoing server</h3>
<p>Configure the  server settings according to the settings provided by your Microsoft account administrators. Here are some typical settings:.
</p>
<ul><li>At the bottom left, click <span class="button">Edit outgoing server…</span>. Configure them as follows:
<ul><li>Server Name: smtp-mail.outlook.com
</li><li>Port: 587
</li><li>Connection security: STARTTLS
</li><li>Authentication method:OAuth2
</li><li>User Name: your username (for example <em><a href="mailto:tbtesttb@hotmail.com">tbtesttb@hotmail.com</a></em>)
</li></ul>
</li></ul>
<div class="note"><strong>Note</strong>: If you receive a password error in Thunderbird when trying to retrieve messages using POP, you may need to sign in using webmail first and <a href="http://windows.microsoft.com/en-us/windows/outlook/send-receive-from-app">enable POP settings</a> under the Options section of your Outlook.com email account.</div>','[{"label": "Revision id", "text": "363928", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 13, 2026, 12:03:11 AM", "datetime": "2026-10-13T00:03:11.989945-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "wip do not approve: discussion: https://github.com/thunderbird/knowledgebase-issues/issues/241", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:14:42+00:00');
