INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (129564,'en-US','protect-your-thunderbird-passwords-primary-password','Protect your Thunderbird passwords with a Primary Password','https://support.mozilla.org/en-US/kb/protect-your-thunderbird-passwords-primary-password','https://support.mozilla.org/en-US/kb/protect-your-thunderbird-passwords-primary-password/revision/129564',123094,'2016-08-04T04:59:20-07:00','Chris Ilias','https://support.mozilla.org/en-US/user/Chris_Ilias/','rewrote the intro/summary to make feature clearer, simplified bits of instructions. https://support.mozilla.org/en-US/kb/master-password/discuss/6744',1,'2016-08-16T01:25:52-07:00','Chris_Ilias',1,0,0,NULL,NULL,'approved','Thunderbird can save passwords for each account, so you don''t have to re-enter them when you check for new messages. You can view them and remove the ones you don''t use anymore.

What if you share a computer, and don''t want to prevent others from being able to see your stored passwords? With the Master Password feature, Thunderbird will require you to enter a master password in order to view or use the passwords you''ve told Thunderbird to remember. When you have a master password set, you''ll only need to enter it once per session.

{note}''''''Want to prevent others from seeing your messages ?'''''' If you share a computer, create a separate {for win}Windows{/for}{for mac}MacOS{/for}{for linux}OS{/for} account for each person, and make sure your {for win}Windows{/for}{for mac}MacOS{/for}{for linux}OS{/for} account requires a password. Thunderbird information is separate for each {for win}Windows{/for}{for mac}MacOS{/for}{for linux}OS{/for} account.{/note}
[[Image:ef5f631b4f4f00424fd9f2a09ddaeb4e-1290640828-218-2.png]]

__TOC__

= Defining a master password =
By default, Thunderbird does not a master password to protect stored credentials. To define a master password:
# [[T:optionspreferences TB]]
# Select the {menu Security} panel.
# Select the {menu Passwords} tab.
# Put a check mark next to ''''''Use a master password''''''. <br/><br/>{for mac}[[Image:Create_Master_Password-Mac]]<br/> {/for}{for linux}[[Image:Create_Master_Password-Mac]]<br/> {/for}{for win}[[Image:ef5f631b4f4f00424fd9f2a09ddaeb4e-1290640828-218-3.png]]<br/>{/for}
# The Change Master Password dialog will appear. As you enter your master password, the Password quality meter will indicate the difficulty of guessing the password. Here are some tips for creating better passwords:
#* Use at least one capital letter
#* Use one or more digits
#* Use at least one non-alphanumeric character, such as: <nowiki>@ # $ % ^ & * ( )</nowiki>.
#* Also, remember to make your password something that is easy for you to remember, but difficult for others to guess to ensure that you, and only you, will be able to retrieve this secure information
# The password must be entered twice to confirm that you can enter it consistently.<br/> <br/>{for mac}[[Image:Choose_Master_Password-Mac]]<br/>{/for}{for linux}[[Image:Choose_Master_Password-Mac]]<br/>{/for}{for win}[[Image:ef5f631b4f4f00424fd9f2a09ddaeb4e-1290640828-218-1.png]]{/for} <br/>
# To set the master password, click {button OK}.

Now that your Master Passord is set, Thunderbird will prompt you to enter it the first time you need to use/view a password per session.

= Changing or removing the master password =

# [[T:optionspreferences TB]]
# Select the {menu Security} panel.
# Select the {menu Passwords} tab.
# Click {button Change Master Password}.
# Enter the current master password to confirm you are authorized to change it.
# Enter the new master password twice.
#* ''''''To remove the master password'''''', leave the new master password fields empty.
# Click {button OK}.


= Forgotten Password =
If you''ve forgotten your master password you can reset it.
{warning}''''''Warning:'''''' This will remove all of your saved usernames and passwords.{/warning}

# Choose {menu Tools -> Error Console}.
# Paste the following text: <br/> <code>openDialog("chrome://pippki/content/resetpassword.xul")</code>
# Press the {button Evaluate} button.
# Accept when prompted with the confirmation dialog box.

<!-- MZ credit -->
<br/> <br/>
''''''''''Based on information from  [http://kb.mozillazine.org/Master_password Master password (mozillaZine KB)]''''''''''','<p>Thunderbird can save passwords for each account, so you don''t have to re-enter them when you check for new messages. You can view them and remove the ones you don''t use anymore.
</p><p>What if you share a computer, and don''t want to prevent others from being able to see your stored passwords? With the Master Password feature, Thunderbird will require you to enter a master password in order to view or use the passwords you''ve told Thunderbird to remember. When you have a master password set, you''ll only need to enter it once per session.
</p>
<div class="note"><strong>Want to prevent others from seeing your messages&nbsp;?</strong> If you share a computer, create a separate <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">MacOS</span><span class="for" data-for="linux" style="display: none;">OS</span> account for each person, and make sure your <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">MacOS</span><span class="for" data-for="linux" style="display: none;">OS</span> account requires a password. Thunderbird information is separate for each <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">MacOS</span><span class="for" data-for="linux" style="display: none;">OS</span> account.</div>
<p><img alt="ef5f631b4f4f00424fd9f2a09ddaeb4e-1290640828-218-2.png" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-03-14-10-07-50-0c0fbe.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_defining-a-master-password"><span class="tocnumber">1</span> <span class="toctext">Defining a master password</span></a></li><li class="toclevel-1"><a href="#w_changing-or-removing-the-master-password"><span class="tocnumber">2</span> <span class="toctext">Changing or removing the master password</span></a></li><li class="toclevel-1"><a href="#w_forgotten-password"><span class="tocnumber">3</span> <span class="toctext">Forgotten Password</span></a></li></ul></div>
<h1 id="w_defining-a-master-password">Defining a master password</h1>
<p>By default, Thunderbird does not a master password to protect stored credentials. To define a master password:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Settings</span>.

</li><li> Select the <span class="menu">Security</span> panel.
</li><li> Select the <span class="menu">Passwords</span> tab.
</li><li> Put a check mark next to <strong>Use a master password</strong>. <br><br><span class="for" data-for="mac"><img alt="Create_Master_Password-Mac" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2016-04-23-22-39-17-24daf9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br> </span><span class="for" data-for="linux" style="display: none;"><img alt="Create_Master_Password-Mac" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2016-04-23-22-39-17-24daf9.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br> </span><span class="for" data-for="win" style="display: none;"><img alt="ef5f631b4f4f00424fd9f2a09ddaeb4e-1290640828-218-3.png" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-03-14-10-07-50-a9f968.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br></span>
</li><li> The Change Master Password dialog will appear. As you enter your master password, the Password quality meter will indicate the difficulty of guessing the password. Here are some tips for creating better passwords:
<ul><li> Use at least one capital letter
</li><li> Use one or more digits
</li><li> Use at least one non-alphanumeric character, such as: @ # $ % ^ &amp; * ( ).
</li><li> Also, remember to make your password something that is easy for you to remember, but difficult for others to guess to ensure that you, and only you, will be able to retrieve this secure information
</li></ul>
</li><li> The password must be entered twice to confirm that you can enter it consistently.<br> <br><span class="for" data-for="mac"><img alt="Choose_Master_Password-Mac" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2016-04-23-22-43-02-3197a1.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br></span><span class="for" data-for="linux" style="display: none;"><img alt="Choose_Master_Password-Mac" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2016-04-23-22-43-02-3197a1.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br></span><span class="for" data-for="win" style="display: none;"><img alt="ef5f631b4f4f00424fd9f2a09ddaeb4e-1290640828-218-1.png" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2011-03-14-10-08-05-ea94cc.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> <br>
</li><li> To set the master password, click <span class="button">OK</span>.
</li></ol>
<p>Now that your Master Passord is set, Thunderbird will prompt you to enter it the first time you need to use/view a password per session.
</p>
<h1 id="w_changing-or-removing-the-master-password">Changing or removing the master password</h1>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Settings</span>.

</li><li> Select the <span class="menu">Security</span> panel.
</li><li> Select the <span class="menu">Passwords</span> tab.
</li><li> Click <span class="button">Change Master Password</span>.
</li><li> Enter the current master password to confirm you are authorized to change it.
</li><li> Enter the new master password twice.
<ul><li> <strong>To remove the master password</strong>, leave the new master password fields empty.
</li></ul>
</li><li> Click <span class="button">OK</span>.
</li></ol>
<p><br>
</p>
<h1 id="w_forgotten-password">Forgotten Password</h1>
<p>If you''ve forgotten your master password you can reset it.
</p>
<div class="warning"><strong>Warning:</strong> This will remove all of your saved usernames and passwords.</div>
<ol><li> Choose <span class="menu">Tools -&gt; Error Console</span>.
</li><li> Paste the following text: <br> <code>openDialog("chrome://pippki/content/resetpassword.xul")</code>
</li><li> Press the <span class="button">Evaluate</span> button.
</li><li> Accept when prompted with the confirmation dialog box.
</li></ol>
<p>
<br> <br>
<em><strong>Based on information from  <a href="http://kb.mozillazine.org/Master_password">Master password (mozillaZine KB)</a></strong></em>
</p>','[{"label": "Revision id", "text": "129564", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 4, 2016, 4:59:20 AM", "datetime": "2016-08-04T04:59:20-07:00", "href": null}, {"label": "Creator", "text": "Chris Ilias", "datetime": null, "href": "https://support.mozilla.org/en-US/user/Chris_Ilias/"}, {"label": "Comment", "text": "rewrote the intro/summary to make feature clearer, simplified bits of instructions. https://support.mozilla.org/en-US/kb/master-password/discuss/6744", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 16, 2016, 1:25:52 AM", "datetime": "2016-08-16T01:25:52-07:00", "href": null}, {"label": "Reviewed by", "text": "Chris_Ilias", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:14:04+00:00','M');
