</p>','[{"label": "Revision id", "text": "130223", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 14, 2016, 12:05:46 AM", "datetime": "2016-08-14T00:05:46-07:00", "href": null}, {"label": "Creator", "text": "Tonnes", "datetime": null, "href": "https://support.mozilla.org/en-US/user/Tonnes/"}, {"label": "Comment", "text": "revert to r117493", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 14, 2016, 12:06:20 AM", "datetime": "2016-08-14T00:06:20-07:00", "href": null}, {"label": "Reviewed by", "text": "Tonnes", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:15:00+00:00','M');
