</dt></dl>
</li></ol>','[{"label": "Revision id", "text": "156744", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 6, 2018, 6:38:35 PM", "datetime": "2018-02-06T18:38:35-08:00", "href": null}, {"label": "Creator", "text": "Michele Rodaro", "datetime": null, "href": "https://support.mozilla.org/en-US/user/michro/"}, {"label": "Comment", "text": "Wiki Syntax: Numbered list for images", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 7, 2018, 1:42:17 AM", "datetime": "2018-02-07T01:42:17-08:00", "href": null}, {"label": "Reviewed by", "text": "Chris_Ilias", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:08:51+00:00','');
