</li></ul>','[{"label": "Revision id", "text": "165912", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 29, 2018, 9:34:14 AM", "datetime": "2018-08-29T09:34:14-07:00", "href": null}, {"label": "Creator", "text": "Chris Ilias", "datetime": null, "href": "https://support.mozilla.org/en-US/user/Chris_Ilias/"}, {"label": "Comment", "text": "bug 1487205: removed Bcc section, and s/right-click any folder and select Subscribe\"/right-click on the account name and select Subscribe\"", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 30, 2018, 2:08:03 AM", "datetime": "2018-08-30T02:08:03-07:00", "href": null}, {"label": "Reviewed by", "text": "Chris_Ilias", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Sep 3, 2018, 2:17:35 AM", "datetime": "2018-09-03T02:17:35-07:00", "href": null}, {"label": "Readied for localization by", "text": "Chris_Ilias", "datetime": null, "href": null}]','2026-11-03T20:17:12+00:00','M');
