</li></ul>','[{"label": "Revision id", "text": "220817", "datetime": null, "href": null}, {"label": "Created", "text": "May 6, 2021, 1:54:01 AM", "datetime": "2021-05-06T01:54:01-07:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "add link to post in support", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:05:29+00:00','');
