</li></ul>','[{"label": "Revision id", "text": "220834", "datetime": null, "href": null}, {"label": "Created", "text": "May 6, 2021, 5:13:02 AM", "datetime": "2021-05-06T05:13:02-07:00", "href": null}, {"label": "Creator", "text": "thomas8", "datetime": null, "href": "https://support.mozilla.org/en-US/user/firefox877/"}, {"label": "Comment", "text": "Fix typos, commas, some other nits and clarifications, and some formatting", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "May 6, 2021, 5:28:27 AM", "datetime": "2021-05-06T05:28:27-07:00", "href": null}, {"label": "Reviewed by", "text": "wsmwk", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:05:22+00:00','MT');
