INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (229945,'en-US','config-editor','Config Editor','https://support.mozilla.org/en-US/kb/config-editor','https://support.mozilla.org/en-US/kb/config-editor/revision/229945',229938,'2021-10-02T18:46:35-07:00','christ1','https://support.mozilla.org/en-US/user/christ1/','some spelling and grammar fixes',1,'2021-10-02T20:40:11-07:00','MattAuSupport',1,0,1,'2022-06-22T21:14:21-07:00','wsmwk','approved','You may sometimes need to view or edit Thunderbird preference settings which are not accessible through the normal user interface. You can use Thunderbird''s Config Editor to do this.

To access the Config Editor, go to [[Image:Fx57Menu]] and select Preferences. Search for config and click on the Config Editor button when it is displayed.

[[Image:Warning on Config editor window]] 

Clicking on the Show All button in the display will show all hidden preferences in a tab called "Advanced Preferences"

[[Image:Image of typical config editor tab]] 

In the Config Editor, you can type a string in the field showing "Search preference name" to filter the list of preferences to only those that contain the specified string in their names or values.

{note}''''''Note:'''''' Preferences that have been changed from their default values are shown in bold. There is a revert arrow on the end of the entry to revert the setting to the default value [[Image:Config Editor RevertIcon]]  {/note}

To edit a boolean preference (true/false value) click on the [[Image:Config Editor Toggle]], for text preferences, double clicking on the preference will enable in-place editing.  Once the edit is complete save your changes by clicking the checkmark. [[Image:Config Editor Save Checkmark]] 

In rare cases you may need to add a new preference. You shouldn''t normally need to do this unless you are instructed to do so by documentation for Thunderbird or one of its add-ons.

To add a new preference: 
# type or paste the preference name into the search box
# Select the appropriate preference type (number, string or [https://developer.mozilla.org/en-US/docs/Glossary/Boolean boolean] from the offered options.
# click on the [[Image:Config Editor Add]] to add the preference
To delete a previously added preference click the trash icon folowing the entry. [[Image:Copnfig Editor Trash Icon]] 

Modifications to preferences happen immediately. However, some parts of Thunderbird or many add-ons only read their preferences on start-up, so it is good practice to restart Thunderbird after editing preferences for your changes to take effect. It is also important to know that when you restore a preference to it''s default value, Thunderbird does not store that preference in the preferences file. It is only non-default preferences that are stored.

