INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (234252,'en-US','thunderbird-and-hotmail','Thunderbird and Microsoft email (Office365, Hotmail, outlook.com, etc)','https://support.mozilla.org/en-US/kb/thunderbird-and-hotmail','https://support.mozilla.org/en-US/kb/thunderbird-and-hotmail/revision/234252',124048,'2021-12-09T01:23:12-08:00','Hotmail','https://support.mozilla.org/en-US/user/hotmail./','new imap and pop server address ( outlook.office365.com ))',1,'2024-11-01T04:12:15.179801-07:00','AliceWyman',0,0,0,NULL,NULL,'rejected','Thunderbird can be used as a client for all of Microsoft''s email services (Hotmail, Outlook<!-- -->.com and Windows Live Mail, henceforth referred to as "Hotmail"). Thunderbird will download messages from the Hotmail server and store them on your local system. Similarly, Thunderbird can be used to compose messages which are sent through Hotmail''s mail servers. You can still use Hotmail''s web-based application - Thunderbird will query the server and synchronize messages.

__TOC__

==Configuring servers==
Hotmail accounts can be configured in Thunderbird''s [[Automatic Account Configuration]]. This article provides instructions on how to manually [[Manual Account Configuration|configure an account]] or modify an existing account.

To manually configure or modify Hotmail account settings:

# {for win,linux}At the top of the Thunderbird window, click on the {/for}{for mac}On the menu bar, click on the {menu Thunderbird} menu, choose {/for}{for linux} {menu Edit}{/for}{for win,mac}{menu Tools}{/for}{for win,linux} menu{/for} and select {menu Account Settings…}. The Account Settings dialog window will be displayed.
# Select your Hotmail account from the list on the left. Make sure your name and account are correctly specified in the {menu Default Identity} section.<br><br>[[Image:sethotmailaccounts]]<br><br>
# In the left panel, below your Hotmail account name, click on {menu Server Settings}. The server settings will be displayed in the right panel.

===Configuring IMAP and POP accounts===
{note}''''''Note'''''': For an explanation of IMAP and POP, [https://support.mozilla.org/kb/glossary-terms-including-types-accounts#w_mail-accounts click here].{/note}

====IMAP mail account settings====
*Server Name: outlook.office365<!---->.com
*Port: 993
*User Name: your username (for example ''''j.kowal@outlook.com'''')
*Connection security: SSL/TLS
*Authentication method: Normal password
*Configure the rest of the server settings according to your preferences.<br><br>[[Image:sethotmailimap]]

====POP mail account settings====
*Server Name: outlook.office365<!---->.com
*Port: 995
*User Name: your username (for example ''''j.kowal@outlook.com'''')
*Connection security: SSL/TLS
*Authentication method: Normal password
*Configure the rest of the server settings according to your preferences.<br><br>[[Image:sethotmailpop]]

===Configuring the outgoing server===
# At the bottom of the list on the left, select {menu Outgoing Server (SMTP)}. Configured outgoing servers will be displayed in the right panel. The Hotmail server will probably be called ''''''Microsoft Live Hotmail'''''' or something similar.<br><br>[[Image:sethotmailsmtp]]<br><br>
# Select the server and click the {button Edit} button to alter the settings. Configure them as follows:
#*Server Name: smtp-mail.outlook<!---->.com
#*Port: 587
#*Connection security: STARTTLS
#*Authentication method: Normal password
#*User Name: your username (for example ''''j.kowal@outlook.com'''')<br><br>[[Image:sethotmailsmtp1]]
{note}''''''Note'''''': If you receive a password error in Thunderbird when trying to retrieve messages using POP, you may need to sign in using webmail first and [https://support.microsoft.com/en-us/office/pop-imap-and-smtp-settings-for-outlook-com-d088b986-291d-42b8-9564-9c414e2aa040 enable POP settings] under the Options section of your Outlook<!-- -->.com email account.
{/note}','<p>Thunderbird can be used as a client for all of Microsoft''s email services (Hotmail, Outlook.com and Windows Live Mail, henceforth referred to as "Hotmail"). Thunderbird will download messages from the Hotmail server and store them on your local system. Similarly, Thunderbird can be used to compose messages which are sent through Hotmail''s mail servers. You can still use Hotmail''s web-based application - Thunderbird will query the server and synchronize messages.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configuring-servers"><span class="tocnumber">1</span> <span class="toctext">Configuring servers</span></a><ul><li class="toclevel-2"><a href="#w_configuring-imap-and-pop-accounts"><span class="tocnumber">1.1</span> <span class="toctext">Configuring IMAP and POP accounts</span></a><ul><li class="toclevel-3"><a href="#w_imap-mail-account-settings"><span class="tocnumber">1.1.1</span> <span class="toctext">IMAP mail account settings</span></a></li><li class="toclevel-3"><a href="#w_pop-mail-account-settings"><span class="tocnumber">1.1.2</span> <span class="toctext">POP mail account settings</span></a></li></ul></li><li class="toclevel-2"><a href="#w_configuring-the-outgoing-server"><span class="tocnumber">1.2</span> <span class="toctext">Configuring the outgoing server</span></a></li></ul></li></ul></div>
<h2 id="w_configuring-servers">Configuring servers</h2>
<p>Hotmail accounts can be configured in Thunderbird''s <a href="/en-US/kb/automatic-account-configuration">Automatic Account Configuration</a>. This article provides instructions on how to manually <a href="/en-US/kb/manual-account-configuration">configure an account</a> or modify an existing account.
</p><p>To manually configure or modify Hotmail account settings:
</p>
<ol><li> <span class="for" data-for="win,linux" style="display: none;">At the top of the Thunderbird window, click on the </span><span class="for" data-for="mac">On the menu bar, click on the <span class="menu">Thunderbird</span> menu, choose </span><span class="for" data-for="linux" style="display: none;"> <span class="menu">Edit</span></span><span class="for" data-for="win,mac"><span class="menu">Tools</span></span><span class="for" data-for="win,linux" style="display: none;"> menu</span> and select <span class="menu">Account Settings…</span>. The Account Settings dialog window will be displayed.
</li><li> Select your Hotmail account from the list on the left. Make sure your name and account are correctly specified in the <span class="menu">Default Identity</span> section.<br><br><img alt="sethotmailaccounts" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-09-14-02-33-06-57dcf8.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</li><li> In the left panel, below your Hotmail account name, click on <span class="menu">Server Settings</span>. The server settings will be displayed in the right panel.
</li></ol>
<h3 id="w_configuring-imap-and-pop-accounts">Configuring IMAP and POP accounts</h3>
<div class="note"><strong>Note</strong>: For an explanation of IMAP and POP, <a href="https://support.mozilla.org/kb/glossary-terms-including-types-accounts#w_mail-accounts">click here</a>.</div>
<h4 id="w_imap-mail-account-settings">IMAP mail account settings</h4>
<ul><li>Server Name: outlook.office365.com
</li><li>Port: 993
</li><li>User Name: your username (for example <em><a href="mailto:j.kowal@outlook.com">j.kowal@outlook.com</a></em>)
</li><li>Connection security: SSL/TLS
</li><li>Authentication method: Normal password
</li><li>Configure the rest of the server settings according to your preferences.<br><br><img alt="sethotmailimap" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-09-14-02-37-04-ed4e42.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ul>
<h4 id="w_pop-mail-account-settings">POP mail account settings</h4>
<ul><li>Server Name: outlook.office365.com
</li><li>Port: 995
</li><li>User Name: your username (for example <em><a href="mailto:j.kowal@outlook.com">j.kowal@outlook.com</a></em>)
</li><li>Connection security: SSL/TLS
</li><li>Authentication method: Normal password
</li><li>Configure the rest of the server settings according to your preferences.<br><br><img alt="sethotmailpop" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-09-14-02-37-45-24ee8a.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ul>
<h3 id="w_configuring-the-outgoing-server">Configuring the outgoing server</h3>
<ol><li> At the bottom of the list on the left, select <span class="menu">Outgoing Server (SMTP)</span>. Configured outgoing servers will be displayed in the right panel. The Hotmail server will probably be called <strong>Microsoft Live Hotmail</strong> or something similar.<br><br><img alt="sethotmailsmtp" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-09-14-02-44-07-f24e88.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""><br><br>
</li><li> Select the server and click the <span class="button">Edit</span> button to alter the settings. Configure them as follows:
<ul><li>Server Name: smtp-mail.outlook.com
</li><li>Port: 587
</li><li>Connection security: STARTTLS
</li><li>Authentication method: Normal password
</li><li>User Name: your username (for example <em><a href="mailto:j.kowal@outlook.com">j.kowal@outlook.com</a></em>)<br><br><img alt="sethotmailsmtp1" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2013-09-14-02-41-42-7e14b8.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ul>
</li></ol>
<div class="note"><strong>Note</strong>: If you receive a password error in Thunderbird when trying to retrieve messages using POP, you may need to sign in using webmail first and <a href="https://support.microsoft.com/en-us/office/pop-imap-and-smtp-settings-for-outlook-com-d088b986-291d-42b8-9564-9c414e2aa040">enable POP settings</a> under the Options section of your Outlook.com email account.
</div>','[{"label": "Revision id", "text": "234252", "datetime": null, "href": null}, {"label": "Created", "text": "Dec 9, 2021, 1:23:12 AM", "datetime": "2021-12-09T01:23:12-08:00", "href": null}, {"label": "Creator", "text": "Hotmail", "datetime": null, "href": "https://support.mozilla.org/en-US/user/hotmail./"}, {"label": "Comment", "text": "new imap and pop server address ( outlook.office365.com ))", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Nov 1, 2024, 4:12:15 AM", "datetime": "2024-11-01T04:12:15.179801-07:00", "href": null}, {"label": "Reviewed by", "text": "AliceWyman", "datetime": null, "href": null}, {"label": "Is approved?", "text": "No", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:18:08+00:00','M');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (235591,'en-US','thunderbird-and-gmail','Thunderbird and Gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail/revision/235591',217290,'2021-12-30T07:09:31-08:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','add limits, remove obsolete add-ons',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Thunderbird can be configured to work seamlessly with Google''s [http://gmail.google.com Gmail] service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.

{warning}''''''Newer Gmail accounts won''t work with Thunderbird 31 and older versions because these versions don''t support Google''s authentication'''''' ([https://bugzilla.mozilla.org/show_bug.cgi?id=849540 bug 849540] contains the full technical details). Please make sure that [[Updating Thunderbird|you are using Thunderbird 38 or newer]] before configuring your account.{/warning}

__TOC__

= Configuring your Gmail account =
{for win}
[[Video:https://www.youtube.com/watch?v=JXs_YE9QyUQ]]
{/for}
To configure Thunderbird to work with Gmail, first enable IMAP on your Gmail account. 
See [http://mail.google.com/support/bin/answer.py?answer=77695 Gmail''s instructions] for help. (IMAP is enabled on new Gmail accounts by default.)
{for not tb38}
Double check that "Access for less secure apps" is enabled. See [https://www.google.com/settings/security/lesssecureapps Google''s article on "less secure apps"] for help.
{/for}

Next, select {menu File > New > Existing Mail Account...}. The "Mail Account Setup" dialog is displayed. After you provide your account information (real name, email address and password), Thunderbird will automatically configure your Gmail connection. Click {button Done}{for tb38}, sign in with your Google account if prompted{/for} and that''s all! Thunderbird will download your existing messages and your Gmail will be ready to use.

For more detailed information, please refer to:
* [[Automatic Account Configuration]] 
* [http://mail.google.com/support/bin/answer.py?answer=180189 First steps with IMAP on Gmail]  
* [http://mail.google.com/support/bin/topic.py?topic=12806 Gmail''s IMAP tips]

= Gmail''s particularities =
== Archiving messages ==

In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the "All Mail" folder, and not in an "Archive" folder as it does for other accounts (as described in the [[Archived Messages]] article).

[[Image:Gmail Archive settings]] 

Note that the {button Archive options...} button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.

== Subscribing to folders and synchronizing messages ==
=== Understanding Gmail labels and Thunderbird folders ===
Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.

In the example shown below, the folders at the same level as the "''''[Gmail]''''" folder ("g+", "Personal", "Receipts", "Travel" and "Work") correspond to Gmail labels.<br> <!--changed order according to screenshot (Artist, Sept. 23, 2014) -->

[[Image:default gmail folders]] <br>

There is also a set of special sub-folders for the "''''[Gmail]''''" folder:
* All Mail: contains all of the messages in your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the ''''[Gmail]/All Mail'''' folder.
* Drafts: contains draft messages.
* Sent Mail: contains sent messages.
* Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
* Starred: contains messages that were starred (either by Gmail or Thunderbird).
* Trash: contains deleted messages.
* Important: contains messages that Gmail has flagged as "important". (See [http://support.google.com/mail/bin/answer.py?answer=186531&topic=1669050&ctx=topic Priority Inbox overview] for more details about this Gmail feature.)

=== Subscribing to or unsubscribing from folders (labels) ===
You can configure which Gmail folders you want to display in Thunderbird. By default all Gmail folders are displayed, as described above. To configure folder display, right-click on the account name and select {menu Subscribe}. <br><!-- removed horizontal ellipsis because the menu shown in the screenshot does not show any (unless it is outdated) Artist, Sept. 23, 2014 -->

[[Image:subscribe gmail folders]] 

Uncheck any folders that you don''t want to display in Thunderbird. Messages will still be downloaded and available through the "All Mail" folder. They will also be included in search results. However, the Gmail label (Thunderbird folder) will not be displayed. 

=== Synchronizing folders (labels) ===
If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click on the message header.

To change how messages are downloaded, set synchronization options for the account and for individual folders. ({for win,mac}{menu Tools > Account Settings...}{/for}{for linux}{menu Edit > Account Settings...}{/for}) See [[IMAP Synchronization#w_synchronization]] for more information.

= Limits =
Be aware that Google applies [https://support.google.com/a/topic/28609?hl=en&ref_topic=9202 connection, bandwidth and other limits] to Gmail, both imap and pop connections, which may affect your ability to get and send mail.

= Useful Add-ons =
* If you want to sync your contacts between Thunderbird and Gmail, you should try [https://extension-finder.thunderbird.net/?q=gContactSync alternatives to the gContactSync] add-on. (gContactSync is obsolete)
* If you want to sync your calendar between Lightning and Google Calendar, you should read [[Using Lightning with Google Calendar]].

= See also =
* [https://support.google.com/mail/answer/78892?hl=en Gmail''s support article]
* [https://bugzilla.mozilla.org/show_bug.cgi?id=402793 The ticket which tracks issues using Gmail with Thunderbird (Bug 402793)]','<p>Thunderbird can be configured to work seamlessly with Google''s <a href="http://gmail.google.com">Gmail</a> service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.
</p>
<div class="warning"><strong>Newer Gmail accounts won''t work with Thunderbird 31 and older versions because these versions don''t support Google''s authentication</strong> (<a href="https://bugzilla.mozilla.org/show_bug.cgi?id=849540">bug 849540</a> contains the full technical details). Please make sure that <a href="/en-US/kb/updating-thunderbird">you are using Thunderbird 38 or newer</a> before configuring your account.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configuring-your-gmail-account"><span class="tocnumber">1</span> <span class="toctext">Configuring your Gmail account</span></a></li><li class="toclevel-1"><a href="#w_gmails-particularities"><span class="tocnumber">2</span> <span class="toctext">Gmail''s particularities</span></a><ul><li class="toclevel-2"><a href="#w_archiving-messages"><span class="tocnumber">2.1</span> <span class="toctext">Archiving messages</span></a></li><li class="toclevel-2"><a href="#w_subscribing-to-folders-and-synchronizing-messages"><span class="tocnumber">2.2</span> <span class="toctext">Subscribing to folders and synchronizing messages</span></a><ul><li class="toclevel-3"><a href="#w_understanding-gmail-labels-and-thunderbird-folders"><span class="tocnumber">2.2.1</span> <span class="toctext">Understanding Gmail labels and Thunderbird folders</span></a></li><li class="toclevel-3"><a href="#w_subscribing-to-or-unsubscribing-from-folders-labels"><span class="tocnumber">2.2.2</span> <span class="toctext">Subscribing to or unsubscribing from folders (labels)</span></a></li><li class="toclevel-3"><a href="#w_synchronizing-folders-labels"><span class="tocnumber">2.2.3</span> <span class="toctext">Synchronizing folders (labels)</span></a></li></ul></li></ul></li><li class="toclevel-1"><a href="#w_limits"><span class="tocnumber">3</span> <span class="toctext">Limits</span></a></li><li class="toclevel-1"><a href="#w_useful-add-ons"><span class="tocnumber">4</span> <span class="toctext">Useful Add-ons</span></a></li><li class="toclevel-1"><a href="#w_see-also"><span class="tocnumber">5</span> <span class="toctext">See also</span></a></li></ul></div>
<h1 id="w_configuring-your-gmail-account">Configuring your Gmail account</h1>
<div class="for" data-for="win" style="display: none;"><p></p><div class="youtube-embed">
  <iframe src="//www.youtube.com/embed/JXs_YE9QyUQ?wmode=transparent&amp;rel=0" frameborder="0" allowfullscreen=""></iframe>
</div>
<p></p></div><p>To configure Thunderbird to work with Gmail, first enable IMAP on your Gmail account. 
See <a href="http://mail.google.com/support/bin/answer.py?answer=77695">Gmail''s instructions</a> for help. (IMAP is enabled on new Gmail accounts by default.)
</p><div class="for" data-for="not tb38" style="display: none;"><p>Double check that "Access for less secure apps" is enabled. See <a href="https://www.google.com/settings/security/lesssecureapps">Google''s article on "less secure apps"</a> for help.
</p></div><p>Next, select <span class="menu">File &gt; New &gt; Existing Mail Account...</span>. The "Mail Account Setup" dialog is displayed. After you provide your account information (real name, email address and password), Thunderbird will automatically configure your Gmail connection. Click <span class="button">Done</span><span class="for" data-for="tb38">, sign in with your Google account if prompted</span> and that''s all! Thunderbird will download your existing messages and your Gmail will be ready to use.
</p><p>For more detailed information, please refer to:
</p>
<ul><li> <a href="/en-US/kb/automatic-account-configuration">Automatic Account Configuration</a> 
</li><li> <a href="http://mail.google.com/support/bin/answer.py?answer=180189">First steps with IMAP on Gmail</a>  
</li><li> <a href="http://mail.google.com/support/bin/topic.py?topic=12806">Gmail''s IMAP tips</a>
</li></ul>
<h1 id="w_gmails-particularities">Gmail''s particularities</h1>
<h2 id="w_archiving-messages">Archiving messages</h2>
<p>In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the "All Mail" folder, and not in an "Archive" folder as it does for other accounts (as described in the <a href="/en-US/kb/archived-messages">Archived Messages</a> article).
</p><p><img alt="Gmail Archive settings" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-17-04-13-09-41649e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>Note that the <span class="button">Archive options...</span> button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.
</p>
<h2 id="w_subscribing-to-folders-and-synchronizing-messages">Subscribing to folders and synchronizing messages</h2>
<h3 id="w_understanding-gmail-labels-and-thunderbird-folders">Understanding Gmail labels and Thunderbird folders</h3>
<p>Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.
</p><p>In the example shown below, the folders at the same level as the "<em>[Gmail]</em>" folder ("g+", "Personal", "Receipts", "Travel" and "Work") correspond to Gmail labels.<br> 
</p><p><img alt="default gmail folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-22-16-07-48-8304a9.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> <br>
</p><p>There is also a set of special sub-folders for the "<em>[Gmail]</em>" folder:
</p>
<ul><li> All Mail: contains all of the messages in your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the <em>[Gmail]/All Mail</em> folder.
</li><li> Drafts: contains draft messages.
</li><li> Sent Mail: contains sent messages.
</li><li> Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
</li><li> Starred: contains messages that were starred (either by Gmail or Thunderbird).
</li><li> Trash: contains deleted messages.
</li><li> Important: contains messages that Gmail has flagged as "important". (See <a href="http://support.google.com/mail/bin/answer.py?answer=186531&amp;topic=1669050&amp;ctx=topic">Priority Inbox overview</a> for more details about this Gmail feature.)
</li></ul>
<h3 id="w_subscribing-to-or-unsubscribing-from-folders-labels">Subscribing to or unsubscribing from folders (labels)</h3>
<p>You can configure which Gmail folders you want to display in Thunderbird. By default all Gmail folders are displayed, as described above. To configure folder display, right-click on the account name and select <span class="menu">Subscribe</span>. <br>
</p><p><img alt="subscribe gmail folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-22-16-20-21-1f5531.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</p><p>Uncheck any folders that you don''t want to display in Thunderbird. Messages will still be downloaded and available through the "All Mail" folder. They will also be included in search results. However, the Gmail label (Thunderbird folder) will not be displayed. 
</p>
<h3 id="w_synchronizing-folders-labels">Synchronizing folders (labels)</h3>
<p>If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click on the message header.
</p><p>To change how messages are downloaded, set synchronization options for the account and for individual folders. (<span class="for" data-for="win,mac"><span class="menu">Tools &gt; Account Settings...</span></span><span class="for" data-for="linux" style="display: none;"><span class="menu">Edit &gt; Account Settings...</span></span>) See <a href="/en-US/kb/imap-synchronization#w_synchronization">IMAP Synchronization</a> for more information.
</p>
<h1 id="w_limits">Limits</h1>
<p>Be aware that Google applies <a href="https://support.google.com/a/topic/28609?hl=en&amp;ref_topic=9202">connection, bandwidth and other limits</a> to Gmail, both imap and pop connections, which may affect your ability to get and send mail.
</p>
<h1 id="w_useful-add-ons">Useful Add-ons</h1>
<ul><li> If you want to sync your contacts between Thunderbird and Gmail, you should try <a href="https://extension-finder.thunderbird.net/?q=gContactSync">alternatives to the gContactSync</a> add-on. (gContactSync is obsolete)
</li><li> If you want to sync your calendar between Lightning and Google Calendar, you should read <a href="/en-US/kb/using-lightning-google-calendar">Using Thunderbird with Google Calendar</a>.
</li></ul>
<h1 id="w_see-also">See also</h1>
<ul><li> <a href="https://support.google.com/mail/answer/78892?hl=en">Gmail''s support article</a>
</li><li> <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=402793">The ticket which tracks issues using Gmail with Thunderbird (Bug 402793)</a>
</li></ul>','[{"label": "Revision id", "text": "235591", "datetime": null, "href": null}, {"label": "Created", "text": "Dec 30, 2021, 7:09:31 AM", "datetime": "2021-12-30T07:09:31-08:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "add limits, remove obsolete add-ons", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:17:05+00:00','');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (238033,'en-US','protect-your-thunderbird-passwords-primary-password','Protect your Thunderbird passwords with a Primary Password','https://support.mozilla.org/en-US/kb/protect-your-thunderbird-passwords-primary-password','https://support.mozilla.org/en-US/kb/protect-your-thunderbird-passwords-primary-password/revision/238033',226046,'2022-02-14T09:41:29-08:00','thomas8','https://support.mozilla.org/en-US/user/firefox877/','Replace ''master'' with ''primary'', update screenshots and steps, restructure top section, add warning, remove misleading security-relevant information.',1,'2022-02-14T09:44:55-08:00','firefox877',1,0,1,'2022-02-14T09:44:55-08:00','firefox877','approved','{note}''''Primary Password'''' has replaced ''''Master Password.'''' [[Primary Password is replacing Master Password in Thunderbird|Learn more]] about why we’ve made this change.{/note}

__TOC__

= What does the Primary Password protect? =

{warning}''''''Your primary password protects your saved passwords, but it ''''does not'''' prevent others from seeing your messages in Thunderbird.{/warning}

Thunderbird can save passwords for each account, so you don''t have to re-enter them when you check for new messages. You can view them and remove the ones you don''t use anymore.

What if you share a computer, and don''t want others to see your stored passwords? With the Primary Password feature, Thunderbird will require you to enter a Primary Password in order to view or use the passwords you''ve told Thunderbird to remember. When you have a Primary Password set, you''ll only need to enter it once per session.

[[Image:tb91-password-required-mozilla-thunderbird-please-enter-your-primary-password]]

{note}''''''Do you want to prevent others from seeing your messages?'''''' If you are sharing a computer, the most secure way is to create a separate {for win}Windows{/for}{for mac}MacOS{/for}{for linux}OS{/for} user account on the operating system for each person, and make sure your {for win}Windows{/for}{for mac}MacOS{/for}{for linux}OS{/for} account requires a password. Thunderbird stores accounts, messages and password information separately for each operating system account.

<!-- [Commented out: Not useful because it''s very easy to reverse this method]<br><br> A weaker method is to change the hidden preference mail.password_protect_local_cache in the [[config editor]] to True. This will prevent the display of email until the Primary Password is entered. It does not however do anything about your mail being stored on the hard disk as a plain text file. Using an operating system account does address that.-->
{/note}

= Setting a Primary Password =
By default, Thunderbird does not use a Primary Password to protect stored credentials. To set a Primary Password:
# [[T:optionspreferences TB]]
# Select the {menu Privacy & Security} section.
# Go to the ''''''Passwords'''''' subsection.
# Put a checkmark next to ''''''Use a Primary Password''''''.<br/><br/>[[Image:tb91-preferences-privacy-security-passwords-use-primary-password]]
# The ''''Change Primary Password'''' dialog will appear. As you enter your Primary Password, the password quality meter will indicate the difficulty of guessing the password. Here are some tips for creating better passwords:
#* Use at least one capital letter.
#* Use one or more digits.
#* Use at least one non-alphanumeric character, such as: <nowiki>@ # $ % ^ & * ( )</nowiki>.
#* Make your Primary Password something that is easy for you to remember, but difficult for others to guess, to ensure that only ''''you yourself'''' will be able to see your saved passwords.
# The password must be entered twice to make sure that you have entered it correctly as intended.<br/><br/>[[Image:tb91-use-primary-password-primary-password-dialog]]
# To set your Primary Password, click {button OK}.

Now that your Primary Password is set, Thunderbird will prompt you to enter it the first time you need to view or use a password per session.

= Changing your Primary Password =

# [[T:optionspreferences TB]]
# Select the {menu Privacy & Security} section.
# Go to the ''''''Passwords'''''' subsection.
# Click the button {button Change Primary Password}.
# Enter your current Primary Password to confirm you are authorized to change it.
# Enter the new Primary Password twice.
# Click {button OK}.

= Removing your Primary Password =

Follow the steps above for ''''Changing the Primary Password'''', but leave both of the new Primary Password fields empty.

= Resetting your Primary Password if you have forgotten it =
If you''ve forgotten your Primary Password you can reset it.
{warning}''''''Warning:'''''' This will remove all of your saved usernames and passwords.{/warning}

# Starting from the app menu button {button ≡} or the main menu, choose {menu Tools -> Developer Tools -> Error Console}.
# Copy the text given below and paste it into the Console. The choice is determined by the version you are using.
#* If using a version prior to 78, copy and paste the following text:<br><code>openDialog("chrome://pippki/content/resetpassword.xul")</code>
#* If using version 78 or later, copy and paste the following text:<br><code>openDialog("chrome://pippki/content/resetpassword.xhtml")</code>
# Click the {button Evaluate} button. If you do not see an ''Evaluate'' button, press {key Return} or {key Enter} on your keyboard.
# When prompted with the confirmation dialog box, click the {button Reset} button.<br/><br/>[[Image:tb91-reset-primary-password-dialog]]','<div class="note"><em>Primary Password</em> has replaced <em>Master Password.</em> <a href="/en-US/kb/primary-password-replacing-master-password-thunderbird">Learn more</a> about why we’ve made this change.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_what-does-the-primary-password-protect"><span class="tocnumber">1</span> <span class="toctext">What does the Primary Password protect?</span></a></li><li class="toclevel-1"><a href="#w_setting-a-primary-password"><span class="tocnumber">2</span> <span class="toctext">Setting a Primary Password</span></a></li><li class="toclevel-1"><a href="#w_changing-your-primary-password"><span class="tocnumber">3</span> <span class="toctext">Changing your Primary Password</span></a></li><li class="toclevel-1"><a href="#w_removing-your-primary-password"><span class="tocnumber">4</span> <span class="toctext">Removing your Primary Password</span></a></li><li class="toclevel-1"><a href="#w_resetting-your-primary-password-if-you-have-forgotten-it"><span class="tocnumber">5</span> <span class="toctext">Resetting your Primary Password if you have forgotten it</span></a></li></ul></div>
<h1 id="w_what-does-the-primary-password-protect">What does the Primary Password protect?</h1>
<div class="warning"><strong>Your primary password protects your saved passwords, but it <em>does not</em> prevent others from seeing your messages in Thunderbird.</strong></div><strong>
</strong>
<p>Thunderbird can save passwords for each account, so you don''t have to re-enter them when you check for new messages. You can view them and remove the ones you don''t use anymore.
</p><p>What if you share a computer, and don''t want others to see your stored passwords? With the Primary Password feature, Thunderbird will require you to enter a Primary Password in order to view or use the passwords you''ve told Thunderbird to remember. When you have a Primary Password set, you''ll only need to enter it once per session.
</p><p><img alt="tb91-password-required-mozilla-thunderbird-please-enter-your-primary-password" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-12-29-50-749867.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<div class="note"><strong>Do you want to prevent others from seeing your messages?</strong> If you are sharing a computer, the most secure way is to create a separate <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">MacOS</span><span class="for" data-for="linux" style="display: none;">OS</span> user account on the operating system for each person, and make sure your <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">MacOS</span><span class="for" data-for="linux" style="display: none;">OS</span> account requires a password. Thunderbird stores accounts, messages and password information separately for each operating system account.
<p>
</p>
</div>
<h1 id="w_setting-a-primary-password">Setting a Primary Password</h1>
<p>By default, Thunderbird does not use a Primary Password to protect stored credentials. To set a Primary Password:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Settings</span>.

</li><li> Select the <span class="menu">Privacy &amp; Security</span> section.
</li><li> Go to the <strong>Passwords</strong> subsection.
</li><li> Put a checkmark next to <strong>Use a Primary Password</strong>.<br><br><img alt="tb91-preferences-privacy-security-passwords-use-primary-password" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-14-09-05-dfd94c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> The <em>Change Primary Password</em> dialog will appear. As you enter your Primary Password, the password quality meter will indicate the difficulty of guessing the password. Here are some tips for creating better passwords:
<ul><li> Use at least one capital letter.
</li><li> Use one or more digits.
</li><li> Use at least one non-alphanumeric character, such as: @ # $ % ^ &amp; * ( ).
</li><li> Make your Primary Password something that is easy for you to remember, but difficult for others to guess, to ensure that only <em>you yourself</em> will be able to see your saved passwords.
</li></ul>
</li><li> The password must be entered twice to make sure that you have entered it correctly as intended.<br><br><img alt="tb91-use-primary-password-primary-password-dialog" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-14-59-36-393ff3.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> To set your Primary Password, click <span class="button">OK</span>.
</li></ol>
<p>Now that your Primary Password is set, Thunderbird will prompt you to enter it the first time you need to view or use a password per session.
</p>
<h1 id="w_changing-your-primary-password">Changing your Primary Password</h1>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Settings</span>.

</li><li> Select the <span class="menu">Privacy &amp; Security</span> section.
</li><li> Go to the <strong>Passwords</strong> subsection.
</li><li> Click the button <span class="button">Change Primary Password</span>.
</li><li> Enter your current Primary Password to confirm you are authorized to change it.
</li><li> Enter the new Primary Password twice.
</li><li> Click <span class="button">OK</span>.
</li></ol>
<h1 id="w_removing-your-primary-password">Removing your Primary Password</h1>
<p>Follow the steps above for <em>Changing the Primary Password</em>, but leave both of the new Primary Password fields empty.
</p>
<h1 id="w_resetting-your-primary-password-if-you-have-forgotten-it">Resetting your Primary Password if you have forgotten it</h1>
<p>If you''ve forgotten your Primary Password you can reset it.
</p>
<div class="warning"><strong>Warning:</strong> This will remove all of your saved usernames and passwords.</div>
<ol><li> Starting from the app menu button <span class="button">≡</span> or the main menu, choose <span class="menu">Tools -&gt; Developer Tools -&gt; Error Console</span>.
</li><li> Copy the text given below and paste it into the Console. The choice is determined by the version you are using.
<ul><li> If using a version prior to 78, copy and paste the following text:<br><code>openDialog("chrome://pippki/content/resetpassword.xul")</code>
</li><li> If using version 78 or later, copy and paste the following text:<br><code>openDialog("chrome://pippki/content/resetpassword.xhtml")</code>
</li></ul>
</li><li> Click the <span class="button">Evaluate</span> button. If you do not see an ''Evaluate'' button, press <span class="key">Return</span> or <span class="key">Enter</span> on your keyboard.
</li><li> When prompted with the confirmation dialog box, click the <span class="button">Reset</span> button.<br><br><img alt="tb91-reset-primary-password-dialog" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-15-48-30-8ed674.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ol>','[{"label": "Revision id", "text": "238033", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 14, 2022, 9:41:29 AM", "datetime": "2022-02-14T09:41:29-08:00", "href": null}, {"label": "Creator", "text": "thomas8", "datetime": null, "href": "https://support.mozilla.org/en-US/user/firefox877/"}, {"label": "Comment", "text": "Replace ''master'' with ''primary'', update screenshots and steps, restructure top section, add warning, remove misleading security-relevant information.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 14, 2022, 9:44:55 AM", "datetime": "2022-02-14T09:44:55-08:00", "href": null}, {"label": "Reviewed by", "text": "firefox877", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Feb 14, 2022, 9:44:55 AM", "datetime": "2022-02-14T09:44:55-08:00", "href": null}, {"label": "Readied for localization by", "text": "firefox877", "datetime": null, "href": null}]','2026-11-03T20:13:23+00:00','MT');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (238564,'en-US','installing-thunderbird-linux','Install Thunderbird on Linux','https://support.mozilla.org/en-US/kb/installing-thunderbird-linux','https://support.mozilla.org/en-US/kb/installing-thunderbird-linux/revision/238564',193857,'2022-02-25T01:03:59-08:00','Danny Colin','https://support.mozilla.org/en-US/user/dannycolin/','[WIP/Do Not Merge] Updating the installation instructions',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','__TOC__

This article explains how to download and install Thunderbird on a Linux. 

{for mac,win}{note}''''''This article only applies to Linux.'''''' {for mac}For instructions to install Thunderbird on Mac, see [[Installing Thunderbird on Mac]].{/for}{for win}For instructions to install Thunderbird on Windows, see [[Installing Thunderbird on Windows]] .{/for}{/note}{/for}

= Installing from your distribution package manager (Recommended) =

To install Thunderbird using your distribution package manager, please refer to your Linux distribution''s documentation.

This method is the recommended way because it ensures Thunderbird and all the required libraries are installed and configured optimally for your distribution. However, there may be a small delay between the official release of a new version of Thundebird and the moment when your distribution updates the version it distributes. Your distribution may also distribute it without the Thunderbird branding.

= Installing Thunderbird manually (For advanced users) = 

{note}
* ''''''Before you install Thunderbird'''''', make sure that your computer has the '''''' [https://www.thunderbird.net/thunderbird/system-requirements/ required libraries]'''''' installed. Missing libraries will cause Thunderbird to be inoperable.
{/note}

1. Go to the [https://www.thunderbird.net/download/ Thunderbird''s download page] and click on the {button Free Download} button.

2. Open a terminal and go to the folder where your download has been saved. For example:

<code>
cd ~/Downloads
</code>

3. Extract the contents of the downloaded file by typing:

<code>
tar xjf thunderbird-*.tar.bz2
</code>

4. Move the uncompressed Thunderbird folder to {filepath /opt}:

<code>
mv thunderbird /opt
</code>

5. Create a symlink to the Thunderbird executable:

<code>
ln -s /opt/thunderbird/thunderbird /usr/local/bin/thunderbird
</code>

6. Download a copy of our desktop file:

<code>
wget https://raw.githubusercontent.com/mozilla-sumo/kb/main/installing-thunderbird-linux/thunderbird.desktop -P /usr/local/share/applications
</code>

Alternatively, if <code>wget</code> is not installed on your computer, go to the URL mentioned above, right-click on the page to open the contextual menu and select {menu Save Page As}. After you downloaded the file, move it to {filepath /usr/local/share/applications}.','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_installing-from-your-distribution-package-manager-recommended"><span class="tocnumber">1</span> <span class="toctext">Installing from your distribution package manager (Recommended)</span></a></li><li class="toclevel-1"><a href="#w_installing-thunderbird-manually-for-advanced-users"><span class="tocnumber">2</span> <span class="toctext">Installing Thunderbird manually (For advanced users)</span></a></li></ul></div>
<p>This article explains how to download and install Thunderbird on a Linux. 
</p>
<div class="for" data-for="mac,win"><div class="note"><strong>This article only applies to Linux.</strong> <span class="for" data-for="mac">For instructions to install Thunderbird on Mac, see <a href="/en-US/kb/installing-thunderbird-on-mac">Install Thunderbird on Mac</a>.</span><span class="for" data-for="win" style="display: none;">For instructions to install Thunderbird on Windows, see <a href="/en-US/kb/installing-thunderbird-windows">Install Thunderbird on Windows</a> .</span></div></div>
<h1 id="w_installing-from-your-distribution-package-manager-recommended">Installing from your distribution package manager (Recommended)</h1>
<p>To install Thunderbird using your distribution package manager, please refer to your Linux distribution''s documentation.
</p><p>This method is the recommended way because it ensures Thunderbird and all the required libraries are installed and configured optimally for your distribution. However, there may be a small delay between the official release of a new version of Thundebird and the moment when your distribution updates the version it distributes. Your distribution may also distribute it without the Thunderbird branding.
</p>
<h1 id="w_installing-thunderbird-manually-for-advanced-users">Installing Thunderbird manually (For advanced users)</h1>
<div class="note">
<ul><li> <strong>Before you install Thunderbird</strong>, make sure that your computer has the <strong> <a href="https://www.thunderbird.net/thunderbird/system-requirements/">required libraries</a></strong> installed. Missing libraries will cause Thunderbird to be inoperable.
</li></ul>
</div>
<p>1. Go to the <a href="https://www.thunderbird.net/download/">Thunderbird''s download page</a> and click on the <span class="button">Free Download</span> button.
</p><p>2. Open a terminal and go to the folder where your download has been saved. For example:
</p><p><code>
cd ~/Downloads
</code>
</p><p>3. Extract the contents of the downloaded file by typing:
</p><p><code>
tar xjf thunderbird-*.tar.bz2
</code>
</p><p>4. Move the uncompressed Thunderbird folder to <span class="filepath">/opt</span>:
</p><p><code>
mv thunderbird /opt
</code>
</p><p>5. Create a symlink to the Thunderbird executable:
</p><p><code>
ln -s /opt/thunderbird/thunderbird /usr/local/bin/thunderbird
</code>
</p><p>6. Download a copy of our desktop file:
</p><p><code>
wget https://raw.githubusercontent.com/mozilla-sumo/kb/main/installing-thunderbird-linux/thunderbird.desktop -P /usr/local/share/applications
</code>
</p><p>Alternatively, if <code>wget</code> is not installed on your computer, go to the URL mentioned above, right-click on the page to open the contextual menu and select <span class="menu">Save Page As</span>. After you downloaded the file, move it to <span class="filepath">/usr/local/share/applications</span>.
</p>','[{"label": "Revision id", "text": "238564", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 25, 2022, 1:03:59 AM", "datetime": "2022-02-25T01:03:59-08:00", "href": null}, {"label": "Creator", "text": "Danny Colin", "datetime": null, "href": "https://support.mozilla.org/en-US/user/dannycolin/"}, {"label": "Comment", "text": "[WIP/Do Not Merge] Updating the installation instructions", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:10:48+00:00','');
