</p>','[{"label": "Revision id", "text": "238953", "datetime": null, "href": null}, {"label": "Created", "text": "Mar 2, 2022, 8:14:16 AM", "datetime": "2022-03-02T08:14:16-08:00", "href": null}, {"label": "Creator", "text": "Danny Colin", "datetime": null, "href": "https://support.mozilla.org/en-US/user/dannycolin/"}, {"label": "Comment", "text": "Add Snap instructions", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:10:44+00:00','');
