INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (240752,'en-US','automatic-conversion-google-mail-accounts-oauth20','Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20/revision/240752',NULL,'2022-04-01T21:55:38-07:00','Matt','https://support.mozilla.org/en-US/user/MattAuSupport/','imitial content.',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Thunderbird 91.8 released 5th April 2022 converts all Gmail accounts to oAuth2.0 in compliance with Googles schedule for requiring this log in method published [https://support.google.com/accounts/answer/6010255?hl=en here].

While a universal conversion has occured in the update to change the method of authentication to oAuth2.0,  some users may experience issues with the requirement for the use of oAuth2.0 if they have cookies disabled in Thunderbird.  

If the default setting to allow cookies has been changed to disable cookies the authentication flow used for oAuth2.0 will fail. Without cookies to store data between page updates the flow can not successfully complete as this is a web page flow using web pages served by Google.

Check in Preferences on the [[Image:Fx57Menu]] menu (search cook in the preferences serch box) and ensure that Accept cookies from sites is enabled to fix cookie issues resulting from this change.','<p>Thunderbird 91.8 released 5th April 2022 converts all Gmail accounts to oAuth2.0 in compliance with Googles schedule for requiring this log in method published <a href="https://support.google.com/accounts/answer/6010255?hl=en">here</a>.
</p><p>While a universal conversion has occured in the update to change the method of authentication to oAuth2.0,  some users may experience issues with the requirement for the use of oAuth2.0 if they have cookies disabled in Thunderbird.  
</p><p>If the default setting to allow cookies has been changed to disable cookies the authentication flow used for oAuth2.0 will fail. Without cookies to store data between page updates the flow can not successfully complete as this is a web page flow using web pages served by Google.
</p><p>Check in Preferences on the <img alt="Fx57Menu" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2017-10-22-15-37-15-18c775.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> menu (search cook in the preferences serch box) and ensure that Accept cookies from sites is enabled to fix cookie issues resulting from this change.
</p>','[{"label": "Revision id", "text": "240752", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 1, 2022, 9:55:38 PM", "datetime": "2022-04-01T21:55:38-07:00", "href": null}, {"label": "Creator", "text": "Matt", "datetime": null, "href": "https://support.mozilla.org/en-US/user/MattAuSupport/"}, {"label": "Comment", "text": "imitial content.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:04:54+00:00','');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (240757,'en-US','automatic-conversion-google-mail-accounts-oauth20','Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20/revision/240757',240752,'2022-04-01T23:24:47-07:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','I''ve made further edits on the initial draft, but there are a couple more things to be done',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to oAuth2.0 to help users  comply with [https://support.google.com/accounts/answer/6010255?hl=en Google''s requirement of oAuth2.0 for Gmail logins].

Thunderbird changing the method of authentication to oAuth2.0 will cause problems if you have cookies disabled in Thunderbird, because cookies must be enabled for oAuth2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google.

To avoid or correct the problem, ensure that ''''''Accept cookies from sites'''''' is enabled at {button ≡} > {menu Preferences} > type ''''''cookies'''''' into the search field.  (You can disable cookies after the oauth process is completed both for receiving and sending mail.)','<p>Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to oAuth2.0 to help users  comply with <a href="https://support.google.com/accounts/answer/6010255?hl=en">Google''s requirement of oAuth2.0 for Gmail logins</a>.
</p><p>Thunderbird changing the method of authentication to oAuth2.0 will cause problems if you have cookies disabled in Thunderbird, because cookies must be enabled for oAuth2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google.
</p><p>To avoid or correct the problem, ensure that <strong>Accept cookies from sites</strong> is enabled at <span class="button">≡</span> &gt; <span class="menu">Preferences</span> &gt; type <strong>cookies</strong> into the search field.  (You can disable cookies after the oauth process is completed both for receiving and sending mail.)
</p>','[{"label": "Revision id", "text": "240757", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 1, 2022, 11:24:47 PM", "datetime": "2022-04-01T23:24:47-07:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "I''ve made further edits on the initial draft, but there are a couple more things to be done", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:04:52+00:00','');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (240948,'en-US','automatic-conversion-google-mail-accounts-oauth20','Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20/revision/240948',240757,'2022-04-04T09:41:19-07:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','more about cookies',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to oAuth2.0 to help users  comply with [https://support.google.com/accounts/answer/6010255?hl=en Google''s requirement of oAuth2.0 for Gmail logins].

Thunderbird changing the method of authentication to oAuth2.0 will cause problems if you have cookies disabled in Thunderbird, because cookies must be enabled for oAuth2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google.

To avoid or correct the problem, ensure that ''''''Accept cookies from sites'''''' is enabled at {button ≡} > {menu Preferences} > type ''''''cookies'''''' into the search field. You can disable cookies after the oAuth process is completed, and receiving and sending mail will work with cookies disabled. But when the oAuth token for Gmail access expires at some date in the future, the oAuth process will be needed again, which will require cookies to be enabled.','<p>Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to oAuth2.0 to help users  comply with <a href="https://support.google.com/accounts/answer/6010255?hl=en">Google''s requirement of oAuth2.0 for Gmail logins</a>.
</p><p>Thunderbird changing the method of authentication to oAuth2.0 will cause problems if you have cookies disabled in Thunderbird, because cookies must be enabled for oAuth2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google.
</p><p>To avoid or correct the problem, ensure that <strong>Accept cookies from sites</strong> is enabled at <span class="button">≡</span> &gt; <span class="menu">Preferences</span> &gt; type <strong>cookies</strong> into the search field. You can disable cookies after the oAuth process is completed, and receiving and sending mail will work with cookies disabled. But when the oAuth token for Gmail access expires at some date in the future, the oAuth process will be needed again, which will require cookies to be enabled.
</p>','[{"label": "Revision id", "text": "240948", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 4, 2022, 9:41:19 AM", "datetime": "2022-04-04T09:41:19-07:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "more about cookies", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:04:49+00:00','');
