INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (241274,'en-US','automatic-conversion-google-mail-accounts-oauth20','Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20/revision/241274',241136,'2022-04-09T12:43:40-07:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','add instructions for making a cookie exception',1,'2022-04-10T21:34:50-07:00','firefox877',1,0,0,NULL,NULL,'approved','Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to oAuth 2.0 to help users comply with [https://support.google.com/accounts/answer/6010255?hl=en Google''s requirement of oAuth 2.0 for Gmail logins].

Thunderbird changing the method of authentication to oAuth 2.0 will cause problems if you have cookies disabled in Thunderbird, because cookies must be enabled for oAuth 2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google.

To avoid or correct the problem, do one of the following:
* Ensure that ''''''Accept cookies from sites'''''' is enabled at {button ≡} > {menu Preferences} > type ''''''cookies'''''' into the search field. You can disable cookies after the oAuth process is completed, and receiving and sending mail will work with cookies disabled. But when the oAuth token for Gmail access expires at some date in the future, the oAuth process will be needed again, which will require cookies to be enabled.
* Create an exception with cookies disabled at {button ≡} > {menu Preferences} > {menu Privacy & Security} > {menu Web Content} > {menu Accept cookies from sites} (with {menu Accept} unchecked), click {menu Exceptions} and enter an address of ''''''https://accounts.google.com''''''. Pick {menu Allow}, then {menu Save Changes}.','<p>Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to oAuth&nbsp;2.0 to help users comply with <a href="https://support.google.com/accounts/answer/6010255?hl=en">Google''s requirement of oAuth&nbsp;2.0 for Gmail logins</a>.
</p><p>Thunderbird changing the method of authentication to oAuth&nbsp;2.0 will cause problems if you have cookies disabled in Thunderbird, because cookies must be enabled for oAuth&nbsp;2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google.
</p><p>To avoid or correct the problem, do one of the following:
</p>
<ul><li> Ensure that <strong>Accept cookies from sites</strong> is enabled at <span class="button">≡</span> &gt; <span class="menu">Preferences</span> &gt; type <strong>cookies</strong> into the search field. You can disable cookies after the oAuth process is completed, and receiving and sending mail will work with cookies disabled. But when the oAuth token for Gmail access expires at some date in the future, the oAuth process will be needed again, which will require cookies to be enabled.
</li><li> Create an exception with cookies disabled at <span class="button">≡</span> &gt; <span class="menu">Preferences</span> &gt; <span class="menu">Privacy &amp; Security</span> &gt; <span class="menu">Web Content</span> &gt; <span class="menu">Accept cookies from sites</span> (with <span class="menu">Accept</span> unchecked), click <span class="menu">Exceptions</span> and enter an address of <strong><a href="https://accounts.google.com">https://accounts.google.com</a></strong>. Pick <span class="menu">Allow</span>, then <span class="menu">Save Changes</span>.
</li></ul>','[{"label": "Revision id", "text": "241274", "datetime": null, "href": null}, {"label": "Created", "text": "Apr 9, 2022, 12:43:40 PM", "datetime": "2022-04-09T12:43:40-07:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "add instructions for making a cookie exception", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Apr 10, 2022, 9:34:50 PM", "datetime": "2022-04-10T21:34:50-07:00", "href": null}, {"label": "Reviewed by", "text": "firefox877", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:04:37+00:00','M');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (241275,'en-US','thunderbird-and-gmail','Thunderbird and Gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail/revision/241275',235591,'2022-04-09T13:11:09-07:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','link to Automatic Conversion of Google mail accounts to oAuth2.0 Authentication',1,'2022-04-10T21:43:44-07:00','firefox877',1,0,0,NULL,NULL,'approved','Thunderbird can be configured to work seamlessly with Google''s [http://gmail.google.com Gmail] service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.

{warning}As of May 30, 2022, Google no longer allows ''''''Less secure app access'''''' for Gmail accounts, thus oAuth is required. If you are using Google supplied "app passwords", Thunderbird version 91.8.0 and newer will [[Automatic Conversion of Google mail accounts to oAuth2.0 Authentication|make that conversion]] for you.  Further, ''''''Gmail accounts do work not with Thunderbird 31 and older because they do not support Google''s oAuth (implmented in [https://bugzilla.mozilla.org/show_bug.cgi?id=849540 bug 849540]).{/warning}

__TOC__

= Configuring your Gmail account =
{for win}
[[Video:https://www.youtube.com/watch?v=JXs_YE9QyUQ]]
{/for}
To configure Thunderbird to work with Gmail, first enable IMAP on your Gmail account. 
See [http://mail.google.com/support/bin/answer.py?answer=77695 Gmail''s instructions] for help. (IMAP is enabled on new Gmail accounts by default.)
{for not tb38}
Double check that "Access for less secure apps" is enabled. See [https://www.google.com/settings/security/lesssecureapps Google''s article on "less secure apps"] for help.
{/for}

Next, select {menu File > New > Existing Mail Account...}. The "Mail Account Setup" dialog is displayed. After you provide your account information (real name, email address and password), Thunderbird will automatically configure your Gmail connection. Click {button Done}{for tb38}, sign in with your Google account if prompted{/for} and that''s all! Thunderbird will download your existing messages and your Gmail will be ready to use.

For more detailed information, please refer to:
* [[Automatic Account Configuration]] 
* [http://mail.google.com/support/bin/answer.py?answer=180189 First steps with IMAP on Gmail]  
* [http://mail.google.com/support/bin/topic.py?topic=12806 Gmail''s IMAP tips]

= Gmail''s particularities =
== Archiving messages ==

In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the "All Mail" folder, and not in an "Archive" folder as it does for other accounts (as described in the [[Archived Messages]] article).

[[Image:Gmail Archive settings]] 

Note that the {button Archive options...} button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.

== Subscribing to folders and synchronizing messages ==
=== Understanding Gmail labels and Thunderbird folders ===
Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.

In the example shown below, the folders at the same level as the "''''[Gmail]''''" folder ("g+", "Personal", "Receipts", "Travel" and "Work") correspond to Gmail labels.<br> <!--changed order according to screenshot (Artist, Sept. 23, 2014) -->

[[Image:default gmail folders]] <br>

There is also a set of special sub-folders for the "''''[Gmail]''''" folder:
* All Mail: contains all of the messages in your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the ''''[Gmail]/All Mail'''' folder.
* Drafts: contains draft messages.
* Sent Mail: contains sent messages.
* Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
* Starred: contains messages that were starred (either by Gmail or Thunderbird).
* Trash: contains deleted messages.
* Important: contains messages that Gmail has flagged as "important". (See [http://support.google.com/mail/bin/answer.py?answer=186531&topic=1669050&ctx=topic Priority Inbox overview] for more details about this Gmail feature.)

=== Subscribing to or unsubscribing from folders (labels) ===

You can configure which Gmail folders you want to display in Thunderbird. By default all Gmail folders are displayed, as described above. To configure folder display, right-click on the account name and select {menu Subscribe}. <br><!-- removed horizontal ellipsis because the menu shown in the screenshot does not show any (unless it is outdated) Artist, Sept. 23, 2014 -->

[[Image:subscribe gmail folders]] 

Uncheck any folders that you don''t want to display in Thunderbird. Messages will still be downloaded and available through the "All Mail" folder. They will also be included in search results. However, the Gmail label (Thunderbird folder) will not be displayed. 


=== Synchronizing folders (labels) ===

If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click on the message header.

To change how messages are downloaded, set synchronization options for the account and for individual folders. ({for win,mac}{menu Tools > Account Settings...}{/for}{for linux}{menu Edit > Account Settings...}{/for}) See [[IMAP Synchronization#w_synchronization]] for more information.


= Useful Add-ons =
* If you want to sync your contacts between Thunderbird and Gmail, you should try either the [https://addons.thunderbird.net/thunderbird/addon/google-contacts/ Google Contacts] or [https://addons.thunderbird.net/thunderbird/addon/gcontactsync/ gContactSync] add-ons.
* If you want to sync your calendar between Lightning and Google Calendar, you should read [[Using Lightning with Google Calendar]].
* [https://addons.thunderbird.net/thunderbird/addon/flat-folder-tree/ Flat Folder Tree]  is useful to show all the sub-folders of the [Gmail] IMAP''s folder at the same level than your other folders.
* [https://addons.thunderbird.net/thunderbird/addon/gmailbuttons/ Gmail Buttons] makes it easier to move messages to the Trash and Spam folders. Beta version also shows all Gmail labels for each message.


= See also =

* [https://support.google.com/mail/answer/78892?hl=en Gmail''s support article]
* [https://bugzilla.mozilla.org/show_bug.cgi?id=402793 The ticket which tracks issues using Gmail with Thunderbird (Bug 402793)]','<p>Thunderbird can be configured to work seamlessly with Google''s <a href="http://gmail.google.com">Gmail</a> service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.
</p>
<div class="warning">As of May 30, 2022, Google no longer allows <strong>Less secure app access</strong> for Gmail accounts, thus oAuth is required. If you are using Google supplied "app passwords", Thunderbird version 91.8.0 and newer will <a href="/en-US/kb/automatic-conversion-google-mail-accounts-oauth20">make that conversion</a> for you.  Further, <strong>Gmail accounts do work not with Thunderbird 31 and older because they do not support Google''s oAuth (implmented in <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=849540">bug 849540</a>).</strong></div><strong>
