INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (243443,'en-US','automatic-conversion-google-mail-accounts-oauth20','Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20','https://support.mozilla.org/en-US/kb/automatic-conversion-google-mail-accounts-oauth20/revision/243443',243428,'2022-05-04T09:51:02-07:00','thomas8','https://support.mozilla.org/en-US/user/firefox877/','Rework article structure and language, add formatting and direct support question link.',1,'2022-05-04T11:17:34-07:00','wsmwk',1,0,1,'2022-05-04T11:17:34-07:00','wsmwk','approved','Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to OAuth 2.0 to help users comply with [https://support.google.com/accounts/answer/6010255 Google''s requirement of OAuth 2.0 for Gmail logins]. These changes are ''''''required'''''' by Google.

{warning} ''''''If you have rejected cookies in Thunderbird, the OAuth process will fail'''''' because some cookies must be accepted for the OAuth 2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google. ''''''You need to accept cookies at least temporarily using one of the methods described below.''''''{/warning}

== How to avoid or correct an OAauth failure caused by rejected cookies ==

First, verify your general setting for cookies in Thunderbird:
* Do {button ≡} > {menu Preferences} > {menu Privacy & Security} > {menu Web Content}
* Look at the checkbox {menu Accept cookies from sites}. 

''''''If {menu Accept cookies from sites} is ''''not'''' checked'''''', do one of the following and then go through the OAuth login process again:
* ''''''Create an exception to accept cookies from Google:''''''
** Click the nearby {button Exceptions…} button to open the ''''Exceptions - Cookies'''' dialog.
** In the ''''''Address of website'''''' input box, enter ''''''https://accounts.google.com''''''.
** Pick {button Allow}, then {button Save Changes}.
* ''''''Alternatively, accept ''''all'''' cookies:''''''
** Set the checkmark for {menu Accept cookies from sites}.

After you have gone through the OAuth process, if you prefer, you can again reject cookies - because receiving and sending mail will work with cookies rejected. But rejecting all cookies or removing the exception has the disadvantage that when the OAuth token for Gmail access expires at some date in the future, the OAuth dialog will show up and fail again until you accept the required cookies.

For greater detail about cookies see the article [[Privacy panel - Remote content and cookie settings in Thunderbird]].

If you''re still having problems, you can [https://support.mozilla.org/questions/new/thunderbird/form ask a question in Thunderbird support].','<p>Thunderbird 91.8.0, released 5th April 2022, converts Gmail accounts to OAuth 2.0 to help users comply with <a href="https://support.google.com/accounts/answer/6010255">Google''s requirement of OAuth 2.0 for Gmail logins</a>. These changes are <strong>required</strong> by Google.
</p>
<div class="warning"> <strong>If you have rejected cookies in Thunderbird, the OAuth process will fail</strong> because some cookies must be accepted for the OAuth 2.0 authentication flow to work properly. Without cookies to store data between page updates, the authentication flow cannot successfully complete the web pages served by Google. <strong>You need to accept cookies at least temporarily using one of the methods described below.</strong></div>
