</p>','[{"label": "Revision id", "text": "254387", "datetime": null, "href": null}, {"label": "Created", "text": "Dec 8, 2022, 12:22:56 AM", "datetime": "2022-12-08T00:22:56-08:00", "href": null}, {"label": "Creator", "text": "Toad-Hall", "datetime": null, "href": "https://support.mozilla.org/en-US/user/Toad-Hall/"}, {"label": "Comment", "text": "updated - Options and Preferences wording now changed to  ''Settings''", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:14:46+00:00','');
