INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (255410,'en-US','templateoptionspreferences','Template:optionspreferences TB','https://support.mozilla.org/en-US/kb/templateoptionspreferences','https://support.mozilla.org/en-US/kb/templateoptionspreferences/revision/255410',254388,'2023-01-08T02:53:55-08:00','Mozinet','https://support.mozilla.org/en-US/user/Mozinet/','bold ⇒ italic, deleted useless conditional markup',1,'2023-06-08T12:12:30-07:00','AliceWyman',1,0,0,NULL,NULL,'approved','{for win}At the top of the Thunderbird window on the ''''Menu Bar'''' toolbar, click the {menu Tools} menu and select {menu Settings}{/for}{for mac}In the menu bar, click the {menu Thunderbird} menu and select {menu Settings}{/for}{for linux}At the top of the Thunderbird window on the ''''''Menu Bar'''''' toolbar, click the {menu Edit} menu and select {menu Settings}{/for}, or on the ''''Mail Toolbar'''' click the menu button [[Image:Fx57menu]] and choose {menu Settings}.','<p><span class="for" data-for="win" style="display: none;">At the top of the Thunderbird window on the <em>Menu Bar</em> toolbar, click the <span class="menu">Tools</span> menu and select <span class="menu">Settings</span></span><span class="for" data-for="mac">In the menu bar, click the <span class="menu">Thunderbird</span> menu and select <span class="menu">Settings</span></span><span class="for" data-for="linux" style="display: none;">At the top of the Thunderbird window on the <strong>Menu Bar</strong> toolbar, click the <span class="menu">Edit</span> menu and select <span class="menu">Settings</span></span>, or on the <em>Mail Toolbar</em> click the menu button <img alt="Fx57menu" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2024-07-21-10-54-51-be5aec.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> and choose <span class="menu">Settings</span>.
</p>','[{"label": "Revision id", "text": "255410", "datetime": null, "href": null}, {"label": "Created", "text": "Jan 8, 2023, 2:53:55 AM", "datetime": "2023-01-08T02:53:55-08:00", "href": null}, {"label": "Creator", "text": "Mozinet", "datetime": null, "href": "https://support.mozilla.org/en-US/user/Mozinet/"}, {"label": "Comment", "text": "bold ⇒ italic, deleted useless conditional markup", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Jun 8, 2023, 12:12:30 PM", "datetime": "2023-06-08T12:12:30-07:00", "href": null}, {"label": "Reviewed by", "text": "AliceWyman", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:14:41+00:00','');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (256630,'en-US','microsoft-oauth-authentication-and-thunderbird-202','Microsoft OAuth Authentication and Thunderbird in 2026','https://support.mozilla.org/en-US/kb/microsoft-oauth-authentication-and-thunderbird-202','https://support.mozilla.org/en-US/kb/microsoft-oauth-authentication-and-thunderbird-202/revision/256630',NULL,'2023-02-02T10:10:17-08:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','first draft, not ready for review',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','Microsoft has made some changes to authentication for their hosted email services for business and academic accounts. This topic describes these changes and how to adjust to them. As of the date of this article, February 3, 2023, this information is still evolving and subject to change.

== Changes to Authentication ==

Microsoft has instututed the following changes :
* Deprecating basic authentication (username/password), and is instead now requiring oAuth authentication.
* Disabling SMTP Auth entirely, in some cases. For new accounts, SMTP always starts disabled. In addition, there are some restrictions on SMTP that are not currently understood.

Microsoft have also changed the way they classify certain clients, and Thunderbird’s previous oAuth setup does not properly qualify as desktop client. As a result, we have been forced to make configuration changes to Thunderbird which may have side effects for users.

== Changes or Problems You May Encounter ==

If you are encountering problems with account setup to outlook.com, hotmail.com, Office 365, or another Microsoft hosted email service, you may see the following issues:

# A screen that indicates admin approval is required for the app. This admin approval must be done, but only once. You must ask your admin to approve Thunderbird.  (Screenshot and instructions? Not sure how we’ll do this.)
# An account worked on Thunderbird 102.6.1, but does not work on 102.7.1 or later.
#*Attempt signing in on a new profile? If this works: deleting scopes/login details/etc should make the account work again. (need more details)
#*Otherwise, [https://support.mozilla.org/en-US/questions/new/thunderbird/form ask for support].
#IMAP/POP3 work, but SMTP does not work:
#*If you have an o365 ''''''business'''''' account, check that SMTP Auth is enabled or ask your admin to check. (instructions/screenshot)
#* If you have an o365/hotmail/etc ''''''personal'''''' account, use basic authentication. (guide on how to change this)
#Calendar does not work. 
#* Thunderbird does not support Exchange calendars. If you are using an add-on or other software to enable calendar, then you will need to seek support from the author of that add-on or software.

== Where to Get Help ==

If you are a user within a business or academic institution that provides Microsoft accounts, you should seek assitance within your organization.

If you have a personal account through one of Microsoft''s hosted services, [https://support.mozilla.org/en-US/questions/new/thunderbird/form ask for support].','<p>Microsoft has made some changes to authentication for their hosted email services for business and academic accounts. This topic describes these changes and how to adjust to them. As of the date of this article, February 3, 2023, this information is still evolving and subject to change.
</p>
<h2 id="w_changes-to-authentication">Changes to Authentication</h2>
<p>Microsoft has instututed the following changes&nbsp;:
</p>
<ul><li> Deprecating basic authentication (username/password), and is instead now requiring oAuth authentication.
</li><li> Disabling SMTP Auth entirely, in some cases. For new accounts, SMTP always starts disabled. In addition, there are some restrictions on SMTP that are not currently understood.
</li></ul>
<p>Microsoft have also changed the way they classify certain clients, and Thunderbird’s previous oAuth setup does not properly qualify as desktop client. As a result, we have been forced to make configuration changes to Thunderbird which may have side effects for users.
</p>
<h2 id="w_changes-or-problems-you-may-encounter">Changes or Problems You May Encounter</h2>
<p>If you are encountering problems with account setup to <a href="http://outlook.com">outlook.com</a>, <a href="http://hotmail.com">hotmail.com</a>, Office 365, or another Microsoft hosted email service, you may see the following issues:
</p>
<ol><li> A screen that indicates admin approval is required for the app. This admin approval must be done, but only once. You must ask your admin to approve Thunderbird.  (Screenshot and instructions? Not sure how we’ll do this.)
</li><li> An account worked on Thunderbird 102.6.1, but does not work on 102.7.1 or later.
<ul><li>Attempt signing in on a new profile? If this works: deleting scopes/login details/etc should make the account work again. (need more details)
</li><li>Otherwise, <a href="https://support.mozilla.org/en-US/questions/new/thunderbird/form">ask for support</a>.
</li></ul>
</li><li>IMAP/POP3 work, but SMTP does not work:
<ul><li>If you have an o365 <strong>business</strong> account, check that SMTP Auth is enabled or ask your admin to check. (instructions/screenshot)
</li><li> If you have an o365/hotmail/etc <strong>personal</strong> account, use basic authentication. (guide on how to change this)
</li></ul>
</li><li>Calendar does not work. 
<ul><li> Thunderbird does not support Exchange calendars. If you are using an add-on or other software to enable calendar, then you will need to seek support from the author of that add-on or software.
</li></ul>
</li></ol>
<h2 id="w_where-to-get-help">Where to Get Help</h2>
<p>If you are a user within a business or academic institution that provides Microsoft accounts, you should seek assitance within your organization.
</p><p>If you have a personal account through one of Microsoft''s hosted services, <a href="https://support.mozilla.org/en-US/questions/new/thunderbird/form">ask for support</a>.
</p>','[{"label": "Revision id", "text": "256630", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 2, 2023, 10:10:17 AM", "datetime": "2023-02-02T10:10:17-08:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "first draft, not ready for review", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:12:12+00:00','');
