</p>','[{"label": "Revision id", "text": "262874", "datetime": null, "href": null}, {"label": "Created", "text": "Jul 4, 2023, 8:51:48 AM", "datetime": "2023-07-04T08:51:48-07:00", "href": null}, {"label": "Creator", "text": "BD", "datetime": null, "href": "https://support.mozilla.org/en-US/user/bd./"}, {"label": "Comment", "text": "minor corrections", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 24, 2023, 2:29:28 AM", "datetime": "2023-09-24T02:29:28-07:00", "href": null}, {"label": "Reviewed by", "text": "AliceWyman", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:07:07+00:00','');
