INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (287187,'en-US','thunderbird-android-import','Import settings and data into Thunderbird for Android','https://support.mozilla.org/en-US/kb/thunderbird-android-import','https://support.mozilla.org/en-US/kb/thunderbird-android-import/revision/287187',286785,'2024-10-22T14:04:04.408669-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP: do not localize, needs content obviously (blocked on this feature being finished) - document what is not supported',1,'2024-10-22T14:04:33.061775-07:00','rtanglao',1,0,0,NULL,NULL,'approved','{warning}This feature is still being developed as part of Thunderbird for Android beta. [https://play.google.com/store/apps/details?id=net.thunderbird.android.beta Upgrade to the latest version of Thunderbird for Android beta] for the most up to date version.{/warning}

= How To Import from Thunderbird Desktop = 
== Export Thunderbird Desktop settings ==
# Click {button ≡} > {menu Tools} > {menu Export for Mobile}. 
# Tick the Email accounts you wish to export to Thunderbird for Android.
# If you have accounts that are not using OAuth and you wish to import your passwords, tick ''''''Include all accounts passwords'''''' under ''''''Security'''''' to export your passwords in the QR code.
# Click {button Export}. A QR code will be displayed. Follow the steps below on your Android phone or tablet to scan the QR code.
== Import the Desktop settings into Thunderbird for Android ==
# Open Thunderbird for Android on your phone or tablet.
## If you see a screen with two buttons: {button Start} and {button Import settings}, tap {button Import settings} > {button Scan QR code} and scan the QR code from Thunderbird Desktop.
## Otherwise, tap {button ≡} at the top left > tap the gear icon:{button [[Image:gear icon]]} at the bottom left > tap {button Import settings} > {button Scan QR code} and scan the QR code from Thunderbird Desktop.
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://en.wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
= Not seeing all your accounts? =
Some emails accounts may be disabled because they are not supported by Thunderbird for Android:
The following configurations are NOT supported (See [https://bugzilla.mozilla.org/show_bug.cgi?id=1919786 Bug 1919786] for full details):
* [https://wikipedia.org/wiki/Generic_Security_Services_Application_Program_Interface GSSAPI]
* [https://wikipedia.org/wiki/NTLM NTLM]
* ''''TlsCertificate'''' 
* ''''TryStartTls''''. See [https://bugzilla.mozilla.org/show_bug.cgi?id=1868517 Bug 1868517]
* More than one outgoing server is not supported
* Non-ASCII email addresses are not supported','<div class="warning">This feature is still being developed as part of Thunderbird for Android beta. <a href="https://play.google.com/store/apps/details?id=net.thunderbird.android.beta">Upgrade to the latest version of Thunderbird for Android beta</a> for the most up to date version.</div>
<h1 id="w_how-to-import-from-thunderbird-desktop">How To Import from Thunderbird Desktop</h1>
<h2 id="w_export-thunderbird-desktop-settings">Export Thunderbird Desktop settings</h2>
<ol><li> Click <span class="button">≡</span> &gt; <span class="menu">Tools</span> &gt; <span class="menu">Export for Mobile</span>. 
</li><li> Tick the Email accounts you wish to export to Thunderbird for Android.
</li><li> If you have accounts that are not using OAuth and you wish to import your passwords, tick <strong>Include all accounts passwords</strong> under <strong>Security</strong> to export your passwords in the QR code.
</li><li> Click <span class="button">Export</span>. A QR code will be displayed. Follow the steps below on your Android phone or tablet to scan the QR code.
</li></ol>
<h2 id="w_import-the-desktop-settings-into-thunderbird-for-android">Import the Desktop settings into Thunderbird for Android</h2>
<ol><li> Open Thunderbird for Android on your phone or tablet.
<ol><li> If you see a screen with two buttons: <span class="button">Start</span> and <span class="button">Import settings</span>, tap <span class="button">Import settings</span> &gt; <span class="button">Scan QR code</span> and scan the QR code from Thunderbird Desktop.
</li><li> Otherwise, tap <span class="button">≡</span> at the top left &gt; tap the gear icon:<span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> at the bottom left &gt; tap <span class="button">Import settings</span> &gt; <span class="button">Scan QR code</span> and scan the QR code from Thunderbird Desktop.
</li></ol>
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> If your account uses <a href="https://en.wikipedia.org/wiki/OAuth">OAuth</a> instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol>
<h1 id="w_not-seeing-all-your-accounts">Not seeing all your accounts?</h1>
<p>Some emails accounts may be disabled because they are not supported by Thunderbird for Android:
The following configurations are NOT supported (See <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=1919786">Bug 1919786</a> for full details):
</p>
<ul><li> <a href="https://wikipedia.org/wiki/Generic_Security_Services_Application_Program_Interface">GSSAPI</a>
</li><li> <a href="https://wikipedia.org/wiki/NTLM">NTLM</a>
</li><li> <em>TlsCertificate</em> 
</li><li> <em>TryStartTls</em>. See <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=1868517">Bug 1868517</a>
</li><li> More than one outgoing server is not supported
</li><li> Non-ASCII email addresses are not supported
</li></ul>','[{"label": "Revision id", "text": "287187", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 22, 2024, 2:04:04 PM", "datetime": "2024-10-22T14:04:04.408669-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not localize, needs content obviously (blocked on this feature being finished) - document what is not supported", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 22, 2024, 2:04:33 PM", "datetime": "2024-10-22T14:04:33.061775-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:32:28+00:00','M');
