</li><li> Non-ASCII email addresses are not supported.
</li></ul>','[{"label": "Revision id", "text": "287202", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 22, 2024, 5:03:40 PM", "datetime": "2024-10-22T17:03:40.158259-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not localize, needs content obviously (blocked on this feature being finished) see https://github.com/thunderbird/android-knowledgebase-issues/issues/5#issuecomment-2430532713", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 22, 2024, 5:06:07 PM", "datetime": "2024-10-22T17:06:07.327078-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:32:21+00:00','M');
