INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (287210,'en-US','thunderbird-android-import','Import settings and data into Thunderbird for Android','https://support.mozilla.org/en-US/kb/thunderbird-android-import','https://support.mozilla.org/en-US/kb/thunderbird-android-import/revision/287210',287209,'2024-10-22T17:41:11.895196-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP: do not localize, needs content obviously (blocked on this feature being finished); https://github.com/thunderbird/android-knowledgebase-issues/issues/5#issuecomment-2430532713',1,'2024-10-22T17:42:45.243334-07:00','rtanglao',1,0,0,NULL,NULL,'approved','{warning}This feature is still being developed as part of Thunderbird for Android and Thunderbird for Desktop. [https://play.google.com/store/apps/details?id=net.thunderbird.android.beta Upgrade to the latest version of Thunderbird for Android beta] for the latest version on Android.{/warning}

__TOC__

= How To Import from Thunderbird Desktop = 
{warning}''''Export for Mobile'''' is available starting with Thunderbird Desktop 128.3.4 or Thunderbird beta 132 or newer. It is not available in older versions of Thunderbird.{/warning}
== Export Thunderbird Desktop settings ==
# Click {button ≡} > {menu Tools} > {menu Export for Mobile}. 
# Tick the Email accounts you wish to export to Thunderbird for Android.
# If you have accounts that are not using OAuth and you wish to import your passwords, tick ''''''Include all accounts passwords'''''' under ''''''Security'''''' to export your passwords in the QR code.
# Click {button Export}. A QR code will be displayed. Follow the steps below on your Android phone or tablet to scan the Thunderbird Desktop settings QR code. If you have many email accounts, multiple QR codes will be displayed when you scan from your Android device in the next step.
== Import the Desktop settings into Thunderbird for Android ==
Open Thunderbird for Android on your phone or tablet:
# Tap {button ≡} at the top left > tap the gear icon:{button [[Image:gear icon]]} at the bottom left.
# Tap {button Import settings} > {button Scan QR code} and scan the QR code from Thunderbird Desktop. Thunderbird for Android will display a confirmation message in the bottom left. If you have many email accounts, after scanning the first QR code, another code will be displayed and scanned until all account settings have been setup.
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://en.wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.

= How To Import from K-9 or other Thunderbird for Android apps = 
Open Thunderbird for Android on your phone or tablet:
# Tap {button ≡} at the top left > tap the ''''gear'''' icon:{button [[Image:gear icon]]} at the bottom left.
# Tap {button Import settings} > tap {button Import from app}.
# Tap the email app you wish to import your email account settins from e.g. ''''''K-9 Mail'''''' (or Thunderbird for Android).
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://en.wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.

= Not seeing all your accounts? =
Some emails accounts may be disabled because they are not supported by Thunderbird for Android:
The following configurations are NOT supported (See [https://bugzilla.mozilla.org/show_bug.cgi?id=1919786 Bug 1919786] for full details):
* [https://wikipedia.org/wiki/Generic_Security_Services_Application_Program_Interface GSSAPI]
* [https://wikipedia.org/wiki/NTLM NTLM]
* ''''TlsCertificate'''' 
* ''''TryStartTls''''. See [https://bugzilla.mozilla.org/show_bug.cgi?id=1868517 Bug 1868517]
* More than one outgoing server is not supported.
* Non-ASCII email addresses are not supported.','<div class="warning">This feature is still being developed as part of Thunderbird for Android and Thunderbird for Desktop. <a href="https://play.google.com/store/apps/details?id=net.thunderbird.android.beta">Upgrade to the latest version of Thunderbird for Android beta</a> for the latest version on Android.</div>
