</li></ul>','[{"label": "Revision id", "text": "287328", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 23, 2024, 10:06:19 PM", "datetime": "2024-10-23T22:06:19.894124-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not localize, needs content obviously (blocked on this feature being finished); https://github.com/thunderbird/android-knowledgebase-issues/issues/5#issuecomment-2434198879", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 23, 2024, 10:06:49 PM", "datetime": "2024-10-23T22:06:49.993617-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:31:59+00:00','M');
