INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (302794,'en-US','thunderbird-and-exchange','Thunderbird and Microsoft protocols (Exchange and Graph)','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange/revision/302794',NULL,'2025-08-19T21:07:12.474869-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP: do not approve or translate. Discussion in github please: https://github.com/thunderbird/knowledgebase-issues/issues/85',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','{warning}Warning: The current built-in code for Exchange in Thunderbird is limited to email. Other features (calendar, address book) are planned to follow, but are not available yet. We recommend using Thunderbird 142 or newer for for a more polished, stable experience, Please refer to our [https://wiki.mozilla.org/Thunderbird:Exchange Thunderbird:Exchange wiki page for full details.{/warning}
==Configure your Exchange account==
===Thunderbird profiles with 1 or more accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with one or more accounts, you will see the new Thunderbird ''''''Account Hub'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} > 
# Follow the flow by entering your name, email address, and your OAuth code. Note: you don''t need to enter your password in the first dialogue.
# Click the {button Exchange} button (not the one labelled {button Exchange  REQUIRES ADD-ON}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange code. 
#;[[Image:tb142-beta-exchange-support-button]] 
[[UI:details_start]]
===Thunderbird profile with no accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with zero accounts, you will see the older, ''''''Set Up Your Existing Email Address'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} > 
# Follow the flow by entering your name, email address, and your OAuth code. Note: you don''t need to enter your password
[[UI:details_end]]','<div class="warning">Warning: The current built-in code for Exchange in Thunderbird is limited to email. Other features (calendar, address book) are planned to follow, but are not available yet. We recommend using Thunderbird 142 or newer for for a more polished, stable experience, Please refer to our [<a href="https://wiki.mozilla.org/Thunderbird:Exchange">https://wiki.mozilla.org/Thunderbird:Exchange</a> Thunderbird:Exchange wiki page for full details.</div>
<h2 id="w_configure-your-exchange-account">Configure your Exchange account</h2>
<h3 id="w_thunderbird-profiles-with-1-or-more-accounts">Thunderbird profiles with 1 or more accounts</h3>
<p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with one or more accounts, you will see the new Thunderbird <strong>Account Hub</strong> flow:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> &gt; 
</li><li> Follow the flow by entering your name, email address, and your OAuth code. Note: you don''t need to enter your password in the first dialogue.
</li><li> Click the <span class="button">Exchange</span> button (not the one labelled <span class="button">Exchange  REQUIRES ADD-ON</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange code. 
<dl><dt><img alt="tb142-beta-exchange-support-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-03-20-2802fd.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li></ol>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h3 id="w_thunderbird-profile-with-no-accounts" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Thunderbird profile with no accounts</button></h3><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true"><p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with zero accounts, you will see the older, <strong>Set Up Your Existing Email Address</strong> flow:
</p><ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> &gt; 
</li><li> Follow the flow by entering your name, email address, and your OAuth code. Note: you don''t need to enter your password
</li></ol><p></p></div>


</section>
