INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (306296,'en-US','thunderbird-android-import','Import settings and data into Thunderbird for Android','https://support.mozilla.org/en-US/kb/thunderbird-android-import','https://support.mozilla.org/en-US/kb/thunderbird-android-import/revision/306296',295345,'2025-09-25T10:28:39.549542-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','feature is no longer in development. Discussion please: https://github.com/thunderbird/android-knowledgebase-issues/issues/24',1,'2025-09-25T10:29:17.402781-07:00','rtanglao',1,0,0,NULL,NULL,'approved','{warning}
The transfer process supports account settings and account passwords. Emails and other data are not transferred.
{/warning}

__TOC__

= How To Import from Thunderbird Desktop =
{warning}''''Export for Mobile'''' is available starting with Thunderbird Desktop 128.4.0 or Thunderbird beta 132 or newer. It is not available in older versions of Thunderbird.{/warning}

== Export Thunderbird Desktop settings ==
# Open Thunderbird Desktop and click {button ≡} > {menu Tools} > {menu Export for Mobile}.
# Tick the Email accounts you wish to export to Thunderbird for Android.
#;[[Image:Thunderbird 128 Export accounts to Thunderbird Mobile]]
# If you have accounts that are not using [https://wikipedia.org/wiki/OAuth OAuth] and you wish to export your passwords, you will see a ''''''Security'''''' section. Tick ''''''Include all accounts passwords'''''' under ''''''Security'''''' to export your passwords in the QR code.
# Click {button Export}. (You may be prompted for a PIN number. For Windows, that would be the Windows signin password.) A QR code will be displayed. Follow the steps below on your Android phone or tablet to scan the Thunderbird Desktop settings QR code. If you have many email accounts, multiple QR codes will be displayed when you scan from your Android device in the next step.
#;[[Image:tb-128-qr-code]]

== Import the Desktop settings into Thunderbird for Android ==
Open Thunderbird for Android on your phone or tablet and follow the steps below.

=== First run ===
After you install Thunderbird for Android and run it for the first time, here''s how to import settings from Desktop:
# Tap {button Get started} on the initial screen.
# Tap {button Import settings}. Thunderbird for Android will start the camera and display ''''Align the QR code provided from Thunderbird Desktop''''. Scan the QR code from Thunderbird Desktop.
#* If you have many email accounts, you will scan multiple QR codes, but only one QR code is displayed at a time by Thunderbird Desktop. After scanning the first QR code, Thunderbird for Android will display a confirmation of the form: ''''Scanned X of Y'''' where ''''X'''' is the count of QR codes you have scanned so far out of a total of ''''Y'''' QR codes (for example ''''Scanned 1 of 2''''). In Thunderbird Desktop, click {button Next} to manually advance to the next QR code to be scanned. Repeat until all QR codes have been scanned.
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.

[[UI:details_start]]
=== Subsequent runs ===
Once you have set up an email account, the next time you import email settings, the process will be slightly different:
# Tap {button ≡} at the top left > tap the gear icon: {button [[Image:gear icon]]} at the bottom left.
# Tap {button Import settings} > {button Scan QR code}. Scan the QR code from Thunderbird Desktop. If you have many email accounts, after scanning the first QR code, another code will be displayed and scanned until all account settings have been set up.
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
[[UI:details_end]]

= How To Import from K-9 or other Thunderbird for Android apps =
{warning}Importing from K-9 Mail requires K-9 Mail 8.0 or later.{/warning}
Open Thunderbird for Android on your phone or tablet and follow the steps below.

== First run ==
After you install Thunderbird for Android and run it for the first time, here''s how to import settings from ''''''K-9'''''' or Thunderbird from Android:
# Tap {button Get started} on the initial screen.
# Tap {button Import your account settings now} > tap {button Import from app}.
# Tap the email app you wish to import your email account settings from (either ''''''K-9 Mail'''''' or another release of Thunderbird for Android, for example Beta).
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.

[[UI:details_start]]
== Subsequent runs ==
Once you have set up an email account, the next time you import email settings, the process will be slightly different:
# Tap {button ≡} at the top left > tap the ''''gear'''' icon: {button [[Image:gear icon]]} at the bottom left.
# Tap {button Import settings} > tap {button Import from app}.
# Tap the email app you wish to import your email account settings from (either ''''''K-9 Mail'''''' or another release of Thunderbird for Android, for example Beta).
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# If your account uses [https://wikipedia.org/wiki/OAuth OAuth] instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
[[UI:details_end]]

[[UI:details_start]]
= How To Import email account settings using a settings file from Thunderbird or K-9 =
{warning} It is not possible to import a settings file from apps other than Thunderbird for Android or ''''K-9''''.{/warning}

== 1. Export Thunderbird or K-9 settings to a file ==
Open the app, K-9 or Thunderbird for Android, whose settings you wish to export.
# Tap {button ≡} at the top left > tap the ''''gear'''' icon: {button [[Image:gear icon]]} at the bottom left.
# Tap {button Export settings}.
# Tick the Email accounts you wish to export to Thunderbird for Android.
# Tap {button Export}.
# Change the directory and the filename as you see fit and tap {button Save}. Take note of the filename and directory, for example a directory in ''''Google Drive'''', the ''''''Downloads'''''' directory, etc. You will need the filename and directory in order to import the settings in ''''Step 2''''.

== 2. Import the exported settings file into Thunderbird for Android ==
Open Thunderbird for Android on your phone or tablet and follow the steps below.

=== First run ===
Here''s how to import settings from the file you created in ''''Step 1'''':
# Tap {button Get started} on the initial screen.
# Tap {button Import your account settings now} > {button Select file}. Select the file you saved from ''''Step 1.''''
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# You will be prompted for your passwords. Follow the prompts to complete your import.

=== Subsequent runs ===
Once you have set up an email account, the next time you import email settings, the process will be slightly different:
# Tap {button ≡} at the top left > tap the ''''gear'''' icon: {button [[Image:gear icon]]} at the bottom left.
# Tap {button Import settings} > tap {button Select file}. Select the file you saved from the ''''Step 1.''''
# Ensure the email accounts you want to import are all ticked. Tap {button Import}.
# You will be prompted for your passwords. Follow the prompts to complete your import.
[[UI:details_end]]

= Not seeing all your email accounts? =
You will not be able to import some email accounts because they are configured in a way that is not supported by Thunderbird for Android.

== Not supported ==
Email accounts with the following configurations are NOT supported (see [https://bugzilla.mozilla.org/show_bug.cgi?id=1919786 Bug 1919786] for full details):
* [https://wikipedia.org/wiki/Generic_Security_Services_Application_Program_Interface GSSAPI].
* [https://wikipedia.org/wiki/NTLM NTLM].
* ''''TlsCertificate''''.
* ''''TryStartTls''''. See [https://bugzilla.mozilla.org/show_bug.cgi?id=1868517 Bug 1868517].
* Non-ASCII email addresses are not supported.
* Non SMTP outgoing servers are not supported.

== Multiple outgoing servers are not exported ==
* Only the SMTP server for the default identity is exported for those email accounts with multiple outgoing servers.','<div class="warning">
<p>The transfer process supports account settings and account passwords. Emails and other data are not transferred.
</p>
</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_how-to-import-from-thunderbird-desktop"><span class="tocnumber">1</span> <span class="toctext">How To Import from Thunderbird Desktop</span></a><ul><li class="toclevel-2"><a href="#w_export-thunderbird-desktop-settings"><span class="tocnumber">1.1</span> <span class="toctext">Export Thunderbird Desktop settings</span></a></li><li class="toclevel-2"><a href="#w_import-the-desktop-settings-into-thunderbird-for-android"><span class="tocnumber">1.2</span> <span class="toctext">Import the Desktop settings into Thunderbird for Android</span></a><ul><li class="toclevel-3"><a href="#w_first-run"><span class="tocnumber">1.2.1</span> <span class="toctext">First run</span></a></li><li class="toclevel-3"><a href="#w_subsequent-runs"><span class="tocnumber">1.2.2</span> <span class="toctext">Subsequent runs</span></a></li></ul></li></ul></li><li class="toclevel-1"><a href="#w_how-to-import-from-k-9-or-other-thunderbird-for-android-apps"><span class="tocnumber">2</span> <span class="toctext">How To Import from K-9 or other Thunderbird for Android apps</span></a><ul><li class="toclevel-2"><a href="#w_first-run_2"><span class="tocnumber">2.1</span> <span class="toctext">First run</span></a></li><li class="toclevel-2"><a href="#w_subsequent-runs_2"><span class="tocnumber">2.2</span> <span class="toctext">Subsequent runs</span></a></li></ul></li><li class="toclevel-1"><a href="#w_how-to-import-email-account-settings-using-a-settings-file-from-thunderbird-or-k-9"><span class="tocnumber">3</span> <span class="toctext">How To Import email account settings using a settings file from Thunderbird or K-9</span></a><ul><li class="toclevel-2"><a href="#w_1-export-thunderbird-or-k-9-settings-to-a-file"><span class="tocnumber">3.1</span> <span class="toctext">1. Export Thunderbird or K-9 settings to a file</span></a></li><li class="toclevel-2"><a href="#w_2-import-the-exported-settings-file-into-thunderbird-for-android"><span class="tocnumber">3.2</span> <span class="toctext">2. Import the exported settings file into Thunderbird for Android</span></a><ul><li class="toclevel-3"><a href="#w_first-run_3"><span class="tocnumber">3.2.1</span> <span class="toctext">First run</span></a></li><li class="toclevel-3"><a href="#w_subsequent-runs_3"><span class="tocnumber">3.2.2</span> <span class="toctext">Subsequent runs</span></a></li></ul></li></ul></li><li class="toclevel-1"><a href="#w_not-seeing-all-your-email-accounts"><span class="tocnumber">4</span> <span class="toctext">Not seeing all your email accounts?</span></a><ul><li class="toclevel-2"><a href="#w_not-supported"><span class="tocnumber">4.1</span> <span class="toctext">Not supported</span></a></li><li class="toclevel-2"><a href="#w_multiple-outgoing-servers-are-not-exported"><span class="tocnumber">4.2</span> <span class="toctext">Multiple outgoing servers are not exported</span></a></li></ul></li></ul></div>
<h1 id="w_how-to-import-from-thunderbird-desktop">How To Import from Thunderbird Desktop</h1>
<div class="warning"><em>Export for Mobile</em> is available starting with Thunderbird Desktop 128.4.0 or Thunderbird beta 132 or newer. It is not available in older versions of Thunderbird.</div>
<h2 id="w_export-thunderbird-desktop-settings">Export Thunderbird Desktop settings</h2>
<ol><li> Open Thunderbird Desktop and click <span class="button">≡</span> &gt; <span class="menu">Tools</span> &gt; <span class="menu">Export for Mobile</span>.
</li><li> Tick the Email accounts you wish to export to Thunderbird for Android.
<dl><dt><img alt="Thunderbird 128 Export accounts to Thunderbird Mobile" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2024-10-22-21-02-15-d056ee.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li><li> If you have accounts that are not using <a href="https://wikipedia.org/wiki/OAuth">OAuth</a> and you wish to export your passwords, you will see a <strong>Security</strong> section. Tick <strong>Include all accounts passwords</strong> under <strong>Security</strong> to export your passwords in the QR code.
</li><li> Click <span class="button">Export</span>. (You may be prompted for a PIN number. For Windows, that would be the Windows signin password.) A QR code will be displayed. Follow the steps below on your Android phone or tablet to scan the Thunderbird Desktop settings QR code. If you have many email accounts, multiple QR codes will be displayed when you scan from your Android device in the next step.
<dl><dt><img alt="tb-128-qr-code" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2024-10-23-21-48-15-38e86e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
</li></ol>
<h2 id="w_import-the-desktop-settings-into-thunderbird-for-android">Import the Desktop settings into Thunderbird for Android</h2>
<p>Open Thunderbird for Android on your phone or tablet and follow the steps below.
</p>
<h3 id="w_first-run">First run</h3>
<p>After you install Thunderbird for Android and run it for the first time, here''s how to import settings from Desktop:
</p>
<ol><li> Tap <span class="button">Get started</span> on the initial screen.
</li><li> Tap <span class="button">Import settings</span>. Thunderbird for Android will start the camera and display <em>Align the QR code provided from Thunderbird Desktop</em>. Scan the QR code from Thunderbird Desktop.
<ul><li> If you have many email accounts, you will scan multiple QR codes, but only one QR code is displayed at a time by Thunderbird Desktop. After scanning the first QR code, Thunderbird for Android will display a confirmation of the form: <em>Scanned X of Y</em> where <em>X</em> is the count of QR codes you have scanned so far out of a total of <em>Y</em> QR codes (for example <em>Scanned 1 of 2</em>). In Thunderbird Desktop, click <span class="button">Next</span> to manually advance to the next QR code to be scanned. Repeat until all QR codes have been scanned.
</li></ul>
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> If your account uses <a href="https://wikipedia.org/wiki/OAuth">OAuth</a> instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h3 id="w_subsequent-runs" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-3" aria-expanded="false">Subsequent runs</button></h3><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-3" aria-hidden="true"><p>Once you have set up an email account, the next time you import email settings, the process will be slightly different:
</p><ol><li> Tap <span class="button">≡</span> at the top left &gt; tap the gear icon: <span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> at the bottom left.
</li><li> Tap <span class="button">Import settings</span> &gt; <span class="button">Scan QR code</span>. Scan the QR code from Thunderbird Desktop. If you have many email accounts, after scanning the first QR code, another code will be displayed and scanned until all account settings have been set up.
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> If your account uses <a href="https://wikipedia.org/wiki/OAuth">OAuth</a> instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol><p></p></div>


</section>
<p></p>
<h1 id="w_how-to-import-from-k-9-or-other-thunderbird-for-android-apps">How To Import from K-9 or other Thunderbird for Android apps</h1>
<div class="warning">Importing from K-9 Mail requires K-9 Mail 8.0 or later.</div>
<p>Open Thunderbird for Android on your phone or tablet and follow the steps below.
</p>
<h2 id="w_first-run_2">First run</h2>
<p>After you install Thunderbird for Android and run it for the first time, here''s how to import settings from <strong>K-9</strong> or Thunderbird from Android:
</p>
<ol><li> Tap <span class="button">Get started</span> on the initial screen.
</li><li> Tap <span class="button">Import your account settings now</span> &gt; tap <span class="button">Import from app</span>.
</li><li> Tap the email app you wish to import your email account settings from (either <strong>K-9 Mail</strong> or another release of Thunderbird for Android, for example Beta).
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> If your account uses <a href="https://wikipedia.org/wiki/OAuth">OAuth</a> instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h2 id="w_subsequent-runs_2" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Subsequent runs</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true"><p>Once you have set up an email account, the next time you import email settings, the process will be slightly different:
</p><ol><li> Tap <span class="button">≡</span> at the top left &gt; tap the <em>gear</em> icon: <span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> at the bottom left.
</li><li> Tap <span class="button">Import settings</span> &gt; tap <span class="button">Import from app</span>.
</li><li> Tap the email app you wish to import your email account settings from (either <strong>K-9 Mail</strong> or another release of Thunderbird for Android, for example Beta).
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> If your account uses <a href="https://wikipedia.org/wiki/OAuth">OAuth</a> instead of password authentication or you have chosen not to import your passwords, you will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol><p></p></div>


</section>
<p></p><p></p><section class="mzp-c-details is-details">
<p></p>
<h1 id="w_how-to-import-email-account-settings-using-a-settings-file-from-thunderbird-or-k-9">How To Import email account settings using a settings file from Thunderbird or K-9</h1>
<div class="warning"> It is not possible to import a settings file from apps other than Thunderbird for Android or <em>K-9</em>.</div>
<h2 id="w_1-export-thunderbird-or-k-9-settings-to-a-file" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-1" aria-expanded="false">1. Export Thunderbird or K-9 settings to a file</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-1" aria-hidden="true"><p>Open the app, K-9 or Thunderbird for Android, whose settings you wish to export.
</p><ol><li> Tap <span class="button">≡</span> at the top left &gt; tap the <em>gear</em> icon: <span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> at the bottom left.
</li><li> Tap <span class="button">Export settings</span>.
</li><li> Tick the Email accounts you wish to export to Thunderbird for Android.
</li><li> Tap <span class="button">Export</span>.
</li><li> Change the directory and the filename as you see fit and tap <span class="button">Save</span>. Take note of the filename and directory, for example a directory in <em>Google Drive</em>, the <strong>Downloads</strong> directory, etc. You will need the filename and directory in order to import the settings in <em>Step 2</em>.
</li></ol></div>


<h2 id="w_2-import-the-exported-settings-file-into-thunderbird-for-android" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-2" aria-expanded="false">2. Import the exported settings file into Thunderbird for Android</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-2" aria-hidden="true"><p>Open Thunderbird for Android on your phone or tablet and follow the steps below.
</p><h3 id="w_first-run_3">First run</h3><p>Here''s how to import settings from the file you created in <em>Step 1</em>:
</p><ol><li> Tap <span class="button">Get started</span> on the initial screen.
</li><li> Tap <span class="button">Import your account settings now</span> &gt; <span class="button">Select file</span>. Select the file you saved from <em>Step 1.</em>
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> You will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol><h3 id="w_subsequent-runs_3">Subsequent runs</h3><p>Once you have set up an email account, the next time you import email settings, the process will be slightly different:
</p><ol><li> Tap <span class="button">≡</span> at the top left &gt; tap the <em>gear</em> icon: <span class="button"><img alt="gear icon" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2014-06-13-01-42-16-c1469d.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""></span> at the bottom left.
</li><li> Tap <span class="button">Import settings</span> &gt; tap <span class="button">Select file</span>. Select the file you saved from the <em>Step 1.</em>
</li><li> Ensure the email accounts you want to import are all ticked. Tap <span class="button">Import</span>.
</li><li> You will be prompted for your passwords. Follow the prompts to complete your import.
</li></ol><p></p></div>







</section>
<p></p>
<h1 id="w_not-seeing-all-your-email-accounts">Not seeing all your email accounts?</h1>
<p>You will not be able to import some email accounts because they are configured in a way that is not supported by Thunderbird for Android.
</p>
<h2 id="w_not-supported">Not supported</h2>
<p>Email accounts with the following configurations are NOT supported (see <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=1919786">Bug 1919786</a> for full details):
</p>
<ul><li> <a href="https://wikipedia.org/wiki/Generic_Security_Services_Application_Program_Interface">GSSAPI</a>.
</li><li> <a href="https://wikipedia.org/wiki/NTLM">NTLM</a>.
</li><li> <em>TlsCertificate</em>.
</li><li> <em>TryStartTls</em>. See <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=1868517">Bug 1868517</a>.
</li><li> Non-ASCII email addresses are not supported.
</li><li> Non SMTP outgoing servers are not supported.
</li></ul>
<h2 id="w_multiple-outgoing-servers-are-not-exported">Multiple outgoing servers are not exported</h2>
<ul><li> Only the SMTP server for the default identity is exported for those email accounts with multiple outgoing servers.
</li></ul>','[{"label": "Revision id", "text": "306296", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 25, 2025, 10:28:39 AM", "datetime": "2025-09-25T10:28:39.549542-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "feature is no longer in development. Discussion please: https://github.com/thunderbird/android-knowledgebase-issues/issues/24", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Sep 25, 2025, 10:29:17 AM", "datetime": "2025-09-25T10:29:17.402781-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:25:53+00:00','M');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (306945,'en-US','filelink-large-attachments','Filelink for Large Attachments','https://support.mozilla.org/en-US/kb/filelink-large-attachments','https://support.mozilla.org/en-US/kb/filelink-large-attachments/revision/306945',306021,'2025-09-29T20:35:12.038882-07:00','Kiki','https://support.mozilla.org/en-US/user/kelimuttu/','Bye Zap',1,'2025-10-23T22:42:39.164569-07:00','kelimuttu',1,0,0,NULL,NULL,'approved','With Thunderbird''s FileLink feature, you can upload large attachments to the cloud and send a link instead of attaching them directly to your email message. This feature is provided by [https://addons.thunderbird.net/thunderbird/tag/filelink Filelink provider add-ons].

__TOC__

= Thunderbird''s Filelink feature =

Many email servers do not accept messages with large file attachments. The file size restriction varies depending on the mail server configuration. While you might be able to send a message with a large attachment, the receiving mail server might refuse to accept a message with a large attachment. This is all beyond the control of Thunderbird.

Thunderbird’s Filelink feature eliminates this problem by providing support for online storage services. It allows you to upload attachments to an online storage service, and then replaces the attachment in the message with a link to that online storage. The message recipient clicks the link to download the attachment. As additional benefits, sending and receiving large files is much faster and both you and the recipient will save disk space.

Note that you can use Thunderbird Filelink in addition to [[How to Use Attachments|regular attachments]]. For example, you can attach small files directly to a message and use Filelink for large attachments in the same message.

The Thunderbird community has made available a number of [https://addons.thunderbird.net/thunderbird/tag/filelink Filelink provider add-ons] for various providers ([[#w_what-storage-services-are-currently-supported|more details below]]).

{note}''''''Note:'''''' The previously inbuilt support for the ''''WeTransfer'''' FileLink provider has been removed.{/note}

= Adding Filelink =

To use this feature, you need to install one of the [https://addons.thunderbird.net/thunderbird/tag/filelink Filelink provider add-ons] first, as described below. For some online storage service providers, you may have to first create a new account or configure an existing account with them.

* Click {button ≡} > {menu Settings} > {menu Composition} > {menu Attachments} > {menu Find more providers...}
* Choose a Filelink Provider add-on, and click {button ＋ Add to Thunderbird}.
* Confirm add-on permissions from the popup panel with {button Add}.
* In the {menu Attachments} section of the ''''Settings'''' (see above), click on the button {button Add [Your Filelink provider]}.
* Add information as requested by the addon.
* Thunderbird will suggest using Filelink for attachments larger than 5 MB (you can change the threshold in the same section), or you can right-click on a regular attachment to convert it.

{note}
* If you want to be prompted to use Filelink when a message attachment exceeds a certain size, tick the following option:
''''''[✓] Offer to share for files larger than [5] MB''''''
* You may also change the threshold file size as required.{/note}

= Using Filelink =

When you attach a file to a message, and the file size exceeds the size you have specified above, Thunderbird will automatically offer to use Filelink:

[[Image:Proton-FileLink-LargeFileNotification]]

* Click the {button Link} button to upload the file to the online storage service provider.
* If you prefer to attach the file as a [[How to Use Attachments|regular attachment]], choose {button Ignore}.

After choosing {button Link}, your file will be uploaded in the background and the displayed message will update to:

[[Image:Proton-FileLink-UploadingFileNotification]]

{note} Regardless of the file size and the Filelink notification, you can always force a file to be attached using Filelink:
* Choose the down arrow of the {button Attach | v} button on the composition toolbar to access the {menu Filelink} submenu.
* Right-click on a regular attachment and from the context menu, choose {menu Convert to...} > {menu [Your FileLink provider]}. You can choose from a list of your enabled providers.{/note}

When the linking is complete – that is, your attachment has been uploaded to the service provider – Thunderbird will automatically add a section in the message with a link to the online copy of your file  as shown below:

[[Image:TB78-filelink-linked-anonymous]]

{note}''''''Note:'''''' The link section will appear in plain text, if ''''''Compose messages in HTML format'''''' is turned off in Account Settings.{/note}

When your recipients receive the message, they will see the same information and clicking the link in the message will take them to a page where they can download the attachment.

----

= Filelink FAQ =

Attachments that you send via Filelink are not stored on Thunderbird servers. Each file storage service provider has its own privacy policy and terms of service. The file storage service provider has reviewed the Filelink feature to ensure that it is consistent with their policies.

== Does Thunderbird know which provider the user has picked? ==

No. Thunderbird is unaware of which provider has been selected by a user. Provider configuration is stored on the local machine.

== What storage services are currently supported? ==

* A number of popular file storage providers are supported through [https://addons.thunderbird.net/thunderbird/tag/filelink Filelink provider add-ons].
* You can also use Filelink with your preferred WebDAV server with the [https://addons.thunderbird.net/thunderbird/addon/filelink-provider-for-webdav/ Filelink provider for WebDAV] add-on.
<!-- [https://addons.thunderbird.net/thunderbird/addon/dl-for-thunderbird DL for Thunderbird] may be the best if you prefer using your own server instead of relying on third-party providers.-->

== Can the storage service view my attachments? ==

Unless you encrypt the file before uploading, the storage services will be able to view the file, as will anyone who obtains the link to the attachment. Users must decide on their own which service provider they trust with that responsibility. Service providers will generally explain your privacy rights in their terms of service. 

Note that standard attachment functionality is also not encrypted. When you send an attachment the "normal" way, without using Thunderbird’s OpenPGP or SMIME features, the file can be accessed by anyone that can access the message between your system and the recipients system (such as your email service provider). Filelink adds some security as file uploads to the storage service provider are sent via HTTPS, a secure protocol. We recommend using Thunderbird''s OpenPGP or SMIME features for maximum security of your communications.

== How long will my file be available on the storage service provider''s site? ==

Depending on the terms and conditions of your third-party storage service provider and your service agreement with them, the file may remain available on the provider’s site for a limited period, a certain number of downloads, or until you explicitly delete it. You will need to log in to the provider’s website to view and delete the files in your personal storage space.

== Can you support service provider X or protocol Y? ==

Please check if the Thunderbird community has provided a [https://addons.thunderbird.net/thunderbird/tag/filelink Filelink provider add-on] for the service provider you are looking for.
[https://webextension-api.thunderbird.net/en/stable/cloudFile.html Developer documentation for the Filelink API] is available.

== I don''t like the idea of storing my files with third-parties like this. Do regular attachments still work? ==

Regular email attachments still work the same as they always have. We are just offering you an option to upload large attachments somewhere else if you wish. Thunderbird''s notion of a large file defaults to 5 MB, but can be customized in Thunderbird’s Settings:
# Click {button ≡} > {menu Settings} > {menu Composition} > {menu Attachments}
# ''''''[✓] Offer to share for files larger than [5] MB''''''
Removing the checkmark will prevent the automatical Filelink notification when you attach big files, but the Filelink feature will still be available from the {button Attach | v} button dropdown as well as other attachment menus and context menus.','<p>With Thunderbird''s FileLink feature, you can upload large attachments to the cloud and send a link instead of attaching them directly to your email message. This feature is provided by <a href="https://addons.thunderbird.net/thunderbird/tag/filelink">Filelink provider add-ons</a>.
</p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_thunderbirds-filelink-feature"><span class="tocnumber">1</span> <span class="toctext">Thunderbird''s Filelink feature</span></a></li><li class="toclevel-1"><a href="#w_adding-filelink"><span class="tocnumber">2</span> <span class="toctext">Adding Filelink</span></a></li><li class="toclevel-1"><a href="#w_using-filelink"><span class="tocnumber">3</span> <span class="toctext">Using Filelink</span></a></li><li class="toclevel-1"><a href="#w_filelink-faq"><span class="tocnumber">4</span> <span class="toctext">Filelink FAQ</span></a><ul><li class="toclevel-2"><a href="#w_does-thunderbird-know-which-provider-the-user-has-picked"><span class="tocnumber">4.1</span> <span class="toctext">Does Thunderbird know which provider the user has picked?</span></a></li><li class="toclevel-2"><a href="#w_what-storage-services-are-currently-supported"><span class="tocnumber">4.2</span> <span class="toctext">What storage services are currently supported?</span></a></li><li class="toclevel-2"><a href="#w_can-the-storage-service-view-my-attachments"><span class="tocnumber">4.3</span> <span class="toctext">Can the storage service view my attachments?</span></a></li><li class="toclevel-2"><a href="#w_how-long-will-my-file-be-available-on-the-storage-service-providers-site"><span class="tocnumber">4.4</span> <span class="toctext">How long will my file be available on the storage service provider''s site?</span></a></li><li class="toclevel-2"><a href="#w_can-you-support-service-provider-x-or-protocol-y"><span class="tocnumber">4.5</span> <span class="toctext">Can you support service provider X or protocol Y?</span></a></li><li class="toclevel-2"><a href="#w_i-dont-like-the-idea-of-storing-my-files-with-third-parties-like-this-do-regular-attachments-still-work"><span class="tocnumber">4.6</span> <span class="toctext">I don''t like the idea of storing my files with third-parties like this. Do regular attachments still work?</span></a></li></ul></li></ul></div>
<h1 id="w_thunderbirds-filelink-feature">Thunderbird''s Filelink feature</h1>
<p>Many email servers do not accept messages with large file attachments. The file size restriction varies depending on the mail server configuration. While you might be able to send a message with a large attachment, the receiving mail server might refuse to accept a message with a large attachment. This is all beyond the control of Thunderbird.
</p><p>Thunderbird’s Filelink feature eliminates this problem by providing support for online storage services. It allows you to upload attachments to an online storage service, and then replaces the attachment in the message with a link to that online storage. The message recipient clicks the link to download the attachment. As additional benefits, sending and receiving large files is much faster and both you and the recipient will save disk space.
</p><p>Note that you can use Thunderbird Filelink in addition to <a href="/en-US/kb/how-use-attachments">regular attachments</a>. For example, you can attach small files directly to a message and use Filelink for large attachments in the same message.
</p><p>The Thunderbird community has made available a number of <a href="https://addons.thunderbird.net/thunderbird/tag/filelink">Filelink provider add-ons</a> for various providers (<a href="#w_what-storage-services-are-currently-supported">more details below</a>).
</p>
<div class="note"><strong>Note:</strong> The previously inbuilt support for the <em>WeTransfer</em> FileLink provider has been removed.</div>
<h1 id="w_adding-filelink">Adding Filelink</h1>
<p>To use this feature, you need to install one of the <a href="https://addons.thunderbird.net/thunderbird/tag/filelink">Filelink provider add-ons</a> first, as described below. For some online storage service providers, you may have to first create a new account or configure an existing account with them.
</p>
<ul><li> Click <span class="button">≡</span> &gt; <span class="menu">Settings</span> &gt; <span class="menu">Composition</span> &gt; <span class="menu">Attachments</span> &gt; <span class="menu">Find more providers...</span>
</li><li> Choose a Filelink Provider add-on, and click <span class="button">＋ Add to Thunderbird</span>.
</li><li> Confirm add-on permissions from the popup panel with <span class="button">Add</span>.
</li><li> In the <span class="menu">Attachments</span> section of the <em>Settings</em> (see above), click on the button <span class="button">Add [Your Filelink provider]</span>.
</li><li> Add information as requested by the addon.
</li><li> Thunderbird will suggest using Filelink for attachments larger than 5 MB (you can change the threshold in the same section), or you can right-click on a regular attachment to convert it.
</li></ul>
<div class="note">
<ul><li> If you want to be prompted to use Filelink when a message attachment exceeds a certain size, tick the following option:
</li></ul>
<p><strong>[✓] Offer to share for files larger than [5] MB</strong>
</p>
<ul><li> You may also change the threshold file size as required.</li></ul></div>

<h1 id="w_using-filelink">Using Filelink</h1>
<p>When you attach a file to a message, and the file size exceeds the size you have specified above, Thunderbird will automatically offer to use Filelink:
</p><p><img alt="Proton-FileLink-LargeFileNotification" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2021-05-10-14-54-16-912351.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<ul><li> Click the <span class="button">Link</span> button to upload the file to the online storage service provider.
</li><li> If you prefer to attach the file as a <a href="/en-US/kb/how-use-attachments">regular attachment</a>, choose <span class="button">Ignore</span>.
</li></ul>
<p>After choosing <span class="button">Link</span>, your file will be uploaded in the background and the displayed message will update to:
</p><p><img alt="Proton-FileLink-UploadingFileNotification" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2021-05-10-14-51-18-5d2e96.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<div class="note"> Regardless of the file size and the Filelink notification, you can always force a file to be attached using Filelink:
<ul><li> Choose the down arrow of the <span class="button">Attach | v</span> button on the composition toolbar to access the <span class="menu">Filelink</span> submenu.
</li><li> Right-click on a regular attachment and from the context menu, choose <span class="menu">Convert to...</span> &gt; <span class="menu">[Your FileLink provider]</span>. You can choose from a list of your enabled providers.</li></ul></div>

<p>When the linking is complete – that is, your attachment has been uploaded to the service provider – Thunderbird will automatically add a section in the message with a link to the online copy of your file  as shown below:
</p><p><img alt="TB78-filelink-linked-anonymous" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2021-08-29-10-09-54-3855ee.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<div class="note"><strong>Note:</strong> The link section will appear in plain text, if <strong>Compose messages in HTML format</strong> is turned off in Account Settings.</div>
<p>When your recipients receive the message, they will see the same information and clicking the link in the message will take them to a page where they can download the attachment.
</p>
<hr>
<h1 id="w_filelink-faq">Filelink FAQ</h1>
<p>Attachments that you send via Filelink are not stored on Thunderbird servers. Each file storage service provider has its own privacy policy and terms of service. The file storage service provider has reviewed the Filelink feature to ensure that it is consistent with their policies.
</p>
<h2 id="w_does-thunderbird-know-which-provider-the-user-has-picked">Does Thunderbird know which provider the user has picked?</h2>
<p>No. Thunderbird is unaware of which provider has been selected by a user. Provider configuration is stored on the local machine.
</p>
<h2 id="w_what-storage-services-are-currently-supported">What storage services are currently supported?</h2>
<ul><li> A number of popular file storage providers are supported through <a href="https://addons.thunderbird.net/thunderbird/tag/filelink">Filelink provider add-ons</a>.
</li><li> You can also use Filelink with your preferred WebDAV server with the <a href="https://addons.thunderbird.net/thunderbird/addon/filelink-provider-for-webdav/">Filelink provider for WebDAV</a> add-on.
</li></ul>
<p>
</p>
<h2 id="w_can-the-storage-service-view-my-attachments">Can the storage service view my attachments?</h2>
<p>Unless you encrypt the file before uploading, the storage services will be able to view the file, as will anyone who obtains the link to the attachment. Users must decide on their own which service provider they trust with that responsibility. Service providers will generally explain your privacy rights in their terms of service. 
</p><p>Note that standard attachment functionality is also not encrypted. When you send an attachment the "normal" way, without using Thunderbird’s OpenPGP or SMIME features, the file can be accessed by anyone that can access the message between your system and the recipients system (such as your email service provider). Filelink adds some security as file uploads to the storage service provider are sent via HTTPS, a secure protocol. We recommend using Thunderbird''s OpenPGP or SMIME features for maximum security of your communications.
</p>
<h2 id="w_how-long-will-my-file-be-available-on-the-storage-service-providers-site">How long will my file be available on the storage service provider''s site?</h2>
<p>Depending on the terms and conditions of your third-party storage service provider and your service agreement with them, the file may remain available on the provider’s site for a limited period, a certain number of downloads, or until you explicitly delete it. You will need to log in to the provider’s website to view and delete the files in your personal storage space.
</p>
<h2 id="w_can-you-support-service-provider-x-or-protocol-y">Can you support service provider X or protocol Y?</h2>
<p>Please check if the Thunderbird community has provided a <a href="https://addons.thunderbird.net/thunderbird/tag/filelink">Filelink provider add-on</a> for the service provider you are looking for.
<a href="https://webextension-api.thunderbird.net/en/stable/cloudFile.html">Developer documentation for the Filelink API</a> is available.
</p>
<h2 id="w_i-dont-like-the-idea-of-storing-my-files-with-third-parties-like-this-do-regular-attachments-still-work">I don''t like the idea of storing my files with third-parties like this. Do regular attachments still work?</h2>
<p>Regular email attachments still work the same as they always have. We are just offering you an option to upload large attachments somewhere else if you wish. Thunderbird''s notion of a large file defaults to 5 MB, but can be customized in Thunderbird’s Settings:
</p>
<ol><li> Click <span class="button">≡</span> &gt; <span class="menu">Settings</span> &gt; <span class="menu">Composition</span> &gt; <span class="menu">Attachments</span>
</li><li> <strong>[✓] Offer to share for files larger than [5] MB</strong>
</li></ol>
<p>Removing the checkmark will prevent the automatical Filelink notification when you attach big files, but the Filelink feature will still be available from the <span class="button">Attach | v</span> button dropdown as well as other attachment menus and context menus.
</p>','[{"label": "Revision id", "text": "306945", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 29, 2025, 8:35:12 PM", "datetime": "2025-09-29T20:35:12.038882-07:00", "href": null}, {"label": "Creator", "text": "Kiki", "datetime": null, "href": "https://support.mozilla.org/en-US/user/kelimuttu/"}, {"label": "Comment", "text": "Bye Zap", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 23, 2025, 10:42:39 PM", "datetime": "2025-10-23T22:42:39.164569-07:00", "href": null}, {"label": "Reviewed by", "text": "kelimuttu", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:06:57+00:00','');
