INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (309112,'en-US','thunderbird-and-exchange','Thunderbird and Microsoft protocols (Exchange and Graph)','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange/revision/309112',303318,'2025-10-16T14:31:02.498216-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WIP: do not localize please until 145 is released, discussion: https://github.com/thunderbird/knowledgebase-issues/issues/109',1,'2025-10-16T14:31:27.061287-07:00','rtanglao',1,0,0,NULL,NULL,'approved','{warning}Warning: The current built-in code for Exchange in Thunderbird is limited to email. Other features (calendar, address book) are planned to follow, but are not available yet. We recommend using Thunderbird 144 or newer for for a more polished, stable experience, Please refer to our [https://wiki.mozilla.org/Thunderbird:Exchange Thunderbird:Exchange wiki page] for full details.{/warning}
__TOC__
==1. Configure your Exchange account==
===Thunderbird profiles with 1 or more accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with one or more accounts, you will see the new Thunderbird ''''''Account Hub'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} 
# Follow the flow by entering your name, email address, and if required, your [https://en.wikipedia.org/wiki/Multi-factor_authentication two factor authentication code] for your Exchange email account. {note}Note: you do not need to enter your password in the ''''''Password'''''' field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.{/note} Here is a screenshot of that panel provided by Microsoft:
#;[[Image:tb-141-oauth-microsoft-enter-password-win11]] 
# Click the {button Exchange} button (not the one labelled {button Exchange  REQUIRES ADD-ON}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange code.{note}Note: The {button Exchange} button only appears if the email you entered is an Exchange account.{/note}
#;[[Image:tb142-beta-exchange-support-button]] 
# Follow the prompts to finish adding your Exchange account.
[[UI:details_start]]
===Thunderbird profile with no accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with no accounts, you will see the older, ''''''Set Up Your Existing Email Address'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} 
# Follow the flow by entering your name, email address, and if required, your [https://en.wikipedia.org/wiki/Multi-factor_authentication two factor authentication code] for your Exchange email account.. {note}Note: you do not need to enter your password in the ''''''Password'''''' field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.{/note} Here is a screenshot of that panel provided by Microsoft:
#;[[Image:tb-141-oauth-microsoft-enter-password-win11]] 
# Click the {button Exchange Web Services} button (not the one labelled {button Exchange/Office365}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange implementation.{note}Note: The {button Exchange Web Services} button only appears if the email you entered is an Exchange account.{/note}
#;[[Image:tb142-beta-old-pre-account-hub-flow-exchange-webservices-button]] 
# Follow the prompts to finish adding your Exchange account.
[[UI:details_end]]
==2. Send and receive emails with your Exchange Account==
Once you have configured your Exchange Account, you can use it to [[Send and receive messages in Thunderbird|send and receive emails]] just like an IMAP or POP account.','<div class="warning">Warning: The current built-in code for Exchange in Thunderbird is limited to email. Other features (calendar, address book) are planned to follow, but are not available yet. We recommend using Thunderbird 144 or newer for for a more polished, stable experience, Please refer to our <a href="https://wiki.mozilla.org/Thunderbird:Exchange">Thunderbird:Exchange wiki page</a> for full details.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_1-configure-your-exchange-account"><span class="tocnumber">1</span> <span class="toctext">1. Configure your Exchange account</span></a><ul><li class="toclevel-2"><a href="#w_thunderbird-profiles-with-1-or-more-accounts"><span class="tocnumber">1.1</span> <span class="toctext">Thunderbird profiles with 1 or more accounts</span></a></li><li class="toclevel-2"><a href="#w_thunderbird-profile-with-no-accounts"><span class="tocnumber">1.2</span> <span class="toctext">Thunderbird profile with no accounts</span></a></li></ul></li><li class="toclevel-1"><a href="#w_2-send-and-receive-emails-with-your-exchange-account"><span class="tocnumber">2</span> <span class="toctext">2. Send and receive emails with your Exchange Account</span></a></li></ul></div>
<h2 id="w_1-configure-your-exchange-account">1. Configure your Exchange account</h2>
<h3 id="w_thunderbird-profiles-with-1-or-more-accounts">Thunderbird profiles with 1 or more accounts</h3>
<p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with one or more accounts, you will see the new Thunderbird <strong>Account Hub</strong> flow:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> 
</li><li> Follow the flow by entering your name, email address, and if required, your <a href="https://en.wikipedia.org/wiki/Multi-factor_authentication">two factor authentication code</a> for your Exchange email account. <div class="note">Note: you do not need to enter your password in the <strong>Password</strong> field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.</div> Here is a screenshot of that panel provided by Microsoft:
<dl><dt><img alt="tb-141-oauth-microsoft-enter-password-win11" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-25-21-26-20-034f89.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Click the <span class="button">Exchange</span> button (not the one labelled <span class="button">Exchange  REQUIRES ADD-ON</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange code.<div class="note">Note: The <span class="button">Exchange</span> button only appears if the email you entered is an Exchange account.</div>
<dl><dt><img alt="tb142-beta-exchange-support-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-03-20-2802fd.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Follow the prompts to finish adding your Exchange account.
</li></ol>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h3 id="w_thunderbird-profile-with-no-accounts" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Thunderbird profile with no accounts</button></h3><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true"><p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with no accounts, you will see the older, <strong>Set Up Your Existing Email Address</strong> flow:
</p><ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> 
</li><li> Follow the flow by entering your name, email address, and if required, your <a href="https://en.wikipedia.org/wiki/Multi-factor_authentication">two factor authentication code</a> for your Exchange email account.. <div class="note">Note: you do not need to enter your password in the <strong>Password</strong> field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.</div> Here is a screenshot of that panel provided by Microsoft:
<dl><dt><img alt="tb-141-oauth-microsoft-enter-password-win11" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-25-21-26-20-034f89.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Click the <span class="button">Exchange Web Services</span> button (not the one labelled <span class="button">Exchange/Office365</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange implementation.<div class="note">Note: The <span class="button">Exchange Web Services</span> button only appears if the email you entered is an Exchange account.</div>
<dl><dt><img alt="tb142-beta-old-pre-account-hub-flow-exchange-webservices-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-23-12-9340ff.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Follow the prompts to finish adding your Exchange account.
</li></ol><p></p></div>


</section>
<p></p>
<h2 id="w_2-send-and-receive-emails-with-your-exchange-account">2. Send and receive emails with your Exchange Account</h2>
<p>Once you have configured your Exchange Account, you can use it to <a href="/en-US/kb/sending-and-receiving-messages-thunderbird">send and receive emails</a> just like an IMAP or POP account.
</p>','[{"label": "Revision id", "text": "309112", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 16, 2025, 2:31:02 PM", "datetime": "2025-10-16T14:31:02.498216-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WIP: do not localize please until 145 is released, discussion: https://github.com/thunderbird/knowledgebase-issues/issues/109", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 16, 2025, 2:31:27 PM", "datetime": "2025-10-16T14:31:27.061287-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:25:30+00:00','M');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (311097,'en-US','thunderbird-and-gmail','Thunderbird and Gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail','https://support.mozilla.org/en-US/kb/thunderbird-and-gmail/revision/311097',290769,'2025-10-23T11:10:24.259478-07:00','rsbrux','https://support.mozilla.org/en-US/user/rsbrux/','Added CardBook to useful add-ons. Changed article target to TB 140 ESR because add-ons are said not to work with later versions.',1,'2025-10-23T11:36:41.473414-07:00','wsmwk',1,0,1,'2025-10-23T11:36:41.473414-07:00','wsmwk','approved','Thunderbird can be configured to work seamlessly with Google''s [https://www.google.com/gmail/about/ Gmail] service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.
{warning}As of May 30, 2022, ''''''Google no longer allows [https://myaccount.google.com/lesssecureapps Less secure apps] access'''''' for Gmail accounts, thus ''''''OAuth is required''''''. If you are using Google supplied “app passwords“, Thunderbird version 91.8.0 and newer will [[Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication|make that conversion]] for you. Further, ''''''Gmail accounts do not work with Thunderbird 31 and older'''''' because they do not support Google''s OAuth (implemented in [https://bugzilla.mozilla.org/show_bug.cgi?id=849540 bug 849540]).{/warning}

__TOC__

= Configuring your Gmail account =
[[Video:https://www.youtube.com/watch?v=JXs_YE9QyUQ]]

To configure Thunderbird to work with Gmail, first ensure IMAP is enabled on your Gmail account (the default for new Gmail accounts). See [https://support.google.com/mail/answer/7126229 Gmail''s instructions] for help.

Next, select {menu File} > {menu New} > {menu Existing Mail Account…} The ''''Mail Account Setup'''' dialog is displayed. After you provide your account information (real name, email address{for not tb38}, password{/for}), Thunderbird will automatically configure your Gmail connection. Click {button Done}{for tb38}, sign in with your Google account if prompted{/for}. Thunderbird will begin downloading your existing messages.

Lastly, review [https://support.google.com/mail/answer/78892#zippy=%2Cthunderbird Google''s recommended settings for Thunderbird] so that your local actions, such as labelling and deleting, correspond to those which Gmail takes and do not cause any conflicts.

For more detailed information, please refer to:
* [[Automatic Account Configuration]]
* [https://support.google.com/mail/topic/7280141 Gmail''s support articles on email clients]

= Gmail''s particularities =
== Archiving messages ==
In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the ''''All Mail'''' folder, and not in an ''''Archive'''' folder as it does for other accounts (as described in the [[Archived Messages]] article).
;[[Image:Gmail Archive settings]]
{note}The {button Archive options…} button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.{/note}

== Subscribing to folders and synchronizing messages ==
=== Understanding Gmail labels and Thunderbird folders ===
Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.

If you copy a message to another folder, Gmail will still store only one message but apply both folder names as labels to it. Moving any copy of a message into the Trash will remove all labels from it, and it will no longer appear in any other folder.

In the example shown below, the folders at the same level as the ''''[Gmail]'''' folder (''''Personal'''', ''''Receipts'''', ''''Travel'''' and ''''Work'''') correspond to Gmail labels.
;[[Image:default gmail folders]]
There is also a set of special sub-folders for the ''''[Gmail]'''' folder:
* All Mail: contains all the messages of your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the ''''[Gmail]/All Mail'''' folder. (It is recommended to unsubscribe this folder.)
* Drafts: contains draft messages.
* Sent Mail: contains sent messages.
* Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
* Starred: contains messages that were starred (either by Gmail or Thunderbird).
* Trash: contains deleted messages.
* Important: contains messages that Gmail has flagged as “important”. (See [https://support.google.com/mail/answer/186531 Priority Inbox overview] for more details about this Gmail feature.)

=== Subscribing to or unsubscribing from folders (labels) ===
You can configure which folder (and its messages) you want to display and download in Thunderbird by changing folder subscriptions. By default, all folders are displayed and downloaded, as described above. To change folder subscription, right-click the account name and select {menu Subscribe…}
;[[Image:subscribe gmail folders]]
Uncheck any folders that you don''t want to display in Thunderbird. 

{note}For performance and space reasons it is recommended to unsubscribe the ''''All Mail'''' folder.
{/note}


=== Synchronizing folders (labels) ===
If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click the message header.

To change how messages are downloaded, set synchronization options for the account and for individual folders. ({for win,mac}{menu Tools} > {menu Account Settings…}{/for}{for linux}{menu Edit} > {menu Account Settings…}{/for}) See [[IMAP Synchronization#w_synchronization]] for more information.

=== Thunderbird''s message lists differ from the web interface ===
If some messages are appearing in your Inbox that shouldn''t be, or aren''t appearing but should be, you may need to select the ''''Don''t override filters'''' option under {menu Inbox} > {menu Filtered mail} in Gmail''s settings.
The same can be achieved by turning off {menu General} > {menu Smart features and personalisation} in Gmail''s settings.

You can also change whether Gmail''s interface should group messages by conversation with the ''''''Conversation View'''''' setting in Gmail''s {menu General} settings page, to match your [[Message threading in Thunderbird - keep messages grouped by conversation|Thunderbird preference]].

See the support article on [https://support.google.com/mail/answer/6562 how to change Gmail settings].

= Updating a Gmail account to use OAuth =
Thunderbird will normally set up or update your Gmail account to OAuth automatically. If something goes wrong, you can use the hints below to check and set up manually. For more details and how to resolve various OAuth issues, see [[Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication]].

The following applies to both POP and IMAP mail accounts.
*Enable cookies in Thunderbird:
*#Click {menu ≡} > {menu Settings}.
*#Select {menu Privacy & Security}.
*#Under ''''Web Content'''' section, tick ''''''Accept cookies from sites''''''.
*You may need to set an exception:
*#Click {button Exceptions…} button.
*#Add an exception for ''''''https://accounts.google<!-- -->.com''''''
*#Click {button Allow}.
*#Click {button Save Changes}.
*Change the authentication method in ''''Account Settings'''':
*#Click {menu ≡} > {menu Account Settings}, which opens in a new tab.
**Change the Outgoing SMTP authentication method:
**#In the left pane, select the POP/IMAP account name and look bottom right for ''''Outgoing Server (SMTP)''''.
**#Click {button Edit Server SMTP…} button.
**#Set ''''Authentication Method'''' to ''''''OAuth2''''''.
**#Click {button OK}.
**Change the Incoming authentication method:
**#In the left pane, select {menu Server Settings} for Gmail account.
**#Set ''''Authentication Method'''' to ''''''OAuth2''''''.

Exit Thunderbird and wait a few moments for background processes to finish. Then restart Thunderbird.

Gmail will prompt you to enter your Gmail email address and password, which is the same password you use to access Gmail webmail account. Follow the instructions to allow Thunderbird to access server.

An OAuth token will get saved in Thunderbird, in the same location as passwords.

= Useful Add-ons =
* [https://addons.thunderbird.net/thunderbird/addon/google-4-tbsync/ Google-4-TbSync: Google contact and contact group sync].
* [https://addons.thunderbird.net/thunderbird/addon/cardbook/ CardBook: Contact Manager, supports CardDAV4, including Google contact labels / groups].
* If you want to sync your calendar between Thunderbird Calendar and Google Calendar, you should read [[Using Lightning with Google Calendar]].
* [https://addons.thunderbird.net/en-US/thunderbird/addon/gtrash/ GTrash] to make true deletion more convenient when using Google''s recommended deletion settings.

= See also =
* [https://support.google.com/mail/answer/78892 Gmail''s support article on recommended settings].
* [https://bugzilla.mozilla.org/show_bug.cgi?id=402793 The ticket which tracks issues using Gmail with Thunderbird (Bug 402793)].','<p>Thunderbird can be configured to work seamlessly with Google''s <a href="https://www.google.com/gmail/about/">Gmail</a> service. Messages are synchronized between your local version of Thunderbird and the web-based Gmail.
</p>
<div class="warning">As of May 30, 2022, <strong>Google no longer allows <a href="https://myaccount.google.com/lesssecureapps">Less secure apps</a> access</strong> for Gmail accounts, thus <strong>OAuth is required</strong>. If you are using Google supplied “app passwords“, Thunderbird version 91.8.0 and newer will <a href="/en-US/kb/automatic-conversion-google-mail-accounts-oauth20">make that conversion</a> for you. Further, <strong>Gmail accounts do not work with Thunderbird 31 and older</strong> because they do not support Google''s OAuth (implemented in <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=849540">bug 849540</a>).</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configuring-your-gmail-account"><span class="tocnumber">1</span> <span class="toctext">Configuring your Gmail account</span></a></li><li class="toclevel-1"><a href="#w_gmails-particularities"><span class="tocnumber">2</span> <span class="toctext">Gmail''s particularities</span></a><ul><li class="toclevel-2"><a href="#w_archiving-messages"><span class="tocnumber">2.1</span> <span class="toctext">Archiving messages</span></a></li><li class="toclevel-2"><a href="#w_subscribing-to-folders-and-synchronizing-messages"><span class="tocnumber">2.2</span> <span class="toctext">Subscribing to folders and synchronizing messages</span></a><ul><li class="toclevel-3"><a href="#w_understanding-gmail-labels-and-thunderbird-folders"><span class="tocnumber">2.2.1</span> <span class="toctext">Understanding Gmail labels and Thunderbird folders</span></a></li><li class="toclevel-3"><a href="#w_subscribing-to-or-unsubscribing-from-folders-labels"><span class="tocnumber">2.2.2</span> <span class="toctext">Subscribing to or unsubscribing from folders (labels)</span></a></li><li class="toclevel-3"><a href="#w_synchronizing-folders-labels"><span class="tocnumber">2.2.3</span> <span class="toctext">Synchronizing folders (labels)</span></a></li><li class="toclevel-3"><a href="#w_thunderbirds-message-lists-differ-from-the-web-interface"><span class="tocnumber">2.2.4</span> <span class="toctext">Thunderbird''s message lists differ from the web interface</span></a></li></ul></li></ul></li><li class="toclevel-1"><a href="#w_updating-a-gmail-account-to-use-oauth"><span class="tocnumber">3</span> <span class="toctext">Updating a Gmail account to use OAuth</span></a></li><li class="toclevel-1"><a href="#w_useful-add-ons"><span class="tocnumber">4</span> <span class="toctext">Useful Add-ons</span></a></li><li class="toclevel-1"><a href="#w_see-also"><span class="tocnumber">5</span> <span class="toctext">See also</span></a></li></ul></div>
<h1 id="w_configuring-your-gmail-account">Configuring your Gmail account</h1>
<p></p><div class="youtube-embed">
  <iframe src="//www.youtube.com/embed/JXs_YE9QyUQ?wmode=transparent&amp;rel=0" frameborder="0" allowfullscreen=""></iframe>
</div>
<p></p><p>To configure Thunderbird to work with Gmail, first ensure IMAP is enabled on your Gmail account (the default for new Gmail accounts). See <a href="https://support.google.com/mail/answer/7126229">Gmail''s instructions</a> for help.
</p><p>Next, select <span class="menu">File</span> &gt; <span class="menu">New</span> &gt; <span class="menu">Existing Mail Account…</span> The <em>Mail Account Setup</em> dialog is displayed. After you provide your account information (real name, email address<span class="for" data-for="not tb38" style="display: none;">, password</span>), Thunderbird will automatically configure your Gmail connection. Click <span class="button">Done</span><span class="for" data-for="tb38">, sign in with your Google account if prompted</span>. Thunderbird will begin downloading your existing messages.
</p><p>Lastly, review <a href="https://support.google.com/mail/answer/78892#zippy=%2Cthunderbird">Google''s recommended settings for Thunderbird</a> so that your local actions, such as labelling and deleting, correspond to those which Gmail takes and do not cause any conflicts.
</p><p>For more detailed information, please refer to:
</p>
<ul><li> <a href="/en-US/kb/automatic-account-configuration">Automatic Account Configuration</a>
</li><li> <a href="https://support.google.com/mail/topic/7280141">Gmail''s support articles on email clients</a>
</li></ul>
<h1 id="w_gmails-particularities">Gmail''s particularities</h1>
<h2 id="w_archiving-messages">Archiving messages</h2>
<p>In order to be consistent with Gmail''s behavior, Thunderbird archives your message in the <em>All Mail</em> folder, and not in an <em>Archive</em> folder as it does for other accounts (as described in the <a href="/en-US/kb/archived-messages">Archived Messages</a> article).
</p>
<dl><dt><img alt="Gmail Archive settings" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-17-04-13-09-41649e.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<div class="note">The <span class="button">Archive options…</span> button is disabled for Gmail accounts, as it is not necessary to define the archive granularity with Gmail.</div>
<h2 id="w_subscribing-to-folders-and-synchronizing-messages">Subscribing to folders and synchronizing messages</h2>
<h3 id="w_understanding-gmail-labels-and-thunderbird-folders">Understanding Gmail labels and Thunderbird folders</h3>
<p>Gmail uses a special implementation of IMAP. In this implementation, Gmail labels become Thunderbird folders. When you apply a label to a message in Gmail, Thunderbird creates a folder with the same name as the label and stores the message in that folder. Similarly, if you move a message to a folder in Thunderbird, Gmail will create a label with the folder name and assign it to the message.
</p><p>If you copy a message to another folder, Gmail will still store only one message but apply both folder names as labels to it. Moving any copy of a message into the Trash will remove all labels from it, and it will no longer appear in any other folder.
</p><p>In the example shown below, the folders at the same level as the <em>[Gmail]</em> folder (<em>Personal</em>, <em>Receipts</em>, <em>Travel</em> and <em>Work</em>) correspond to Gmail labels.
</p>
<dl><dt><img alt="default gmail folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-22-16-07-48-8304a9.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>There is also a set of special sub-folders for the <em>[Gmail]</em> folder:
</p>
<ul><li> All Mail: contains all the messages of your Gmail account, including sent and archived messages. Any messages that you see in the inbox will also appear in the <em>[Gmail]/All Mail</em> folder. (It is recommended to unsubscribe this folder.)
</li><li> Drafts: contains draft messages.
</li><li> Sent Mail: contains sent messages.
</li><li> Spam: contains messages that were marked as spam (either by Gmail or Thunderbird).
</li><li> Starred: contains messages that were starred (either by Gmail or Thunderbird).
</li><li> Trash: contains deleted messages.
</li><li> Important: contains messages that Gmail has flagged as “important”. (See <a href="https://support.google.com/mail/answer/186531">Priority Inbox overview</a> for more details about this Gmail feature.)
</li></ul>
<h3 id="w_subscribing-to-or-unsubscribing-from-folders-labels">Subscribing to or unsubscribing from folders (labels)</h3>
<p>You can configure which folder (and its messages) you want to display and download in Thunderbird by changing folder subscriptions. By default, all folders are displayed and downloaded, as described above. To change folder subscription, right-click the account name and select <span class="menu">Subscribe…</span>
</p>
<dl><dt><img alt="subscribe gmail folders" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2012-03-22-16-20-21-1f5531.jpg" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</dt></dl>
<p>Uncheck any folders that you don''t want to display in Thunderbird. 
</p>
<div class="note">For performance and space reasons it is recommended to unsubscribe the <em>All Mail</em> folder.
</div>
<p><br>
</p>
<h3 id="w_synchronizing-folders-labels">Synchronizing folders (labels)</h3>
<p>If you want to see all your Gmail labels and messages in Thunderbird but prefer to avoid all the messages being downloaded to your system, you may want to tweak the synchronization settings. This allows you to define which folder should be synchronized. If you don''t synchronize a folder, the message header will still be displayed in Thunderbird, but the message content will only be downloaded when you click the message header.
</p><p>To change how messages are downloaded, set synchronization options for the account and for individual folders. (<span class="for" data-for="win,mac"><span class="menu">Tools</span> &gt; <span class="menu">Account Settings…</span></span><span class="for" data-for="linux" style="display: none;"><span class="menu">Edit</span> &gt; <span class="menu">Account Settings…</span></span>) See <a href="/en-US/kb/imap-synchronization#w_synchronization">IMAP Synchronization</a> for more information.
</p>
<h3 id="w_thunderbirds-message-lists-differ-from-the-web-interface">Thunderbird''s message lists differ from the web interface</h3>
<p>If some messages are appearing in your Inbox that shouldn''t be, or aren''t appearing but should be, you may need to select the <em>Don''t override filters</em> option under <span class="menu">Inbox</span> &gt; <span class="menu">Filtered mail</span> in Gmail''s settings.
The same can be achieved by turning off <span class="menu">General</span> &gt; <span class="menu">Smart features and personalisation</span> in Gmail''s settings.
</p><p>You can also change whether Gmail''s interface should group messages by conversation with the <strong>Conversation View</strong> setting in Gmail''s <span class="menu">General</span> settings page, to match your <a href="/en-US/kb/message-threading-thunderbird">Thunderbird preference</a>.
</p><p>See the support article on <a href="https://support.google.com/mail/answer/6562">how to change Gmail settings</a>.
</p>
<h1 id="w_updating-a-gmail-account-to-use-oauth">Updating a Gmail account to use OAuth</h1>
<p>Thunderbird will normally set up or update your Gmail account to OAuth automatically. If something goes wrong, you can use the hints below to check and set up manually. For more details and how to resolve various OAuth issues, see <a href="/en-US/kb/automatic-conversion-google-mail-accounts-oauth20">Automatic Conversion of Google mail accounts to OAuth 2.0 Authentication</a>.
</p><p>The following applies to both POP and IMAP mail accounts.
</p>
<ul><li>Enable cookies in Thunderbird:
<ol><li>Click <span class="menu">≡</span> &gt; <span class="menu">Settings</span>.
</li><li>Select <span class="menu">Privacy &amp; Security</span>.
</li><li>Under <em>Web Content</em> section, tick <strong>Accept cookies from sites</strong>.
</li></ol>
</li><li>You may need to set an exception:
<ol><li>Click <span class="button">Exceptions…</span> button.
</li><li>Add an exception for <strong><a href="https://accounts.google">https://accounts.google</a>.com</strong>
</li><li>Click <span class="button">Allow</span>.
</li><li>Click <span class="button">Save Changes</span>.
</li></ol>
</li><li>Change the authentication method in <em>Account Settings</em>:
<ol><li>Click <span class="menu">≡</span> &gt; <span class="menu">Account Settings</span>, which opens in a new tab.
</li></ol>
<ul><li>Change the Outgoing SMTP authentication method:
<ol><li>In the left pane, select the POP/IMAP account name and look bottom right for <em>Outgoing Server (SMTP)</em>.
</li><li>Click <span class="button">Edit Server SMTP…</span> button.
</li><li>Set <em>Authentication Method</em> to <strong>OAuth2</strong>.
</li><li>Click <span class="button">OK</span>.
</li></ol>
</li><li>Change the Incoming authentication method:
<ol><li>In the left pane, select <span class="menu">Server Settings</span> for Gmail account.
</li><li>Set <em>Authentication Method</em> to <strong>OAuth2</strong>.
</li></ol>
</li></ul>
</li></ul>
<p>Exit Thunderbird and wait a few moments for background processes to finish. Then restart Thunderbird.
</p><p>Gmail will prompt you to enter your Gmail email address and password, which is the same password you use to access Gmail webmail account. Follow the instructions to allow Thunderbird to access server.
</p><p>An OAuth token will get saved in Thunderbird, in the same location as passwords.
</p>
<h1 id="w_useful-add-ons">Useful Add-ons</h1>
<ul><li> <a href="https://addons.thunderbird.net/thunderbird/addon/google-4-tbsync/">Google-4-TbSync: Google contact and contact group sync</a>.
</li><li> <a href="https://addons.thunderbird.net/thunderbird/addon/cardbook/">CardBook: Contact Manager, supports CardDAV4, including Google contact labels / groups</a>.
</li><li> If you want to sync your calendar between Thunderbird Calendar and Google Calendar, you should read <a href="/en-US/kb/using-lightning-google-calendar">Using Thunderbird with Google Calendar</a>.
</li><li> <a href="https://addons.thunderbird.net/en-US/thunderbird/addon/gtrash/">GTrash</a> to make true deletion more convenient when using Google''s recommended deletion settings.
</li></ul>
<h1 id="w_see-also">See also</h1>
<ul><li> <a href="https://support.google.com/mail/answer/78892">Gmail''s support article on recommended settings</a>.
</li><li> <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=402793">The ticket which tracks issues using Gmail with Thunderbird (Bug 402793)</a>.
</li></ul>','[{"label": "Revision id", "text": "311097", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 23, 2025, 11:10:24 AM", "datetime": "2025-10-23T11:10:24.259478-07:00", "href": null}, {"label": "Creator", "text": "rsbrux", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rsbrux/"}, {"label": "Comment", "text": "Added CardBook to useful add-ons. Changed article target to TB 140 ESR because add-ons are said not to work with later versions.", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 23, 2025, 11:36:41 AM", "datetime": "2025-10-23T11:36:41.473414-07:00", "href": null}, {"label": "Reviewed by", "text": "wsmwk", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 23, 2025, 11:36:41 AM", "datetime": "2025-10-23T11:36:41.473414-07:00", "href": null}, {"label": "Readied for localization by", "text": "wsmwk", "datetime": null, "href": null}]','2026-11-03T20:16:21+00:00','M');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (311448,'en-US','thunderbird-and-exchange','Thunderbird and Microsoft protocols (Exchange and Graph)','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange','https://support.mozilla.org/en-US/kb/thunderbird-and-exchange/revision/311448',309112,'2025-10-24T12:23:04.842023-07:00','Wayne Mery','https://support.mozilla.org/en-US/user/wsmwk/','update warning. more to come',0,NULL,NULL,NULL,NULL,0,NULL,NULL,'unreviewed','{warning}Warning: Thunderbird Version 145 implements Exchange via the EWS API (Exchange Web Services), ''''''currently limited to email''''''. 

Calendar and address book using the EWS API will follow at a later date. Also in the future is Exchange via Graph API, so please do not file bug reports for these items at this time. 

For more technical detail, as well as things to test and look for, see the [https://wiki.mozilla.org/Thunderbird:Exchange Thunderbird:Exchange wiki page]. We welcome your [[#feedback and bug reports]].{/warning}

__TOC__
=Setup=
When creating a new account using classic account creation, choose the "Exchange Web Services" option. Or if using the new Account Hub, when providing an exchange email address, "Exchange" should be automatically detected. If exchange is not detected, choose the first "Exchange" option.
==1. Configure your Exchange account==
===Thunderbird profiles with 1 or more accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with one or more accounts, you will see the new Thunderbird ''''''Account Hub'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} 
# Follow the flow by entering your name, email address, and if required, your [https://en.wikipedia.org/wiki/Multi-factor_authentication two factor authentication code] for your Exchange email account. {note}Note: you do not need to enter your password in the ''''''Password'''''' field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.{/note} Here is a screenshot of that panel provided by Microsoft:
#;[[Image:tb-141-oauth-microsoft-enter-password-win11]] 
# Click the {button Exchange} button (not the one labelled {button Exchange  REQUIRES ADD-ON}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange code.{note}Note: The {button Exchange} button only appears if the email you entered is an Exchange account.{/note}
#;[[Image:tb142-beta-exchange-support-button]] 
# Follow the prompts to finish adding your Exchange account.
[[UI:details_start]]
===Thunderbird profile with no accounts===
If you have a [[Profiles - Where Thunderbird stores your messages and other user data|Thunderbird profile]] with no accounts, you will see the older, ''''''Set Up Your Existing Email Address'''''' flow:
# Click Thunderbird app menu {menu ☰} > {button New Account} > {menu Email} 
# Follow the flow by entering your name, email address, and if required, your [https://en.wikipedia.org/wiki/Multi-factor_authentication two factor authentication code] for your Exchange email account.. {note}Note: you do not need to enter your password in the ''''''Password'''''' field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.{/note} Here is a screenshot of that panel provided by Microsoft:
#;[[Image:tb-141-oauth-microsoft-enter-password-win11]] 
# Click the {button Exchange Web Services} button (not the one labelled {button Exchange/Office365}) in the ''''''Choose your email account type'''''' dialogue to use Thunderbird''s built-in Exchange implementation.{note}Note: The {button Exchange Web Services} button only appears if the email you entered is an Exchange account.{/note}
#;[[Image:tb142-beta-old-pre-account-hub-flow-exchange-webservices-button]] 
# Follow the prompts to finish adding your Exchange account.
[[UI:details_end]]
==2. Send and receive emails with your Exchange Account==
Once you have configured your Exchange Account, you can use it to [[Send and receive messages in Thunderbird|send and receive emails]] just like an IMAP or POP account.

=Limitations=


=Feedback and Bug Reports=','<div class="warning">Warning: Thunderbird Version 145 implements Exchange via the EWS API (Exchange Web Services), <strong>currently limited to email</strong>. 
<p>Calendar and address book using the EWS API will follow at a later date. Also in the future is Exchange via Graph API, so please do not file bug reports for these items at this time. 
</p>
For more technical detail, as well as things to test and look for, see the <a href="https://wiki.mozilla.org/Thunderbird:Exchange">Thunderbird:Exchange wiki page</a>. We welcome your <a href="#feedback_and_bug_reports">#feedback and bug reports</a>.</div>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_setup"><span class="tocnumber">1</span> <span class="toctext">Setup</span></a><ul><li class="toclevel-2"><a href="#w_1-configure-your-exchange-account"><span class="tocnumber">1.1</span> <span class="toctext">1. Configure your Exchange account</span></a><ul><li class="toclevel-3"><a href="#w_thunderbird-profiles-with-1-or-more-accounts"><span class="tocnumber">1.1.1</span> <span class="toctext">Thunderbird profiles with 1 or more accounts</span></a></li><li class="toclevel-3"><a href="#w_thunderbird-profile-with-no-accounts"><span class="tocnumber">1.1.2</span> <span class="toctext">Thunderbird profile with no accounts</span></a></li></ul></li><li class="toclevel-2"><a href="#w_2-send-and-receive-emails-with-your-exchange-account"><span class="tocnumber">1.2</span> <span class="toctext">2. Send and receive emails with your Exchange Account</span></a></li></ul></li><li class="toclevel-1"><a href="#w_limitations"><span class="tocnumber">2</span> <span class="toctext">Limitations</span></a></li><li class="toclevel-1"><a href="#w_feedback-and-bug-reports"><span class="tocnumber">3</span> <span class="toctext">Feedback and Bug Reports</span></a></li></ul></div>
<h1 id="w_setup">Setup</h1>
<p>When creating a new account using classic account creation, choose the "Exchange Web Services" option. Or if using the new Account Hub, when providing an exchange email address, "Exchange" should be automatically detected. If exchange is not detected, choose the first "Exchange" option.
</p>
<h2 id="w_1-configure-your-exchange-account">1. Configure your Exchange account</h2>
<h3 id="w_thunderbird-profiles-with-1-or-more-accounts">Thunderbird profiles with 1 or more accounts</h3>
<p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with one or more accounts, you will see the new Thunderbird <strong>Account Hub</strong> flow:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> 
</li><li> Follow the flow by entering your name, email address, and if required, your <a href="https://en.wikipedia.org/wiki/Multi-factor_authentication">two factor authentication code</a> for your Exchange email account. <div class="note">Note: you do not need to enter your password in the <strong>Password</strong> field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.</div> Here is a screenshot of that panel provided by Microsoft:
<dl><dt><img alt="tb-141-oauth-microsoft-enter-password-win11" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-25-21-26-20-034f89.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Click the <span class="button">Exchange</span> button (not the one labelled <span class="button">Exchange  REQUIRES ADD-ON</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange code.<div class="note">Note: The <span class="button">Exchange</span> button only appears if the email you entered is an Exchange account.</div>
<dl><dt><img alt="tb142-beta-exchange-support-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-03-20-2802fd.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Follow the prompts to finish adding your Exchange account.
</li></ol>
<p></p><section class="mzp-c-details is-details">
<p></p>
<h3 id="w_thunderbird-profile-with-no-accounts" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Thunderbird profile with no accounts</button></h3><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true"><p>If you have a <a href="/en-US/kb/profiles-where-thunderbird-stores-user-data">Thunderbird profile</a> with no accounts, you will see the older, <strong>Set Up Your Existing Email Address</strong> flow:
</p><ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="button">New Account</span> &gt; <span class="menu">Email</span> 
</li><li> Follow the flow by entering your name, email address, and if required, your <a href="https://en.wikipedia.org/wiki/Multi-factor_authentication">two factor authentication code</a> for your Exchange email account.. <div class="note">Note: you do not need to enter your password in the <strong>Password</strong> field of the first dialogue. You will enter your password in a separate, branded panel provided by Microsoft (not Mozilla) as part of their OAuth implementation.</div> Here is a screenshot of that panel provided by Microsoft:
<dl><dt><img alt="tb-141-oauth-microsoft-enter-password-win11" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-25-21-26-20-034f89.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Click the <span class="button">Exchange Web Services</span> button (not the one labelled <span class="button">Exchange/Office365</span>) in the <strong>Choose your email account type</strong> dialogue to use Thunderbird''s built-in Exchange implementation.<div class="note">Note: The <span class="button">Exchange Web Services</span> button only appears if the email you entered is an Exchange account.</div>
<dl><dt><img alt="tb142-beta-old-pre-account-hub-flow-exchange-webservices-button" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2025-08-19-21-23-12-9340ff.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title=""> 
</dt></dl>
</li><li> Follow the prompts to finish adding your Exchange account.
</li></ol><p></p></div>


</section>
<p></p>
<h2 id="w_2-send-and-receive-emails-with-your-exchange-account">2. Send and receive emails with your Exchange Account</h2>
<p>Once you have configured your Exchange Account, you can use it to <a href="/en-US/kb/sending-and-receiving-messages-thunderbird">send and receive emails</a> just like an IMAP or POP account.
</p>
<h1 id="w_limitations">Limitations</h1>
<h1 id="w_feedback-and-bug-reports">Feedback and Bug Reports</h1>','[{"label": "Revision id", "text": "311448", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 24, 2025, 12:23:04 PM", "datetime": "2025-10-24T12:23:04.842023-07:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "update warning. more to come", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:16:10+00:00','');
