</p>','[{"label": "Revision id", "text": "314002", "datetime": null, "href": null}, {"label": "Created", "text": "Nov 18, 2025, 9:58:23 AM", "datetime": "2025-11-18T09:58:23.001099-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix formating (extra '') discussion: https://github.com/thunderbird/knowledgebase-issues/issues/109", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Nov 18, 2025, 9:59:06 AM", "datetime": "2025-11-18T09:59:06.101591-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Nov 18, 2025, 9:59:06 AM", "datetime": "2025-11-18T09:59:06.101591-08:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:24:24+00:00','M');
