INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (319677,'en-US','thunderbird-desktop-and-thundermail','Thunderbird for Desktop and Thundermail','https://support.mozilla.org/en-US/kb/thunderbird-desktop-and-thundermail','https://support.mozilla.org/en-US/kb/thunderbird-desktop-and-thundermail/revision/319677',NULL,'2026-02-10T09:47:44.671310-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','english only for now, so do not translate please! Discussion please https://github.com/thunderbird/knowledgebase-issues/issues/103',1,'2026-02-10T09:48:07.429702-08:00','rtanglao',1,0,0,NULL,NULL,'approved','[[Template:TBproEarlyBirdInviteOnly]]

__TOC__

=Configure Thundermail for Thunderbird Desktop=
{note}''''''NOTE'''''': Thunderbird Pro requires Thunderbird 140 for Desktop or newer. We recommend the latest monthly release version of Thunderbird which is documented in: [[New in Thunderbird Desktop]].{/note}
# Click  {menu New Account} > {menu Email}
# Enter your Thundermail email address and follow the prompts to set up your Thundermail email account.

=Manual settings=

Thunderbird should automatically configure your Thundermail email settings to match your [https://accounts.tb.pro/self-serve/connection-info TB Pro accounts page]. If it doesn’t, please try manually changing the Receiving email and Sending email settings as per the sections below. If manual setup fails, please create a support ticket using our form at: [https://accounts.tb.pro/contact/ accounts.tb.pro/contact].
[[UI:details_start]]
==Receiving Email==
# Switch to your Thundermail account: Thunderbird app menu {menu ☰}  > {menu Account Settings}.
# In the left sidebar, click on your Thundermail email account. (For example: [mailto:nemo@thundermail.com nemo@thundermail.com].) Then, click on the chevron “&gt;” to expand the drop down menu. Finally, click on {menu Server Settings} and set the following values:

* ''''''Server Name:'''''' [http://mail.thundermail.com mail.thundermail.com] ''''''Server Port:'''''' 993
* ''''''Security:'''''' SSL/TLS
* ''''''Username:'''''' your full Thundermail email address e.g. nemo@thundermail.com
* ''''''Authentication method:'''''' OAuth2

==Sending Email==
# Switch to your Thundermail account: Thunderbird app menu {menu ☰}  > {menu Account Settings}.
# In the left sidebar click on your Thundermail email account. (For example [mailto:nemo@thundermail.com nemo@thundermail.com].) Click on {button Edit outgoing server…} and set the following values:

* ''''''Server Name:'''''' mail.thundermail.com
* ''''''Server Port:'''''' 465 ''''''Connection'''''' ''''''Security:'''''' SSL/TLS
* ''''''Username:'''''' your full Thundermail email address For example: nemo@thundermail.com
* ''''''Authentication method:'''''' OAuth2
[[UI:details_end]]

=Send and receive email, and have some fun!=
* [[Send and receive email]] with Thundermail. If you have large files, you can also use [https://support.tb.pro/hc/sections/43937747865235 ''''''Thunderbird Send'''''']. which is included with your Thunderbird Pro subscription.
* New to Thunderbird? Then check out [[Get started with Thunderbird]].','<p></p><div class="warning">NOTE: Thundermail (formerly known as Thunderbird Pro) is currently in its Early Bird release and available  by invitation only. To learn more and join the waitlist, visit <a href="https://tb.pro/">our website</a>. We’ll be opening Thundermail to the public once the Early Bird release concludes.</div>
<p></p>
<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_configure-thundermail-for-thunderbird-desktop"><span class="tocnumber">1</span> <span class="toctext">Configure Thundermail for Thunderbird Desktop</span></a></li><li class="toclevel-1"><a href="#w_manual-settings"><span class="tocnumber">2</span> <span class="toctext">Manual settings</span></a><ul><li class="toclevel-2"><a href="#w_receiving-email"><span class="tocnumber">2.1</span> <span class="toctext">Receiving Email</span></a></li><li class="toclevel-2"><a href="#w_sending-email"><span class="tocnumber">2.2</span> <span class="toctext">Sending Email</span></a></li></ul></li><li class="toclevel-1"><a href="#w_send-and-receive-email-and-have-some-fun"><span class="tocnumber">3</span> <span class="toctext">Send and receive email, and have some fun!</span></a></li></ul></div>
<h1 id="w_configure-thundermail-for-thunderbird-desktop">Configure Thundermail for Thunderbird Desktop</h1>
<div class="note"><strong>NOTE</strong>: Thunderbird Pro requires Thunderbird 140 for Desktop or newer. We recommend the latest monthly release version of Thunderbird which is documented in: <a href="/en-US/kb/new-thunderbird-desktop">New in Thunderbird Desktop</a>.</div>
<ol><li> Click  <span class="menu">New Account</span> &gt; <span class="menu">Email</span>
</li><li> Enter your Thundermail email address and follow the prompts to set up your Thundermail email account.
</li></ol>
<h1 id="w_manual-settings">Manual settings</h1>
<p>Thunderbird should automatically configure your Thundermail email settings to match your <a href="https://accounts.tb.pro/self-serve/connection-info">TB Pro accounts page</a>. If it doesn’t, please try manually changing the Receiving email and Sending email settings as per the sections below. If manual setup fails, please create a support ticket using our form at: <a href="https://accounts.tb.pro/contact/">accounts.tb.pro/contact</a>.
</p><section class="mzp-c-details is-details">
<p></p>
<h2 id="w_receiving-email" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-expanded="false">Receiving Email</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-0" aria-hidden="true"><ol><li> Switch to your Thundermail account: Thunderbird app menu <span class="menu">☰</span>  &gt; <span class="menu">Account Settings</span>.
</li><li> In the left sidebar, click on your Thundermail email account. (For example: <a href="mailto:nemo@thundermail.com">nemo@thundermail.com</a>.) Then, click on the chevron “&gt;” to expand the drop down menu. Finally, click on <span class="menu">Server Settings</span> and set the following values:
</li></ol><ul><li> <strong>Server Name:</strong> <a href="http://mail.thundermail.com">mail.thundermail.com</a> <strong>Server Port:</strong> 993
</li><li> <strong>Security:</strong> SSL/TLS
</li><li> <strong>Username:</strong> your full Thundermail email address e.g.&nbsp;<a href="mailto:nemo@thundermail.com">nemo@thundermail.com</a>
</li><li> <strong>Authentication method:</strong> OAuth2
</li></ul></div>


<h2 id="w_sending-email" class="is-summary"><button type="button" aria-controls="expand-mzpcdetailshmzpcdetailsdivforh-1" aria-expanded="false">Sending Email</button></h2><div class="mzp-js-details-wrapper is-closed" id="expand-mzpcdetailshmzpcdetailsdivforh-1" aria-hidden="true"><ol><li> Switch to your Thundermail account: Thunderbird app menu <span class="menu">☰</span>  &gt; <span class="menu">Account Settings</span>.
</li><li> In the left sidebar click on your Thundermail email account. (For example <a href="mailto:nemo@thundermail.com">nemo@thundermail.com</a>.) Click on <span class="button">Edit outgoing server…</span> and set the following values:
</li></ol><ul><li> <strong>Server Name:</strong> <a href="http://mail.thundermail.com">mail.thundermail.com</a>
</li><li> <strong>Server Port:</strong> 465 <strong>Connection</strong> <strong>Security:</strong> SSL/TLS
</li><li> <strong>Username:</strong> your full Thundermail email address For example: <a href="mailto:nemo@thundermail.com">nemo@thundermail.com</a>
</li><li> <strong>Authentication method:</strong> OAuth2
</li></ul><p></p></div>


</section>
<p></p>
<h1 id="w_send-and-receive-email-and-have-some-fun">Send and receive email, and have some fun!</h1>
<ul><li> <a class="new" href="/en-US/kb/new?title=Send+and+receive+email" title="Page does not exist.">Send and receive email</a> with Thundermail. If you have large files, you can also use <a href="https://support.tb.pro/hc/sections/43937747865235"><strong>Thunderbird Send</strong></a>. which is included with your Thunderbird Pro subscription.
</li><li> New to Thunderbird? Then check out <a href="/en-US/kb/getting-started-thunderbird">Get started with Thunderbird</a>.
</li></ul>','[{"label": "Revision id", "text": "319677", "datetime": null, "href": null}, {"label": "Created", "text": "Feb 10, 2026, 9:47:44 AM", "datetime": "2026-02-10T09:47:44.671310-08:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "english only for now, so do not translate please! Discussion please https://github.com/thunderbird/knowledgebase-issues/issues/103", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Feb 10, 2026, 9:48:07 AM", "datetime": "2026-02-10T09:48:07.429702-08:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:23:53+00:00','MT');
INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (319684,'en-US','thundermail-and-thunderbird-android','Thundermail and Thunderbird for Android','https://support.mozilla.org/en-US/kb/thundermail-and-thunderbird-android','https://support.mozilla.org/en-US/kb/thundermail-and-thunderbird-android/revision/319684',NULL,'2026-02-10T10:37:29.998969-08:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','english only for now, so do not translate please! Discussion please https://github.com/thunderbird/android-knowledgebase-issues/issues/23',1,'2026-02-10T10:38:12.051426-08:00','rtanglao',1,0,0,NULL,NULL,'approved','[[Template:TBproEarlyBirdInviteOnly]]
Here’s how to get started with Mozilla’s Thundermail service. 

=Configure Thundermail for Thunderbird for Android=
''''''NOTE'''''': Thunderbird Pro requires Thunderbird 15 for Android or newer. We recommend the latest monthly release version of Thunderbird for Android, which is documented in [[New in Thunderbird for Android]].

# Thunderbird app menu {menu ≡} > Settings gear icon {button [[Image:gear icon]]} > {menu Add account}.
# Enter your Thundermail email address (for example [mailto:nemo@thundermail.com nemo@thundermail.com]) 
# Click {button Next}.
# The next screen will prompt you to ''''''Please specify the special folders for your account'''''' along with some suggested settings for your Thunderbird special folders. For most people the defaults are fine. Configure them to your needs and click {button Next}. 
# On the next screen, configure your user name under ''''''Your name'''''' and optionally your signature and {button Next}.
# The next screen will give you some sync and notification options. For most people, the defaults are fine. Configure them to your needs and click {button Next} .

=Manual settings=

Thunderbird should automatically configure your Thundermail email settings to match your [https://accounts.tb.pro/self-serve/connection-info TB Pro accounts page]. If it doesn’t, please try manually changing the receiving email and sending email settings as per the sections below. If manual setup fails, please create a support ticket using our form at: https://accounts.tb.pro/contact/
[[UI:details_start]]

