</li></ul>','[{"label": "Revision id", "text": "327482", "datetime": null, "href": null}, {"label": "Created", "text": "May 1, 2026, 10:21:19 PM", "datetime": "2026-05-01T22:21:19.936407-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "CardDAV, check spaces, formatting, WIP, please do not translate. Discussion: https://github.com/thunderbird/knowledgebase-issues/issues/193", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "May 1, 2026, 10:23:37 PM", "datetime": "2026-05-01T22:23:37.440789-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:22:01+00:00','M');
