INSERT INTO article_revisions (revision_id, locale, article_slug, article_title, article_url, revision_url, previous_revision_id, created, creator_name, creator_url, comment, reviewed, reviewed_date, reviewed_by, is_approved, is_current, ready_for_l10n, readied_for_l10n_date, readied_for_l10n_by, status, source, content_html, info_json, scraped_at, significance) VALUES (345976,'en-US','protect-your-thunderbird-passwords-primary-password','Protect your Thunderbird passwords with a Primary Password','https://support.mozilla.org/en-US/kb/protect-your-thunderbird-passwords-primary-password','https://support.mozilla.org/en-US/kb/protect-your-thunderbird-passwords-primary-password/revision/345976',345943,'2026-08-07T21:16:42.807604-07:00','Roland Tanglao','https://support.mozilla.org/en-US/user/rtanglao/','WARNING:We do not recommend using the Primary Password feature. It is not secure',1,'2026-08-07T21:16:53.972681-07:00','rtanglao',1,0,1,'2026-08-07T21:16:53.972681-07:00','rtanglao','approved','__TOC__

{warning}WARNING:''''''We do not recommend using the Primary Password feature. It is not secure''''''. Until this feature is removed, we will keep this article for legacy reasons. ''''''Your primary password protects only authentication information, such as saved passwords - it ''''does not'''' prevent others from seeing your messages, youe calendars, your contacts, or other personal information in Thunderbird.'''''' To block access to locally stored (downloaded) messsages you should use traditional computer protections such as disk encryption, computer accounts, and file system permissions. Create a separate {for win}Windows{/for}{for mac}macOS{/for}{for linux}OS{/for} user account on the operating system for each person, make sure your {for win}Windows{/for}{for mac}macOS{/for}{for linux}OS{/for} account requires a password, do not give  administrator capability and do not give access to your computer account''s file system. (Thunderbird stores mail accounts, messages and password information separately for each operating system account.) {/warning}
<!-- [Commented out: Not useful because it''s very easy to reverse this method]<br><br> A weaker method is to change the hidden preference mail.password_protect_local_cache in the [[config editor]] to True. This will prevent the display of email until the Primary Password is entered. It does not however do anything about your mail being stored on the hard disk as a plain text file. Using an operating system account does address that.-->

= What does the Primary Password protect? =
Thunderbird can save passwords and other authentication information for each account in the [[Password Manager - Remember, delete and change passwords in Thunderbird|Password Manager]], so you don''t have to re-enter them when you check for new messages. 

What if you share a computer, and don''t want others to see your stored passwords and authentication informatio?  You can set a Primary Password, which must be entered to view or use the passwords you''ve told Thunderbird to remember. You only need to enter your Primary Password once per Thunderbird session.

[[Image:tb91-password-required-mozilla-thunderbird-please-enter-your-primary-password]]

= Set a Primary Password =
By default, Thunderbird does not use a Primary Password to protect stored credentials. To set a Primary Password:
# [[T:optionspreferences TB]]
# Select the {menu Privacy & Security} section.
# Go to the ''''Passwords'''' subsection.
# Put a checkmark next to ''''''Use a Primary Password''''''.<br/><br/>[[Image:tb91-preferences-privacy-security-passwords-use-primary-password]]
# The ''''Change Primary Password'''' dialog will appear. As you enter your Primary Password, the password quality meter will indicate the difficulty of guessing the password. Here are some tips for creating better passwords:
#* Use at least one capital letter.
#* Use one or more digits.
#* Use at least one non-alphanumeric character, such as: <nowiki>@ # $ % ^ & * ( )</nowiki>
#* Make your Primary Password something that is easy for you to remember, but difficult for others to guess, to ensure that only ''''you yourself'''' will be able to see your saved passwords.
# The password must be entered twice to make sure that you have entered it correctly as intended.<br/><br/>[[Image:tb91-use-primary-password-primary-password-dialog]]
# To set your Primary Password, click {button OK}.
Now that your Primary Password is set, Thunderbird will prompt you to enter it the first time you need to view or use a password per session.

= Change your Primary Password =
# [[T:optionspreferences TB]]
# Select the {menu Privacy & Security} section.
# Go to the ''''Passwords'''' subsection.
# Click the button {button Change Primary Password}.
# Enter your current Primary Password to confirm you are authorized to change it.
# Enter the new Primary Password twice.
# Click {button OK}.

= Remove your Primary Password =
Follow the steps above to ''''Change your Primary Password'''', but leave both of the new Primary Password fields empty. However, if you do not know your primary password, then you must use the reset instructions below.

= Reset your Primary Password if you have forgotten it =
If you''ve forgotten your Primary Password, you can reset it.
{warning}''''''Warning:'''''' This will remove all of your saved authentication information. You will need other information sources for your account usernames and passwords.{/warning}
# Press the shortcut keys {key Ctrl+Shift+J} ({key Command+Shift+J} on macOS) to open the error console
# Copy the text given below and paste it into the console.<br><code>openDialog("chrome://pippki/content/resetpassword.xhtml")</code>
# Click the {button Evaluate} button. If you do not see an ''''Evaluate'''' button, press {key Return} or {key Enter} on your keyboard.
# When prompted with the confirmation dialog box, click the {button Reset} button.<br/><br/>[[Image:tb91-reset-primary-password-dialog]]','<div id="toc"><h2>Table of Contents</h2><ul><li class="toclevel-1"><a href="#w_what-does-the-primary-password-protect"><span class="tocnumber">1</span> <span class="toctext">What does the Primary Password protect?</span></a></li><li class="toclevel-1"><a href="#w_set-a-primary-password"><span class="tocnumber">2</span> <span class="toctext">Set a Primary Password</span></a></li><li class="toclevel-1"><a href="#w_change-your-primary-password"><span class="tocnumber">3</span> <span class="toctext">Change your Primary Password</span></a></li><li class="toclevel-1"><a href="#w_remove-your-primary-password"><span class="tocnumber">4</span> <span class="toctext">Remove your Primary Password</span></a></li><li class="toclevel-1"><a href="#w_reset-your-primary-password-if-you-have-forgotten-it"><span class="tocnumber">5</span> <span class="toctext">Reset your Primary Password if you have forgotten it</span></a></li></ul></div>
<div class="warning">WARNING:<strong>We do not recommend using the Primary Password feature. It is not secure</strong>. Until this feature is removed, we will keep this article for legacy reasons. <strong>Your primary password protects only authentication information, such as saved passwords - it <em>does not</em> prevent others from seeing your messages, youe calendars, your contacts, or other personal information in Thunderbird.</strong> To block access to locally stored (downloaded) messsages you should use traditional computer protections such as disk encryption, computer accounts, and file system permissions. Create a separate <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">macOS</span><span class="for" data-for="linux" style="display: none;">OS</span> user account on the operating system for each person, make sure your <span class="for" data-for="win" style="display: none;">Windows</span><span class="for" data-for="mac">macOS</span><span class="for" data-for="linux" style="display: none;">OS</span> account requires a password, do not give  administrator capability and do not give access to your computer account''s file system. (Thunderbird stores mail accounts, messages and password information separately for each operating system account.) </div>
<p>
</p>
<h1 id="w_what-does-the-primary-password-protect">What does the Primary Password protect?</h1>
<p>Thunderbird can save passwords and other authentication information for each account in the <a href="/en-US/kb/password-manager-remember-delete-change-tb">Password Manager</a>, so you don''t have to re-enter them when you check for new messages. 
</p><p>What if you share a computer, and don''t want others to see your stored passwords and authentication informatio?  You can set a Primary Password, which must be entered to view or use the passwords you''ve told Thunderbird to remember. You only need to enter your Primary Password once per Thunderbird session.
</p><p><img alt="tb91-password-required-mozilla-thunderbird-please-enter-your-primary-password" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-12-29-50-749867.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</p>
<h1 id="w_set-a-primary-password">Set a Primary Password</h1>
<p>By default, Thunderbird does not use a Primary Password to protect stored credentials. To set a Primary Password:
</p>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Settings</span>.

</li><li> Select the <span class="menu">Privacy &amp; Security</span> section.
</li><li> Go to the <em>Passwords</em> subsection.
</li><li> Put a checkmark next to <strong>Use a Primary Password</strong>.<br><br><img alt="tb91-preferences-privacy-security-passwords-use-primary-password" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-14-09-05-dfd94c.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> The <em>Change Primary Password</em> dialog will appear. As you enter your Primary Password, the password quality meter will indicate the difficulty of guessing the password. Here are some tips for creating better passwords:
<ul><li> Use at least one capital letter.
</li><li> Use one or more digits.
</li><li> Use at least one non-alphanumeric character, such as: @ # $ % ^ &amp; * ( )
</li><li> Make your Primary Password something that is easy for you to remember, but difficult for others to guess, to ensure that only <em>you yourself</em> will be able to see your saved passwords.
</li></ul>
</li><li> The password must be entered twice to make sure that you have entered it correctly as intended.<br><br><img alt="tb91-use-primary-password-primary-password-dialog" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-14-59-36-393ff3.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li><li> To set your Primary Password, click <span class="button">OK</span>.
</li></ol>
<p>Now that your Primary Password is set, Thunderbird will prompt you to enter it the first time you need to view or use a password per session.
</p>
<h1 id="w_change-your-primary-password">Change your Primary Password</h1>
<ol><li> Click Thunderbird app menu <span class="menu">☰</span> &gt; <span class="menu">Settings</span>.

</li><li> Select the <span class="menu">Privacy &amp; Security</span> section.
</li><li> Go to the <em>Passwords</em> subsection.
</li><li> Click the button <span class="button">Change Primary Password</span>.
</li><li> Enter your current Primary Password to confirm you are authorized to change it.
</li><li> Enter the new Primary Password twice.
</li><li> Click <span class="button">OK</span>.
</li></ol>
<h1 id="w_remove-your-primary-password">Remove your Primary Password</h1>
<p>Follow the steps above to <em>Change your Primary Password</em>, but leave both of the new Primary Password fields empty. However, if you do not know your primary password, then you must use the reset instructions below.
</p>
<h1 id="w_reset-your-primary-password-if-you-have-forgotten-it">Reset your Primary Password if you have forgotten it</h1>
<p>If you''ve forgotten your Primary Password, you can reset it.
</p>
<div class="warning"><strong>Warning:</strong> This will remove all of your saved authentication information. You will need other information sources for your account usernames and passwords.</div>
<ol><li> Press the shortcut keys <span class="key">Ctrl</span> + <span class="key">Shift</span> + <span class="key">J</span> (<span class="key">Command</span> + <span class="key">Shift</span> + <span class="key">J</span> on macOS) to open the error console
</li><li> Copy the text given below and paste it into the console.<br><code>openDialog("chrome://pippki/content/resetpassword.xhtml")</code>
</li><li> Click the <span class="button">Evaluate</span> button. If you do not see an <em>Evaluate</em> button, press <span class="key">Return</span> or <span class="key">Enter</span> on your keyboard.
</li><li> When prompted with the confirmation dialog box, click the <span class="button">Reset</span> button.<br><br><img alt="tb91-reset-primary-password-dialog" class="wiki-image frameless lazy" data-original-src="https://assets-prod.sumo.prod.webservices.mozgcp.net/media/uploads/gallery/images/2022-02-14-15-48-30-8ed674.png" src="https://assets-prod.sumo.prod.webservices.mozgcp.net/static/placeholder.cb78bf81388965e3.gif" title="">
</li></ol>','[{"label": "Revision id", "text": "345976", "datetime": null, "href": null}, {"label": "Created", "text": "Aug 7, 2026, 9:16:42 PM", "datetime": "2026-08-07T21:16:42.807604-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "WARNING:We do not recommend using the Primary Password feature. It is not secure", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Aug 7, 2026, 9:16:53 PM", "datetime": "2026-08-07T21:16:53.972681-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Aug 7, 2026, 9:16:53 PM", "datetime": "2026-08-07T21:16:53.972681-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:18:21+00:00','M');
