<ul><li> <a href="https://support.google.com/mail/answer/78892">Gmail’s support article on recommended settings</a>.
</li><li> <a href="https://bugzilla.mozilla.org/show_bug.cgi?id=402793">This ticket, which tracks issues using Gmail with Thunderbird (Bug 402793)</a>.
</li></ul>','[{"label": "Revision id", "text": "353019", "datetime": null, "href": null}, {"label": "Created", "text": "Sep 16, 2026, 6:32:14 AM", "datetime": "2026-09-16T06:32:14.328509-07:00", "href": null}, {"label": "Creator", "text": "Wayne Mery", "datetime": null, "href": "https://support.mozilla.org/en-US/user/wsmwk/"}, {"label": "Comment", "text": "add section Slow message downloads and missing messages", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 6, 2026, 8:55:12 AM", "datetime": "2026-10-06T08:55:12.390131-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "Yes", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T20:16:19+00:00','M');
