</p>','[{"label": "Revision id", "text": "359085", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 5, 2026, 12:06:53 AM", "datetime": "2026-10-05T00:06:53.086879-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "wip do not translate", "datetime": null, "href": null}, {"label": "Reviewed", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "No", "datetime": null, "href": null}]','2026-11-03T18:16:37+00:00','');
