</p>','[{"label": "Revision id", "text": "367441", "datetime": null, "href": null}, {"label": "Created", "text": "Oct 31, 2026, 10:57:18 AM", "datetime": "2026-10-31T10:57:18.379769-07:00", "href": null}, {"label": "Creator", "text": "Roland Tanglao", "datetime": null, "href": "https://support.mozilla.org/en-US/user/rtanglao/"}, {"label": "Comment", "text": "fix https://github.com/thunderbird/knowledgebase-issues/issues/248", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Yes", "datetime": null, "href": null}, {"label": "Reviewed", "text": "Oct 31, 2026, 10:57:51 AM", "datetime": "2026-10-31T10:57:51.302304-07:00", "href": null}, {"label": "Reviewed by", "text": "rtanglao", "datetime": null, "href": null}, {"label": "Is approved?", "text": "Yes", "datetime": null, "href": null}, {"label": "Is current revision?", "text": "No", "datetime": null, "href": null}, {"label": "Ready for localization", "text": "Yes", "datetime": null, "href": null}, {"label": "Readied for localization", "text": "Oct 31, 2026, 10:58:17 AM", "datetime": "2026-10-31T10:58:17.103291-07:00", "href": null}, {"label": "Readied for localization by", "text": "rtanglao", "datetime": null, "href": null}]','2026-11-03T18:14:25+00:00','M');
